\title{On Decision-Dependent Uncertainties in Power Systems with High-Share Renewables}

\author{Yunfan Zhang,
		Yifan Su,
        Feng Liu

	\thanks{This work was supported by the Joint Research Fund in Smart Grid (No.U1966601) under cooperative agreement between the National Natural Science Foundation of China (NSFC) and State Grid Corporation of China. \textit{(Corresponding author: Feng Liu)}}
