\subsection{The Partial Separability of DDUS}
\label{subsec:partial_separa}

\subsubsection{Definition}
We define the partial separability of a DDUS as follows.
\begin{definition}[Partial Separability of DDUS]
\label{def:sep:partial}	
If the following two conditions hold for a DDUS $\mathcal{U}(x)$, then $\mathcal{U}(x)$ is called \textbf{partially separable}.
\begin{itemize}
	\item [a)] There exists a set-valued map $\mathcal{U}^{\rm sub}(x):X\rightrightarrows U$ such that the graph of $\mathcal{U}^{\rm sub}(x)$ is the subset of the graph of $\mathcal{U}(x)$, i.e., 
	$$
	\text{graph}(\mathcal{U}^{\rm sub}(\cdot))\subseteq \text{graph}(\mathcal{U}(\cdot)).
	$$
	\item [b)] The set-valued map $\mathcal{U}^{\rm sub}(x)$ in condition a) is separable with the following formulation:
	$$
	\mathcal{U}^{\rm sub}(x)=\left\{
	u=\mathcal{C}(\xi,x)\ |\ \xi\in \Xi
	\right\},\forall x\in X.
	$$
\end{itemize}
\end{definition}

\subsubsection{Ubiquity} 
Considering the DDU-integrated TSRO problem \eqref{tsro}, we would like to show that any given DDUS $\mathcal{U}(x)$ is partially separable and can be equivalently substituted by the set-valued map with complete separability. 

For the TSRO problem \eqref{tsro} and any given DDUS $\mathcal{U}(x)$, define the separable DDUSs with regard to robust feasibility and robust optimality respectively as follows:
\begin{itemize}
	\item [a)] The DDUS $\mathcal{U}^{\rm sep}_{\rm fea}(x):X\rightrightarrows U$ is formulated considering the robust feasibility of TSRO problem \eqref{tsro} as follows:
	\begin{subequations}
		\label{sep:fea}
		\begin{align}
			\label{sep:fea:1}
			\mathcal{U}_{\rm fea}^{\rm sep}(x):=\left\{
			u=\mathcal{C}_{\rm fea}(\xi,x)\ |\ \xi\in \Xi
			\right\},\forall x\in X
		\end{align}
		where $\Xi$ is the decision-independent support of auxiliary random variable $\xi$:
		\begin{align} 
			\label{sep:fea:2}
			\Xi:=\left\{
			\xi\ |\ B^{\mathsf{T}}\xi \le \mathbf{0},-\mathbf{1}\le \xi\le \mathbf{0}
			\right\}
		\end{align}
		and $\mathcal{C}_{\rm fea}(\cdot)$ is the coupling function defined as follows:
		\begin{align}
			\label{sep:fea:3}
			\mathcal{C}_{\rm fea}(\xi,x) := \arg \left\{
			\begin{array}{ll}
				\max_{u}\ &-\xi^{\mathsf{T}}Cu\\
				\text{s.t.}\ &u\in\mathcal{U}(x)
			\end{array}
			\right\}
		\end{align}
	\end{subequations}

	\item [b)] The DDUS $\mathcal{U}^{\rm sep}_{\rm opt}(x):X\rightrightarrows U$ is formulated considering the robust optimality of TSRO problem \eqref{tsro} as follows:
	\begin{subequations}
		\label{sep:opt}
		\begin{align}
			\label{sep:opt:1}
			\mathcal{U}_{\rm opt}^{\rm sep}(x):=\left\{
			u=\mathcal{C}_{\rm opt}(\pi,x)\ |\ \pi\in \Pi
			\right\},\forall x\in X
		\end{align}
		where $\Pi$ is the decision-independent support of auxiliary random variable $\pi$:
	    \begin{align}
			\label{sep:opt:2}
			\Pi:=\left\{
			\pi\ |\ B^{\mathsf{T}}\pi \le c,\pi\le \mathbf{0}
			\right\}
		\end{align}
		and $\mathcal{C}_{\rm opt}(\cdot)$ is the coupling function formulated as follows:
		\begin{align}
			\label{sep:opt:3}
			\mathcal{C}_{\rm opt}(\pi,x) := \arg \left\{
			\begin{array}{ll}
				\max_{u}\ &-\pi^{\mathsf{T}}Cu\\
				\text{s.t.}\ &u\in\mathcal{U}(x)
			\end{array}
			\right\}
		\end{align}
	\end{subequations}
\end{itemize}

First of all, it is easy to verify that the graph of $\mathcal{U}_{\rm fea}^{\rm sep}(x)$ and $\mathcal{U}_{\rm opt}^{\rm sep}(x)$ are the subsets of the graph of $\mathcal{U}(x)$, therefore the condition a) in Definition \ref{def:sep:partial} is satisfied. Combining with the fact that  $\mathcal{U}_{\rm fea}^{\rm sep}(x)$ and $\mathcal{U}_{\rm opt}^{\rm sep}(x)$ are completely separable, it is revealed that the DDUS $\mathcal{U}(x)$ is with partial separability regardless of the specific formulation of $\mathcal{U}(x)$.

Next, we would like to justify that the DDUS $\mathcal{U}(x)$ in TSRO problem \eqref{tsro} can be equivalently substituted by the two separable DDUSs $\mathcal{U}_{\rm fea}^{\rm sep}(x)$ and $\mathcal{U}_{\rm opt}^{\rm sep}(x)$.
\begin{theorem}
	\label{thm:eq}
	The TSRO problem \eqref{tsro} with arbitrary DDUS $\mathcal{U}(x)$ has surrogate model as follows:
\begin{itemize}
	\item [a)] The RFR $X_R$ is with the following equivalent formulation:
	\begin{subequations}
		\label{xr:eq}
		\begin{align}
			\label{xr:eq:1}
			X_R&\overset{(i)}{:=}\left\{x\in X\ |\ Y(x,u)\neq \emptyset,\forall u\in \mathcal{U}(x)\right\}\\
			\label{xr:eq:2}
			&\overset{(ii)}{=}\left\{x\in X\ |\ Y(x,u)\neq \emptyset,\forall u\in \mathcal{U}_{\rm fea}^{\rm sep}(x)\right\}
		\end{align}
	\end{subequations}
	where $(i)$ is according to the definition of $X_R$ in \eqref{tsro:4} and $(ii)$ implies the surrogate formulation of $X_R$.
	\item [b)] The robust optimality sub-function $S(x)$ is with the following equivalent formulation:
	\begin{subequations}
	\label{s:eq}
	\begin{align}
		S(x)\overset{(i)}{:=}&\max_{u\in \mathcal{U}(x)}\min_{y\in Y(x,u)}\ c^{\mathsf{T}}y,\quad\forall x\in X\\
		\overset{(ii)}{=}&\max_{u\in \mathcal{U}_{\rm opt}^{\rm sep}(x)}\min_{y\in Y(x,u)}\ c^{\mathsf{T}}y,\quad\forall x\in X
	\end{align}
	\end{subequations}
	where $(i)$ is according to the definition of $S(x)$ in \eqref{tsro:3} and $(ii)$ implies the surrogate formulation of function $S(x)$.
\end{itemize}
\end{theorem}
The proof of Theorem \ref{thm:eq} is provided in the appendix.

According to Theorem \ref{thm:eq}, for any DDUS $\mathcal{U}(x)$, the TSRO problem \eqref{tsro} is equivalent with \eqref{tsro-eq} as follows
\begin{subequations}
	\label{tsro-eq}
\begin{gather}
\min_{x}\ 
\left\{f(x)+\max_{u\in \mathcal{U}_{\rm opt}^{\rm sep}(x)}\min_{y\in Y(x,u)}\ c^{\mathsf{T}}y\right\}\\
\text{s.t.}\quad x\in X\\
Y(x,u)\neq \emptyset,\forall u\in \mathcal{U}_{\rm fea}^{\rm sep}(x)
\end{gather}
\end{subequations}
where $\mathcal{U}_{\rm opt}^{\rm sep}(x)$ and $\mathcal{U}_{\rm fea}^{\rm sep}(x)$ are two separable DDUSs. 

