\begin{align}
x\in X_R&\iff \mathcal{U}(x)\subseteq \mathcal{D}(x)\\
&\iff \mathcal{U}_{\rm fea}^{\rm sep}(x)\subseteq \mathcal{D}(x)\\
&\iff \Xi\subseteq \mathfrak{D}(x)
\end{align}
\end{subequations}

