\section*{Proof of Lemma \ref{lemma:diu:convex}}
\label{app-C}
Consider set $\Gamma$ as follows:
\begin{gather}
	\Gamma:=
\cap_{u\in\mathcal{U}^0}\left\{
(x,\alpha,y)|Y(x,u) \cap \{y|c^{\mathsf{T}}y\le \alpha\}
\neq \emptyset
\right\}
\end{gather}
Since $Y(\cdot)$ and $\mathcal{U}^0$ are both polyhedrons, $\Gamma$ is equivalent to:
\begin{gather}
	\label{app-C:eq:1}
	\Gamma=
	\cap_{u\in\text{vert}(\mathcal{U}^0)}\left\{
	(x,\alpha,y)|Y(x,u) \cap \{y|c^{\mathsf{T}}y\le \alpha\}
	\neq \emptyset
	\right\}
\end{gather}
According to \eqref{app-C:eq:1}, $\Gamma$ is the intersection of a finite number of polyhedrons. Therefore, $\Gamma$ is a polytope in the space of $(x,\alpha,y)$. 

By projecting $\Gamma$ onto the subspace of $(x,\alpha)$, constraint \eqref{eq-tsro:2} is derived. Since the projection of a polyhedron onto its subspace is still a polyhedron, \eqref{eq-tsro:2} is proved to be a polyhedron. This completes the proof that \eqref{eq-tsro:2} is convex.

\section*{Proof of Theorem \ref{thm:convex}}
\label{app-D}
Let Assumption \ref{assp-tsro} hold. Assume that $\mathcal{T}$ is convex.

First, define optimization problem $R(x,\alpha,u^{'})$ as follows:
\begin{subequations}
	\label{chp2:def:R}
	\begin{align}
		\label{chp2:def:R:1}
		R(x,\alpha,\xi)\triangleq  \min\nolimits_{y,s}\quad &g(y,s)\\
		\label{chp2:def:R:2}
		\text{s.t.}\quad & Ax+By+\mathcal{T}(\xi,x)\le b+s_1\\
		\label{chp2:def:R:3}
		&y+ s_2\ge \mathbf{0}\\
		\label{chp2:def:R:4}
		&c^{\mathsf{T}}y\le \alpha+s_3\\
		\label{chp2:def:R:5}
		&s_1,s_2,s_3\ge \mathbf{0}
	\end{align}
\end{subequations}
where the objective function $g(y,s)$ is:
\begin{gather}
	g(y,s)=\mathbf{1}^{\mathsf{T}}s_1+\mathbf{1}^{\mathsf{T}}s_2+\mathbf{1}^{\mathsf{T}}s_3
\end{gather}
The objective function $g(\cdot)$ is linear and the feasible region \eqref{chp2:def:R:2}-\eqref{chp2:def:R:5} consist of a polyhedron.

Next, we would like to justify that $R(x,\alpha,\xi)$ is convex with respect to $x$, $\alpha$, and $\xi$. For any $\lambda\in [0,1]$, $(x^1,\alpha^1,\xi^{1})$, and $(x^2,\alpha^2,\xi^{2})$, denote by $(y^1,s^1)$ the optimal solution of $R(x^1,\alpha^1,\xi^1)$ and $(y^2,s^2)$ the optimal solution of $R(x^2,\alpha^2,\xi^2)$. Therefore, we have
\begin{subequations}
	\begin{gather}
		\left(x^1,\alpha^1,\xi^{1},y^1,s^1
		\right)\in \eqref{chp2:def:R:2}\text{-}\eqref{chp2:def:R:5}\\
		\left(x^2,\alpha^2,\xi^{2},y^2,s^2
		\right)\in \eqref{chp2:def:R:2}\text{-}\eqref{chp2:def:R:5}
	\end{gather}
\end{subequations}
Since $\mathcal{T}(\cdot)$ is a convex function, constraints \eqref{chp2:def:R:2}-\eqref{chp2:def:R:5} is convex with respect to $(x,\alpha,\xi,y,s)$. Therefore, we have
\begin{gather}
	\left(
	\begin{array}{c}
		\lambda x^1+(1-\lambda)x^2\\
		\lambda\alpha^1+(1-\lambda)\alpha^2\\
		\lambda \xi^{1}+(1-\lambda)\xi^{2}\\
		\lambda y^1+(1-\lambda)y^2\\
		\lambda s^1+(1-\lambda)s^2
	\end{array}
	\right)\in \eqref{chp2:def:R:2}\text{-}\eqref{chp2:def:R:5}
\end{gather}
which indicates that $\lambda y^1+(1-\lambda)y^2,\lambda s^1+(1-\lambda)s^2$ is the feasible solution to problem
$$
R\left(\lambda x^1+(1-\lambda)x^2,\lambda\alpha^1+(1-\lambda)\alpha^2,\lambda \xi^{1}+(1-\lambda)\xi^{2}\right)
$$
Therefore, the following relationships hold.
\begin{subequations}
	\label{chp2:R:relation}
	\begin{align}
		&\lambda R(x^1,\alpha^1,\xi^{1})+(1-\lambda)R(x^2,\alpha^2,\xi^{2})\\
		\overset{(a)}{=}\quad &\lambda g(y^1,s^1)+(1-\lambda)g(y^2,s^2)\\
		\overset{(b)}{=}\quad&g\left(
		\lambda y^1+(1-\lambda)y^2,\lambda s^1+(1-\lambda)s^2
		\right)\\
		\overset{(c)}{\ge}\quad&
		R\left(\lambda x^1+(1-\lambda)x^2,\lambda\alpha^1+(1-\lambda)\alpha^2,\lambda \xi^{1}+(1-\lambda)\xi^{2}\right)
	\end{align}
\end{subequations}

In \eqref{chp2:R:relation}, equation (a) is because $(y^1,s^1)$ is optimal to $R(x^1,\alpha^1,\xi^1)$ and $(y^2,s^2)$ is optimal to $R(x^2,\alpha^2,\xi^2)$; Equation (b) is because function $g(\cdot)$ is linear; Inequality (c) is because $\lambda y^1+(1-\lambda)y^2,\lambda s^1+(1-\lambda)s^2$ is the feasible solution to the minimization problem $R\left(\lambda x^1+(1-\lambda)x^2,\lambda\alpha^1+(1-\lambda)\alpha^2,\lambda \xi^{1}+(1-\lambda)\xi^{2}\right)$.

Equations \eqref{chp2:R:relation} justify that $R(x,\alpha,\xi)$ is a convex function with respect to $x$, $\alpha$, and $\xi$.

According to the definition of $\mathcal{D}^{\rm ext}(x,\alpha)$ in \eqref{def-ex-dis-reg} and the definition of $R(\cdot)$ in \eqref{chp2:def:R}, we have:
\begin{subequations}
	\begin{align}
		&(x,\alpha)\in \eqref{eq-tsro:2}\\
		\Leftrightarrow\quad &
		Y(x,\mathcal{C}(\xi,x))
		\cap \{
		y|c^{\mathsf{T}}y\le \alpha
		\}
		\neq \emptyset,\forall \xi\in \Xi\\
		\Leftrightarrow\quad &
		\left\{
		\begin{array}{c}
			Ax+By+\mathcal{T}(\xi,x)\le b\\
			y\ge \mathbf{0}\\
			c^{\mathsf{T}}y\le \alpha
		\end{array}
		\right\}\neq \emptyset,\forall \xi\in \Xi\\
		\Leftrightarrow\quad & R(x,\alpha,\xi)\le 0,\forall \xi\in \Xi
	\end{align}
\end{subequations}

Therefore, constraint \eqref{eq-tsro:2} equals to
\begin{gather}
	\eqref{eq-tsro:2}=\left\{
	x\in \mathbb{R}^{n_x},\alpha\in \mathbb{R}^1\ |\ 
	R(x,\alpha,\xi)\le 0,\forall \xi\in \Xi
	\right\}
\end{gather}

Next, we prove \eqref{eq-tsro:2} is convex by contradiction. Suppose there exist $(x^1,\alpha^1),(x^2,\alpha^2)\in \eqref{eq-tsro:2}$ and $\lambda\in [0,1]$ such that $(\lambda x^1+(1-\lambda)x^2,\lambda \alpha^1+(1-\lambda)\alpha^2)\notin \eqref{eq-tsro:2}$. This implies there exists $\xi^{*}\in \Xi$ such that
\begin{gather}
	\label{chp2:proof:ineq}
	R\left(\lambda x^1+(1-\lambda)x^2,\lambda \alpha^1+(1-\lambda)\alpha^2,{\xi}^{*}\right)>0
\end{gather}

Since $(x^1,\alpha^1),(x^2,\alpha^2)\in \eqref{eq-tsro:2}$, we have
$R(x^1,\alpha^1,\xi^{*})\le 0$ and $R(x^2,\alpha^2,\xi^{*})\le 0$. Since $R(\cdot)$ is convex, we have
\begin{subequations}
\begin{align}
	&R\left(
	\lambda x^1+(1-\lambda)x^2,\lambda \alpha^1+(1-\lambda)\alpha^2,\xi^{*}
	\right)\\
	\le\quad &\lambda R(x^1,\alpha^1,\xi^{*})+(1-\lambda)R(x^2,\alpha^2,\xi^{*})\\
	\le\quad & 0
\end{align}
\end{subequations}
which contradicts with \eqref{chp2:proof:ineq}. This completes the proof that \eqref{eq-tsro:2} is convex.

