\subsection{Structure of paper}

In Section \ref{HCIR}, we review the particle method for approximating the calibrated dynamics and summarise key properties of the CIR process that will be important in our proofs. To keep the focus on the convergence results, we postpone establishing the well-posedness of the regularised equation until Section \ref{WellposednessSection}. In Section \ref{PropOfChaos}, we prove a strong propagation of chaos result, showing that the particle system converges to the regularised MV equation up to a critical time. We then turn to the time-discretised setting in Section \ref{timediscretisation}, where we establish the strong convergence of the Euler--Maruyama scheme applied to the particle system with order $1/2$ in time (up to a logarithmic factor) up to a critical time. Finally, in Section \ref{numexp}, we perform numerical experiments that illustrate our theoretical findings and explore scenarios in which certain assumptions in our proofs may be violated.

\subsection{Notation and Preliminaries}
Given $T>0$, let $(\Omega, \mathcal{F}, \mathbb{P})$ denote a complete probability space endowed with $\mathbb{F} = (\mathcal{F}_t)_{t \in [0,T]}$, the natural filtration that satisfies the usual conditions, i.e., it is right-continuous and $\mathcal{F}_0$ contains all $\mathbb{P}$-null sets. Also, let $(W_t)_{t\in [0,T]}$ be a standard multi--dimensional Brownian motion on $(\Omega, \mathcal{F}, \mathbb{F},\mathbb{P})$ such that it is $\mathbb{F}$-adapted. We use $L^2(\Omega, \mathcal{F},\mathbb{P};\mathbb{R}^n)$ to denote the space of $\mathbb{R}^n-$valued square integrable random variables on $(\Omega, \mathcal{F},\mathbb{P})$ and for any $\theta \in L^2(\Omega, \mathcal{F},\mathbb{P};\mathbb{R}^n),\lVert \theta \rVert_{L^2} := \mathbb{E} \left[ |\theta|^2 \right]^{1/2}$. By $(\mathbb{R}^n,|\cdot|)$ we denote the $n$-dimensional Euclidean space and $|\cdot|$ the Hilbert--Schmidt norm. Also, by $\langle \cdot,\cdot \rangle$ we denote the usual inner product in a given Euclidean space.\bigbreak


\noindent Given a complete separable metric space $(E, d)$ (often being a Polish space), let $\mathcal{P}(E)$ denote the set of probability measures on $(E,\mathcal{B}(E))$, with $\mathcal{B}(E)$ the Borel $\sigma$-field over $E$, and for any $p\ge 1$, let $\mathcal{P}_p(E)$ be the subspace of $\mathcal{P}(E)$ of the probability measures of order $p$, i.e.
 \begin{equation*}
 \mathcal{P}_p(E) := \bigg\{ \mu \in \mathcal{P}(E): \text{ for all }x_0 \in E, \int_E d(x_0,x)^p\mu (\diff x) < + \infty \bigg\},    
 \end{equation*}
 where $d: E \times E \to [0, \infty)$, is a metric of the "distance" between two points in $E$. The set $\mathcal{P}_p(E)$ is equipped with the $p-$Wasserstein distance $\mathcal{W}_p(\mu,\nu)$ defined as
\begin{equation}
\mathcal{W}_p(\mu,\nu) = \inf_{\pi}\left(\iint_{E \times E}d(x,y)^p \pi (\diff x,\diff y) \right)^{\frac{1}{p}},
\end{equation}
where $\pi \in \mathcal{P}(E\times E)$ such that $\pi(. \times E) = \mu $ and $\pi(E \times .) = \nu$, i.e. $\pi$ is a coupling of $\mu$ and $\nu$, for any $p\ge 1$ and $\mu, \nu \in \mathcal{P}_p(E).$ Here we work on $\mathbb{R}^n$, and $d$ is the standard Euclidean norm.

\section{Problem formulation}\label{HCIR}

We recall for convenience the complete regularised MV-SDE, with $Z=(X,V)$, $z=(x,v)$, $\mu^{Z}_t = \mathbb{P}_{(X_t, V_t)}$:
\begin{equation}\label{independentparticles3}
\begin{split}
\diff X_t &=  \beta(t,Z_t,\mu^{Z}_t)\diff t + \sigma(t,Z_t,\mu^{Z}_t)\diff  W^{x}_t, %\,\,\, X^i_0=X^i_0,
\,\,\,t \in [0,T], \\
\diff V_t &= k(\theta-V_t)\diff t + \xi\sqrt{V_t}\diff W^v_t,
\end{split}
\end{equation}
with $\diff W^x_t \diff W^v_t = \rho \diff t$, $\rho \in (-1,1)$, and
\begin{eqnarray*}
\sigma(t,z,\mu^{Z}_t) = \sqrt{v}\sigma_{\text{Dup}}(t,e^{x})
\frac{\sqrt{\mathbb{E}^{\mu^{Z}_t}[K(\frac{X-x}{\epsilon})]+ \delta}}{\sqrt{\mathbb{E}^{\mu^{Z}_t}[V K(\frac{X-x}{\epsilon})]+\delta}}, \quad
\beta = -\frac{{\sigma}^2}{2}.
\end{eqnarray*}

For the analysis, we make the following assumptions on the coefficient functions.
\begin{assumption}\label{A3} We assume that
\begin{enumerate}[label=(\subscript{A}{{\arabic*}})]
    \item $(t,x) \to \sigma_{\mathrm{Dup}}(t,e^{x})$ is bounded, Lipschitz in $x$, and $\frac{1}{2}$-H\"{o}lder  in $t$, so that there exist positive constants $A_1, \,L_{\mathrm{Dup}}$ such that for all $x_1,x_2 \in \mathbb{R}$, and $t_1,t_2 \in [0,T],$\newline
$|\sigma_{\mathrm{Dup}}(t_1,e^{x_1})|\le A_1, \text{ and } \big|\sigma_{\mathrm{Dup}}(t_1,e^{x_1}) - \sigma_{\mathrm{Dup}}(t_2,e^{x_2})\big| \le L_{\mathrm{Dup}}\big(|t_1-t_2|^{1/2} + |x_1 - x_2| \big).$ 
    \item $K(\cdot)$ is bounded and Lipschitz continuous so that there exist positive constants $A_2, L_K$ such that for all $x_1,x_2 \in \mathbb{R}$, %\newline
    $|K(x_1)|\le A_2, $ and  $|K(x_1)-K(x_2)|\le L_K |x_1-x_2|$.
\end{enumerate}
\end{assumption}

Neither of these assumptions is practically very restrictive. For the function $L_{\mathrm{Dup}}$, a parametric ansatz is typically calibrated to a discrete set of options data. Common choices are splines in the spatial (i.e., second) variable with some extrapolation, which can be made to satisfy the assumption.
The assumption could be weakened to allow a finite number of discontinuities in time (i.e., the first variable) without complicating the analysis.


\begin{subsection}{Particle method}\label{particlemethod}
To approximate the conditional expectation that appears in the calibrated dynamics of the log-spot process $X$ in \eqref{sde}, we apply a particle method as introduced by Guyon and Henry--Labord\`ere in \cite{GuyHen} for a general LSV model. This involves approximating the true measure $\mu^{Z}_t$ of the joint law of $(X_t,V_t)$ by
\begin{equation*}
 \mu^{Z^N}_t(x,v; \epsilon_x,\epsilon_v) := \frac{1}{N}\sum_{i=1}^{N}\Phi_{\epsilon_x}(X_t^{i,N}-x)\Phi_{\epsilon_v}(V_t^{i}-v),
\end{equation*}
where $\Phi_{\epsilon}(\cdot)$ is a regularising kernel function of the form 
\begin{equation} \label{ReTskernel}
%    \Phi_{\epsilon}(x) = \frac{1}{\epsilon}K\left(\frac{x}{\epsilon}\right),
    \Phi_{\epsilon}(x) = \epsilon^{-1}K\left(\epsilon^{-1} x\right),
\end{equation}
with $K(\cdot)$ a real--valued, non--negative kernel function satisfying $\int_{-\infty}^{+\infty} K(u)\diff u = 1$, and $\epsilon$ the bandwidth of the kernel. For ease of notation, from now on, we denote $\epsilon_x$ by $\epsilon$. This leads to the Nadaraya--Watson estimator for the conditional expectation as follows:
\begin{equation*}
\mathbb{E}[V_t|X_t=x] \approx \frac{\frac{1}{N}\sum_{i=1}^{N}V_t^{i}\Phi_{\epsilon}(X_t^{i,N}-x)}{\frac{1}{N}\sum_{i=1}^{N}\Phi_{\epsilon}(X_t^{i,N}-x)},
\end{equation*}
where $(\textbf{X}^N_t)_{t\in[0,T]}:= \big(X_t^{1,N}, X_t^{2,N}, ... , X_t^{N,N}\big)^\intercal_{t\in[0,T]} $ denotes the interacting particle system for $X$, and $(\textbf{V}_t)_{t\in[0,T]}:= \big(V_t^{1}, V_t^{2}, ... , V_t^{N}\big)^\intercal_{t\in[0,T]} $ independent Monte Carlo samples for $V$.\newline
$\mathbb{E}^{\mu_t^{Z}}\left[V_t\Phi_{\epsilon}(X_t-x)\right]$ is then estimated by
\begin{equation*}\label{NW22}
 \mathbb{E}^{\mu_t^{Z^N}} \left[V_t\Phi_{\epsilon}(X_t-x)\right] = \iint \left( \tilde{V}\Phi_{\epsilon}(\tilde{X}-x)\right)\diff \mu_t^{Z^N} ( \tilde{X},\tilde{V})= \frac{1}{N} \sum_{i=1}^N\,{V^i}\,\Phi_{\epsilon}(X^{i,N}-x).
\end{equation*}
This leads to the following system that we can simulate.\bigbreak

\noindent \textit{Interacting particle system}\bigbreak

\noindent Consider particles $X^{i,N}$, $i=1,...,N$, satisfying the following SDE,
\begin{equation}\label{particlessystem}
%\begin{split}
\diff X^{i,N}_t = \beta(t,(X_t^{i,N},V_t^{i}), \mu_t^{Z^N})\diff t+\sigma(t,(X_t^{i,N},V_t^{i}),\mu_t^{Z^N})\diff{W^{x,i}_t},\, t\in [0,T],
%\diff V^{i}_t &=& k(\theta - V^{i}_t)\diff t + \xi \sqrt{V_t^i} \diff W^{v}_t,
%\end{split}
\end{equation}
with i.i.d. $X^{i,N}_0=X^{i}_0$, and
\begin{equation*}
\sigma(t,(X_t^{i,N},V_t^{i}), \mu_t^{Z^N}) = \sqrt{V_t^{i}}\,\sigma_{\text{Dup}}(t,e^{X^{i,N}_t})\frac{\sqrt{\sum_{j=1}^{N}K\big(\frac{X_t^{j,N} - X_t^{i,N}}{\epsilon}\big)+\delta}}{\!\!\!\!\sqrt{\sum_{j=1}^{N}V_t^{j}K\big(\frac{X_t^{j,N} - X_t^{i,N}}{\epsilon}\big)+\delta}}, \qquad \beta = -\frac{\sigma^2}{2}.
\end{equation*}
The positive constant $\delta$ is added to the numerator and denominator to avoid potential singularities. Also, for each $i$, $W^{x,i}$ are independent Brownian motions and $V^i$ independent Monte Carlo samples that evolve according to the dynamics
\begin{equation}\label{volparticles}
\diff V^{i}_t = k(\theta - V^{i}_t)\diff t + \xi \sqrt{V_t^i} \diff W^{v}_t, \,\,\, V^i_0 = V^i_0, \,\,\, t\in[0,T].
\end{equation}
The interaction term $\mu_t^{Z^N}$ distinguishes the particle method from the classical Monte Carlo method since the paths in the former are no longer independent. As discussed above, it is necessary for the particle system to satisfy a \textit{propagation of chaos} property. %In our work, we prove the strong convergence of the particle system in the  \textcolor{blue}{Need to explain more here on propagation of chaos}. Under global Lipschitz conditions this result is well--established, see, e.g., \cite{Sznitman} and \cite{Meleard} that provide a pathwise convergence result in the sense of Theorem \ref{PropChaos} below. These results, however, are not applicable in the case of a $\frac{1}{2}$--H\"{o}lder continuous diffusion coefficient in the state variable. 
We refer to the Introduction, where we discuss some of the available literature on propagation of chaos results for irregular MV SDEs. Since we are interested in the strong convergence, we prove a strong convergence result in Theorem \ref{PropChaos}. In the limit, we expect the particles to become independent and satisfy the following MV SDE, which we restate from the Introduction.\bigbreak

\noindent \textit{Non--interacting particle system}\bigbreak

\noindent For each $i$, let $X^i$ be independent particles that satisfy the MV SDE
\begin{equation}\label{independentparticles2}
\begin{split}
\diff X^i_t &=  \beta(t,(X^i_t,V^i_t),\mu^{Z}_t)\diff t + \sigma(t,(X^i_t,V^i_t),\mu^{Z}_t)\diff  W^{x,i}_t,\,\,\, X^i_0=X^i_0,\,\,\,t \in [0,T],
\end{split}
\end{equation}
with 
\begin{eqnarray*}
\sigma(t,(x,v),\mu^Z) = \sqrt{v}\sigma_{\text{Dup}}(t,e^{x})\frac{\sqrt{\mathbb{E}^{\mu^Z}[K(\frac{X-x}{\epsilon})]+ \delta}}{\sqrt{\mathbb{E}^{\mu^Z}[V K(\frac{X-x}{\epsilon})]+\delta}}, \quad
\beta = -\frac{{\sigma}^2}{2}.
\end{eqnarray*}
Here, $\mu^{Z}_t$ denotes the true joint law of $(X^i_t,V^i_t)$, which is the same for all $(X^i_t,V^i_t)$ since the particles here are independent.\newline

\begin{remark}
For convenience of notation, let $\tilde{\beta}(t,x,\nu) := -\frac{1}{2}\sigma^2_{\text{Dup}}(t,e^{x})\frac{\mathbb{E}^{\nu}[K(\frac{X-x}{\epsilon})]+ \delta}{\mathbb{E}^{\nu}[V K(\frac{X-x}{\epsilon})]+\delta},$ and $\tilde{\sigma}(t,x,\nu) := \sigma_{\text{Dup}}(t,e^{x})\frac{\sqrt{\mathbb{E}^{\nu}[K(\frac{X-x}{\epsilon})]+ \delta}}{\sqrt{\mathbb{E}^{\nu}[V K(\frac{X-x}{\epsilon})]+\delta}}$, so that $\beta(t,(x,v),\nu) := v \tilde{\beta}(t,x,\nu)$ and $\sigma(t,(x,v),\nu) := \sqrt{v} \tilde{\sigma}(t,x,\nu)$. Under Assumption \ref{A3}, and by adapting Proposition 1 in \cite{ReiTsi} to system \eqref{sde}, we conclude that $\tilde{\beta}(t,x,\nu)$ and $\tilde{\sigma}(t,x,\nu)$ are Lipschitz continuous in the state and measure variables with Lipschitz constants $L_{\tilde{\beta}}$ and $L_{\tilde{\sigma}}$ respectively, and $1/2-$H\"older continuous in time. $L_{\tilde{\beta}}$ and $L_{\tilde{\sigma}}$ depend on $\epsilon, \delta$ and the constants in Assumption \ref{A3}. For the exact dependence, we refer to the proof of Proposition 1 in \cite{ReiTsi}. In our work, we keep $\epsilon, \delta$, and the constants in Assumption \ref{A3} fixed. Also, $|\tilde{\beta}(t,x,\nu)|$ and $|\tilde{\sigma}(t,x,\nu)|$ are bounded by positive constants $\tilde{\beta}_{\max}$ and $\tilde{\sigma}_{\max}$, respectively, which depend on $A_1$, $A_2$, and $\delta$. It holds that, $\tilde{\beta}_{\max} = \frac{\tilde{\sigma}^2_{\max}}{2}$.
\end{remark}

\begin{remark}
In the proofs below, we use a technique involving the stopping--time $\tau^i_{\omega}:= \underset{t\ge 0}{\inf}\{\int_0^t V^i_u \diff u \ge \omega\}$. Although using stopping--times for McKean--Vlasov SDEs is tricky to handle, this is not the case here since the stopped process follows a standard SDE.
\end{remark}

\subsection{Properties of the Cox--Ingersoll--Ross process}
Before establishing the convergence of the particle system, we recall key properties of the CIR process that play a crucial role in our analysis. For further details, see for instance \cite{AndPit}, \cite{CozMarRei}, \cite{CozRei}, \cite{DNS}, \cite{HurKuz}, and the references therein.\bigbreak

\noindent Let $\nu = \frac{2k\theta}{\xi^2}$ be the Feller ratio and $\nu^* = 2+\sqrt{3}$. Also, for $\lambda >0$, let 
\begin{equation}\label{Tbound}
T^* :=
\begin{cases} 
\frac{2}{\sqrt{2\lambda \xi^2 -k^2}}\left[ \frac{\pi}{2} +\text{tan}^{-1}\left(\frac{k}{\sqrt{2\lambda \xi^2 -k^2}} \right)\right],& \text{if } k^2  < 2 \lambda \xi^2 , \\
\infty, & \text{if } k^2  \geq 2 \lambda \xi^2.
\end{cases}
\end{equation}
\begin{lemma}\label{momentboundvol}
  Let $V^i$ denote the CIR volatility process as in \eqref{volparticles}. It holds that 
\begin{enumerate}
\item $\underset{t\in [0,T]}{\sup}\mathbb{E}\left[{V_t^i}^p\right] < \infty, \, \forall \, p>-\nu, \, \textit{i.e. it has bounded moments,}$
\item $     \mathbb{E}\left[\underset{t\in [0,T]}{\sup}{V_t^i}^p\right] < \infty, \, \forall \, p\ge 1, \, \textit{i.e. it has uniformly bounded moments}.$
\end{enumerate}
\end{lemma}
\begin{proof}
For the first bound we refer the reader to formula $(3.1)$ in \cite{DNS}, while for a proof of the second bound to Proposition 3.7 in \cite{CozMarRei}.
%or Lemma 3.2 in \cite{DNS} -> this reference requires the Feller ratio to be bigger than 1. This is why for now i don't include it!
\end{proof}
\begin{lemma}\label{ExpIntVol}
Let $V^i$ denote the CIR volatility process as in \eqref{volparticles} and $\lambda >0$. For $T<T^*$, with $T^*$ the critical time as in \eqref{Tbound}, we have that
\begin{equation}
   \mathbb{E}\left[\exp\{\lambda \int_0^T {V_t}^i\diff t\}\right]< \infty.
\end{equation}
\end{lemma}
\begin{proof}
 This follows from Proposition 3.1 in \cite{AndPit}.  
\end{proof}

\subsection{Well-posedness of the regularised system}
For completeness, we state the existence and uniqueness result for equation \eqref{independentparticles3} here, while deferring its proof and analysis to Section~\ref{WellposednessSection} to maintain the focus on the convergence analysis.
\begin{theorem}[Well-posedness]\label{wellposedness}
Let Assumptions \ref{A3} hold and also assume that $\nu \ge 1$ and $\mathbb{E}[|X_0|^4] < \infty$. Then, there exists a unique strong solution to equation \eqref{independentparticles3} up to a critical time $T^*$, for $T^*$ as in $\eqref{Tbound}$.
\end{theorem}

 We are now well-equipped to prove a strong propagation of chaos result that establishes the convergence of the particle system \eqref{particlessystem} to the McKean--Vlasov SDE \eqref{independentparticles2},
 and in the following section a timestepping approximation scheme. \newline

\section{Propagation of chaos}\label{PropOfChaos}
 To prove the result below we use techniques from \cite{ReiEngSmi} and \cite{CozRei2}. The authors in \cite{ReiEngSmi} prove propagation of chaos for a MV SDE with drift of super-linear growth and also provide the rate of convergence. However, their analysis assumes a global Lipschitz diffusion in the state variable. The study in \cite{CozRei2} addresses the square--root diffusion by considering a Heston-type LSV model and proves strong convergence of the Euler scheme. However, they do not consider the calibrated system so their equation is a standard SDE, without mean-field dependence.
\begin{theorem}\label{PropChaos}
    Let $Z^i := (X^i,V^i)$ and $Z^{i,N} := (X^{i,N},V^i)$ with $X^i$, $X^{i,N}$, and $V^i$ solutions to equations \eqref{independentparticles2}, \eqref{particlessystem}, and \eqref{volparticles} respectively. Further, let $Z^{i}_0,Z^{i,N}_0 \in L^2(\mathbb{R}^2)$. Suppose that  $\nu \ge 1$ and that Assumption \ref{A3} holds. For $T<T^*$ we have that,
\begin{equation*}
\lim_{N\to \infty}\sup_{i \in \{1,..,N\}} \mathbb{E} \Bigg[\sup_{t \in [0,T]} \lvert Z^{i,N}_t - Z^i_t \rvert^2\Bigg]=0.
\end{equation*} 
\end{theorem}
\begin{proof}
In our proof, we let $C$ denote a constant independent of $N$, and only possibly dependent on $T$ and the Lipschitz constants $L_{\tilde{\beta}}$ and $L_{\tilde{\sigma}}$ which depend on $\epsilon$ and $\delta$. We allow $C$ to vary from line to line.\bigbreak

Note that $\lvert Z^{i,N}_t - Z^i_t \rvert^2 =  \lvert X^{i,N}_t - X^i_t \rvert^2$ since the second component of $Z^i$ and $Z^{i,N}$ is identical for all $i$. We fix $i \in \{1,...,N\}$ and let $E^N_t:=X^{i,N}_t - X^i_t,\,\,E^N_0=0 $. Applying It\^{o}'s formula to $|E^N_{t \wedge \tau}|^{2p}$, for $\tau$ a stopping time and $1<p<2$, we get
\begin{equation*}
\begin{split}
|E^N_{t \wedge \tau}|^{2p} &= 2p \int_0^{t \wedge \tau} |E^N_{u}|^{2p-1}\text{sgn}(E^N_{u})(\beta(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\beta(u,(X_u^{i},V^i_u), \mu_u^{Z})) \diff u \\
&+2p \int_0^{t \wedge \tau} |E^N_{u}|^{2p-1}\text{sgn}(E^N_{u})(\sigma(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\sigma(u,(X_u^{i},V^i_u), \mu_u^{Z})) \diff  W^{x,i}_u\\
&+\frac{1}{2}2p(2p-1)\int_0^{t \wedge \tau}|E^N_{u}|^{2p-2}\lvert\sigma(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\sigma(u,(X_u^{i},V^i_u), \mu_u^{Z})\lvert^2 \diff u, \\ 
\end{split}
\end{equation*}
where $\text{sgn}(E^N_u)=1$ if $E^N_u>0$ and $\text{sgn}(E^N_u)=-1$ otherwise.\newline
Taking the supremum over $t \in [0,T]$ on both sides, noting that the supremum of the integrals occurs at $t=T$, and then expectations yields
\begin{equation}\label{propsplit1}
    \begin{split}
        &\mathbb{E}\left[\sup_{t\in[0,T]} |E^N_{t \wedge \tau}|^{2p}\right] \le 2p  \mathbb{E}\left[\int_0^{T \wedge \tau} |E^N_{u}|^{2p-1}\lvert\beta(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\beta(u,(X_u^{i},V^i_u), \mu_u^{Z})\lvert \diff u\right] \\
        &+2p \mathbb{E}\left[\sup_{t\in[0,T]}\int_0^{t \wedge \tau} |E^N_{u}|^{2p-1}\text{sgn}(E^N_{u})(\sigma(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\sigma(u,(X_u^{i},V^i_u), \mu_u^{Z})) \diff  W^{x,i}_u\right]\\
        &+\frac{1}{2}2p(2p-1)\mathbb{E}\left[\int_0^{T \wedge \tau}|E^N_{u}|^{2p-2}\lvert\sigma(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\sigma(u,(X_u^{i},V^i_u), \mu_u^{Z})\lvert^2 \diff u\right].\\ 
    \end{split}
\end{equation}
We treat each term on the RHS above separately. Looking at the first term of \eqref{propsplit1}, 
%let
%\begin{equation*}
%  \tilde{\beta}(t,x,\nu):= -\frac{1}{2}\sigma^2_{\text{Dup}}(t,e^{x})\frac{\mathbb{E}^{\nu}[K(\frac{X-x}{\epsilon})]+ \delta}{\mathbb{E}^{\nu}[V K(\frac{X-x}{\epsilon})]+\delta},\, \text{ so that }\, \beta(t,(x,v),\nu) := v \tilde{\beta}(t,x,\nu).   
%\end{equation*}
%Under Assumption \ref{A3}, it follows from Proposition 1 in \cite{ReiTsi} adapted to system \eqref{sde}, that $\tilde{\beta}(t,x,\nu)$ is Lipschitz in the space and measure components. We denote its Lipschitz constant by $L_{\tilde{b}}$. We use this result to get
\begin{equation*}
\begin{split}
  |E^N_{u}|^{2p-1}&V^i_u\lvert\tilde{\beta}(u,X_u^{i,N}, \mu_u^{Z^N})-\tilde{\beta}(u,X_u^{i},\mu_u^{Z})\lvert \le L_{\tilde{b}} |E^N_{u}|^{2p-1}V^i_u \Big( \lvert E^N_{u} \lvert + \mathcal{W}_2(\mu_u^{Z^N},\mu_u^{Z} )\Big)\\
  &\le L_{\tilde{b}} |E^N_{u}|^{2p-1} V^i_u \Big( |E^N_{u}| + \mathcal{W}_2(\mu_u^{Z^N},\mu_u^{N}) +\mathcal{W}_2(\mu_u^{N},\mu_u^{Z} )\Big),
\end{split} 
\end{equation*}
where $\mu_u^{N}$ denotes the empirical measure of $Z^{i}_u$ and we applied the property of the Wasserstein metric, see Chapter 6 in \cite{Vil}, that for $\mu_1,\mu_2,\mu_3 \in \mathcal{P}_2(\mathbb{R}^{2n}), \, \mathcal{W}_2(\mu_1,\mu_2) \le \mathcal{W}_2(\mu_1,\mu_3)+\mathcal{W}_2(\mu_3,\mu_2).$\newline
Also, since $\mu_u^{Z^N}$ and $\mu_u^{N}$ are empirical measures we have the standard bound
\begin{equation*}
\mathcal{W}_2(\mu_u^{Z^N},\mu_u^{N})\le \left( \frac{1}{N}\sum_{j=1}^N |Z^{j,N}_u-Z^{j}_u|^2 \right)^{1/2} =\left( \frac{1}{N}\sum_{j=1}^N |X^{j,N}_u-X^{j}_u|^2 \right)^{1/2}.   
\end{equation*}
Also, by Young's inequality one gets
\begin{equation*}
    \begin{split}
    |E^N_{u}|^{2p-1}\mathcal{W}_2(\mu_u^{N},\mu_u^{Z}) &\le \frac{2p-1}{2p} |E^N_{u}|^{2p} +\frac{1}{2p} \mathcal{W}_2(\mu_u^{N},\mu_u^{Z})^{2p},\\
    |E^N_{u}|^{2p-1}\left( \frac{1}{N}\sum_{j=1}^N |X^{j,N}_u-X^{j}_u|^2 \right)^{1/2} & \le \frac{2p-1}{2p}|E^N_{u}|^{2p} +\frac{1}{2p}\left( \frac{1}{N}\sum_{j=1}^N |X^{j,N}_u-X^{j}_u|^2 \right)^{p}\\
    & \le \frac{2p-1}{2p}|E^N_{u}|^{2p} + \frac{1}{2p}N^{-1}\sum_{j=1}^N |X^{j,N}_u-X^{j}_u|^{2p},\\
    \end{split}
\end{equation*}
where the last step follows by applying H\"{o}lder's inequality to the sum.
We therefore have
\begin{equation*}
\begin{split}
    &\mathbb{E}\left[ \int_0^{T \wedge \tau}|E^N_{u}|^{2p-1}\lvert\beta(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\beta(u,(X_u^{i},V^i_u), \mu_u^{Z})\lvert \diff u \right]\\
    &\le C \mathbb{E}\left[ \int_0^{T \wedge \tau}\Big( |E^N_{u}|^{2p} +N^{-1}\sum_{j=1}^N |X^{j,N}_u-X^{j}_u|^{2p}+ \mathcal{W}_2(\mu_u^{N},\mu_u^{Z})^{2p} \Big)V^i_u\diff u\right].\\   
\end{split}
\end{equation*}
Notice that by exchangeability of the components of $X$ and $X^N$, 
\begin{equation*}
  \mathbb{E}\left[N^{-1}\sum_{j=1}^N |X^{j,N}_u-X^{j}_u|^{2p} \right] = \mathbb{E}\left[|X^{i,N}_u-X^{i}_u|^{2p} \right]= \mathbb{E}\left[|E^N_{u}|^{2p} \right].
\end{equation*}
We now define the following stochastic process which is strictly increasing since $V^i$ has almost surely strictly positive paths for $\nu \ge 1$:
\begin{equation}\label{g}
    g^i(t) = \int_0^tV^i_u \diff u.
\end{equation}
Applying Fubini's theorem yields
\begin{equation}
    \begin{split}
       &\mathbb{E}\left[ \int_0^{T \wedge \tau}|E^N_{u}|^{2p-1}\lvert\beta(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\beta(u,(X_u^{i},V^i_u), \mu_u^{Z})\lvert \diff u \right]\\
       & \le C \int_0^{T \wedge \tau} \Big(\mathbb{E}\left[\sup_{t \in [0,u]} |E^N_{t}|^{2p}\right]+\mathbb{E}\left[\mathcal{W}_2(\mu_u^{N},\mu_u^{Z})^{2p}\right]\Big) \diff g^i(u)\\
       & \le T_1:= C  \int_0^{T \wedge \tau}\left(\mathbb{E}\left[\sup_{t \in [0,T]} |E^N_{t\wedge u}|^{2p}\right] +\mathbb{E}\left[\mathcal{W}_2(\mu_u^{N},\mu_u^{Z})^{2p}\right]\right) \diff g^i(u).\\
    \end{split}
\end{equation}
Now looking at the second term of equation \eqref{propsplit1}, to remove the stochastic integral one may apply the Burkholder--Davis--Gundy (BDG) inequality to get for $C$ a positive constant,
\begin{equation}
\begin{split}\label{propsplit2}
&2p\mathbb{E}\left[\sup_{t\in[0,T]}\int_0^{t \wedge \tau} |E^N_{u}|^{2p-1}\text{sgn}(E^N_{u})(\sigma(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\sigma(u,(X_u^{i},V^i_u), \mu_u^{Z})) \diff  W^{x,i}_u\right] \\
 & \le C\mathbb{E}\left[\left(\int_0^{T \wedge \tau} |E^N_{u}|^{2(2p-1)}|\sigma(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\sigma(u,(X_u^{i},V^i_u), \mu_u^{Z})|^2 \diff u\right)^{\frac{1}{2}}\right]\\ 
  & \le \mathbb{E}\left[\left(\sup_{t\in [0,T]}|E^N_{t \wedge \tau}|^{2p}C^2\int_0^{T \wedge \tau} |E^N_{u}|^{2p-2}|\sigma(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\sigma(u,(X_u^{i},V^i_u), \mu_u^{Z})|^2 \diff u\right)^{\frac{1}{2}}\right]\\ 
  &\le \frac{1}{2}\mathbb{E}\left[\sup_{t\in [0,T]}|E^N_{t \wedge \tau}|^{2p}\right]+\frac{1}{2}C^2\mathbb{E}\left[\int_0^{T \wedge \tau} |E^N_{u}|^{2p-2}|\sigma(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\sigma(u,(X_u^{i},V^i_u), \mu_u^{Z})|^2 \diff u\right],\\ 
\end{split}
\end{equation}
which follows from the arithmetic and geometric mean (AM--GM) inequality. It is left to find a bound for the last term in equation \eqref{propsplit1}.
%Let
%\begin{equation*}
%  \tilde{\sigma}(t,x,\nu):= \sigma_{\text{Dup}}(t,e^{x})\frac{\sqrt{\mathbb{E}^{\nu}[K(\frac{X-x}{\epsilon})]+ \delta}}{\sqrt{\mathbb{E}^{\nu}[V K(\frac{X-x}{\epsilon})]+\delta}},\, \text{ so that }\, \sigma(t,(x,v),\nu) := \sqrt{v} \tilde{\sigma}(t,x,\nu).   
%\end{equation*}
%It follows from Proposition 1 in \cite{ReiTsi}, adapted to system \eqref{sde}, that under Assumption \ref{A3}, $\tilde{\sigma}(t,x,\nu)$ is Lipschitz in the space and measure components. Let $L_{\tilde{\sigma}}$ denote its Lipschitz constant. We use this result to get
\begin{equation*}
\begin{split}
& \mathbb{E}\left[\int_0^{T \wedge \tau}|E^N_{u}|^{2p-2}\lvert\sigma(u,(X_u^{i,N},V^i_u), \mu_u^{Z^N})-\sigma(u,(X_u^{i},V^i_u), \mu_u^{Z})\lvert^2 \diff u\right]\\
 &= \mathbb{E}\left[\int_0^{T \wedge \tau}|E^N_{u}|^{2p-2}V^i_u\lvert\tilde{\sigma}(u,X_u^{i,N}, \mu_u^{Z^N})-\tilde{\sigma}(u,X_u^{i}, \mu_u^{Z})\lvert^2 \diff u\right]\\
 &\le L_{\tilde{\sigma}}^2 \mathbb{E}\left[\int_0^{T \wedge \tau}|E^N_{u}|^{2p-2}V^i_u \big(|E^N_{u}| + \mathcal{W}_2(\mu_u^{Z^N},\mu_u^{Z}) \big)^2 \diff u\right]\\
&\le T_2:= L_{\tilde{\sigma}}^2 \mathbb{E}\left[\int_0^{T \wedge \tau}|E^N_{u}|^{2p-2}V^i_u \big(2|E^N_{u}|^2 + 4\mathcal{W}^2_2(\mu_u^{Z^N},\mu_u^{N}) + 4\mathcal{W}^2_2(\mu_u^{N},\mu_u^{Z}) \big) \diff u\right],\\
\end{split}
\end{equation*}
where $\mu_u^{N}$ is the empirical measure of $Z^{i}_u$ as above. Recall the definition of process $g^i$ in \eqref{g}. We then have for $C$ a positive constant that depends on $p$ and is of order $L_{\tilde{\sigma}}^2$,
\begin{equation*}
    \begin{split}
        &T_2 := L_{\tilde{\sigma}}^2 \mathbb{E}\left[\int_0^{T \wedge \tau}|E^N_{u}|^{2p-2}\big(2|E^N_{u}|^2 + 4\mathcal{W}^2_2(\mu_u^{Z^N},\mu_u^{N}) + 4\mathcal{W}^2_2(\mu_u^{N},\mu_u^{Z}) \big) \diff g^i(u)\right]\\
        & \le C \mathbb{E}\left[\int_0^{T \wedge \tau}\big(|E^N_{u}|^{2p} +|E^N_{u}|^{2p-2}\mathcal{W}^2_2(\mu_u^{Z^N},\mu_u^{N}) + |E^N_{u}|^{2p-2}\mathcal{W}^2_2(\mu_u^{N},\mu_u^{Z}) \big) \diff g^i(u)\right]\\
        & \le C \mathbb{E}\left[\int_0^{T \wedge \tau}\Big(|E^N_{u}|^{2p}+\frac{2(p-1)}{p}|E^N_u|^{2p}+\frac{1}{p}\mathcal{W}^{2p}_{2}(\mu_u^{Z^N}, \mu_u^{N})+\frac{1}{p}\mathcal{W}^{2p}_{2}(\mu_u^{N}, \mu_u^{Z}) \Big) \diff g^i(u)\right]\\
        & \le C \mathbb{E}\left[\int_0^{T \wedge \tau}\Big(|E^N_{u}|^{2p}+N^{-1}\sum_{j=1}^N |X^{j,N}_u-X^{j}_u|^{2p}+\mathcal{W}^{2p}_{2}(\mu_u^{N}, \mu_u^{Z}) \Big) \diff g^i(u)\right]\\
        & \le C \mathbb{E}\left[\int_0^{T \wedge \tau}\left(\sup_{t\in[0,u]}|E^N_{t}|^{2p}+N^{-1}\sum_{j=1}^N \sup_{t\in[0,u]}|X^{j,N}_t-X^{j}_t|^{2p}+\mathcal{W}^{2p}_{2}(\mu_u^{N}, \mu_u^{Z}) \right) \diff g^i(u)\right]\\
        & \le T_3 := C \mathbb{E}\left[\int_0^{T \wedge \tau}\left(\sup_{t\in[0,T]}|E^N_{t \wedge u}|^{2p}+N^{-1}\sum_{j=1}^N \sup_{t\in[0,T]}|X^{j,N}_{t\wedge u}-X^{j}_{t\wedge u}|^{2p}+\mathcal{W}^{2p}_{2}(\mu_{u}^{N}, \mu_{ u}^{Z}) \right) \diff g^i(u)\right].\\
    \end{split}
\end{equation*}
Note that by exchangeability, 
\begin{equation*} 
  \mathbb{E}\left[N^{-1}\sum_{j=1}^N \sup_{t\in[0,T]}|X^{j,N}_{t\wedge u}-X^{j}_{t\wedge u}|^{2p}\right] = \mathbb{E}\left[\sup_{t\in[0,T]}|X^{j,N}_{t\wedge u}-X^{j}_{t\wedge u}|^{2p}\right]= \mathbb{E}\left[\sup_{t\in[0,T]}|E^N_{t\wedge u}|^{2p} \right].
\end{equation*}
Adopting a technique from \cite{BerBosDio} and \cite{CozRei2}, we let $\tau^i_{\omega}$ be a stopping time such that $\tau^i_{\omega}:= \inf\{t\ge 0 \, \lvert \, g^i(t) \ge \omega\}$, for any $\omega \ge 0$ and $\tau^i_0 = 0$. It holds that $g^i(\tau^i_{\omega}) = \omega$ and $g^i(T \wedge \tau^i_{\omega}) = g^i(T)\wedge g^i(\tau^i_{\omega}) = g^i(T)\wedge \omega$.
\bigbreak
We now fix $\omega >0$, set $\tau = \tau^i_{\omega}$, and consider a stochastic time change $s= g^i(u)$ so that $u = \tau^i_s$. Notice that $s$ also depends on $i$. From now on, we drop the superscript $i$ from $\tau^i_{\cdot}$ and $g^i(\cdot)$ for ease of notation. Applying the Lebesgue's change of time formula and Fubini's theorem gives
\begin{equation}\label{propsplit3}
\begin{split}
T_1 +T_3 &\le C \mathbb{E}\left[\int_0^{g(T) \wedge \omega}\left(\sup_{t\in[0,T]}|E^N_{t \wedge {\tau}_s}|^{2p}+\mathcal{W}^{2p}_{2}(\mu_{{\tau}_s}^{N}, \mu_{ {\tau}_s}^{Z}) \right) \diff s\right]\\
& \le C \int_0^{\omega}\left(\mathbb{E}\left[\sup_{t\in[0,T]}|E^N_{t \wedge {\tau}_s}|^{2p}\right]+\mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{{\tau}_s}^{N}, \mu_{ {\tau}_s}^{Z}) \right]\right) \diff s.\\
\end{split}
\end{equation}
Putting equations \eqref{propsplit1}, \eqref{propsplit2}, and \eqref{propsplit3} together we have
\begin{equation}\label{propsplit4}
    \begin{split}
        &\mathbb{E}\left[\sup_{t\in[0,T]} |E^N_{t \wedge \tau_{\omega}}|^{2p}\right] \le C \int_0^{\omega}\mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{{\tau}_s}^{N}, \mu_{ {\tau}_s}^{Z}) \right]\diff s +C\int_0^{\omega}\mathbb{E}\left[\sup_{t\in[0,T]}|E^N_{t \wedge {\tau}_s}|^{2p}\right]\diff s.\\ 
        \end{split}
\end{equation}
It follows by Gr\"{o}nwall's inequality that for $\omega >0$,
\begin{equation}\label{gronwalls1}
  \mathbb{E}\left[\sup_{t\in[0,T]} |E^N_{t \wedge \tau_{\omega}}|^{2p}\right] \le   C  e^{C\omega}\int_0^{\omega}\mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{{\tau}_s}^{N}, \mu_{ {\tau}_s}^{Z}) \right]\diff s.
  %\le \omega Ce^{\omega}\tilde{C},
\end{equation}
%where we use that $\mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{{\tau}_s}^{N}, \mu_{ {\tau}_s}^{Z}) \right] \le \tilde{C}$, for $\tilde{C}$ a constant, which 
By Lemma 1.9 in \cite{Carmona} we have that $\mathcal{W}^{2}_{2}(\mu_{{\tau}_s}^{N}, \mu_{ {\tau}_s}^{Z})$ converges to $0$ as $N\to \infty$ almost surely. Building on this result and by the estimate in Lemma \ref{aprioriestimates}, the sequence $\left(\mathcal{W}^{2p}_{2}(\mu_{{\tau}_s}^{N}, \mu_{ {\tau}_s}^{Z})\right)_{N \ge 1}$ of random variables is uniformly integrable and $\mathcal{W}^{2p}_{2}(\mu_{{\tau}_s}^{N}, \mu_{ {\tau}_s}^{Z})$ converges to $0$ almost surely for $\tau_s <T^*$. By the Vitali convergence theorem, the convergence also holds in the sense of $L^1$. We therefore conclude that for all $\tau_s <T^*$, 

\begin{equation}\label{Wassbound3}
\underset{N \to \infty}{\lim}\mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{{\tau}_s}^{N}, \mu_{ {\tau}_s}^{Z}) \right]=0.
\end{equation}
Let $u = \tau_{\omega}$ for ease of notation. Therefore, by taking limits in \eqref{gronwalls1} and applying Fubini's theorem, we get that for all $u < T^*$:
\begin{equation}\label{gronwalls2}
 \underset{N\to \infty}{\lim} \mathbb{E}\left[\sup_{t\in[0,T]} |E^N_{t \wedge u}|^{2p}\right] \le C \sup_{k \in [0,u]} \underset{N\to \infty}{\lim}\mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{k}^{N}, \mu_{k}^{Z}) \right] =0.
\end{equation}


\noindent Following similar steps as above for $|E^N_{t \wedge \tau}|^{2}$ and setting $\tau = T$ gives
\begin{equation}\label{propsplit4}
    \begin{split}
        &\mathbb{E}\left[\sup_{t\in[0,T]} |E^N_{t}|^{2}\right] \le C \mathbb{E}\left[\int_0^{T}\Big(\sup_{t\in[0,T]}|E^N_{t \wedge u}|^{2}+N^{-1}\sum_{j=1}^N \sup_{t\in[0,T]}|X^{j,N}_{t\wedge u}-X^{j}_{t\wedge u}|^{2}+\mathcal{W}^{2}_{2}(\mu_{u}^{N}, \mu_{u}^{Z}) \Big) \diff g(u)\right]\\
        &\le C \mathbb{E}\left[\int_0^{T}\Big(\sup_{t\in[0,T]}|E^N_{t \wedge u}|^{2}+N^{-1}\sum_{j=1}^N \sup_{t\in[0,T]}|X^{j,N}_{t\wedge u}-X^{j}_{t\wedge u}|^{2}+\mathcal{W}^{2}_{2}(\mu_{u}^{N}, \mu_{u}^{Z}) \Big) V^i_u\diff u\right]\\
        & \le C \int_0^{T} \mathbb{E}\left[ \left(\sup_{t\in[0,T]}|E^N_{t \wedge u}|^{2}+N^{-1}\sum_{j=1}^N \sup_{t\in[0,T]}|X^{j,N}_{t\wedge u}-X^{j}_{t\wedge u}|^{2} +\mathcal{W}^{2}_{2}(\mu_{u}^{N}, \mu_{u}^{Z}) \right) V^i_u \right]\diff u\\
        & \le C \int_0^{T} \mathbb{E}\left[ V^i_u\left(\sup_{t\in[0,T]}|E^N_{t \wedge u}|^{2}\right)\right] + \mathbb{E}\left[V^i_u N^{-1}\sum_{j=1}^N \sup_{t\in[0,T]}|X^{j,N}_{t\wedge u}-X^{j}_{t\wedge u}|^{2}\right] +\mathbb{E}\left[ V^i_u\mathcal{W}^{2}_{2}(\mu_{u}^{N}, \mu_{u}^{Z})\right]\diff u\\
        &\le C \int_0^{T} \mathbb{E}\left[ \sup_{t\in[0,T]}|E^N_{t \wedge u}|^{2p}\right]^{\frac{1}{p}}\mathbb{E}\left[{V^i_u}^{\frac{p}{p-1}} \right]^{\frac{p-1}{p}}+\mathbb{E}\left[N^{-1}\sum_{j=1}^N \sup_{t\in[0,T]}|X^{j,N}_{t\wedge u}-X^{j}_{t\wedge u}|^{2p} \right]^{\frac{1}{p}}  \mathbb{E}\left[{V^i_u}^{\frac{p}{p-1}} \right]^{\frac{p-1}{p}} \diff u\\ 
        &+C \int_0^{T} \mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_u^{N}, \mu_u^{Z})\right]^{\frac{1}{p}}\mathbb{E}\left[{V^i_u}^{\frac{p}{p-1}} \right]^{\frac{p-1}{p}}\diff u\\
        &\le C \int_0^{T}\left(\mathbb{E}\left[ \sup_{t\in[0,T]}|E^N_{t \wedge u}|^{2p}\right]^{\frac{1}{p}} + \mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{u}^{N}, \mu_{u}^{Z})\right]^{\frac{1}{p}}\right) \mathbb{E}\left[{V^i_u}^{\frac{p}{p-1}} \right]^{\frac{p-1}{p}} \diff u\\
        &= C \sup_{t\in [0,T]}\mathbb{E}\left[{V^i_t}^{\frac{p}{p-1}} \right]^{\frac{p-1}{p}}\int_0^{T}\left(\mathbb{E}\left[ \sup_{t\in[0,T]}|E^N_{t \wedge u}|^{2p}\right]^{\frac{1}{p}} + \mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{u}^{N}, \mu_{u}^{Z})\right]^{\frac{1}{p}}\right)  \diff u.\\
\end{split}
\end{equation}
By Lemma \ref{momentboundvol}, we know that $\underset{t\in [0,T]}{\sup}\mathbb{E}\left[{V^i_t}^{\frac{p}{p-1}} \right]^{\frac{p-1}{p}}$ is finite. Taking the limit $N\to \infty $ on both sides and applying Fubini's theorem gives
\begin{equation}\label{propchaoslast}
\begin{split}
&\lim_{N \to \infty} \mathbb{E}\left[\sup_{t\in[0,T]} |E^N_{t}|^{2}\right]\\
&\le C \sup_{t\in[0,T]}\mathbb{E}\left[{V^i_t}^{\frac{p}{p-1}} \right]^{\frac{p-1}{p}} \int_0^{T}\lim_{N \to \infty}\mathbb{E}\left[ \sup_{t\in[0,T]}|E^N_{t \wedge u}|^{2p}\right]^{\frac{1}{p}}+ \lim_{N \to \infty}\mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{u}^{N}, \mu_{u}^{Z})\right]^{\frac{1}{p}}\diff u \\ 
& \le C T \sup_{t\in[0,T]}\mathbb{E}\left[{V^i_t}^{\frac{p}{p-1}} \right]^{\frac{p-1}{p}} \sup_{k \in[0,T]}\left(\lim_{N \to \infty}\mathbb{E}\left[ \sup_{t\in[0,T]}|E^N_{t \wedge k}|^{2p}\right]^{\frac{1}{p}} + \lim_{N \to \infty}\mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{k}^{N}, \mu_{k}^{Z})\right]^{\frac{1}{p}} \right).\\
\end{split}
\end{equation}
By \eqref{Wassbound3} and \eqref{gronwalls2}, $\underset{k \in[0,T]}{\sup} \underset{N \to \infty}{\lim}\mathbb{E}\left[\mathcal{W}^{2p}_{2}(\mu_{k}^{N}, \mu_{k}^{Z})\right]^{\frac{1}{p}} $ and $\underset{k \in[0,T]}{\sup} \underset{N \to \infty}{\lim}\mathbb{E}\left[ \underset{t \in[0,T]}{\sup}|E^N_{t \wedge k}|^{2p}\right]^{\frac{1}{p}} $are both equal to $0$, and therefore so is the RHS of equation \eqref{propchaoslast}. This concludes the proof.
\bigbreak

\end{proof}
\end{subsection}
\section{Time-discretisation scheme}\label{timediscretisation}
To simulate the particle system \eqref{particlessystem} on $[0,T]$, we consider a time--grid with $M$ uniform time-steps of width $\Delta t = T/M$, and use the classical Euler--Maruyama (EM) scheme for the state process $X$, and a full--truncation Euler (FTE) scheme for the squared volatility process $V$.\bigbreak

\noindent Let $\{t_0=0,t_1,t_2, ... ,t_M=T\}$ denote the time discretisation of $[0,T]$ so that $t_m = m\Delta t$, and for $m \in \{0,1,...,M-1\}$,
\begin{equation} \label{EM}
\begin{split}
&\hat{X}^{i,N}_{t_{m+1}} = \hat{X}^{i,N}_{t_{m}}+ \beta(t_m,(\hat{X}^{i,N}_{t_m},\hat{V}^{i,+}_{t_m}),\mu_{t_m}^{\hat{Z}^N})\Delta t+\sigma(t_m,(\hat{X}^{i,N}_{t_m},\hat{V}^{i,+}_{t_m}),\mu_{t_{m}}^{\hat{Z}^N})\Delta W^{x,i}_{t_m}, \, \hat{X}^{i,N}_{0} = X^i_0,\\
&\hat{V}^{i}_{t_{m+1}} = \hat{V}^{i}_{t_{m}} + k(\theta -\hat{V}^{i,\!+}_{t_{m}})\Delta t+ \xi\sqrt{\hat{V}^{i,\!+}_{t_{m}}} \Delta W^{v}_{t_m},\, \hat{V}^{i}_{0} = V^i_0,\\
\end{split}
\end{equation}
where $\Delta W^{\cdot,i}_{t_m}=(W^{\cdot,i}_{t_{m+1}}-W^{\cdot,i}_{t_m})\sim N(0,\Delta t)$, increments $\Delta W^{x,i}_{t_m}, \Delta W^{v,i}_{t_m}$ have correlation $\rho$, and $\hat{V}^{i,\!+}_{t_m} = \text{max}(\hat{V}^{i}_{t_m},0)$ for all particles $i \in \{1,...,N\}$.\bigbreak
