\noindent To show the convergence of the approximated log-spot process, we use the following established results for the full truncation Euler discretised squared volatility process.

\begin{subsection}{The full truncation Euler (FTE) scheme}
\begin{lemma}
    The FTE scheme has uniformly bounded moments so that for $\tilde{V}^{i}_{t}$ as in \eqref{continuoustimehlsv}, 
    \begin{equation*}
        \mathbb{E}\left[ \sup_{t\in [0,T]}|\tilde{V}^{i}_{t}|^p \right] < \infty,\, \forall p\ge 1,\, i \in \{1,...,N\}, \, \, M\ge 1.
    \end{equation*}
\end{lemma} 
%{\color{red} \fbox{What's differnt from CozMarRei?}}
\begin{proof}
    The proof follows by Proposition 3.7 in \cite{CozMarRei}, together with applying the Burkholder--Davis--Gundy inequality.
\end{proof}
The following proposition, previously established, demonstrates the strong convergence of the discretised volatility process in $L^p$.
\begin{proposition}{(Theorem 1.1 in \cite{CozRei})}\label{convdiscretisedvol}
    Assume that $\nu >3$ and let $2 \le p < \nu-1$. Let ${V}^i_{t}$ be the solution to % the squared volatility process
 \eqref{volparticles} and $\hat{V}^{i,N}_{t}$ the solution to 
%the FTE discretised process 
\eqref{piecewiseconstvol}. Then there exist $M_0 \in \mathbb{N}$ and a positive constant $C>0$ such that $\forall \, i \in \{1,...,N\}, \, M > M_0$, 
    \begin{equation*}
       \sup_{t\in [0,T]} \mathbb{E}[|{V}^{i}_{t}-\hat{V}^{i}_{t}|^p]^{\frac{1}{p}}\le CM^{-\frac{1}{2}},
    \end{equation*}
    i.e., the discretised process converges strongly with order $1/2$ in $L^p$.
\end{proposition}
\end{subsection}
\begin{subsection}{Strong convergence of Euler--Maruyama (EM) scheme}

We are now well-equipped to demonstrate the strong convergence of the discretised log-spot process in $L^2$, achieving a rate of $1/2$ in time, up to a logarithmic factor. Our proof builds on ideas from Theorem 2.2 and Lemma 3.4 in \cite{BerBosDio}, as well as Proposition 4.3 in \cite{CozRei2}. While the aforementioned works also address non-Lipschitz diffusion coefficients, our setting poses an additional challenge due to the law dependence of the coefficients.

\begin{theorem}\label{hlsvEM}
    Let $X^{i,N}$ be the solution to the particle system (\ref{particlessystem}) and $\hat{X}^{i,N}$ its approximation (\ref{continuoustimehlsv}). Furthermore, suppose that $X^{i}_0 \in L^2(\mathbb{R})$ and $\nu >{\nu}^* = 2 + \sqrt{3}$. Under Assumption \ref{A3}, we have that for all $T< T^*$ and $M >M_0$,
    \begin{equation*}
        \underset{i\in \{1,..., N\}}{\sup}\mathbb{E}\left[\sup_{t\in[0,T]}|X^{i,N}_t-\hat{X}^{i,N}_t|^2 \right]^{1/2} \le C \sqrt{\log(2M)}M^{-\frac{1}{2}},
    \end{equation*}
for a positive constant $C$.
\end{theorem}

\begin{proof}
For fixed $i$, let $E^i_t := X^{i,N}_t-\hat{X}^{i,N}_t$, $E^i_0 = 0$ and $\Delta {X}^{i,N}_t := {X}^{i,N}_t-{X}^{i,N}_{t'}$. To simplify the notation, we drop the superscript $i$ from $E^i_t$ from now on.  We apply It\^{o}'s formula to $|E_{t \wedge \tau}|^{2p}$, where $\tau$ is a stopping time and  $1<p< \frac{\nu^2 - \nu}{3\nu -1}$, to get that
  \begin{equation*}
  \begin{split}
     |E_{t \wedge \tau}|^{2p} &= {2p}\int_0^{t \wedge \tau} |E_u|^{2p-1}\text{sgn}(E_u)\big(\beta(u,(X^{i,N}_u,V^i_u),\mu_u^{Z^N}) - \beta(u',(\hat{X}^{i,N}_{u'},\hat{V}^{i}_{u} ),\mu_{u'}^{\hat{Z}^{N}})\big)\diff u\\
     &+2p\int_0^{t \wedge \tau} |E_u|^{2p-1}\text{sgn}(E_u)\left(\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})\right)\diff W^{x,i}_u\\  
     &+\frac{1}{2}2p(2p-1)\int_0^{t \wedge \tau} |E_u|^{2p-2}\left(\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})\right)^2\diff u,\\  
  \end{split}
\end{equation*}
where $\text{sgn}(E)=1$ if $E>0$, and $\text{sgn}(E)=-1$ otherwise.\newline
Taking the supremum over time (noting that the supremum value of the integrals over time is at $t=T$) and expectations on both sides, we get 
  \begin{equation}\label{error1}
  \begin{split}
     \mathbb{E}&\left[\sup_{t\in[0,T]}|E_{t \wedge \tau}|^{2p}\right] = 2p\mathbb{E}\Bigg[\int_0^{T \wedge \tau} |E_u|^{2p-1}|\beta(u,(X^{i,N}_u,V^i_u),\mu_u^{Z^N}) - \beta(u',(\hat{X}^{i,N}_{u'},\hat{V}^{i}_{u} ),\mu_{u'}^{\hat{Z}^{N}})|\diff u\Bigg]\\
     &+2p\mathbb{E}\left[\sup_{t\in[0,T]}\int_0^{t \wedge \tau} |E_u|^{2p-1}\text{sgn}(E_u)\left(\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})\right)\diff W^{x,i}_u\right]\\  
     &+\frac{1}{2}2p(2p-1)\mathbb{E}\left[\int_0^{T \wedge \tau} |E_u|^{2p-2} |\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})|^2\diff u\right].\\  
  \end{split}
\end{equation}
We now bound each term above separately. Looking at the second term, to remove the stochastic integral we apply the BDG inequality to get that for $C_p>0$,
\begin{equation}\label{subst1}
\begin{split}
    &2p\mathbb{E}\left[\sup_{t\in[0,T]}\int_0^{t \wedge \tau} |E_u|^{2p-1}\text{sgn}(E_u)\left(\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})\right)\diff W^{x,i}_u\right]\\
    &\le C_p\mathbb{E}\left[\left(\int_0^{T \wedge \tau}|E_u|^{2(2p-1)}|\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})|^2\diff u \right)^{1/2}\right]\\
    &\le \mathbb{E}\left[\left(\sup_{t\in[0,T]}|E_{t\wedge \tau}|^{2p} C_p^2\int_0^{T \wedge \tau}|E_u|^{2p-2}|\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})|^2\diff u \right)^{1/2}\right]\\
 &\le \frac{1}{2}\mathbb{E}\left[\sup_{t\in[0,T]}|E_{t \wedge \tau}|^{2p}\right] + \frac{1}{2}C_p^2\mathbb{E}\left[\int_0^{T \wedge \tau}|E_u|^{2p-2}|\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})|^2\diff u \right],\\
\end{split}
\end{equation}
where the last step follows from the AM--GM inequality. We now treat the first term in \eqref{error1}. 
\begin{equation*}
  \begin{split}
     \Lambda_1 &:= \mathbb{E}\Bigg[\int_0^{T\wedge\tau} |E_u|^{2p-1}|\beta(u,(X^{i,N}_u,V^i_u),\mu_u^{Z^N}) - \beta(u',(\hat{X}^{i,N}_{u'},\hat{V}^{i}_{u} ),\mu_{u'}^{\hat{Z}^{N}})|\diff u\Bigg]\\
     &\le \mathbb{E}\Bigg[\int_0^{T\wedge\tau} |E_u|^{2p-1}V^i_u|\tilde{\beta}(u,X^{i,N}_u,\mu_u^{Z^N}) - \tilde{\beta}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})| + \tilde{\beta}_{\max}|E_u|^{2p-1}|V^i_u-\hat{V}^{i}_{u}|\diff u\Bigg]\\
     &\le \mathbb{E}\Bigg[\int_0^{T\wedge\tau}L_{\tilde{\beta}} |E_u|^{2p-1}V^i_u\left(|u-u'|^{1/2}+|X^{i,N}_u-\hat{X}^{i,N}_{u'}|+\mathcal{W}_2(\mu_u^{Z^N},\mu_{u'}^{\hat{Z}^{N}})\right)\\
     & + \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad +\tilde{\beta}_{\max}|E_u|^{2p-1}|V^i_u-\hat{V}^{i}_{u}|\diff u\Bigg]\\
     &\le \mathbb{E}\Bigg[\int_0^{T\wedge\tau}L_{\tilde{\beta}} |E_u|^{2p-1}V^i_u\left(|u-u'|^{1/2}+|\Delta X^{i,N}_u|+|E_{u'}|+\mathcal{W}_2(\mu_u^{Z^N},\mu_{u'}^{\hat{Z}^{N}})\right)+\\
     & \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad \quad +\tilde{\beta}_{\max}|E_u|^{2p-1}|V^i_u-\hat{V}^{i}_{u}|\diff u\Bigg].\\
  \end{split}
\end{equation*}
Applying Young's inequality, we get the following bounds
\begin{equation}
\begin{split}
    |E_u|^{2p-1}V^i_u|u-u'|^{1/2} &\le \frac{2p-1}{2p}|E_u|^{2p}+\frac{1}{2p}{V^i_u}^{2p}|u-u'|^{p},\\
    |E_u|^{2p-1}V^i_u|\Delta {X}^{i,N}_u|&\le \frac{2p-1}{2p}|E_u|^{2p}+\frac{1}{2p}{V^i_u}^{2p}|\Delta {X}^{i,N}_u|^{2p},\\
    \tilde{\beta}_{\max}|E_u|^{2p-1}|V^{i}_u-\hat{V}^{i}_u|&\le \frac{2p-1}{2p}|E_u|^{2p}+\frac{1}{2p}\tilde{\beta}_{\max}^{2p}|V^{i}_u-\hat{V}^{i}_u|^{2p},\\
    |E_u|^{2p-1}V^i_u\mathcal{W}_2(\mu_u^{Z^N},\mu_{u'}^{\hat{Z}^{N}})&\le \frac{2p-1}{2p}|E_u|^{2p}+\frac{1}{2p}{V^i_u}^{2p}\mathcal{W}_2(\mu_u^{Z^N},\mu_{u'}^{\hat{Z}^{N}})^{2p}\\
    &\le \frac{2p-1}{2p}|E_u|^{2p}+\frac{1}{2p}{V^i_u}^{2p}\Big(\mathbb{E}\left[|X^{i,N}_u-\hat{X}^{i,N}_{u'}|^2+|V^{i}_u-\hat{V}^{i}_u|^2 \right]\Big)^{p},\\
\end{split}
\end{equation}
which follows by the definition of the Wasserstein metric. Further, we have that
\begin{equation}\label{Wassbound1}
\begin{split}
 |X^{i,N}_u-\hat{X}^{i,N}_{u'}|^2+|V^{i}_u-\hat{V}^{i}_u|^2 &\le 2|E_{u'}|^2+2|\Delta X^{i,N}_u|^2+|V^{i}_u-\hat{V}^{i}_u|^2\\
 &\le 3^{\frac{p-1}{p}}\Big(2^p|E_{u'}|^{2p}+2^p|\Delta X^{i,N}_u|^{2p}+|V^{i}_u-\hat{V}^{i}_u|^{2p}\Big)^{\frac{1}{p}},\\
\end{split}
\end{equation}
where we applied H\"{o}lder's inequality for $p>1$ in the second step. Taking the expectation on both sides and applying H\"{o}lder's inequality for $p>1$ once again, we get that
\begin{equation*}
\begin{split}
 \mathbb{E}\left[|X^{i,N}_u-\hat{X}^{i,N}_{u'}|^2+|V^{i}_u-\hat{V}^{i}_u|^2\right] & \le \mathbb{E}\left[\big(|X^{i,N}_u-\hat{X}^{i,N}_{u'}|^2+|V^{i}_u-\hat{V}^{i}_u|^2\big)^{p}\right]^{\frac{1}{p}}\\
 &\le 3^{p-1}\mathbb{E}\left[2^p|E_{u'}|^{2p}+2^p|\Delta X^{i,N}_u|^{2p}+|V^{i}_u-\hat{V}^{i}_u|^{2p}\right]^{\frac{1}{p}}.\\
\end{split}
\end{equation*}
Finally, raising both sides to the power of $p$ we get that
\begin{equation}\label{Wassbound2}
 \Big(\mathbb{E}\left[|X^{i,N}_u-\hat{X}^{i,N}_{u'}|^2+|V^{i}_u-\hat{V}^{i}_u|^2\right]\Big)^p\le 3^{p(p-1)}\mathbb{E}\left[2^p|E_{u'}|^{2p}+2^p|\Delta X^{i,N}_u|^{2p}+|V^{i}_u-\hat{V}^{i}_u|^{2p}\right].
\end{equation}
We now use Fubini's theorem and the fact that 
\begin{equation*}
    |E_{u'}| \le \sup_{t\in [0,u]}|E_{t}|, \text{\, \,} \mathbb{E}[|E_{u'}|^2]\le \mathbb{E}[\sup_{t\in [0,u]}|E_{t}|^2]\text{\, and \,} \mathbb{E}[|V^{i}_u-\hat{V}^{i}_u|^2] \le \sup_{t\in[0,u]}\mathbb{E}[|V^{i}_t-\hat{V}^{i}_t|^2],
\end{equation*} to get

\begin{equation*}
  \begin{split}
     &\Lambda_1 \le \mathbb{E}\int_0^{T\wedge\tau} \frac{2p-1}{2p}(4L_{\tilde{\beta}}+1)|E_u|^{2p}+\frac{L_{\tilde{\beta}}}{2p}V^i_u|E_{u'}|^{2p} +\frac{L_{\tilde{\beta}}}{2p}{V^i_u}^{2p}|u-u'|^{p} + \frac{L_{\tilde{\beta}}}{2p}{V^i_u}^{2p} |\Delta X^{i,N}_u|^{2p} \\
     &+ L_{\tilde{\beta}} \frac{3^{p(p-1)}}{2p}{V^i_u}^{2p} \mathbb{E}\left[2^p |E_{u'}|^{2p} + 2^{p}|\Delta X^{i,N}_u|^{2p}+|V^i_u - \hat{V}^i_u|^{2p}\right] + \frac{1}{2p}\tilde{\beta}^{2p}_{\max}|V^i_u - \hat{V}^i_u|^{2p}\diff u \\ 
     & \le C_{L_{\tilde{\beta}},p} \Bigg(T\Delta t^p \mathbb{E}[\sup_{t \in [0,T]}{V^i_t}^{2p}] + T\mathbb{E}\left[ \sup_{t\in [0,T]} {V^i_t}^{2p} \sup_{t\in [0,T]}|\Delta {X}^{i,N}_t|^{2p} \right] \\
     &+ \mathbb{E}\left[\int_0^{T\wedge\tau} (V^i_u+1)\sup_{t\in [0,u]}|E_t|^{2p}\diff u\right] +T {\tilde{\beta}_{\max}}^{2p} \sup_{t\in [0,T]} \mathbb{E}[|V^i_t - \hat{V}^i_t|^{2p}] \\
     &+T \mathbb{E}\left[ \sup_{t\in [0,T]} {V^i_t}^{2p}\right] \mathbb{E}\left[\sup_{t\in [0,T]}|\Delta {X}^{i,N}_t|^{2p} \right] +T \mathbb{E}\left[ \sup_{t\in [0,T]} {V^i_t}^{2p}\right] \mathbb{E}\left[ \sup_{t\in [0,T]}|V^{i}_t-\hat{V}^{i}_t|^{2p}\right] \\
     &+ \mathbb{E}\left[\sup_{t\in [0,T]}{V^i_t}^{2p}\right] \mathbb{E}\left[\int_0^{T \wedge \tau} \sup_{t\in [0,u]}|E_{t}|^{2p} \diff u\right] \Bigg),\\
    \end{split}
\end{equation*}
where $C_{L_{\tilde{\beta}},p}$ is a positive constant.\newline
By Lemma \ref{momentboundvol}, Proposition \ref{convdiscretisedvol}, and the Cauchy--Schwarz inequality together with Theorem 1 in \cite{FisNap} for the process $X^{i,N}$, we get that for $C>0$,
\begin{equation}\label{bounds}
\begin{split}
&\mathbb{E}\left[ \sup_{t\in [0,T]} {V^i_t}^{2p} \sup_{t\in [0,T]}|\Delta {X}^{i,N}_t|^{2p} \right] \le \mathbb{E}\left[ \sup_{t\in [0,T]} {V^i_t}^{4p}\right]^{\frac{1}{2}} \mathbb{E}\left[ \sup_{t\in [0,T]}|\Delta {X}^{i,N}_t|^{4p} \right]^{\frac{1}{2}} \le C \Big(\frac{\text{log}(2M)}{M}\Big)^p,\\
& \mathbb{E}\left[ \sup_{t\in [0,T]}|\Delta {X}^{i,N}_t|^{2p} \right] \le C \left(\frac{\text{log}(2M)}{M}\right)^p,\\
\end{split}
\end{equation}
so that 
\begin{equation}\label{subst2}
\Lambda_1 \le C\left(M^{-p}+\left(\frac{M}{\text{log}(2M)}\right)^{-p}+ \mathbb{E}\left[\int_0^{T \wedge \tau} \sup_{t\in [0,u]}|E_{t}|^{2p} \big(V^i_u +1 \big)\diff u\right]\right).
\end{equation}
Now, looking at the third term in \eqref{error1} and using similar techniques as above we get 

\begin{equation}\label{secondsplit}
\begin{split}
&\mathbb{E}\left[\int_0^{T \wedge \tau} |E_u|^{2p-2} \left|\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})\right|^2 \diff u\right] \\
&\le 2 \mathbb{E}\Bigg[\int_0^{T \wedge \tau} |E_u|^{2p-2} |\sqrt{V^i_u}|^2 \left|\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})\right|^2 \\
&\quad\quad\quad\quad\quad\quad\quad\quad\quad \quad\quad\quad\quad\quad\quad\quad\quad\quad\quad + |E_u|^{2p-2} \left|\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})\right|^2 \left|\sqrt{V^i_u}-\sqrt{\hat{V}^{i}_u}\right|^2 \diff u \Bigg] \\
&\le 2 \mathbb{E}\Bigg[\int_0^{T \wedge \tau} L_{\tilde{\sigma}}^2 |E_u|^{2p-2} V^i_u \left(|u-u'|^{1/2} + |X^{i,N}_u - \hat{X}^{i,N}_{u'}| + \mathcal{W}_2(\mu_u^{Z^N},\mu_{u'}^{\hat{Z}^{N}})\right)^2 \\
&\quad\quad\quad\quad \quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad+ |E_u|^{2p-2} |\tilde{\sigma}_{\max}|^2 \left|\sqrt{V^i_u} - \sqrt{\hat{V}^{i}_u}\right|^2 \diff u \Bigg] \\
&\le 2 \mathbb{E}\Bigg[\int_0^{T \wedge \tau} L_{\tilde{\sigma}}^2 |E_u|^{2p-2} V^i_u \left(|u-u'|^{1/2} + |E_{u'}| + |\Delta{X}^{i,N}_u| + \mathcal{W}_2(\mu_u^{Z^N},\mu_{u'}^{\hat{Z}^{N}})\right)^2 \\
&\quad\quad\quad\quad\quad\quad\quad\quad \quad\quad\quad\quad \quad\quad\quad\quad\quad\quad\quad\quad \quad\quad\quad\quad+ |E_u|^{2p-2} |\tilde{\sigma}_{\max}|^2 \left|\sqrt{V^i_u} - \sqrt{\hat{V}^{i}_u}\right|^2 \diff u \Bigg] \\
&\le C \mathbb{E}\Bigg[\int_0^{T \wedge \tau} L_{\tilde{\sigma}}^2 |E_u|^{2p-2} V^i_u \left(\Delta t + |E_{u'}|^2 + |\Delta{X}^{i,N}_u|^2 + \mathcal{W}^2_2(\mu_u^{Z^N},\mu_{u'}^{\hat{Z}^{N}})\right) \\
&\quad\quad\quad\quad \quad\quad\quad\quad \quad\quad\quad\quad \quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad + |E_u|^{2p-2} |\tilde{\sigma}_{\max}|^2 \left|\sqrt{V^i_u} - \sqrt{\hat{V}^{i}_u}\right|^2 \diff u \Bigg]. \\
\end{split}
\end{equation}


\noindent We now treat each term in the equation above separately using similar techniques as above. Specifically, we apply Young's inequality to get 
\begin{equation}
\begin{split}
    |E_u|^{2p-2}V^i_u \Delta t &\le \frac{2p-2}{2p}|E_u|^{2p}+\frac{1}{p}{V^i}^p_u \Delta t^p ,\\
    |E_u|^{2p-2}V^i_u |\Delta {X}^{i,N}_u|^2&\le \frac{2p-2}{2p}|E_u|^{2p}+\frac{1}{p}{V^i}^p_u|\Delta {X}^{i,N}_u|^{2p},\\
    |E_u|^{2p-2}V^i_u\mathcal{W}^2_2(\mu_u^{Z^N},\mu_{u'}^{\hat{Z}^{N}})&\le \frac{2p-2}{2p}|E_u|^{2p}+\frac{1}{p}{V^i}^p_u\mathcal{W}^{2p}_{p}(\mu_u^{Z^N},\mu_{u'}^{\hat{Z}^{N}})\\
    &\le \frac{p-1}{p}|E_u|^{2p}+\frac{1}{p}{V^i}^p_u\Big(\mathbb{E}\left[|X^{i,N}_u-\hat{X}^{i,N}_{u'}|^2+|V^{i}_u-\hat{V}^{i}_u|^2 \right]\Big)^{p}\\
    & \le \frac{p-1}{p}|E_u|^{2p} + \frac{3^{p(p-1)}}{p}{V^i}^p_u \mathbb{E}\left[2^p|E_{u'}|^{2p}+2^p|\Delta X^{i,N}_u|^{2p}+|V^{i}_u-\hat{V}^{i}_u|^{2p}\right],\\
\end{split}
\end{equation}
where the last step follows by using bound \eqref{Wassbound2} derived above. Substituting the above bounds back in \eqref{secondsplit} we get 

\begin{equation}\label{fourthsplit}
\begin{split}
&\mathbb{E}\left[\int_0^{T \wedge \tau} |E_u|^{2p-2} \left|\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})\right|^2 \diff u\right]\\
& \le C \mathbb{E}\Bigg[\int_0^{T \wedge \tau}  |E_u|^{2p} + {V^i_u}^p \Delta t^p + V^i_u |E_{u'}|^2 |E_u|^{2p-2} + {V^i_u}^p |\Delta{X}^{i,N}_u|^{2p} \\
& \qquad + {V^i_u}^p \mathbb{E}\Big[2^p|E_{u'}|^{2p} + 2^p|\Delta X^{i,N}_u|^{2p} + |V^i_u - \hat{V}^i_u|^{2p}\Big] + |\tilde{\sigma}_{u'}|^{2p} \left|\sqrt{V^i_u} - \sqrt{\hat{V}^i_u}\right|^{2p} \diff u\Bigg]\\
& \le C \Bigg(T\Delta t^p \mathbb{E}\big[\sup_{t \in [0,T]} {V^i_t}^p\big] 
+ T\mathbb{E}\big[\sup_{t \in [0,T]} {V^i_t}^p \sup_{t \in [0,T]} |\Delta {X}^{i,N}_t|^{2p}\big] \\
& \qquad + \mathbb{E}\Bigg[\int_0^{T \wedge \tau} (V^i_u+1) \sup_{t \in [0,u]} |E_t|^{2p} \diff u\Bigg] 
+ \mathbb{E}\big[\sup_{t \in [0,T]} {V^i_t}^p\big] \mathbb{E}\Bigg[\int_0^{T \wedge \tau} \sup_{t \in [0,u]} |E_t|^{2p} \diff u\Bigg] \\
& \qquad + T \mathbb{E}\big[\sup_{t \in [0,T]} {V^i_t}^p\big] \mathbb{E}\big[\sup_{t \in [0,T]} |\Delta {X}^{i,N}_t|^{2p}\big] 
+ T \mathbb{E}\big[\sup_{t \in [0,T]} {V^i_t}^p\big] \mathbb{E}\big[\sup_{t \in [0,T]} |V^i_t - \hat{V}^i_t|^{2p}\big] \\
& \qquad + T \tilde{\sigma}_{\text{max}}^{2p} \sup_{t \in [0,T]} \mathbb{E}\big[|\sqrt{V^i_t} - \sqrt{\hat{V}^i_t}|^{2p}\big] \Bigg),
\end{split}
\end{equation}
which follows from Fubini's theorem. Using similar arguments as above, see \eqref{bounds}, we get that terms $\mathbb{E}\left[ \underset{t\in [0,T]}{\sup} {V^i_t}^p \underset{t\in [0,T]}{\sup}|\Delta {X}^{i,N}_t|^{2p} \right]$ and $\mathbb{E}\left[ \underset{t\in [0,T]}{\sup}|\Delta {X}^{i,N}_t|^{2p} \right] $ are bounded above by $C \Big(\frac{\text{log}(2M)}{M}\Big)^p$ for $C$ a positive constant.\newline
% Applying Lemma \ref{momentboundvol}, Proposition \ref{convdiscretisedvol}, and the Cauchy--Schwarz inequality together with Theorem 1 in \cite{FisNap} for the process $X^{i,N}$, we get that for $C>0$,
% \begin{equation*}
% \begin{split}
% &\mathbb{E}\left[ \sup_{t\in [0,T]} {V^i_t}^p \sup_{t\in [0,T]}|\Delta {X}^{i,N}_t|^{2p} \right] \le \mathbb{E}\left[ \sup_{t\in [0,T]} {V^i_t}^{2p}\right]^{\frac{1}{2}} \mathbb{E}\left[ \sup_{t\in [0,T]}|\Delta {X}^{i,N}_t|^{4p} \right]^{1/2} \le C \Big(\frac{\text{log}(2M)}{M}\Big)^p,\\
% & \mathbb{E}\left[ \sup_{t\in [0,T]}|\Delta {X}^{i,N}_t|^{2p} \right] \le C \Big(\frac{\text{log}(2M)}{M}\Big)^p.\\
% \end{split}
% \end{equation*}
Also, since $\nu \ge 1$, the squared volatility process has strictly positive paths almost surely, so that we can write 
\begin{equation}
   |\sqrt{V^i_t}-\sqrt{\hat{V}^{i}_t}|^2 \le  {V^i_t}^{-1}|V^i_t-\hat{V}^{i}_t|^2,
\end{equation}
so that by H\"{o}lder's inequality, Lemma \ref{momentboundvol}, and Proposition \ref{convdiscretisedvol}, we have that
\begin{equation}
   \sup_{t \in [0,T]}\mathbb{E}\left[|\sqrt{V^i_t}-\sqrt{\hat{V}^{i}_t}|^{2p} \right]\le \sup_{t \in [0,T]}\mathbb{E}\left[|V^i_t|^{-pr}\right]^{\frac{1}{r}} \sup_{t \in [0,T]}\mathbb{E}\left[|V^i_t-\hat{V}^{i}_t|^{\frac{2pr}{r-1}}\right]^{\frac{r-1}{r}} \le CM^{-p},
\end{equation}
for $r>1$ such that $-pr>- \nu$ and $2 \le \frac{2pr}{r-1} < \nu -1$ that after some algebra are combined to
\begin{equation*}
    \frac{\nu}{\nu-p}<\frac{r}{r-1}<\frac{\nu-1}{2p}.
\end{equation*}
For the above condition to be satisfied, we need to choose $p$ such that $p< \frac{\nu^2 - \nu}{3\nu -1}$. Recall that $p>1$ so that we need $\nu > 2+\sqrt{3}$. Substituting everything back in equation \eqref{fourthsplit}, we get
\begin{equation}\label{subst3}
\begin{split}
 \mathbb{E}&\left[\int_0^{T \wedge \tau} |E_u|^{2p-2} |\sqrt{V^i_u}\tilde{\sigma}(u,X^{i,N}_u,\mu_u^{Z^N}) - \sqrt{\hat{V}^{i}_u}\tilde{\sigma}(u',\hat{X}^{i,N}_{u'},\mu_{u'}^{\hat{Z}^{N}})|^2\diff u\right] \\
 & \le C\left(M^{-p}+\Big(\frac{M}{\text{log}(2M)}\Big)^{-p}+ \mathbb{E}\left[\int_0^{T \wedge \tau} \sup_{t\in [0,u]}|E_{t}|^{2p} \big(V^i_u +1 \big)\diff u\right]\right).
\end{split}
\end{equation}
Substituting bounds \eqref{subst1}, \eqref{subst2}, and \eqref{subst3} back in \eqref{error1} and rearranging, we get that for a positive constant $C$ that only depends on $p, T, \tilde{\beta}_{\max}$ and $\tilde{\sigma}_{\max}$,
\begin{equation}\label{subst4}
    \mathbb{E}\left[\sup_{t\in[0,T]}|E_{t \wedge \tau}|^{2p}\right] \le  C\left(M^{-p}+\Big(\frac{M}{\text{log}(2M)}\Big)^{-p}+ \mathbb{E}\left[\int_0^{T \wedge \tau} \sup_{t\in [0,u]}|E_{t}|^{2p} \big(V^i_u +1 \big)\diff u\right]\right).
\end{equation}
The following steps use ideas from \cite{CozRei2} and \cite{BerBosDio}. First, we consider the strictly increasing stochastic process
\begin{equation}
  g^i(t) := \int_0^t \Big(V^i_u+1\Big) \diff u,
\end{equation}
so that \eqref{subst4} can be written as 
\begin{equation}\label{subst5}
    \mathbb{E}\left[\sup_{t\in[0,T]}|E_{t \wedge \tau}|^{2p}\right] \le  C\left(M^{-p}+\Big(\frac{M}{\text{log}(2M)}\Big)^{-p}+ \mathbb{E}\left[\int_0^{T \wedge \tau} \sup_{t\in [0,T]}|E_{t \wedge u}|^{2p} \diff g^i(u)\right]\right).
\end{equation}
Let ${\tau}_{\omega}$ be a stopping time defined by ${\tau}^i_{\omega}:= \text{inf}\{t\ge 0 \,| \,g^i(t)\ge \omega\}$ for $\omega \ge 0$ with ${\tau}_{0}=0.$\newline
Notice that $g^i(\tau^i_{\omega})=\omega, \, g^i(T\wedge \tau^i_{\omega}) = g^i(T) \wedge g^i(\tau^i_{\omega}) = g^i(T) \wedge \omega ,$ and $\tau^i_{\omega}$ is finite since 
\begin{equation*}
    \tau^i_{\omega} = \omega - \int_0^{\tau^i_{\omega}}V^i_u \diff u \le \omega.
\end{equation*}
We now set $\tau = \tau^i_{\omega}$ for fixed $\omega >0$ in \eqref{subst5} and to simplify the notation, in what follows, we drop the superscript $i$ from $\tau^i_{\cdot}$ and $g^i(\cdot)$. Also, consider the stochastic time-change $s=g(u)$, so that $u = \tau_s$. Applying Lebesgue's change-of-time integral formula we get
\begin{equation*}
\mathbb{E}\left[\int_0^{T \wedge \tau_{\omega}} \sup_{t\in [0,T]}|E_{t \wedge u}|^{2p} \diff g(u)\right] = \mathbb{E}\left[\int_0^{g(T) \wedge \omega} \sup_{t\in [0,T]}|E_{t \wedge \tau_s}|^{2p} \diff s\right] \le \int_0^{\omega} \mathbb{E}\left[ \sup_{t\in [0,T]} |E_{t \wedge \tau_s}|^{2p} \right] \diff s,
\end{equation*}
so that 
\begin{equation*}
\mathbb{E}\left[\sup_{t\in[0,T]}|E_{t \wedge \tau_\omega}|^{2p}\right] \le C\left(\frac{M}{\text{log}(2M)} \right)^{-p}+C\int_0^{\omega} \mathbb{E}\left[ \sup_{t\in [0,T]} |E_{t \wedge \tau_s}|^{2p} \right] \diff s,
\end{equation*}
and by applying Gr\"{o}nwall's inequality we get that for all $\omega>0$ and $p> 1$,
\begin{equation}
\mathbb{E}\left[\sup_{t\in[0,T]}|E_{t \wedge \tau_\omega}|^{2p}\right] \le C e^{C\omega} \left(\frac{M}{\text{log}(2M)} \right)^{-p}. 
\end{equation}
We now take $\tau = T$ in \eqref{subst5} and use similar techniques as above to find
\begin{equation*}
\mathbb{E}\left[\sup_{t\in[0,T]}|E_{t}|^{2}\right] \le C\left(\frac{M}{\text{log}(2M)} \right)^{-1}+C\mathbb{E}\left[ \int_0^{T} \sup_{t\in [0,T]} |E_{t \wedge u}|^{2}  \diff g(u)\right].
\end{equation*}
Using a stochastic time-change as before, together with Fubini's theorem and H\"{o}lder's inequality one gets
\begin{equation*}
\begin{split}
\mathbb{E}\left[ \int_0^{T} \sup_{t\in [0,T]} |E_{t \wedge u}|^{2}  \diff g(u)\right] &\le \int_0^\infty \mathbb{E}\left[  \sup_{t\in [0,T]} |E_{t \wedge \tau_s}|^{2p} \right]^{\frac{1}{p}}   \mathbb{E}\left[ \mathbbm{1}_{s \le g(T)} \right]^{1-\frac{1}{p}} \diff s\\
& \le C \int_0^\infty e^{\frac{Cs}{p}} \left(\frac{M}{\text{log}(2M)} \right)^{-1}   \mathbb{P}\Big( s \le g(T)\Big)^{1-\frac{1}{p}} \diff s.
\end{split}
\end{equation*}
We therefore deduce that
\begin{equation}\label{FinBound} \mathbb{E}\left[\sup_{t\in[0,T]}|E_{t}|^{2}\right] \le C \frac{\text{log}(2M)}{M} \left(1+\int_0^\infty e^{\frac{Cs}{p}} \mathbb{P}\Big( s \le g(T)\Big)^{1-\frac{1}{p}} \diff s \right).
\end{equation}
By Markov's inequality, we have that for $\lambda>\frac{C}{p-1}$,
\begin{equation}\label{MarkIneq}
 \mathbb{P}\Big( s \le g(T)\Big) \le e^{-\lambda s} \mathbb{E}\left[ e^{\lambda g(T)} \right] = e^{-\lambda s} \mathbb{E}\left[ e^{\lambda \int_0^T (V^i_t+1) \diff t} \right].
\end{equation}
Substituting this bound in \eqref{FinBound}, we get that 
\begin{equation}\label{FinBound2} \mathbb{E}\left[\sup_{t\in[0,T]}|E_{t}|^{2}\right] \le C \frac{\text{log}(2M)}{M} \left(1 + \int_0^\infty e^{\frac{Cs}{p}-\lambda s ( 1-\frac{1}{p})} \mathbb{E}\left[ e^{\lambda \int_0^T (V^i_t+1) \diff t} \right]^{1-\frac{1}{p}} \diff s \right).
\end{equation}
By Lemma \ref{ExpIntVol}, we know that for $T<T^*$, the expectation on the right--hand side of equation \eqref{FinBound2} is finite. Also, since $\lambda>\frac{C}{p-1}$,
\begin{equation*}
 \int_0^{\infty}\text{exp}\Big(\frac{Cs}{p}-\lambda s\big(1-\frac{1}{p}\big)\Big) \diff s =  \int_0^{\infty}\text{exp}\Big(-\frac{s}{p}\Big(\lambda(p-1)-C\Big)\Big) \diff s = \frac{p}{\big(\lambda (p-1)-C\big)}.
\end{equation*}
The result follows by substituting the above bound in \eqref{FinBound2}.
\end{proof}

\begin{remark}
The condition on the Feller ratio in Theorem \ref{hlsvEM} may appear restrictive. An alternative approach to ensure positivity of the variance process is to employ an implicit discretisation scheme as proposed in \cite{BriAlf}, which leads to the backward Euler--Maruyama scheme analysed in \cite{Alf} for the CIR process. Retracing the proof of Theorem \ref{hlsvEM} using this implicit scheme instead of the FTE scheme for the variance component shows that we can relax the Feller condition to $\nu > 2$ in that case. For a broader discussion of discretisation schemes for the CIR process, we also refer the reader to \cite{DeeDel} and \cite{ADiop}. We choose to work with the FTE scheme for a representative example here, as it remains one of the most widely used methods in practice due to its favourable properties and low bias, as detailed in \cite{LorKoe}.
\end{remark}
\end{subsection}

\section{Proof of well-posedness of the regularised equations}\label{WellposednessSection}
In this section, we prove Theorem \ref{wellposedness}, the well-posedness of the regularised calibrated dynamics \eqref{independentparticles3}. Recall that this is a McKean--Vlasov SDE with an unbounded $1/2$-H\"{o}lder continuous diffusion coefficient. The primary challenge in this task arises from the non-Lipschitz continuity and the measure dependence of the diffusion coefficient. We first recall the definition of a strong solution for MV SDE \eqref{independentparticles3} on a given probability space $(\Omega, \mathcal{F}, \mathbb{P})$ and with respect to the fixed Brownian motion $W$ and initial condition $\xi$, as stated in, e.g., \cite{CarDel}.

\begin{definition}\label{strongsolndefn}
Process $(X_t)_{t \in [0,T]}$ is a unique strong solution of equation \eqref{independentparticles3} if:
\begin{enumerate}[label=(\roman*)]
\item it is $\mathbb{F}$-adapted and continuous,
\item $\mathbb{P}[X_0 = \xi] = 1$, 
\item $\int_0^T \left(|\beta(t, (X_t, V_t), \mu^Z_t)| + \left\| \sigma(t, (X_t, V_t), \mu^Z_t) \right\|^2\right) \diff t < \infty, \quad \mathbb{P}$--a.s.,
\item for $t \in [0,T]$, 
\begin{equation*}
X(t) = X(0)+ \int_0^t \beta(s, (X_s, V_s), \mu^Z_s) \diff s + \int_0^t \sigma(s, (X_s, V_s), \mu^Z_s) \diff W_s, \quad \mathbb{P}\text{--a.s.}, 
\end{equation*}
\item for another solution $(\tilde{X}_t)_{t \in [0,T]}$ with $\tilde{X}_0 = \xi$, $\mathbb{P}\{{X}_t = \tilde{X}_t \, \, \, \forall \, \, \,  t \in [0,T] \} = 1$.
\end{enumerate}
\end{definition}

