\begin{lemma}[Estimate for a solution]\label{aprioriestimates}
Let Assumptions \ref{A3} hold. Furthermore, assume that $\nu \ge 1$ and $\mathbb{E}[|X_0|^4] < \infty$. Then for $t< T^*$ for $T^*$ as in $\eqref{Tbound}$ and $(X_t)_{t \in [0,T]}$ a solution to \eqref{independentparticles3}, we have that for $n \in \{1,2,3, 4\}$,
%\begin{enumerate}[I.]
\[\mathbb{E}\left[\underset{s \in [0,t]}{\sup}|X_s|^n\right]< \infty.\]
%\item $ \underset{s \in [0,t]}{\sup} \mathbb{E}[e^{c_t|X_s|}] < \infty$, for $0<c_t<c$.
%\end{enumerate}
\end{lemma}

\begin{proof}
%We begin by showing that $\mathbb{E}[\underset{s \in [0,t]}{\sup}|X_s|^n] < \infty$.
Let $2 \le n \le 4$, since the case $n=1$ follows from similar techniques.
Consider $m$ such that $n < m \le 4$ and let $\tau >0$ be a stopping time.
\begin{equation*}
\begin{aligned}
&|X_{s \wedge \tau}|^m \le |X_0|^m + m \int_0^{s \wedge \tau} \langle (X_u)^{m-1}, \beta(u, (X_u, V_u), \mu^Z_u) \rangle \, \diff u \\
&+ m \int_0^{s \wedge \tau} \langle (X_u)^{m-1}, \sigma(u, (X_u, V_u), \mu^Z_u)  \diff W_u \rangle + \frac{m(m-1)}{2} \int_0^{s \wedge \tau} |X_u|^{m-2}|\sigma(u, (X_u, V_u), \mu^Z_u)|^2 \diff u.
\end{aligned}
\end{equation*}
By taking the supremum over time and expectations on both sides, we get

\begin{equation}
\begin{aligned}
&\mathbb{E}\left[\underset{s \in [0,t]}{\sup}|X_{s \wedge \tau}|^m \right] \le \mathbb{E}\left[ |X_0|^m \right] + m \mathbb{E}\left[\int_0^{t \wedge \tau} |X_u|^{m-1}  |\beta(u, (X_u, V_u), \mu^Z_u)|\, \diff u \right] \\
& + m \mathbb{E}\left[\underset{s \in [0,t]}{\sup} \int_0^{s \wedge \tau} \langle (X_u)^{m-1}, \sigma(u, (X_u, V_u), \mu^Z_u)  \diff W_u \rangle \right]\\
& + \frac{m(m-1)}{2} \mathbb{E} \left[\int_0^{t \wedge \tau} |X_u|^{m-2}|\sigma(u, (X_u, V_u), \mu^Z_u)|^2 \diff u \right] \\
&\le \mathbb{E}\left[ |X_0|^m \right] + m{\tilde{\beta}}_{\max}\mathbb{E}\left[\int_0^{t \wedge \tau} |X_u|^{m-1} V_u \, \diff u \right]  + m \beta_0 \mathbb{E}\left[ \left( \int_0^{t \wedge \tau} |X_u|^{2(m-1)} |\sigma(u,(X_u, V_u), \mu^Z_u)|^2  \diff u \right)^{1/2} \right]\\
& + \frac{m(m-1)}{2} {\tilde{\sigma}^2}_{\max}\mathbb{E} \left[\int_0^{t \wedge \tau} |X_u|^{m-2} V_u \diff u \right],
\end{aligned}
\end{equation}
where $\beta_0$ is a constant coming from the application of the Burkholder--Davis--Gundy inequality to the third term of the RHS above.
\begin{equation}\label{split1}
\begin{aligned}
&\mathbb{E}\left[\underset{s \in [0,t]}{\sup}|X_{s \wedge \tau}|^m\right] \le  \mathbb{E}\left[ |X_0|^m \right] + m {\tilde{\beta}}_{\max}\mathbb{E}\left[\int_0^{t \wedge \tau} |X_u|^{m-1} V_u \, \diff u \right]\\
&+ m \beta_0 {\tilde{\sigma}}_{\max} \mathbb{E}\left[ \left( \int_0^{t \wedge \tau}  |X_u|^{2(m-1)} V_u \diff u \right)^{1/2} \right] + \frac{m(m-1)}{2} {\tilde{\sigma}^2}_{\max} \mathbb{E} \left[\int_0^{t \wedge \tau} |X_u|^{m-2} V_u \diff u \right].
\end{aligned}
\end{equation}
Notice that applying Young's inequality to the third term of the RHS above gives
\begin{equation*}
\begin{aligned}
& m \beta_0{\tilde{\sigma}}_{\max} \mathbb{E}\left[ \left( \int_0^{t \wedge \tau}  |X_u|^{2(m-1)} V_u \diff u \right)^{1/2} \right] \le  m \beta_0 {\tilde{\sigma}}_{\max}\mathbb{E}\left[ \underset{s \in [0,t]}{\sup} |X_{s\wedge \tau}|^{m/2}\left( \int_0^{t \wedge \tau}  |X_u|^{m-2} V_u \diff u \right)^{1/2} \right]\\
& \le \frac{1}{2} \mathbb{E}\left[ \underset{s \in [0,t]}{\sup} |X_{s\wedge \tau}|^{m} \right] + \frac{(m \beta_0 {\tilde{\sigma}}_{\max})^2}{2}\mathbb{E}\left[  \int_0^{t \wedge \tau}  |X_u|^{m-2} V_u \diff u  \right].\\
\end{aligned}
\end{equation*}
Substituting back in equation \eqref{split1} and rearranging gives 
\begin{equation*}
\begin{aligned}
&\mathbb{E}\left[\underset{s \in [0,t]}{\sup}|X_{s \wedge \tau}|^m\right] \le  2\mathbb{E}\left[ |X_0|^m \right] + 2m {\tilde{\beta}}_{\max}\mathbb{E}\left[\int_0^{t \wedge \tau} |X_u|^{m-1} V_u \, \diff u \right]\\
&+ \left(m(m-1){\tilde{\sigma}^2}_{\max}+(m \beta_0 {\tilde{\sigma}}_{\max})^2\right)  \mathbb{E} \left[\int_0^{t \wedge \tau} |X_u|^{m-2} V_u \diff u \right]\\
& \le 2\mathbb{E}\left[ |X_0|^m \right] + 2 \gamma(m)  \mathbb{E} \left[\int_0^{t \wedge \tau} \left(|X_u|^{m-2}+|X_u|^{m-1}\right) V_u \diff u \right],
\end{aligned}
\end{equation*}
where $ \gamma(m) :=\max \{2m{\tilde{\beta}}_{\max}, \left(m(m-1){\tilde{\sigma}^2}_{\max}+(m \beta_0 {\tilde{\sigma}}_{\max})^2\right) \}$. Also, note that for all $m > 2$, $|X_u|^{m-2}+|X_u|^{m-1} \le 1+2 |X_u|^{m-1} \le 3+ 2|X_u|^{m} $, so that
\begin{equation*}
\begin{aligned}
&\mathbb{E}\left[\underset{s \in [0,t]}{\sup}|X_{s \wedge \tau}|^m\right] \le 2\mathbb{E}\left[ |X_0|^m \right] + 2 \gamma(m)  \mathbb{E} \left[\int_0^{t \wedge \tau} \left(3+2|X_u|^{m}\right) V_u \diff u \right]\\
& \le 2\mathbb{E}\left[ |X_0|^m \right] + 6\gamma(m) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(m)  \mathbb{E} \left[\int_0^{t \wedge \tau} |X_u|^{m} V_u \diff u \right].\\
\end{aligned}
\end{equation*}
Following a similar reasoning as in the proofs above, we define the strictly increasing stochastic process
\begin{equation*}
g(t) := \int_0^t V_u \diff u.
\end{equation*}
We then have that
\begin{equation*}
\begin{aligned}
&\mathbb{E}\left[\underset{s \in [0,t]}{\sup}|X_{s \wedge \tau}|^m\right] \le 2\mathbb{E}\left[ |X_0|^m \right] + 6\gamma(m) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(m)  \mathbb{E} \left[\int_0^{t \wedge \tau} \underset{s \in [0,u]}{\sup} |X_s|^{m} \diff g(u) \right]\\
&\le 2\mathbb{E}\left[ |X_0|^m \right] + 6\gamma(m) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(m)  \mathbb{E} \left[\int_0^{t \wedge \tau} \underset{s \in [0,t]}{\sup} |X_{s \wedge u}|^{m} \diff g(u) \right].\\
\end{aligned}
\end{equation*}
For $\omega \ge 0$, let $\tau_{\omega}:=\{t \ge 0 \, | \, g(t)\ge \omega\}$. Notice that $g(t \wedge \tau_{\omega}) =  g(t) \wedge \omega$. In what follows, we fix $\omega >0$ and set $\tau = \tau_{\omega }$.\bigbreak

\noindent We consider a stochastic time change $r = g(u)$ so that $u = \tau _{r}$.

\begin{equation*}
\begin{aligned}
&\mathbb{E}\left[\underset{s \in [0,t]}{\sup}|X_{s \wedge \tau_\omega}|^m\right] \le 2\mathbb{E}\left[ |X_0|^m \right] + 6\gamma(m) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(m)  \mathbb{E} \left[\int_0^{\omega \wedge g(t)} \underset{s \in [0,t]}{\sup} |X_{s \wedge \tau_r}|^{m} \diff r \right]\\
& \le 2\mathbb{E}\left[ |X_0|^m \right] + 6\gamma(m) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(m)  \int_0^{\omega}\mathbb{E} \left[ \underset{s \in [0,t]}{\sup} |X_{s \wedge \tau_r}|^{m} \right] \diff r.\\
\end{aligned}
\end{equation*}
Applying Gr\"{o}nwall's inequality gives
\begin{equation}\label{Xbound}
\mathbb{E}\left[\underset{s \in [0,t]}{\sup}|X_{s \wedge \tau_\omega}|^m\right] \le T_1(t) e^{4 \gamma(m) \omega},
\end{equation}
for $T_1 (t) = 2\mathbb{E}\left[ |X_0|^m \right] + 6\gamma(m) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] < \infty $ by Lemma \ref{momentboundvol}.\newline

\noindent We now repeat the same process as above for $n<m$ and set $\tau = t$ to get:

\begin{equation*}
\begin{aligned}
&\mathbb{E}\left[\underset{s \in [0,t]}{\sup}|X_{s}|^n \right] \le \mathbb{E}\left[ |X_0|^n \right] + n \tilde{\beta}_{\max}\mathbb{E}\left[\int_0^{t} |X_u|^{n-1} V_u \, \diff u \right] \\
&+ n \beta_0 \mathbb{E}\left[ \left( \int_0^{t } |X_u|^{2(n-1)} |\sigma(u, X_u, V_u, \mu^Z_u)|^2  \diff u \right)^{1/2} \right] + \frac{n(n-1)}{2} \tilde{\sigma}^2_{\max}\mathbb{E} \left[\int_0^{t } |X_u|^{n-2} V_u \diff u \right],\\
& \le 2\mathbb{E}\left[ |X_0|^n \right] + 6\gamma(n) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(n)  \mathbb{E} \left[\int_0^{t} \underset{s \in [0,t]}{\sup} |X_{s \wedge u}|^{n} \diff g(u) \right].\\
%& \le 2 \mathbb{E}\left[|X_0|^n \right] + 6\gamma(n) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(n)  \int_0^{\infty} \mathbb{E} \left[\left(\underset{s \in [0,t]}{\sup} |X_{s \wedge \tau^i_r}|^{n}\right) \mathbbm{1}_{r \le g(t)}\right] \diff r \\
%& \le 2 \mathbb{E}\left[|X_0|^n \right] + 6\gamma(n) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(n)  \int_0^{\infty} \mathbb{E} \left[\left(\underset{s \in [0,t]}{\sup} |X_{s \wedge \tau^i_r}|^{n}\right)^{\frac{m}{n}}\right]^{\frac{n}{m}} \mathbb{E}\left[\mathbbm{1}_{r \le g(t)}\right]^{\frac{m-n}{m}}\diff r \\
%& \le 2 \mathbb{E}\left[|X_0|^n \right] + 6\gamma(n) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(n)  \int_0^{\infty} \mathbb{E} \left[\underset{s \in [0,t]}{\sup} |X_{s \wedge \tau^i_r}|^{m}\right]^{\frac{n}{m}}\mathbb{P}\Big(r \le g(t)\Big)^{\frac{m-n}{m}}\diff r \\
%& \le 2 \mathbb{E}\left[|X_0|^n \right] + 6\gamma(n) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(n)  \int_0^{\infty} \left(T_1(t) e^{4 \gamma(m) r}\right)^{\frac{n}{m}}\Big( 
%e^{-r} \mathbb{E}\left[ e^{\int_0^t V_s \diff s} \right] \Big)^{\frac{m-n}{m}}\diff r, \\
\end{aligned}
\end{equation*}
Regarding the last term above, after applying a stochastic time-change as before followed by Fubini's theorem and H\"{o}lder's inequality we get
\begin{equation*}
\begin{aligned}
&\mathbb{E} \left[\int_0^{t} \underset{s \in [0,t]}{\sup} |X_{s \wedge u}|^{n} \diff g(u) \right] \le \int_0^{\infty} \mathbb{E} \left[\left(\underset{s \in [0,t]}{\sup} |X_{s \wedge \tau_r}|^{n}\right) \mathbbm{1}_{r \le g(t)}\right] \diff r \\
&  \le \int_0^{\infty} \mathbb{E} \left[\left(\underset{s \in [0,t]}{\sup} |X_{s \wedge \tau_r}|^{n}\right)^{\frac{m}{n}}\right]^{\frac{n}{m}} \mathbb{E}\left[\mathbbm{1}_{r \le g(t)}\right]^{\frac{m-n}{m}}\diff r \le  \int_0^{\infty} \mathbb{E} \left[\underset{s \in [0,t]}{\sup} |X_{s \wedge \tau_r}|^{m}\right]^{\frac{n}{m}}\mathbb{P}\Big(r \le g(t)\Big)^{\frac{m-n}{m}}\diff r \\
& \le \int_0^{\infty} \left(T_1(t) e^{4 \gamma(m) r}\right)^{\frac{n}{m}}\Big( 
e^{-\lambda r} \mathbb{E}\left[ e^{\lambda \int_0^t V_s \diff s} \right] \Big)^{\frac{m-n}{m}}\diff r,\\
\end{aligned}
\end{equation*}
where we applied bound \eqref{Xbound} and Markov's inequality with $\lambda >\frac{4n\gamma(m)}{m-n}$ in the last line. By Lemma \ref{ExpIntVol}, $\mathbb{E}\left[ e^{\lambda \int_0^t V_s \diff s} \right]$ is finite for $t<T^*$, with $T^*$ as in \eqref{Tbound}.
Also, for $\lambda > \frac{4n\gamma(m)}{m-n}$,
\[ \int_0^{\infty} e^{-r\left(\frac{\lambda (m-n)-4n\gamma(m)}{m}\right)}\diff r = \left[\frac{-m}{\lambda (m-n)-4n\gamma(m)}e^{-r\left(\frac{\lambda (m-n)-4n\gamma(m)}{m}\right)}\right]_0^{\infty} = \frac{m}{\lambda (m-n)-4n\gamma(m)}. \] 
Let $T_2(t) :=  2 \mathbb{E}\left[|X_0|^n \right] + 6\gamma(n) t \mathbb{E}\left[\underset{s \in [0,t]}{\sup} V_s \right] + 4\gamma(n)T_1(t)^{\frac{n}{m}}\frac{m}{\lambda (m-n)-4n\gamma(m)}\mathbb{E}\left[ e^{\lambda \int_0^t V_s \diff s} \right]^{\frac{m-n}{m}}.$\newline
We therefore conclude that 
\begin{equation*}\label{i}
\mathbb{E}\left[\underset{s \in [0,t]}{\sup}|X_{s}|^n \right] \le T_2(t) < \infty.
\end{equation*}
\newline
