%For part (ii) of the Lemma, write 
%\begin{equation}
% \mathbb{E}[e^{c|X_s|}] = \sum_{n = 0}^{\infty} \frac{c^n}{n!} \mathbb{E}[|X_s|^n],
%\end{equation}
%where we need to choose $c_t$ such that the sum is finite. tbd....
\end{proof}

\begin{proposition}[Pathwise uniqueness]\label{pathwiseuniqueness}
Let Assumptions \ref{A3} hold together with $\nu \ge 1$ and $\mathbb{E}[|X_0|^4] < \infty$. Then the solution to \eqref{independentparticles3} is pathwise unique until time $T^*$, for $T^*$ as in $\eqref{Tbound}$.
\end{proposition}
\begin{proof}

Let $(X^{(1)}_t)_{t \in [0,T]}$ and $(X^{(2)}_t)_{t \in [0,T]}$ two solutions to \eqref{independentparticles3} with respect to the same initial solution $X_0$ and Brownian motion $W$. We aim to show that $\mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t}- X^{(2)}_{t}|^2\right] = 0 $.\newline

\noindent Let $\tau >0$ be a stopping time. Applying It\^{o}'s formula to $|X^{(1)}_{t \wedge \tau}- X^{(2)}_{t \wedge \tau}|^2$, and following similar arguments as in the proofs of Theorem \ref{PropChaos} and Theorem \ref{hlsvEM}, we get

\begin{equation*}
\begin{aligned}
\mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t \wedge \tau}- X^{(2)}_{t \wedge \tau}|^2\right] &\le C \mathbb{E}\left[\int_0^{T \wedge \tau} \left( |X^{(1)}_{r}- X^{(2)}_{r}|^2 + \mathcal{W}_2^2(\mu_{(1)}(r), \mu_{(2)}(r))\right) \diff g(r) \right]\\
& \le C\mathbb{E}\left[ \int_0^{T \wedge \tau}  \underset{t \in [0,T]}{\sup}|X^{(1)}_{t \wedge r}- X^{(2)}_{t \wedge r}|^2 + \mathcal{W}_2^2(\mu_{(1)}(r), \mu_{(2)}(r))  \diff g( r) \right],
\end{aligned}
\end{equation*}
where $g(\cdot) = \int_0^{\cdot} V_r \diff r$, and $C$ depends on the Lipschitz constants $L_{\tilde{\beta}}$ and $L_{\tilde{\sigma}}$. Note that since $\nu \ge 1$, then $V$ is strictly positive and $g$ increasing. Also, $\mu_{(1)}(r) = \mathbb{P}_{(X^{(1)}_r, V_r)}$ and similarly for $\mu_{(2)}(r)$.\newline

\noindent Similarly as in the previous proofs, let $\tau_{\omega}:= \inf\{t\ge 0 \, \lvert \, g(t) \ge \omega\}$, for any $\omega \ge 0$ and $\tau_0 = 0$.\newline 

\noindent Set $\tau = \tau_{\omega}$ for fixed $\omega >0$. Also, consider a stochastic time change $s= g(r)$ so that $r = \tau_s$. Applying the above and using the definition of the Wasserstein metric leads to
%It holds that $g(\tau^i_{\omega}) = \omega$ and $g(T \wedge \tau^i_{\omega}) = g^i(T)\wedge g^i(\tau^i_{\omega}) = g^i(T)\wedge \omega$.

\begin{equation*}
\begin{aligned}
\mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t \wedge \tau_{\omega}}- X^{(2)}_{t \wedge \tau_{\omega}}|^2\right] &\le C  \mathbb{E}\left[ \int_0^{g(T) \wedge \omega}\underset{t \in [0,T]}{\sup} |X^{(1)}_{t \wedge \tau_s}- X^{(2)}_{t \wedge \tau_s}|^2 + \mathbb{E}\left[|X^{(1)}_{\tau_s}- X^{(2)}_{\tau_s}|^2 \right] \diff s \right] \\
&\le C \int_0^{\omega} \mathbb{E}\left[\underset{t \in [0,T]}{\sup} |X^{(1)}_{t \wedge \tau_s}- X^{(2)}_{t \wedge \tau_s}|^2 \right] \diff s.
\end{aligned}
\end{equation*}
Applying Gr\"{o}nwall's lemma leads to 
\(\mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t \wedge \tau_{\omega}}- X^{(2)}_{t \wedge \tau_{\omega}}|^2\right] =0. \)
Therefore, for fixed $\omega > 0$ and $t \in [0,T]$, we have $X^{(1)}_{t \wedge \tau_{\omega}} = X^{(2)}_{t \wedge \tau_{\omega}}.$
To finish the proof, we can write for any $\omega > 0 $,
\begin{equation*}
\begin{aligned}
&\mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t}- X^{(2)}_{t}|^2\right]  \le \mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t}- X^{(2)}_{t}|^2 \mathbbm{1}_{\{\tau_{\omega} > T\}}\right] + \mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t}- X^{(2)}_{t}|^2 \mathbbm{1}_{\{\tau_{\omega} \le T\}}\right] \\
& \le \mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t \wedge \tau_{\omega}}- X^{(2)}_{{t \wedge \tau_{\omega}}}|^2 \right] + \mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t}- X^{(2)}_{t}|^2 \mathbbm{1}_{\{\tau_{\omega} \le T\}}\right].
\end{aligned}
\end{equation*}
We've already shown that the first term above is $0$. Looking at the second term, since $\tau_{\omega} \le T$ and $g$ is increasing, then $\omega \le g(T)$. We therefore have
\begin{equation}\label{omegaeqn}
\begin{aligned}
\mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t}- X^{(2)}_{t}|^2\right]  &\le \mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t}- X^{(2)}_{t}|^2 \cdot \frac{g(T)}{\omega}\right]\\
&\le \frac{1}{\omega} \mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t}|^4 + \underset{t \in [0,T]}{\sup}|X^{(2)}_{t}|^4 + 2g^2(T)\right],
\end{aligned}
\end{equation}
where we used $|X^{(1)}_{t}- X^{(2)}_{t}|^2 g(T) \le (2|X^{(1)}_{t}|^2 + 2|X^{(2)}_{t}|^2)g(T) \le  |X^{(1)}_{t}|^4 + |X^{(2)}_{t}|^4 + 2g^2(T).$\newline

From Lemma \ref{aprioriestimates}, $\mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t}|^4]\right]$ and $\mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(2)}_{t}|^4\right]$  are finite for $T<T^{*}$. For the last term in equation \eqref{omegaeqn} notice that by Cauchy--Schwarz inequality,
\begin{equation*}
\mathbb{E}\left[g^2(T)\right] \le T \mathbb{E}\left[\int_0^T V^2_r \diff r \right]  \le T \int_0^T \mathbb{E}\left[\underset{r \in [0,T]}{\sup}V^2_r  \right] \diff r,
\end{equation*}
which, by Lemma \ref{momentboundvol}, is also finite. Sending $\omega \to \infty$ in equation \eqref{omegaeqn} gives
\begin{equation*}
\mathbb{E}\left[\underset{t \in [0,T]}{\sup}|X^{(1)}_{t}- X^{(2)}_{t}|^2\right]  = 0,
\end{equation*}
concluding that $X^{(1)}_{t}= X^{(2)}_{t}$ for all $t \in [0,T]$, as required.
\end{proof}

To establish the existence of a strong solution to \eqref{independentparticles3}, we partition $[0,T]$ into uniform time intervals and use an interpolated Euler-like sequence in which at each time-step of the partition the measure component is held constant. This technique is inspired by Section 3 in \cite{KloLor}, and Section 3 in \cite{LiMaoSongWuYin}. We will show that this sequence is Cauchy in $L^2(\Omega, \mathcal{F},\mathbb{P})$ and by the completeness of $L^2(\Omega, \mathcal{F},\mathbb{P})$ there exists a limit $X:\Omega \times [0,T] \to \mathbb{R}$, which we show to be a solution to \eqref{independentparticles3}.
\begin{proposition}[Existence]\label{existencetheorem}
Let Assumptions \ref{A3} hold and also assume that $\mathbb{E}[|X_0|^2] < \infty$ and $\nu \ge 1$. There exists a strong solution of \eqref{independentparticles3} on $[0,T]$ for $T < T^*$ for $T^*$ as in \eqref{Tbound}.
\end{proposition}
We include a sketch of the proof in the appendix, since it follows using similar arguments as those in Theorem 2.2 of \cite{LiMaoSongWuYin}.





%\begin{lemma}[Osgood's lemma]
%Let $q$ be a measurable function from $[t_0, T]$ to $[0, b]$, $\gamma$ a locally integrable function from $[t_0, T]$ to $\mathbb{R}_+$, and $\mu$ a continuous and non-decreasing function from $[0, b]$ to $\mathbb{R}_+$. Suppose that for all $t \in [t_0, T]$ and for some $c \in ]0, b[$,
%\[
