\section{Proof of Proposition \ref{existencetheorem}}
\textit{\textbf{Proposition 3.} Let Assumptions \ref{A3} hold and also assume that $\mathbb{E}[|X_0|^2] < \infty$ and $\nu \ge 1$. There exists a strong solution of \eqref{independentparticles3} on $[0,T]$ for $T < T^*$ for $T^*$ as in \eqref{Tbound}.}
\begin{proof}
We can prove the result by following similar arguments as those in \cite{LiMaoSongWuYin}, Theorem 2.2, so here for brevity we summarise the key steps.
\begin{enumerate}[label=\textopenbullet]
\item We start by defining an Euler-like sequence where the measure component is piecewise constant. 

Specifically, let $n \ge 1$ and partition $[0,T]$ to $[t_0 = 0, t_1], (t_1,t_2], ..., (t_{n-1}, t_n = T]$, where for all $m \in \{0,1, ..., n-1\}$, $t_m = \frac{mT}{n} $ and for $t \in (t_{m}, t_{m+1}]$ we define $X^{n}_t$ as

\begin{equation*}
\diff X^{n}_t =  \beta(t,(X^{n}_t,V_t),\mu^{Z^n}_{t_m})\diff t + \sigma(t,(X^{n}_t,V_t),\mu^{Z^n}_{t_m})\diff  W^{x}_t,\,\,\, X^{n}_0=X_0.
\end{equation*}
This is a local SDE since the non--local dependence on the distribution is replaced by $\mu^{Z^n}_{t_m} = \mathbb{P}_{(X^{n}_{t_m},V_{t_m})}$ which is deterministic and independent of $X^{n}_t$ at each time-step. The existence of the above SDE is established (see, for example, Section 2 in \cite{HuangWang}).\bigbreak

\noindent Note that $X^{n} \in L^2(\Omega, \mathcal{F}, \mathbb{P})$ since for $T < T^*$
\[ \mathbb{E}\left[\underset{t\in [0,T]}{\sup}|X^{n}_t|^2\right] \le \sum_{m=0}^{n-1}\mathbb{E}\left[ \underset{t \in [t_m, t_{m+1}]}{\sup}|X^{n}_t|^2\right] < \infty, \]
which follows by similar arguments as those in Lemma \ref{aprioriestimates}. 
\item We can then show that $(X^{n})_{n \in \mathbb{N}}$ is Cauchy in $L^2(\Omega, \mathcal{F},\mathbb{P})$ by showing that 
% % Maybe need to include the following for extra details?
%We start by finding an upper bound for $\mathbb{E}\left[\underset{t\in [0,T]}{\sup}|X^{n}_t - X^{i,l}_t |^2 \right]$.\newline Following similar steps as in the proof of uniqueness above, and using the one--step estimate that for $t \in (t_m, t_{m+1}]$, $m\ge 0$ and $C$ a constant,

%\[\underset{n \in \mathbb{N}}{\sup}\,\mathbb{E}\left[|X^{n}_t - X^{n}_{t_m} |^2 \right] \le C \frac{T}{n},\]
%which tends to $0$ as $n \to \infty$. The same holds for $(X^{i,l})_{l \in \mathbb{N}}$.
%\textcolor{blue}{Add a proof of this in the appendix}
%\item This helps us find an upper bound for $ \sqrt{\mathbb{E}\left[\underset{t\in [0,T]}{\sup}|X^{n}_t - X^{i,l}_t |^2 \right]}$ and letting $n,l \to \infty$ we get that

\begin{equation*}
\underset{n,l \to \infty}{\lim} \sqrt{\mathbb{E}\left[\underset{t\in [0,T]}{\sup}|X^{n}_t - X^{l}_t |^2 \right]} =0.
\end{equation*}
By the completeness of $L^2(\Omega, \mathcal{F},\mathbb{P})$ we conclude that there exists a unique limit $X \in L^2(\Omega, \mathcal{F},\mathbb{P})$ of the sequence $\{X^{n}\}_{n \in \mathbb{N}}$, i.e.,
\begin{equation}\label{Cauchylimit}
\underset{n \to \infty}{\lim}\mathbb{E}\left[\underset{t\in [0,T]}{\sup}|X^{n}_t - X_t |^2 \right] = 0
\end{equation}
\item It remains to show that this limit satisfies equation \eqref{independentparticles3}.
From \eqref{Cauchylimit}, we get
\begin{equation}
\underset{n \to \infty}{\lim}\mathbb{E}\left[|X^{n}_t - X_t |^2 \right] = 0.
\end{equation}
The convergence in mean-square for fixed $t \in [0,T]$ implies that there exists a subsequence $\{X^{n_k}\}_{k=1}^{\infty}$ that converges to $X$ almost surely for all $t \in [0,T]$, i.e.,\newline 
for almost all $\omega \in \Omega$,
\[X^{n_k}_t(\omega) \xrightarrow{} X_t(\omega) \text{ as } k \to \infty.\]
Furthermore, we need to ensure that the measure $\mu^{Z^{n_k}}_{t_m}$ converges to $\mu^{Z}_{t}$ in an appropriate metric. Here, we consider the Wasserstein $\mathcal{W}_2$ distance and show that
\begin{equation*}
\begin{split}
\underset{k \to \infty}{\lim}\underset{t \in [0, T]}{\sup}\mathcal{W}_2(\mu^{Z^{n_k}}_{t_m},\mu^{Z}_{t})^2 &\le 2 \underset{k \to \infty}{\lim}\underset{t \in [0, T]}{\sup}\mathbb{E}\left[|X^{{n_k}}_t - X^{{n_k}}_{t_m} |^2 \right] + 2\underset{k \to \infty}{\lim}\underset{t \in [0, T]}{\sup}\mathbb{E}\left[|X^{{n_k}}_t - X_{t} |^2 \right]\\
& \le 2 \underset{k \to \infty}{\lim} C\frac{T}{{n_k}} = 0.
\end{split}
\end{equation*}
Therefore, since for all $t \in [0,T]$, $\beta(t,.,.,.)$ and $\sigma(t,.,.,.)$ are jointly continuous in $\mathbb{R} \times \mathbb{R} \times \mathcal{P}_2(\mathbb{R} \times \mathbb{R})$, we deduce that for all $t \in [0,T]$ and almost all $\omega \in \Omega$,
$$\underset{k \to \infty}{\lim}\beta(t,(X^{{n_k}}_t,V_t),\mu^{Z^{n_k}}_{t_m}) = \beta(t,(X_t,V_t),\mu^{Z}_{t}),$$ and 
\[\underset{k \to \infty}{\lim}\sigma(t,(X^{{n_k}}_t,V_t),\mu^{Z^{n_k}}_{t_m}) = \sigma(t,(X_t,V_t),\mu^{Z}_{t}).\]
\item We now show that conditions \textit{(iii)} and \textit{(iv)} of Definition \ref{strongsolndefn} hold. Notice that for all $k \ge 1$, $\mathbb{E}\left[\left| \beta(t,(X^{{n_k}}_t,V_t),\mu^{Z^{n_k}}_{t_m}) -\beta(t,(X_t,V_t),\mu^{Z}_{t}) \right|\right] \le 2\tilde{\beta}_{\max}\mathbb{E}\left[|V_t| \right]$. By Lemma \ref{momentboundvol}, $\underset{t\in [0,T]}{\mathbb{E}\left[|V_t| \right]} <\infty$ which concludes that $\{\mathbb{E}\left[\left| \beta(t,(X^{{n_k}}_t,V_t),\mu^{Z^{n_k}}_{t_m}) -\beta(t,(X_t,V_t),\mu^{Z}_{t}) \right|\right]\}_{k\ge 1}$ is uniformly integrable.\newline Similarly, one can show the same for $\{\mathbb{E}\left[\left| \sigma(t,(X^{{n_k}}_t,V_t),\mu^{Z^{n_k}}_{t_m}) -\sigma(t,(X_t,V_t),\mu^{Z}_{t}) \right|^2\right]\}_{k\ge 1}$.\newline

Also, $\left| \beta(t,(X^{{n_k}}_t,V_t),\mu^{Z^{n_k}}_{t_m})-\beta(t,(X_t,V_t),\mu^{Z^{n}}_{t}) \right| \le 2 \tilde{\beta}_{\max}\left|V_t \right|$ and $\underset{t \in [0,T]}{\sup}\mathbb{E}\left[\left|V_t \right| \right] < \infty$, concluding that $\{|\beta(t,(X^{{n_k}}_t,V_t),\mu^{Z^{n_k}}_{t_m})- \beta(t,(X_t,V_t),\mu^{Z^{n}}_{t})|\}_{k \ge 1}$ is uniformly integrable. The same holds for $\{|\sigma(t,(X^{{n_k}}_t,V_t),\mu^{Z^{n_k}}_{t_m})- \sigma(t,(X_t,V_t),\mu^{Z^{n}}_{t})|^2\}_{k \ge 1}$.\bigbreak


\noindent We can now show that for $t \in [0,T]$,
$\int_0^t\beta(s,(X^{{n_k}}_s,V_s),\mu^{Z^{n_k}}_{s_m})\diff s$ converges to\newline $\int_0^t\beta(s,(X_s,V_s),\mu^{Z^{n}}_{s})\diff s$ in the $L^1$ sense. Applying the dominated convergence theorem twice, see, for example, Theorem $4$ in \cite{ANShi}, we can show
\begin{equation}
\begin{split}
& \underset{k \to \infty}{\lim}\mathbb{E}\left[\left|\int_0^t\beta(s,(X^{{n_k}}_s,V_s),\mu^{Z^{n_k}}_{s_m})\diff s - \int_0^t\beta(s,(X_s,V_s),\mu^{Z^{n}}_{s})\diff s \right| \right]\\
& \le \int_0^t  \underset{k \to \infty}{\lim}\mathbb{E}\left[\left|\beta(s,(X^{{n_k}}_s,V_s),\mu^{Z^{n_k}}_{s_m})\diff s - \beta(s,(X_s,V_s),\mu^{Z^{n}}_{s})\right| \right]\diff s\\
& = \int_0^t \mathbb{E}\left[ \underset{k \to \infty}{\lim}\left|\beta(s,(X^{{n_k}}_s,V_s),\mu^{Z^{n_k}}_{s_m})\diff s - \beta(s,(X_s,V_s),\mu^{Z^{n}}_{s})\right| \right]\diff s = 0.
\end{split}
\end{equation}
For the sequence of stochastic integrals $\{\int_0^t\sigma(s,(X^{{n_k}}_s,V_s),\mu^{Z^{n_k}}_{s_m})\diff W_s \}_{k \ge 1}$, we prove convergence in an $L_2$ sense using the BDG inequality. Specifically,
\begin{equation}
\begin{split}
& \underset{k \to \infty}{\lim}\mathbb{E}\left[\left|\int_0^t\sigma(s,(X^{{n_k}}_s,V_s),\mu^{Z^{n_k}}_{s_m})-\sigma(s,(X_s,V_s),\mu^{Z^{n}}_{s})\diff W_s\right|^2 \right]\\
& \le \underset{k \to \infty}{\lim}\mathbb{E}\left[\left(\underset{t \in [0,T]}{\sup}\left|\int_0^t\sigma(s,(X^{{n_k}}_s,V_s),\mu^{Z^{n_k}}_{s_m})-\sigma(s,(X_s,V_s),\mu^{Z^{n}}_{s})\diff W_s\right| \right)^2 \right]\\
& \le C\underset{k \to \infty}{\lim} \mathbb{E}\left[\int_0^T \left|\sigma(s,(X^{{n_k}}_s,V_s),\mu^{Z^{n_k}}_{s_m}) - \sigma(s,(X_s,V_s),\mu^{Z^{n}}_{s}) \right|^2 \diff s\right]\\
& = C \int_0^T \mathbb{E} \left[ \underset{k \to \infty}{\lim} \left|\sigma(s,(X^{{n_k}}_s,V_s),\mu^{Z^{n_k}}_{s_m}) - \sigma(s,(X_s,V_s),\mu^{Z^{n}}_{s}) \right|^2 \right] \diff s =0.\\
\end{split}
\end{equation}






