\subsection{Some basic representations}

The analysis of $u(t,x)$ is largely based on its Feynman-Kac representation
stated below. Its proof is standard and is thus omitted.
\begin{prop}
\label{prop:FKRep}The solution $u(t,x)$ to the PAM (\ref{eq:HypPAM}) is given by 
\begin{equation}
u(t,x)=\mathbb{E}_{x}\big[\exp\big(\beta\int_{0}^{t}W(ds,B_{s})-\frac{1}{2}\beta^{2}\int_{0}^{t}f(B_{s},B_{s})ds\big)\big],\label{eq:FKRep}
\end{equation}
where $B$ is a hyperbolic Brownian motion starting at $x$ that is independent
of $W$ and $\mathbb{E}_{x}$ means taking expectation with respect
to $B$. 
\end{prop}
%
An important consequence of Proposition \ref{prop:FKRep} is the following
representation of the second moment of $u(t,x)$.
\begin{lem}
\label{lem:2MomRep}One has 
\begin{equation}
\mathbf{E}\big[u(t,x)^{2}\big]=\mathbb{E}_{x,x}\big[\exp\big(\beta^{2}\int_{0}^{t}f(B_{s},\tilde{B}_{s})ds\big)\big].\label{eq:2MomRep}
\end{equation}
The expectation $\mathbf{E}$ on the left hand side is taken with respect
to the Gaussian field $W$. On the right hand side, $B,\tilde{B}$ are two independent
copies of hyperbolic Brownian motions starting at $x$ (jointly independent of $W$)
and $\mathbb{E}_{x,x}$ means taking expectation with respect to them.
\end{lem}
\begin{proof}
By using the Feynman-Kac representation (\ref{eq:FKRep}), one can
write
\[
u(t,x)^{2}=\mathbb{E}_{x,x}\big[\exp\big(\beta N_{t}(B)+\beta N_{t}(\tilde{B})-\frac{1}{2}\beta^{2}\int_{0}^{t}\big(f(B_{s},B_{s})+f(\tilde{B}_{s},\tilde{B}_{s})\big)ds\big)\big],
\]
where we set $N_{t}(\omega)\triangleq\int_{0}^{t}W(ds,\omega_{s})$
for each fixed path $\omega$ in $M$. Note that $N_{t}(\omega)$
is a Gaussian martingale with quadratic variation $\int_{0}^{t}f(\omega_{s},\omega_{s})ds$
(under $\mathbf{E}$). In addition, given two fixed paths $\omega^{1},\omega^{2}$
in $M$, the process $N_{t}(\omega^{1})+N_{t}(\omega^{2})$ is a Gaussian
martingale with quadratic variation 
\begin{equation}
V_{t}(\omega^{1},\omega^{2})\triangleq\int_{0}^{t}f(w_{s}^{1},w_{s}^{1})ds+\int_{0}^{t}f(w_{s}^{2},w_{s}^{2})ds+2\int_{0}^{t}f(w_{s}^{1},w_{s}^{2})ds.\label{eq:2MomRepPf1}
\end{equation}
In particular, one has 
\begin{equation}
\mathbf{E}\big[\exp\big(\beta N_{t}(\omega^{1})+\beta N_{t}(\omega^{2})-\frac{1}{2}\beta^{2}V_{t}(\omega^{1},\omega^{2})\big)\big]=1.\label{eq:2MomRepPf2}
\end{equation}
It follows from (\ref{eq:2MomRepPf1}, \ref{eq:2MomRepPf2}) that
\begin{align*}
 & \mathbf{E}\big[u(t,x)^{2}\big]\\
 & =\mathbf{E}\mathbb{E}_{x,x}\Big[\exp\big(\beta N_{t}(B)+\beta N_{t}(\tilde{B})-\frac{1}{2}\beta^{2}V_{t}(B,\tilde{B})+\beta^{2}\int_{0}^{t}f(B_{s},\tilde{B}_{s})ds\big)\Big]\\
 & =\mathbb{E}_{x,x}\Big[\mathbf{E}\big[\exp\big(\beta N_{t}(B)+\beta N_{t}(\tilde{B})-\frac{1}{2}\beta^{2}V_{t}(B,\tilde{B})\big]\exp\big(\beta^{2}\int_{0}^{t}f(B_{s},\tilde{B}_{s})ds\big)\Big]\\
 & =\mathbb{E}_{x,x}\Big[\exp\big(\beta^{2}\int_{0}^{t}f(B_{s},\tilde{B}_{s})ds\big)\Big].
\end{align*}
This gives the desired relation (\ref{eq:2MomRep}).
\end{proof}
%

\subsection{Some hyperbolic estimates}

We recall two fundamental estimates in hyperbolic geometry. The first
one is about uniform estimates for the heat kernel.

\begin{lem}\label{lem:HKEst}(\cite[Theorem 3.1]{DM98}) Let $H_{t}(\rho(x,y))$
be the heat kernel on $M$. Then one has 
\begin{equation}
H_{t}(\rho)\asymp t^{-d/2}\exp\big(-\frac{(d-1)^{2}t}{4}-\frac{\rho^{2}}{4t}-\frac{(d-1)\rho}{2}\big)(1+\rho+t)^{\frac{d-3}{2}}(1+\rho)\label{eq:HKEst}
\end{equation}
uniformly for $\rho\geqslant0$ and $t>0$. Here ``$A\asymp B$''
means $c_{1}B\leqslant A\leqslant c_{2}B$ with some universal constants
$c_{1},c_{2}>0.$

\end{lem}

The second estimate is a reversed triangle inequality that is only
valid in hyperbolic geometry. 

\begin{lem}{\label{lem:RevTri}}(\cite[Lemma 3.4]{HL10}) Let $\Delta ABC$
be a hyperbolic triangle with geodesic edges $a,b,c$. Then one has
\begin{equation}
0\leqslant b+c-a\leqslant\log\frac{2}{1-\cos A}.\label{eq:RevTri}
\end{equation}


\end{lem}
\begin{rem}
Lemma \ref{lem:HKEst} shows that the Laplacian has a strictly positive
bottom spectrum $\lambda_{0}=(d-1)^{2}/4$ and the heat kernel decays
like $t^{-3/2}e^{-\lambda_{0}t}$ as $t\rightarrow\infty.$ A remarkable
point about Lemma \ref{lem:RevTri} is that the estimate is uniform
in $a,b,c$ (with the angle $A$ fixed). In particular, when
$b,c$ are very large (so is $a$ as a function of $b,c$ when $A$
is fixed), taking the detour path $(b,c)$ to go from $B$ to $C$
is not-so-different from directly taking the geodesic path $a$. These two properties
are both consequences of negative curvature and are drastically different
from the Euclidean situation. Their implications on Brownian motion are contained
in the estimates (\ref{eq:LowBdDist1}, \ref{eq:FlucEst}) below. 
\end{rem}

\subsection{Reduction to a single integral estimate}

To prove Theorem \ref{thm1-intro} (a), we begin by applying triangle
inequality to the Feynman-Kac representation (\ref{eq:2MomRep}) so that 
\begin{equation}
\mathbf{E}\big[u(t,x)^{2}\big]\leqslant\mathbb{E}_{x,x}\Big[\exp\big(\beta^{2}\int_{0}^{\infty}|f|(B_{t},\tilde{B}_{t})dt\big)\Big]=:I(\beta).\label{eq:IBet3}
\end{equation}
To ease notation, we will assume $f\geqslant0$ (otherwise just regard $|f|$
as $f$). One has 
\begin{align*}
\exp\Big(\beta^{2}\int_{0}^{\infty}f(B_{t},\tilde{B}_{t})dt\Big) & =\sum_{n=0}^{\infty}\frac{\beta^{2n}}{n!}\Big(\int_{0}^{\infty}f(B_{t},\tilde{B}_{t})dt\Big)^{n}\\
 & =\sum_{n=0}^{\infty}\beta^{2n}\int_{0<t_{1}<\cdots<t_{n}<\infty}\prod_{k=1}^{n}f(B_{t_{k}},\tilde{B}_{t_{k}})dt_{1}\cdots dt_{n}.
\end{align*}
Note that $(B_{t},\tilde{B}_{t})$ can be viewed as the Brownian motion on the
product space $M\times M$ (equipped with the product metric), whose
heat kernel is clearly given by 
\[
P_{t}((x,y),(x',y'))=H_{t}(\rho(x,x'))H_{t}(\rho(y,y')).
\]
It follows that 
\begin{align}
I(\beta) & =\sum_{n=0}^{\infty}\beta^{2n}\int_{0<t_{1}<\cdots<t_{n}<\infty}\int_{(M\times M)^{n}}\prod_{k=1}^{n}f(x_{k},y_{k})\nonumber \\
 & \ \ \ \times P_{t_{k}-t_{k-1}}\big((x_{k-1},y_{k-1}),(x_{k},y_{k})\big)d{\bf t}d{\bf x}d{\bf y},\label{eq:IBet1}
\end{align}
where $x_{0}=y_{0}\triangleq x$, $t_{0}\triangleq0$ and 
\[
d{\bf t}\triangleq dt_{1}\cdots dt_{n},\ d{\bf x}d{\bf y}\triangleq\prod_{k=1}^{n}{\rm vol}_{M}(dx_{k}){\rm vol}_{M}(dy_{k}).
\]
Let us further denote $z_{k}\triangleq(x_{k},y_{k})$ to ease notation.
By applying a change of variables $s_{k}\triangleq t_{k}-t_{k-1}$
in (\ref{eq:IBet1}) and noting that each $s_{k}$ has independent integral range
$(0,\infty)$, one finds that 
\begin{align}
I(\beta) & =\sum_{n=0}^{\infty}\beta^{2n}\int_{M^{2}}f(z_{1})\Big(\int_{0}^{\infty}P_{t}(z_{0},z_{1})dt\Big)dz_{1}\times\cdots\times\int_{M^{2}}f(z_{n-1})\nonumber \\
 & \ \ \ \Big(\int_{0}^{\infty}P_{t}(z_{n-2},z_{n-1})dt\Big)dz_{n-1}\int_{M^{2}}f(z_{n})\Big(\int_{0}^{\infty}P_{t}(z_{n-1},z_{n})dt\Big)dz_{n}.\label{eq:IBet2}
\end{align}
Now it becomes clear that the conclusion of Theorem \ref{thm1-intro}-(a)  will follow
directly from the lemma below.
\begin{lem}
\label{lem:KeyLem2MomUp}There exists a positive constant $\Lambda$,
such that 
\begin{equation}
\int_{M\times M}f(x',y')dx'dy'\int_{0}^{\infty}P_{t}((x,y),(x',y'))dt\leqslant\Lambda\label{eq:KeyLem2MomUp}
\end{equation}
for all $(x,y)\in M\times M.$
\end{lem}
%
\begin{proof}[Proof of Theorem \ref{thm1-intro}-(a)]Presuming that
(\ref{eq:KeyLem2MomUp}) is true, one has from (\ref{eq:2MomRepPf2},
\ref{eq:IBet3}) that 
\[
I(\beta)\leqslant\sum_{n=0}^{\infty}\beta^{2n}\Lambda^{n}.
\]
The conclusion thus follows by taking $\beta_{0}\triangleq1/\sqrt{\Lambda}.$ 

\end{proof}

\subsection{Proof of Lemma \ref{lem:KeyLem2MomUp}}

It remains to prove Lemma \ref{lem:KeyLem2MomUp}. Note that the LHS
of (\ref{eq:KeyLem2MomUp}) equals 
\[
\int_{0}^{\infty}\mathbb{E}_{x,y}\big[f(B_{t},\tilde{B}_{t})\big]dt,
\]
where $B_{t},\tilde{B}_{t}$ are independent Brownian motions starting at $x,y$
respectively. The idea of bounding this integral is very simple; recalling
the assumption (\ref{eq:UpDecayAssump}) on the decay rate of $f$,
one basically replaces $f(B_{t},\tilde{B}_{t})$ by $C\rho(B_{t},\tilde{B}_{t})^{-\alpha}$
and applies the approximation $\rho(B_{t},\tilde{B}_{t})\approx2(d-1)t$
for all large $t$. As we will see below, this is legal since the
heat kernel estimate (\ref{eq:HKEst}) forces the radial process $\rho(x,B_{t})$
to behave like $(d-1)t$ with a $\sqrt{t}$-fluctuation,
while the reversed triangle inequality (\ref{eq:RevTri}) forces $\rho(B_{t},\tilde{B}_{t})\approx\rho(x,B_{t})+\rho(y,\tilde{B}_{t})$ with  high probability. 

We assume without loss of generality that (\ref{eq:UpDecayAssump}) holds for all $x,y\in M$
(by enlarging the constant $C$ if necessary). For each $t>1$, we
will also introduce a localising event $M_{t}$ (its precise definition
is given by (\ref{eq:MainEvt}) below) on which the distance $\rho(B_{t},\tilde{B}_{t})$
can be effectively estimated. One then has the decomposition
\begin{align}
 & \int_{0}^{\infty}\mathbb{E}_{x,y}\big[f(B_{t},\tilde{B}_{t})\big]dt\nonumber \\
 & \leqslant\|f\|_{\infty}+\int_{1}^{\infty}\mathbb{E}_{x,y}\big[f(B_{t},\tilde{B}_{t});M_{t}^{c}\big]dt+\int_{1}^{\infty}\mathbb{E}_{x,y}\big[f(B_{t},\tilde{B}_{t});M_{t}\big]dt\nonumber \\
 & \leqslant\|f\|_{\infty}+\|f\|_{\infty}\int_{1}^{\infty}\mathbb{P}_{x,y}(M_{t}^{c})dt+C\int_{1}^{\infty}\mathbb{E}_{x,y}\big[\rho(B_{t},\tilde{B}_{t})^{-\alpha};M_{t}\big]dt.\label{eq:IntDecomp}
\end{align}
We first analyse the last integral in (\ref{eq:IntDecomp}), which
will also motivate the definition of $M_{t}.$ By applying Lemma \ref{lem:RevTri}
to both triangles $\Delta B_{t}y\tilde{B}_{t}$ and $\Delta B_{t}xy$,
one finds that 
\begin{align}
\rho(B_{t},\tilde{B}_{t}) & \geqslant\rho(B_{t},y)+\rho(y,\tilde{B}_{t})-\log\frac{2}{1-\cos\Psi_{t}}\nonumber \\
 & \geqslant\rho(B_{t},x)+\rho(x,y)-\log\frac{2}{1-\cos\Phi_{t}}+\rho(y,\tilde{B}_{t})-\log\frac{2}{1-\cos\Psi_{t}}\nonumber \\
 & \geqslant\rho(B_{t},x)+\rho(y,\tilde{B}_{t})-\log\frac{2}{1-\cos\Phi_{t}}-\log\frac{2}{1-\cos\Psi_{t}}.\label{eq:LowBdDist1}
\end{align}
where $\Phi_{t}\triangleq\angle B_{t}xy$ and $\Psi_{t}\triangleq\angle B_{t}y\tilde{B}_{t}$
(both $\Phi_{t},\Psi_{t}\in[0,\pi]$),
