\section{Analytic formula without borrowing and lending rate spreads}\label{sec price formula without spread} 

  This section presents the analytic formula for  the buyer's price in the case without interests rate spreads, i.e.,  
   $r^{b,D}=r^{c,D}$ and 
  $r^{b,E}=r^{c,E}$, considering the case where the buyer takes the stopping time $\tau =T$ instead of  strategically optimising  over all stopping times $\tau$. 


First we observe that interest paid on collateral, represented here by risky asset $P$, are equivalent to the asset paying a dividend with the rate $r^{c,E}$. Classical non-arbitrage pricing theory applied to risky asset yielding dividends, tells us that that absence of arbitrage implies the existence of martingale measure $\mathbb Q$ such that $(e^{-r^{c,D}t} P_t e^{r^{c,E} t})_t$ is $\mathbb Q$-martingale. We will next find such measure $\mathbb Q$.

Let $W=(W_t)_{t\ge 0}$ be a standard Brownian motion on a probability space 
$(\Omega, \mathcal F,\mathbb{P})$
and let $\mathbb F=(\mathcal{F})_{t\ge 0}$
be the natural filtration of $W$ augmented with $\mathbb{P}$-null sets. 
 Fix
 $P_0>0$, 
 $\theta^0\in [0,1)$
 and 
 $ \theta\in (\theta_0,1)$. 
The price $P$ of ETH/USDC is given by 
\begin{equation}\label{eq gbm}  
    P_t=P_0 \exp\left( (\mu - \frac{1}{2}\sigma^2)t + \sigma W_t  \right)\,,\quad t>0\,,
\end{equation}
 for some $\mu\in \mathbb R$ and $\sigma>0$. We denote $Y_t := P_t e^{r^{c,E}t}$ the value of the risky asset with the compounded dividends at time $t$. Then
 \begin{equation}\label{eq gbm dividends}  
    Y_t=P_0 \exp\left( (\mu + r^{c,E} - \frac{1}{2}\sigma^2)t + \sigma W_t  \right)\,,\quad t>0\,,
\end{equation}
 Define the $\mathbb F$-martingale $(\gamma_t)_{t\geq 0}$ by
 \[
 \gamma_t = \exp\left( -\nu W_t - \frac1{2} \nu^2 t \right),\,\, \nu = \frac{\mu + r^{c,E} - r^{c,D}}{\sigma},\,\,t\geq 0 
 \]
and the measure $\mathbb Q$ with the Radon-Nikodym derivative
\begin{equation}\label{eq change of measure}
\frac{d \mathbb Q}{d \mathbb P}\bigg |_{\mathcal F_t} = \gamma_t, \,\, t\geq 0. 
\end{equation}
By the Girsanov theorem, the process $X = \{X_t := \nu t + W_t, t\geq 0\}$ is an $\mathbb F$-Brownian motion with respect to $\mathbb Q$. Note that under $\mathbb Q$,  $(e^{-r^{c,D}t} Y_t)_{t\geq 0}$ is a martingale,
\[
e^{-r^{c,D}t} Y_t = Y_0 \exp\left(-\frac1{2} \sigma^2 t + \sigma \underbrace{\left( \frac{\mu + r^{c,E} - r^{c,D}}{\sigma} t + W_t \right)}_{\text{Brownian motion under } \mathbb Q}  \right).
\]
The fair price of the option is
\begin{equation} 
\label{eq:value_P0 european}
\begin{split}
V(P_0) & :=  \mathbb{E}^\mathbb Q\left[ e^{-r^{c,D}T} (P_ \tau \,e^{r^{c,E}\, T} - \theta^0 \,P_0\,e^{r^{b,D}\, T} )\mathbbm{1}_{\{T<\tau^B\}}\right]\, \\
      & = \mathbb{E}^\mathbb Q\left[ e^{-r^{c,D}\,T} (Y_T  - \theta^0 \,P_0\,e^{r^{b,D}\, \tau} )\mathbbm{1}_{\{T<\tau^B\}}\right]\,,
\end{split}
\end{equation}
where 
\begin{equation*} 
\begin{split}
   \tau^B & :=   \inf  \{ t \geq 0: \theta\, \overbrace{P_t e^{r^{c,E}\, t}}^{Y_t} = \theta^0 {P_0} e^{r^{b,D}\, t}   \} \, \\
          & =  \inf  \left\{ t \geq 0: \frac{Y_t}{P_0} e^{-  r^{b,D} \, t} = \theta^{-1 }\theta^0  \right\} \,
\end{split}
\end{equation*}



 Observe that by setting $S_t :=\frac{Y_t}{P_0} e^{-  r^{b,D}\, t}$ and considering no-spread $r^{c,D} = r^{b,D}$,
\eqref{eq:value_P0 european}  can be equivalently written as 
 \begin{equation} 
 \label{eq:value_S0 european}
V(P_0) := P_0 \mathbb{E}^\mathbb Q\left[(S_T - \theta^0   )\mathbbm{1}_{\{T<\tau^B\}}\right]\,,
\end{equation}
where
\begin{equation} 
\label{eq:S_dynamics}
S_t =  \exp\left(-\frac1{2} \sigma^2 t + \sigma \underbrace{\left( \frac{\mu + r^{c,E} - r^{c,D}}{\sigma} t + W_t \right)}_{\text{Brownian motion under } \mathbb Q}  \right),
\end{equation}
and 
\begin{equation}
\label{eq:tau_B_S}
   \tau^B :=   \inf  \left\{ t \geq 0: S_t = B    \right\} \,,
\end{equation}
where $B\coloneqq \theta^{-1 }\theta^0 \in (\theta^0,1)$.

The price \eqref{eq:value_S0 european} is an European  down-and-out call option where
the underlying asset starts at $S_0=1$ and pays no dividends,
the interest rate is zero, and the barrier is  
a barrier
larger than the strike. One can show by
  the reflection principle that 
\begin{align}
\label{eq:do_european_call}
\begin{split}
&\mathbb{E}^\mathbb Q[(S_T    -\theta^0  )_{+}\mathbbm{1}_{\{T<\tau^B\}}]
\\
&= C_v(1, T,B)+(B-\theta^0)C_d(1,T, B)-\frac{1}{B}\left(C_v(B^2, T,B)+(B-\theta^0)C_d(B^2,T, B) \right),
\end{split}
\end{align}
where $C_v$ is the vanilla call price given by
\begin{align*}
C_v (S,T,E)=S N(d_1)-KN(d_2), \quad d_1=\frac{\log(S/E)+\frac{1}{2}\sigma^2T}{\sigma\sqrt{T}},\quad 
d_2=d_1-\sigma \sqrt{T},
\end{align*}
and $C_d$ is the digital call price given by
$$
C_d (S,T,E)= N(d_2).
$$
Substituting the formula of $C_v$ and $C_d$ into \eqref{eq:do_european_call}  yields that 
\begin{equation}\label{eq european barrier option price}
\begin{split}
&\mathbb{E}[(S_T    -\theta^0  )_{+}\mathbbm{1}_{\{T<\tau^B\}}]
\\
&=  N(\bar{d}_1)-B N(\bar{d}_2) +(B-\theta^0)N(\bar{d}_2) 
-\frac{1}{B}\left(B^2 N(\hat{d}_1)-BN(\hat{d}_2)  +(B-\theta^0)N(\hat{d}_2)   \right)
\\
&=  N(\bar{d}_1)-\theta^0 N(\bar{d}_2) 
- B N(\hat{d}_1)+ \frac{\theta^0}{B}  N(\hat{d}_2),
\end{split}
\end{equation}
where 
\begin{align*}
\bar{d}_1 &= \frac{-\log(\frac{\theta^0}{\theta})+\frac{1}{2}\sigma^2 T}{\sigma\sqrt{T}}, \quad \bar{d}_2= \frac{-\log(\frac{\theta^0}{\theta})-\frac{1}{2}\sigma^2 T}{\sigma\sqrt{T}},
\\
\hat{d}_1 &= \frac{\log(\frac{\theta^0}{\theta})+\frac{1}{2}\sigma^2T}{\sigma\sqrt{T}}, \quad \hat{d}_2 =  \frac{\log(\frac{\theta^0}{\theta})-\frac{1}{2}\sigma^2T}{\sigma\sqrt{T}}.
\end{align*}
As  $\hat{d}_1=-\bar{d}_2$, $\hat{d}_2= -\bar{d}_1$ and $\theta^0/B=\theta$, 
\begin{align}
\begin{split}
&\mathbb{E}[(S_T    -\theta^0  )_{+}\mathbbm{1}_{\{T<\tau^B\}}]
\\
&=  N(\bar{d}_1)-\theta^0 N(\bar{d}_2) 
-B N(\hat{d}_1)+ {\theta}  N(\hat{d}_2)
\\
&=N(\bar{d}_1)-\theta^0 N(\bar{d}_2) 
-\frac{\theta^0}{\theta} (1- N(\bar{d}_2))+\theta (1-N(\bar{d}_1))
\\
&=\theta- \frac{\theta^0}{\theta} + (1-\theta) N(\bar{d}_1)+\theta^0(\frac{1}{\theta}-1) N(\bar{d}_2).
\end{split}
\end{align}
Consequently, 
with $\tau=T$, 
the buyer's price at $t=0$ is 
\begin{align}
V^B_0=P_0 \left(\theta- \frac{\theta^0}{\theta} + (1-\theta) N(\bar{d}_1)+\theta^0(\frac{1}{\theta}-1) N(\bar{d}_2)\right),
\end{align}
where 
\begin{align*}
\bar{d}_1 &= \frac{-\log(\frac{\theta^0}{\theta})+\frac{1}{2}\sigma^2 T}{\sigma\sqrt{T}}, \quad \bar{d}_2= 
\bar{d}_1-\sigma\sqrt{T}.
\end{align*}

Note that one expects that 
the European barrier option's price  \eqref{eq european barrier option price} is strictly less than the American option price $1-\theta^0$. 
Indeed, 
as discussed above,  for the American barrier option, it is optimal to stop before $S$ touches the barrier. This implies the stopping time $\tau= T$ for European barrier option  is strictly sub-optimal, as  there is non-zero probability for $S$ to touch  the barrier before $T$. Consequently, the European barrier option's price should be strictly smaller than the American one. 


\section{Nonlinear pricing framework for the lending contract}\label{sec non linear bsde pricing}

In this section, we derive a   nonlinear backward equation for the fair price of the lending contract with non-zero rate spread \emph{from the borrower's perspective}.

% We shall assume
% that $(\Omega,\cF, \sP)$
%  is a complete probability space,
% $W$ is a standard  Brownian motion on a 
%  complete probability space $(\Omega,\cF, \sP)$,
%  and 
%  $\sF=(\mathcal F_t)_{t\ge 0}$
%  be the filtration generated by $W$ 
% augmented by $\sP$-null sets, 
% and 
As before the price process $P$ of ETH/USDC satisfies \ref{eq gbm}.

Furthermore, we consider the replicating portfolio of the lending contract payoff \eqref{eq:payoff_tau} with wealth process $V$ whose dynamics obey \eqref{eq replicating portfolio with P}. Sending $\Delta t \rightarrow 0$ yields 

\begin{equation*}
    \begin{split}
  \d V_t &  =
      \left(r^{c,D}  V_{t}    - (  r^{b,D}-r^{c,D})   (V_{t} - \pi_{t} P_{t})^- 
  + (r^{c,E} -r^{c,D} +\mu_{t} ) \pi_{t} P_{t}  - (  r^{b,E} -r^{c,E}) \left( \pi_{t}   \right)^- P_{t}  
  \right)\d t
  \\
  &\quad 
  + \pi_t P_{t} \sigma_t \d W_{t} ,
    \end{split}
\end{equation*}



Using a change of variable which
associates $\pi\,P \in \mathcal H^2(\mathbb R) $ with $Z= \pi\,P\,\sigma \in \mathcal H^2(\mathbb R) $, one can write the wealth dynamics as 
\begin{align}
\label{eq:wealth_dynamics}
   \d  V_{t }  
  &=   f(t,V_t, Z_t) 
     \d t
  + Z_t \d W_t,
\end{align}
where 
$$
f(t,y,z) =
 r^{c,D}  y    - (  r^{b,D}-r^{c,D})   (y - \frac{z}{\sigma_t} )^- 
  + \frac{ r^{c,E} -r^{c,D} +\mu_t }{\sigma_t} z    - 
  \frac{r^{b,E} -r^{c,E}}{\sigma_t}
   \left( z  \right)^-  .
$$
Thus the value of the lending contract from the buyer's perspective is given by 
$$
V^B_0=\sup_{\tau \in \cT} V^{P_0,\tau}_0\,,
$$
where 
 $V^{P_0,\tau}$
satisfies 
\eqref{eq:wealth_dynamics} for all $t\in   [0,\tau] $
and 
$V^{P_0,\tau}_\tau$ is given by 
\eqref{eq:payoff_tau}.

We now apply a Girsanov’s transform to remove the drift $\mu$. Indeed, we define the probability measure $\sQ$ equivalent to $\sP$ with Radon-Nikodym derivative \eqref{eq change of measure}. 
Then $W^\sQ= W_t+\frac{ r^{c,E} -r^{c,D} +\mu_t }{\sigma_t}t$ is a standard Brownian motion on the filtered space 
$(\Omega, \cF,\sF,\sQ)$. 
Hence under the measure $\sQ$, the buyer's optimal value is given by
$$
V^B_0=\sup_{\tau \in \cT} V^{P_0,\tau}_0\,,
$$
where 
$(P, V^{P_0,\tau}, Z^{P_0,\tau})$
is the unique square-integrable solution to the following forward-backward stochastic differential equation (FBSDE): for all $t\in [0,\tau]$,
\begin{align}
\label{eq:fbsde_p0}
\begin{split}
\d P_t &=  P_t \left( (r^{c,D}-r^{c,E})  \d t + \sigma_t \d W^\sQ_t \right),  
\\ 
\d  V_{t }  
  &=  - g(t,V_t, Z_t) 
     \d t
  + Z_t \d W^\sQ_t,
  \\
  V_\tau &= (P_\tau \,e^{r^{c,E}\,\tau } -\theta^0 \,P_0 e^{r^{b,D}\, \tau } )_{+}\mathbf{1}_{\{\tau<\tau^B\}},
\end{split}
\end{align}
 where $g $ is defined by 
 $$
 g(t,y, z)=
- r^{c,D}  y    + (  r^{b,D}-r^{c,D})   \left(y - \frac{z}{\sigma_t} \right)^- 
    +
  \frac{r^{b,E} -r^{c,E}}{\sigma_t}
   \left( z  \right)^-,
 $$
 and $\tau^B $ is defined as in   \eqref{eq:liquidation_time}.
 If $\tau^*\in \mathcal T$ is the optimal stopping time, then 
  the corresponding hedging strategy is given by
  $ \pi^*_t =Z^{P_0,\tau^*}_t/\left(P_t \sigma_t\right)$.

Finally, 
observe that $g$ is homogeneous in $y,z$ in the sense that for all $\alpha>0$,
$g(t,\alpha y,\alpha z)= \alpha g(t,y,z)$. Hence  
by introducing the scaled processes 
$$
(S_t , V^\tau_t, Z^\tau_t)= \left(\frac{1}{P_0} P_t e^{(r^{c,E}-r^{b,D})t},
 \frac{1}{P_0}V^{P_0,\tau}_t e^{-r^{b,D} t},
 \frac{1}{P_0}Z^{P_0,\tau}_t e^{-r^{b,D} t}
 \right),
 \quad t>0,
$$
 the buyer's price can be equivalently expressed as   
\begin{align}
\label{eq:v^B_P_0}
V^B_0=P_0\sup_{\tau \in \cT} V^{\tau}_0\,,    
\end{align}
where $(V^{\tau}, Z^{\tau})$ satisfies 
\begin{align}
\label{eq:fbsde}
\begin{split}
\d S_t &=  S_t \left( (r^{c,D}-r^{b,D})  \d t + \sigma_t \d W^\sQ_t \right), 
\quad 
S_0=1,  
\\ 
\d  V_{t }  
  &=  - \bar{g}(t,V_t, Z_t) 
     \d t
  + Z_t \d W^\sQ_t,
\quad 
  V_\tau  =  
 (S_\tau    -\theta^0  )_{+}\mathbf{1}_{\{\tau<\tau^B\}},
\end{split}
\end{align}
and $\bar{g}$ and $\tau^B$ are given by
\begin{align}
\label{eq:bar_g}
\bar{g}(t,y, z) &\coloneqq 
( r^{b,D} - r^{c,D})  y    + (  r^{b,D}-r^{c,D})   \left(y - \frac{z}{\sigma_t} \right)^- 
    +
  \frac{r^{b,E} -r^{c,E}}{\sigma_t}
   \left( z  \right)^-,
   \\
   \tau^B & \coloneqq \inf \left\{ t \in [0,T] \mid   S_t   \leq \theta^0/\theta     \right\}\,.
\end{align}

