\section{Preliminaries}
\label{sec:preliminaries}

\noindent
{\bf Notation}: The natural numbers $\mathbb{N}$ include $0$.

The ground field is denoted by $k$ and a variety over $k$ is an integral separated scheme of finite type over $k$.  Given a scheme $X$ over $k$, a component of $X$ will mean an irreducible component unless we state otherwise. We will denote the base change of $X\to \Spec \, k$ to $\Spec \, \overline{k}$ by $X_{\overline{k}}$.

For a projective variety $X$, we denote the space of $\mathbb R$-Cartier divisors up to numerical equivalence by $N^1(X)$ and the space of $\mathbb R$-$1$-cycles up to numerical equivalence by $N_1(X)$. Inside these real vector spaces, we denote the lattice generated by integral Cartier divisors (resp.~integral $1$-cycles) by $N^1(X)_\bZ$ (resp.~$N_1(X)_\bZ$).
The nef cones of divisors and curves are denoted by $\Nef^1(X) \subset N^1(X)$ and $\Nef_1(X) \subset N_1(X)$ respectively, and the pseudo-effective cones of divisors and curves are denoted by $\overline{\mathrm{Eff}}^1(X) \subset N^1(X)$ and $\overline{\mathrm{Eff}}_1(X) \subset N_1(X)$ respectively.
For any closed cone $\mathcal C \subset N_1(X)$, we denote $\mathcal C\cap N_1(X)_{\mathbb Z}$ by $\mathcal C_{\mathbb Z}$.


\begin{lemm} \label{lemm:smoothnesscriterion}
Let $f: X \to Y$ be a $k$-morphism of finite-type separated $k$-schemes such that $X$ is equidimensional and $Y$ is irreducible. 
Suppose that $Y$ is smooth and that every fiber of $f$ over a closed point is smooth of dimension $\dim(X) - \dim(Y)$.  Then $X$ is a smooth scheme and $f$ is a smooth morphism.
\end{lemm}

\begin{proof}

Let $x \in X$ be a closed point.  Since the fiber of $f$ containing $x$ is smooth, $\rk_{x} \Omega_{X/Y} = \dim(X) - \dim(Y)$.  Since $Y$ is smooth, the exact sequence
\begin{equation*}
f^{*}\Omega_{Y/k} \otimes k(x) \to \Omega_{X/k} \otimes k(x) \to \Omega_{X/Y} \otimes k(x) \to 0
\end{equation*}
shows that $\rk_{x}\Omega_{X/k} \leq \dim(X)$.  Since $\dim(X)$ is also a lower bound on the rank, equality is achieved.  Thus $X$ is smooth at every closed point, hence smooth.



By upper semicontinuity of fiber dimension on the domain, every fiber of $f$ has dimension $\dim(X)-\dim(Y)$.  Since $X,Y$ are smooth, we conclude that $f$ is flat by \cite[Tag 00R4]{stacks}. 
Finally, a flat morphism of finite-type $k$-schemes such that the fibers over closed points are smooth is a smooth morphism.
\end{proof}

\subsection{Bounds on traces of endomorphisms}



In this section, we record certain estimates for the sum of eigenvalues of an endmorphism, which we will eventually apply to Frobenius acting on étale cohomology:

\begin{defi}
Suppose that $K$ is a field equipped with a norm $|\cdot|: \overline K \to \mathbb R$.  For any finite-dimensional $K$-vector space $V$ with an endomorphism $F$, the $\mathsf L^{1}$-trace of $F$ on $V$ is
$$|F,V| = \sum_{\lambda \in \overline K}\dim((V\otimes \overline K)_{\lambda}) |\lambda|,$$ where  $(V\otimes \overline K)_{\lambda}$ denotes the generalized eigenspace of $F$ with eigenvalue $\lambda$.
\end{defi}

Note that $|\Tr(F \curvearrowright V)| \leq |F,V|$ and if $W$ is an $F$-subquotient 
then $|F,W| \leq |F,V|$.   Furthermore the $\mathsf L^{1}$-trace is additive in short exact sequences.

Our first lemma addresses the behavior of spectral sequences when taking the trace of an endomorphism.  Let $E_1^{i,j}$ be a spectral sequence of $K$-vector spaces which are nonzero for only finitely many $i,j$,  converging to $H^{i+j}$ equivariantly with respect to the action of an endomorphism $F$.  We denote the differentials in this spectral sequence by $d_{r}$.


\begin{lemm}
\label{lemm:spectral}
	For any integer $I$, we have the inequality $$|\sum_{n\geq I}(-1)^n\Tr(F\curvearrowright \bigoplus_{i+j =n} E_1^{i,j}) - \sum_{n \geq I} (-1)^n\Tr(F \curvearrowright H^n)| \leq |F, \bigoplus_{i+j = I} E_1^{i,j}|.$$  
\end{lemm}
\begin{proof}
	We write $(E_r)^m$ for the group $\bigoplus_{i+j = m} E_r^{i,j}$ and we write $B_r^n$ for $d_r((E_r)^{n-1})$, i.e.~for the total boundary group in cohomological degree $n$ 
	on the $r$-th page.  We have that 
	$$(-1)^{I-1} \Tr(F\curvearrowright B_r^I) + \sum_{n \geq I} (-1)^n \Tr(F \curvearrowright (E_{r})^n)  = \sum_{n \geq I} (-1)^n \Tr(F \curvearrowright (E_{r+1})^n).$$
	Since there are finitely many nonzero terms on the $E_{1}$ page, the spectral sequence degenerates at a finite stage $R$ so that $E_R = E_\infty$.  Inductively  we obtain
	\begin{align*}
	\sum_{n \geq I} (-1)^n\Tr(F \curvearrowright H^n) &=\sum_{n \geq I} (-1)^n\Tr(F\curvearrowright (E_R)^n) \\
	&= (-1)^{I-1}\sum_{r = 1}^R \Tr(F\curvearrowright B_r^I) + \sum_{n \geq I} (-1)^n \Tr(F\curvearrowright (E_1)^n).
	\end{align*}
	To bound $\sum_{r = 1}^R \Tr(F\curvearrowright B_r^I)$, note that there is a filtration $0 \subseteq G_1 \subseteq G_2 \subseteq  \dotsb \subseteq G_R$ of $(E_1)^I$ such that the associated graded $G_r/G_{r-1} = B_r^I$.  Hence we have that $$ \left| \sum_{r = 1}^R \Tr(F\curvearrowright B_r^I) \right| \leq \sum_{r = 1}^R |F,B_r^I|  = |F,G_R| = |F, (E_1)^I|$$  
	as desired. 
	\end{proof}

Our next goal is to bound the $\mathsf L^{1}$-trace under various tensor operations.  Let $W = \oplus_{(n,i) \in \mathbb{N}^{2}} W_{n,i}$ be an $\mathbb{N}^{2}$-graded $K$-vector space.  We will be interested in the case when $W$ is equipped with an endomorphism $F$ that respects the grading.


\begin{lemm}\label{singletensor}% 
	Let $V,W$ be $\mathbb{N}^{2}$-bigraded vector spaces equipped with endomorphisms $F_{V}$ and $F_{W}$ which are compatible with the grading.  Suppose there are positive constants $d,b$ such that $|F_{V},V_{n,i}| \leq C_{1} d^n b^i$ and $|F_{W},W_{n,i}| \leq C_{2} d^n b^i$.  Then $$|F_{V} \otimes F_{W}, (V \otimes W)_{n,i}| \leq C_{1}C_{2} (n+1)(i+1) d^n b^i.$$ 
\end{lemm}
\begin{proof}
	We have
	\begin{align*}
	|F_{V} \otimes F_{W}, (V \otimes W)_{n,i}|  & = %|F, \bigoplus_{(n,i) = (n_1,i_2) + (n_2, i_2)} V_{n_1, i_1}\otimes W_{n_2,i_2}| = 
	\sum_{(n,i) = (n_1,i_2) + (n_2, i_2)}  |F_{V}, V_{n_1, i_1}| |F_{W}, W_{n_2,i_2}|  %\\
	%& \leq C_{1}C_{2}a^{n}b^{i} \sum_{(n,i) = (n_1,i_2) + (n_2, i_2)}  1
	\end{align*}
	and the sum is indexed over a set of size $(n+1)(i+1)$.
\end{proof}


\begin{lemm}\label{tensoralgebrabound}
	Let $W$ be an $\mathbb{N}^{2}$-bigraded vector space with endomorphism $F$ which is compatible with the grading.  Suppose that $W_{0, i} = W_{n,0} = 0$ for all $n,i$ and that there are positive constants $E,d,b$ with $E \geq 1$ such that  $|F, W_{n,i}| \leq E d^n b^i$.  Then the free associative algebra $T(W) = \bigoplus_{r} W^{\otimes r}$ satisfies $|F,T(W)_{n,i}| \leq (2Ed)^n (2b)^i$.
\end{lemm}
\begin{proof}
We have 
	$$|F, T(W)_{n,i}| = \sum_{r \geq 0} \sum_{(n,i) = (n_1,i_1) + \dotsb + (n_r,i_r)} \prod_{s = 1}^r |F, W_{n_s,i_s}|.$$
	By our vanishing hypothesis on $W$, the only non-zero contributions occur when $r \leq n$.
	In particular, since we have $E^{r} \leq E^{n}$ in this range, we conclude that
	$$|F, T(W)_{n,i}| \leq \sum_{r \geq 0} \sum_{(n,i) = (n_1,i_1) + \dotsb + (n_r,i_r)}  E^n d^n b^i. $$  
	Since a positive integer $t$ has $2^{t-1}$ compositions (i.e.~ordered partitions) there are no more than $2^{n-1} 2^{i-1}$ tuples satisfying the hypotheses. 
\end{proof}


\begin{lemm}\label{symbound}
Let $W$ be an $\mathbb{N}^{2}$-bigraded vector space with an endomorphism $F$ that is compatible with the grading.  Suppose that:
\begin{itemize}
\item $W_{0,i} = 0$ for all $n$,
\item $W_{\bullet, 0} := \bigoplus_{n} W_{n,0}$ is finite dimensional, and; 
\item there are positive constants $E,d,b$ with $E \geq 1$ such that $|F, W_{n,i}| \leq E d^n b^i$.
\end{itemize}
Let  $D > 1$ be a constant such that $|F,W_{\bullet,0}| \leq D$.
Then the free symmetric algebra $\Sym(W)$ satisfies $|F,\Sym(W)_{n,i}| = O((n + 1)(i + 1) (\max(2Ed, D))^n (2b)^i)$ (where the implied constants are independent of $n,i$).
\end{lemm}
\begin{proof}
We have that $\Sym(W) = \Sym(W_{\bullet, 0}) \otimes \Sym(\bigoplus_{i > 0} W_{\bullet, i})$.  We may apply \cref{tensoralgebrabound} and appeal to the surjection $T(V) \to \Sym(V)$ to obtain that $|F, (\Sym(\bigoplus_{i > 0} W_{\bullet, i}))_{n,i}| \leq (2Ed)^n (2b)^i$.    Furthermore $$|F, \Sym(W_{\bullet, 0})_{n,0}| \leq |F, \Sym^{ \leq n}(W_{\bullet,0})| \leq \sum_{j\leq n} D^j = O(D^n).$$   So applying \cref{singletensor} to the the tensor decomposition of $\Sym(W)$ we obtain the result.
\end{proof}



\subsection{Homology of configuration space}
Given a poset $P$ with a bottom element $\hat{0}$ and a top element $\hat{1}$, we denote by $H^*(P)$ the reduced cohomology with $\mathbb Q_\ell$-coefficients of the nerve of the open interval $(\hat{0}, \hat{1})$ in $P$.  In particular, when $X$ is a finite set then the poset $\mathrm{P}(X)$ of set partitions admits a bottom and top element and thus it makes sense to discuss $H^{*}(\mathrm{P}(X))$.

\cite[Example 3.14]{Petersen} gives a description of an upper bound for the compactly supported cohomology of the ordered configuration space.  This example is stated when the base field is $\mathbb C$, however the analogous statement over arbitrary fields follows from \cite[Theorem 3.3 (ii)]{Petersen}: 



\begin{theo}\label{ConfigCohom}
	There is a Frobenius and $S_n$-equivariant spectral sequence converging to $H^*_{\text{\'et}, c}(\mathrm{Conf}_n \mathbb P^1_{\overline{k}}, \mathbb Q_\ell)$ with total $E_1$ page given by  
	$$\bigoplus_{\substack{p  \text{ a set partition} \\ \text{of degree $n$}}}    \bigotimes_{\lambda \in p} \left(H_{\text{\'et}}^*(\mathbb P^1_{\overline{k}}, \mathbb Q_\ell)  \otimes H^{|\lambda|-3}(\mathrm{P}(\lambda))[-|\lambda|+1] \right).$$ 
	Summing over all $n$, we obtain a spectral sequence converging to $\oplus_{n} H^*_{\text{\'et}, c}(\mathrm{Conf}_n \mathbb P^1_{\overline{k}}, \mathbb Q_\ell)$ with total $E_1$ page
	$$\mathrm{Sym}\left( H_{\text{\'et}}^*(\mathbb P^1_{\overline{k}}, \mathbb Q_\ell)[1] \otimes \left(\bigoplus_{n} H^{n - 3}(\mathrm{P}(\{1, \dotsc, n\}))[-n] \right) \right),$$ 
	where the symmetric power takes place in the category of symmetric sequences of bigraded vector spaces with Frobenius action.
\end{theo}



We need the following upper bound on the poset homology of the partition lattice.
\begin{prop}[{\cite[Theorem 7.3]{Stanley}}]
         Assume that $K$ is a field of characteristic $0$.
	For all $n \geq 1$, there is an $S_n$-equivariant quotient
	\[
	\overline{K}S_n \to H^{n - 3}(\mathrm{P}(\{1,\dotsc,n\}),\overline{K}),
	\]
	 where $S_n$ acts by left multiplication.
\end{prop}

In particular, for any vector space $V$, there is a surjection 
$$V^{\otimes n} = \overline{K}S_n \otimes_{S_n} V^{\otimes n} \to  H^{n - 3}(\mathrm{P}(\{1,\dotsc, n\}), \overline{K}) \otimes_{S_n} V^{\otimes n}.$$
Combining this with \cref{ConfigCohom} we obtain the following upper bound on $\mathsf L^1$-traces.


\begin{prop} \label{SchurBound}
        Assume that our ground field $k$ is $\mathbb F_q$.
	Let $V$ be a bigraded vector space over $K$.
Suppose that $F$ acts as an endomorphism on $V$ and as the Frobenius on $H^*_{\text{\'et}}(\mathbb P^1_{\overline{k}}, \mathbb Q_\ell)$.
	Then there is an inequality of $\mathsf L^1$-traces 
	$$\left|F, \mathrm{Sym} \left(H^*_{\text{\'et}}(\mathbb P^1_{\overline{k}}, \mathbb Q_\ell)[1] \otimes \bigoplus_{n \geq 1} (V[-1])^{\otimes n} \right)\right| \geq \left|F,  \bigoplus_{m \geq 0}  H_{\text{\'et}, c}^*(\mathrm{Conf}_m \mathbb P^1_{\overline{k}}, \mathbb Q_\ell) \otimes_{S_m} V^{\otimes m}\right|.$$
\end{prop}

Using the estimates of the previous subsection we get the following.

\begin{prop}\label{CombinedBound}
 Assume that our ground field $k$ is $\mathbb F_q$.  
	Let $V$ be a bigraded vector space with an action of $F$ that is concentrated in homological degrees $\geq 2$ (equivalently in cohomological degrees $\leq - 2$) and in grading degree $\geq 1$.  
	We also assume that $F$ acts on $H_{\text{\'et}, c}^*(\mathrm{Conf}_m \mathbb P^1_{\overline{k}}, \mathbb Q_\ell)$ as the Frobenius. Suppose that $|F, V_{\bullet, 2}| \leq D$.  If $|F, V_{n,i}| \leq E d^n b^i$ for some $E, d ,b > 0$  
	with $E \geq 1$
	and $b<1$, then $W:= \oplus_m H_{\text{\'et}, c}^*(\mathrm{Conf}_m \mathbb P^1_{\overline{k}}, \mathbb Q_\ell) \otimes_{S_m} V^{\otimes m}$  is concentrated in homological degrees $\geq 0$ and satisfies 
	$$|F, (W_{n,i})_{S_n} | = O\left(ni \max\left(2Ed + 8Edb^2q, D\right)^n (4b)^i\right). $$ 
\end{prop}
\begin{proof}
 	By  \cref{SchurBound} it suffices to bound the $\mathsf L^1$-trace on 
	$$\mathrm{Sym}(H_{\text{\'et}}^*(\mathbb P^1_{\overline{k}}, \mathbb Q_\ell)[1] \otimes \bigoplus_{n \geq 1} (V[-1])^{\otimes n}).$$ Applying \cref{tensoralgebrabound} to $V[-1]$ we obtain that 
	\[
	|F, (\bigoplus_{m\geq 1}  (V[-1])^{\otimes m})_{n,i} | \leq (2Eba)^n (2b)^i.
	\]  
	So $|F, (\bigoplus_{m \geq 1} H_{\text{\'et}}^*(\mathbb P^1_{\overline{k}}, \mathbb Q_\ell)[1] \otimes  (V[-1])^{\otimes m} )_{n, i} | \leq (\frac{1}{2b} +   2bq) (2Ebd)^n (2b)^i $. 
	Therefore applying \cref{symbound} to $\bigoplus_{m \geq 1} H_{\text{\'et}}^*(\mathbb P^1_{\overline{k}}, \mathbb Q_\ell)[1] \otimes  (V[-1])^{\otimes m}$  (observing that the homological degree zero component of this space is $V_{\bullet,2}$) we obtain the result.
\end{proof}



\subsection{Simplicial schemes and cohomology}

We next discuss simplicial schemes and their cohomology.  We follow closely the exposition of \cite[Section 2.2]{DH24}. (For a more classical reference, one may consult Brian Conrad's notes \cite{Conrad}.)



\begin{defi} %[{\cite[Definition 2.1.1]{DH24}}]
Let $\Delta$ be the simplex category whose objects are non-empty finite subsets of $\mathbb N$ and whose morphisms are non-decreasing maps.  A simplicial scheme is a functor $\Delta^{\mathrm{op}} \to \mathrm{sSch}$ where $\mathrm{sSch}$ is the category of separated schemes.  A morphism between simplicial schemes is a natural transformation of functors.

For each $n \in \mathbb N$, we write $[n] = \{0, \dotsc, n\} \in \Delta$.  Then a simplicial scheme is determined by its values on the full subcategory $\{ [n] \, |\,  n \in \mathbb N \} \subset \Delta^{\mathrm{op}}$. 

Given a separated scheme $X$, the constant simplicial scheme $X_{\bullet}$ is defined by setting $X_\bullet([n]) = X$ for every $n \in \mathbb N$ and setting all maps to be $\mathrm{id}_X$.  
Throughout the paper, we frequently drop $\bullet$ and identify separated schemes and constant simplicial schemes.
\end{defi}

\begin{defi} %[{\cite[Section 2.1.5]{DH24}}]
Let $X$ be a separated scheme and $A$ be a simplicial scheme. Then an augmentation morphism from $A$ to $X$ is a morphism $\epsilon: A \to X$ in the category of simplicial schemes. \end{defi}


For any separated scheme 
$X$, we let $\mathrm{Sh}(X)$ denote the abelian category of $\mathbb Z_\ell$-module sheaves in the pro-\'etale topology as in \cite{BS15} and let $D^b(X)$ denote the associated bounded derived category.

Suppose that $A$ is a simplicial scheme; 
as mentioned earlier we can work with $A$ by restricting our attention to the full subcategory $\{ [n] \, |\,  n \in \mathbb{N} \} \subset \Delta^{\mathrm{op}}$. A $\mathbb Z_\ell$-sheaf on $A$ is a family of $\mathbb Z_\ell$-sheaves $\mathcal F_n$ on $A([n])$ in the pro-\'etale topology equipped with a compatible family of maps $A(i)^*\mathcal F_n \to \mathcal F_m$ for $i : [n] \to [m]$.
Let $\mathrm{Sh}(A)$ be the category of $\mathbb Z_\ell$-sheaves on $A$.  This is an abelian category with enough injective objects and thus the formalism of derived categories works in this settings. We denote the corresponding bounded derived category by $D^b(A)$. (For more details, see \cite[Section 2.2]{DH24}.)

Let $X$ be a separated scheme and let $A$ be a simplicial scheme with an augmentation $\epsilon : A \to X$. We next define the following functors:
\[
\epsilon_* : \mathrm{Sh}(A) \to \mathrm{Sh}(X), \quad \epsilon^* : \mathrm{Sh}(X) \to \mathrm{Sh}(A).
\]
First, for any sheaf $\mathcal G$ on $X$ we define $(\epsilon^*\mathcal G)_n = \epsilon_n^*\mathcal G$ with the natural identification $A(i)^*\epsilon_n^* \mathcal G \cong \epsilon^*_m\mathcal G$ coming from $\epsilon_m = \epsilon_n \circ A(i)$ where $i : [n] \to [m]$. The adjoint pushforward $\epsilon_*$ is given by $\epsilon_* \mathcal F= \mathrm{Eq}(\epsilon_{0 *}\mathcal F_0 \rightrightarrows \epsilon_{1*}\mathcal F_1)$ for any sheaf $\cF$ on $A$.  
These induce the derived functors:
\[
R\epsilon_* : D^b(A) \to D^b(X), \quad  \epsilon^* : D^b(X) \to D^b(A).
\]
\begin{rema}
There is a concrete description of $R \epsilon_*$: given a complex $\cI^\bullet$ of sheaves on $A$ such that $(\cI^i)_n$ is an injective sheaf on $A_n$ for every $i,n$, we may construct a representative of $R \epsilon_*\cI^\bullet$ as follows.   Take the chain complex of cosimplicial sheaves $[n] \mapsto \epsilon_{n*} \cI^\bullet$, form a bicomplex by applying the functor that takes a cosimplicial sheaf to its (normalized) chain complex, and then take the total complex.  (This construction works because we may factor $\epsilon_*$ as a pushforward to sheaves on the constant simplicial scheme on $X_\bullet$, followed by the functor from simplicial sheaves on $X_\bullet$ to sheaves on $X$ given by taking the limit over $\Delta$.  Because the pushforward preserves injectives, $R\epsilon_*$ factors as a composite of derived functors,  and the levelwise injectives are acyclic for the pushforward to $X_\bullet$, while the derived functor of the limit over $\Delta$ is modeled by the (normalized)  total complex.)
\end{rema}

\begin{rema}\label{Simplicial_Model}
	As a consequence of the previous remark, we note that if $X = \Spec ( \overline k)$ and $A_n$ is finite \'etale over  $X$ for all $n$ (so that $A$ corresponds to a simplicial set) then $R \epsilon_* \mathbb Z_l$ is canonically isomorphic to the normalized $\mathbb Z_l$ cochains on $A$ (considered as a simplicial set).
\end{rema}

Now suppose that $\pi : X\to \Spec \, k$ is a $k$-separated scheme where $k$ is a field.  We use the derived functor to define cohomology as
\[
H^i_{\text{\'et}}(A, \mathcal F) := H^i_{\text{\'et}}(R(\pi \circ \epsilon)_*\mathcal F).
\]
When the augmentation $\epsilon : A \to X$ is proper, i.e, for every $n \in \mathbb Z_{\geq 0}$ the morphism $\epsilon_n : A_n \to X$ is proper, we define cohomology with compact supports as
\[
 H^i_{\text{\'et}, c}(A, \mathcal F) := H^i_{\text{\'et}}(R\pi_! \circ R\epsilon_*\mathcal F).
\]
Finally when we have the constant sheaf $\mathcal F = \underline{\mathbb Z}_\ell$ or $\underline{\mathbb Q}_\ell$ on $X$, we have a natural morphism
\[
\mathcal F \to R\epsilon_*\epsilon^*\mathcal F.
\]
In particular, we have an induced homomorphism between cohomologies
\[
H^i_{\text{\'et}}(X, \mathbb Z_\ell) \to H^i_{\text{\'et}}(A, \mathbb Z_\ell). 
\]
When the augmentation $\epsilon : A \to X$ is proper, we also have an induced homomorphism
\[
H^i_{\text{\'et}, c}(X, \mathbb Z_\ell) \to H^i_{\text{\'et}, c}(A, \mathbb Z_\ell). 
\]



\subsection{Poschemes and the bar complex}



Following \cite[Section 2.2]{DT24}, we recall the notion of poschemes and the construction of the bar complex.




\begin{defi} %[{\cite[Definition 3.1.1]{DH24}}]
Let $S$ be a scheme.
A poscheme over $S$ is a finite type morphism $P \to S$ with a closed poset relation $\leq_P \subset P\times_{S} P$, i.e., for any scheme $T \to S$ the pair $(P(T), \leq_P(T))$ is a poset. 
We denote the poscheme obtained by swapping the two coordinates of $\leq_P$ by $\geq_P$. Then we have $\Delta_{P/S} = \leq_P\cap \geq_P$. In particular, $\Delta_{P/S}$ is closed so that $P \to S$ is separated.
\end{defi}



 In this paper, we will usually work with poschemes $P \to S$ which are proper and will usually assume that $\Delta_{P/S}$ is also open in $\leq_P$ so that the relation $<_{P} := \leq_{P} \! \backslash \Delta_{P/S}$ is closed.  Whenever we discuss a finite poset $Q$, we will implicitly think of it as a finite poscheme over the ground field $k$ consisting entirely of $k$-points.  



\begin{defi}
Let $P$ be a poscheme over $k$. The nerve $N(P)$ associated to $P$ is the simplicial scheme which assigns to $[n]$ the scheme
\[
N(P)([n]) = \leq_P \times_P \dotsb \times_P \leq_P = \{ p_0 \leq \dotsb \leq p_n \, | \, (p_i \leq p_{i + 1}) \in \leq_P \text{ for any $i = 0, \dotsc, n-1$} \},
\]
and which assignes to a non-decreasing map $i: [n] \to [m]$ the morphism
\[
N(P)([m]) \to N(P)([n]), \, (p_0 \leq \dotsb \leq p_m) \mapsto (p_{i(0)} \leq \dotsb \leq p_{i(n)}).
\]
\end{defi}

We will frequently work not just with poschemes $P$ but also with schemes $Z$ that admit stratifications indexed by a poscheme $P$.  The following definitions make this notion precise.  



\begin{defi} %[{\cite[Section 2.2]{DT24}}]
Let $P$ be a poscheme over $S$. A $P$-space consists of an 
$S$-morphism $Z \to P$ with another $P$-morphism
\[
a : \leq_P \! \times_{\pi_2} Z \to Z,
\]
where $\pi_i : \leq_P \subset P\times_{S} P \to P$ denotes the projection map to the $i$th factor and $\leq_P \! \times_{\pi_2} Z $ is considered as a $P$-scheme via $\pi_1$. For any $S$-morphism $T \to P$, we denote the base change of $Z \to P$ over $T \to P$ by $Z_T$.
\end{defi}


\begin{defi} %[{\cite[Definition 2.4]{DT24}}]
Let $X$ be a scheme of finite type over $S$ and $P$ be a poscheme over $S$. A stratification of $X$ by $P$ is a closed subscheme $Z \subset P\times_{S} X$ such that the morphism
\begin{align*}
\leq_P \! \times_{\pi_2} Z & \to P\times_{S} X, \\
(p \leq q, z \in Z_q) & \mapsto (p, \rho (z)),
\end{align*}
factors through $Z$ where $\rho : Z \subset P \times_{S} X \to X$ is the projection.  
In other words, for any $p, q \in P$ with $p \leq q$ we have $Z_q \subset Z_p$.  Note that $Z$ carries the structure of a $P$-space.
\end{defi}

The analogue of the nerve construction for a $P$-space is known as the bar complex.  


\begin{defi}[{\cite[Definition 2.3]{DT24}}]
Let $P$ be a poscheme over $S$ such that $\Delta_P$ is open in $\leq_P$. 
Let $Z$ be a $P$-space.
The bar complex $B(P, Z)$   
is the simplicial scheme which assigns to $[n]$ the scheme
\[
B(P, Z)([n]) = \leq_P \! \times_P \dotsb \times_P \leq_P \! \times_P Z = \{ p_0 \leq \dotsb \leq p_n, z \in Z_{p_n}\}
\]
and which assigns to a non-decreasing map $i : [n] \to [m]$ the morphism 
\[
B(P, Z)([m]) \to B(P, Z)([n]), \, (p_0 \leq \dotsb \leq p_m, z) \mapsto (p_{i(0)}\leq \dotsb \leq p_{i(n)}, a(p_{i(n)} \leq p_{m},z)).
\]
\end{defi}


\subsubsection{Relative posets} \label{sect:relativeposets}

We will also need analogues of the previous constructions in a relative setting.


\begin{defi} %[{\cite[Definition 2.5]{DT24}}]
\label{defi:relativebarcomplexes}
Let $H$ be a poscheme over $k$ such that $\Delta_H$ is open in $\leq_H$. Let us fix a locally closed subscheme $W \subset H$ and define the poscheme
\[
(W < H) = \{ (w, x) \in W \times H\, | \, w < x\},
\]
with the poset structure
\[
\leq_{W<H} = \{(w < x_1, w < x_2) \, | \, x_1 \leq x_2\}.
\]
This is a poscheme over $W$. %in the sense of \cite[Definition 3.1.1]{DH24}.
\end{defi}

Let $X$ be a separated scheme of finite type over $W$ and $Z \subset (W < H) \times_W X$ be a stratification of $X$ by $(W < H)$.  
Let $P \subset (W < H)$ be a closed and downward closed subscheme.
Then we define the simplicial scheme $B(P, Z)$ to be the bar complex applied to $P$ and $Z$.   
In other words
\[
B(P, Z)([n]) = B(P, Z)([n]) = \{ w <  x_0 \leq \dotsb \leq x_n, z \in Z_{w < x_n} \}.
\]
This admits the augmentation morphism 
\[
\epsilon : B(P, Z)([n]) \to X, \, (w < x_0 \leq \dotsb \leq x_n, z) \mapsto (w, \rho(z) \in X_w).
\]






\subsection{Spectral sequences for the inclusion-exclusion principle for stratified schemes}
\label{subsec:spectralsequenceforstratifiedspaces}

The following exposition is based on \cite[Section 2.1]{DT24}.
Let $k$ be a perfect field and let $X$ be a separated scheme of finite type over $k$. %Let $\underline{\mathbb Z}_{\ell}$ be the constant sheaf on $X_{\overline{k}}$ 
%in the pro-\'etale topology as in \cite{BS15}.
%Then the $\ell$-adic cohomology $H^i_{\text{\'et}, c}(X_{\overline{k}}, \mathbb Z_\ell)$ with compact supports is defined as the sheaf cohomology for $\underline{\mathbb Z}_{\ell}$, i.e., if $\pi : X_{\overline{k}} \to \Spec \, \overline{k}$ denotes the structure morphism then the $\ell$-adic cohomology with compact supports is $H^i_{\text{\'et}}(R\pi_! \underline{\mathbb Z}_{\ell})$.

Suppose that we have a finite filtration by closed subschemes: 
\[
Z_0 \subset  Z_1 \subset \dotsb \subset  Z_n = X.
\]
This induces a co-filtration of complexes
\[
\underline{\mathbb Z}_{\ell} \to i_{n-1!}\underline{\mathbb Z}_{\ell}|_{(Z_{n-1})_{\overline{k}}} \to \dotsb \to i_{0!}\underline{\mathbb Z}_{\ell}|_{(Z_0)_{\overline{k}}}
\]
and thus a spectral sequence with $E_1$-page
\[
E_1^{i, j} = H^{i + j}_{\text{\'et}, c}((U_i)_{\overline{k}}, \mathbb Z_\ell),
\]
converging to $H^{i+j}_{\text{\'et}, c}(X_{\overline{k}}, \mathbb Z_\ell)$ where $U_i = Z_i \setminus Z_{i-1}$.

We extend this spectral sequence to spaces stratified by posets.
Suppose that we have a finite poset $P$ and a collection of closed subschemes $Z_p \subset X$ for $p \in P$ such that $Z_p \supset Z_q$ whenever $p \leq q$.
We let $S_p = Z_p \setminus \cup_{p < q} Z_q$ which is a locally closed subscheme of $X$.
Since $P$ is finite, we may choose an injective homomorphism $h : P \to (\mathbb N, \leq)$.
We define $n$ to be $\max h(P)$ and set 
$K_i : = \cup_{h(p) \geq n-i} Z_p$ with the reduced scheme structure.  We obtain the associated filtration:
\[
\emptyset = K_{-1} \subset K_0 \subset \dotsb \subset K_n \subset X
\]

First suppose that for any $x \in X$ the set $\{p \in P \, | \, x \in Z_p\}$ has a maximal element. In particular this shows that $S_p \cap S_q = \emptyset$ whenever $p \neq q$.
This assumption implies that we have $K_{i} \setminus K_{i-1} = S_{h^{-1}(n-i)}$  
and there is a spectral sequence with $E_1$-page 
\[
E_1^{i, j} =  H^{i + j}_{\text{\'et}, c}((S_{h^{-1}(n-i)})_{\overline{k}}, \mathbb Z_\ell)
\]
converging to $H^{i + j}_{\text{\'et}, c}((K_n)_{\overline{k}}, \mathbb Z_\ell)$. 
Note that for each $n$ we have 
\[
\bigoplus_{i + j = n} E_1^{i, j} = \bigoplus_{p \in P} H^{n}_{\text{\'et}, c}((S_p)_{\overline{k}}, \mathbb Z_\ell)
\]
so that this direct sum is independent of the choice of $h$. However the differentials depend on the choice of $h$.



When the above assumption fails, we can define Zariski open subsets
\[
S'_{h^{-1}(n-i)} := K_i \setminus K_{i -1} \subset S_{h^{-1}(n-i)},
\]
and we still have a spectral sequence with $E_1$-page
\begin{equation} \label{eq:stratss}
E_1^{i, j} = H^{i + j}_{\text{\'et}, c}((S'_{h^{-1}(n-i)})_{\overline{k}}, \mathbb Z_\ell),
\end{equation}
converging to $H^{i + j}_{\text{\'et}, c}((K_n)_{\overline{k}}, \mathbb Z_\ell)$.
However, note that the definition of $S'_{h^{-1}(n-i)}$, and thus also the terms in the spectral sequence, depends on the choice of $h$.

Finally we introduce a version of this spectral sequence for bar complexes.
We work in the setting of \cref{sect:relativeposets} so that $X$ is a separated scheme of finite type over $W$ with a stratification $Z$ by $(W<H)$ with $P \subset (W < H)$.
We assume that $P$ is proper over $W$.
Suppose that our poscheme $P$ over $W$ admits a stratification by a finite poset $\mathfrak T = \{ T \in \mathfrak T\}$ via the collection of closed subschemes $\mathcal Z_T \subset P \to W$ such that $\mathcal Z_T$ is downward closed with respect to the poset structure over $W$ and $\mathcal Z_T \subset \mathcal Z_{T'}$ whenever $T\leq T'$.  We also assume that for any $(w < x) \in P$, the set $\{ T \in \mathfrak T \, | \, (w < x) \in \mathcal Z_T\}$ has a minimal element.  
Again we fix an injective homomorphism $h : \mathfrak T \to \mathbb N$.
We define 
\[
\mathcal Z_i = \cup_{h(T)\leq i} \mathcal Z_T.
\]
We denote the inclusion $\mathcal Z_i \subset P$ by $\iota_i$, and we consider the sub-bar complex
\[
\iota'_i : B_i = B(\mathcal Z_i, \iota_{i}^*Z) \hookrightarrow B(P, Z),
\]
which induces a stratification of closed simplicial schemes 
\[
\emptyset = B_{-1} \subset B_0 \subset \dotsb \subset B_n = B(P, Z)
\]
This induces a co-filtration:
\[
\underline{\mathbb Z}_{\ell} \to \iota'_{n-1!}\underline{\mathbb Z}_{\ell}|_{(B_{n-1})_{\overline{k}}} \to \dotsb \to \iota'_{0!}\underline{\mathbb Z}_{\ell}|_{(B_0)_{\overline{k}}} \to 0.
\]
We denote the induced filtration by
\[
0 = F^n\underline{\mathbb Z}_{\ell} \to F^{n-1}\underline{\mathbb Z}_{\ell} \to F^{n-2}\underline{\mathbb Z}_{\ell} \to \dotsb \to F^{-1}\underline{\mathbb Z}_{\ell} = \underline{\mathbb Z}_{\ell}.
\]
Then the graded part is given by
\[
\mathrm{Gr}_F^i\underline{\mathbb Z}_{\ell} = F^{i-1}\underline{\mathbb Z}_{\ell}/F^{i}\underline{\mathbb Z}_{\ell},
\]
and this gives rise to a spectral sequence
\[
E_1^{i, j} = H^{i + j}_{\text{\'et}, c}(B(P, Z)_{\overline{k}}, \mathrm{Gr}_F^i\underline{\mathbb Z}_{\ell} ) \implies H^{i + j}_{\text{\'et}, c}(B(P, Z)_{\overline{k}}, \mathbb Z_\ell).
\]








\section{Rational curves on del Pezzo surfaces}
\label{sec:ratondel}

In this section we collect several preliminary results about the nef cone and rational curves on degree $4$ del Pezzo surfaces.  We will focus on del Pezzo surfaces satisfying the following condition:

\begin{defi}
Let $S$ be a smooth del Pezzo surface of degree $\leq 7$ over a field $k$.  We say that $S$ is split if it satisfies any of the following equivalent conditions:
\begin{itemize}
\item the pullback map $\Pic(S) \to \Pic(S_{\overline{k}})$ is an isomorphism;
\item every $(-1)$-curve on $S_{\overline{k}}$ is defined over $k$;
\item the Picard ranks $\rho(S)$ and $\rho(S_{\overline{k}})$ are equal.
\end{itemize}
\end{defi}

\subsection{Nef cone}

Suppose that $S$ is a split del Pezzo surface of degree $4 \leq d \leq 7$.  Then:
\begin{itemize}
\item The pseudo-effective cone of $S$ is generated by classes of $(-1)$-curves.
\item The nef cone of $S$ is generated by fibers of conic fibrations $S \to \mathbb{P}^{1}$ and pullbacks of the hyperplane class under birational morphisms $S \to \mathbb{P}^{2}$.
\end{itemize}
We will impose a chamber decomposition on $\Nef_{1}(S)$ using the following structures which were used previously by \cite[Corollary 2.3]{Testa09}.

\begin{lemm}
Let $S$ be a split del Pezzo surface of degree $4 \leq d \leq 7$.  For any class $\alpha \in \Nef_{1}(X)_{\mathbb{Z}}$, there is a non-negative integer $b$, a contraction of a $(-1)$-curve $\psi: S \to Y$, and a nef class $\beta \in \Nef_{1}(Y)_{\mathbb{Z}}$ such that $\alpha = -bK_{S} + \psi^{*}\beta$.

Furthermore if $\beta$ is ample then the choice of $b,\psi,\beta$ is unique.
\end{lemm}

\begin{proof}
Every codimension $1$ extremal face of $\Nef_{1}(S)$ is the pullback of $\Nef_{1}(Y)$ for some contraction of a $(-1)$-curve $\psi: S \to Y$.  Consider the subdivision of $\Nef_{1}(S)$ where the top-dimensional subcones are generated by $-K_{S}$ and a codimension $1$ extremal face.  Every nef class is contained in some cone in this subdivision, yielding an expression of the form $\alpha = -bK_{S} + \psi^{*}\beta$ for some $b \in \mathbb{R}_{\geq 0}$ and $\beta \in \Nef_{1}(Y)$.  Since $b = \alpha \cdot E$ where $E$ is the contracted curve we see that $b \in \mathbb{Z}$, and hence $\beta$ is also an integral class.  Finally if $\beta$ is ample then there is only one full-dimensional cone in this subdivision whose closure contains $\alpha$.  
\end{proof}

Applying the lemma repeatedly, we obtain:

\begin{prop} \label{prop:nefexpression}
Let $S$ be a split del Pezzo surface of degree $4$ and let $\alpha \in \Nef_{1}(X)_{\mathbb{Z}}$.  Then there is a sequence of contractions of $(-1)$-curves
\begin{equation*}
S \to S_3 \to S_2 \to S_1
\end{equation*} 
with the following property: writing $\psi_{i}: S \to S_i$ for the induced map, $H$ for the unique pullback of a hyperplane class on $\mathbb{P}^{2}$ to $S_1$, and $F_{1},F_{2}$ for the two classes of conics on $S_1$, there are non-negative integers $b, b_{3},b_{2},x,y_{1},y_{2}$ with
\begin{equation} \label{eq:alphaexpression}
\alpha = -bK_{S} - b_{3}\psi_{3}^{*}K_{S_{3}} - b_{2} \psi_{2}^{*}K_{S_{2}} + \psi_{1}^{*}(xH + y_{1}F_{1} + y_{2}F_{2}).
\end{equation}
If all these integers (except possibly $b$) are positive, then there is a unique sequence of contractions of three disjoint $(-1)$-curves such that $\alpha$ admits such an expression.
\end{prop}

\begin{defi} \label{defi:regions}
Suppose $\vec{E} = (E_{1},E_{2},E_{3})$ is an ordered triple of disjoint $(-1)$-curves.  We define $\mathcal T_{\vec{E}} \subset \Nef_{1}(S)$ to be the subcone generated by all curve classes $\alpha \in \Nef_{1}(S)_{\mathbb{Z}}$ which admit an expression as in \cref{eq:alphaexpression} for the ordered sequence of contractions of $E_{1},E_{2},E_{3}$.
\end{defi}

The arrangement of $(-1)$-curves on a split degree $4$ del Pezzo surface are described by the $5$-regular Clebsch graph so there are 960 
choices of ordered triples of disjoint $(-1)$-curves.  (The Weyl group $D_{5}$ has order $1920$; its action on this set of triples has stabilizer of order $2$ corresponding to identifying one of the two conic fibrations $S_{1} \to \mathbb{P}^{1}$.)  
\cref{prop:nefexpression} shows that as we vary $\vec{E}$ over all such choices, the union of the subcones $\mathcal T_{\vec{E}}$ is all of $\Nef_{1}(S)$ and the intersections of their interiors are empty.  We will use this subdivision of $\Nef_{1}(S)$ in later sections.

\begin{nota} \label{nota:bignota}
Fix $\alpha \in \Nef_{1}(S)$.  By an abuse of notation, we denote by $\mathcal T_{\alpha}$ any region as in \cref{defi:regions} that contains $\alpha$.  (We will only use this notation when the choice of $\mathcal T_{\alpha}$ is irrelevant.)

Retaining the notation of \cref{prop:nefexpression}, we define $\rho_{\alpha}: S \to \mathbb{P}^{1} \times \mathbb{P}^{1}$ to be the composition of $\psi_{1}$ with the contraction of the unique $(-1)$-curve yielding a map to $\mathbb{P}^{1} \times \mathbb{P}^{1}$.  Labeling the strict transform of this curve on $S$ as $E_{4}$, we write $(E_{1},E_{2},E_{3},E_{4})$ for the corresponding tuple of disjoint $(-1)$-curves on $S$.

We define $p_{\alpha}: S \to \mathbb{P}^{1}$ to be the composition of $\rho_{\alpha}$ with the projection to the first factor.  We let $F_{\alpha}$ denote a general fiber of $p_{\alpha}$.  Finally we define the non-negative integers
\begin{gather*}
h(\alpha) = -K_{S} \cdot \alpha \qquad \qquad a(\alpha)  = F_{\alpha} \cdot \alpha \qquad \qquad k_{i} = E_{i} \cdot \alpha \\
a'(\alpha)  = \frac{1}{2} \left( h(\alpha) - 2a(\alpha) + \sum_{i=1}^{4} k_{i}(\alpha) \right)
\end{gather*}
Note that $a'(\alpha)$ is the intersection of $\alpha$ against a fiber $F'_{\alpha}$ of the composition of $\rho_{\alpha}$ with the second projection map $\mathbb{P}^{1} \times \mathbb{P}^{1} \to \mathbb{P}^{1}$.  We will sometimes surpress the $\alpha$ from $\rho,p,F,h,a,a',k_{i}$ in situations where it can be understood.  We write $\mathbf{k} = (k_{1},k_{2},k_{3},k_{4})$.  In the notation of \cref{eq:alphaexpression} we have: 
\begin{gather*}
\begin{aligned}
-K_{S} \cdot \alpha & = 4b + 5b_{3} + 6b_{2} + 3x + 2y_{1} + 2y_{2} \\
F_{\alpha} \cdot \alpha &= 2b + 2b_{3} + 2b_{2} + x + y_{1}
\end{aligned}\\
E_{1} \cdot \alpha = b \qquad E_{2} \cdot \alpha = b + b_{3} \qquad E_{3} \cdot \alpha = b  + b_{3} + b_{2} \qquad E_{4} \cdot \alpha = b + b_{3} + b_{2} + x
\end{gather*}
yielding the inequalities
\begin{equation*}
h(\alpha) \geq 2a(\alpha) \geq \sum_{i=1}^{4} k_{i}(\alpha).
\end{equation*}
If $\alpha$ lies in the interior of $\mathcal{T}_{\alpha}$ then the inequalities are all strict.  The same inequalities hold for $a'(\alpha)$ by symmetry.
\end{nota}






\subsection{Rational curves}

We next address the geometry of rational curves on $S$.  Since maps to $(-1)$-curves are ignored both by Manin's Conjecture and by the Cohen-Jones-Segal conjecture, we will concentrate on rational curves whose numerical classes are nef.  Given a class $\alpha \in N_{1}(S)_{\mathbb{Z}}$, we denote by $\Mor(\mathbb{P}^{1},S)_{\alpha}$ the space of morphisms $s: \mathbb{P}^{1} \to S$ such that $s_{*}[\mathbb{P}^{1}] = \alpha$.


\begin{theo}[{\cite{Testa09}, \cite{BLRT21}}]
\label{theo: Testa}
Let $S$ be a del Pezzo surface of degree $4$ over a field $k$.  For every $\alpha \in \mathrm{Nef}_1(S)_{\mathbb{Z}}$ the moduli space $\Mor(\mathbb{P}^{1},S)_{\alpha}$ is geometrically irreducible of the expected dimension and generically parametrizes free curves.
\end{theo}



\begin{proof}
It suffices to prove the statement when $k$ is algebraically closed.  \cite[Corollary 5.2]{Testa09} addresses characteristic $0$ and \cite[Theorem 1.5]{BLRT21} addresses positive characteristic.
\end{proof}

\begin{nota}
Given a nef curve class $\alpha \in \Nef_{1}(S)_{\mathbb{Z}}$, we will denote by $M_{\alpha}$ the scheme $\Mor(\mathbb{P}^{1},S)_{\alpha}$ as in \cref{theo: Testa}.  
\end{nota}

We will verify in \cref{lemm:psismooth} that $M_{\alpha}$ is smooth over every field.





\section{Curves and conic bundle structures}
\label{sec:curvesandconicbundle}

Let $S$ be a split degree $4$ del Pezzo surface over a field $k$.  Suppose we fix a nef class $\alpha \in \Nef_{1}(S)_{\mathbb{Z}}$ along with the associated constructions in \cref{nota:bignota}.  Note that $p: S \to \mathbb{P}^{1}$ induces a morphism $p_{*}: \Mor(\mathbb{P}^{1},S) \to \Mor(\mathbb{P}^{1},\mathbb{P}^{1})$ sending $M_{\alpha}$ to the irreducible component $N_{a}$ that parametrizes morphisms of degree $a(\alpha) := F \cdot \alpha$.  In this section we will construct a factorization
\begin{equation*}
\xymatrix{
M_{\alpha} \ar[rr]^{p_{*}} \ar[dr]_{\psi_{\alpha}} & & N_{a} \\
& R_{\alpha} \ar[ur]_{\pi_{\alpha}} &
}
\end{equation*}
where $\psi_{\alpha}$ is smooth surjective with connected fibers and $\pi_{\alpha}$ is quasi-finite.  The key result in this section is that $M_{\alpha}$ is an open subset of a Zariski-locally trivial projective bundle over $R_{\alpha}$ and in turn $R_{\alpha}$ is an open subset of a Zariski-locally trivial projective bundle over an open subset of a product of projective spaces.  In particular, $M_{\alpha}$ is smooth.



