\subsection{Compactification of $R_{\alpha}$} \label{sect:compactza}

In this subsection we work over a ground field different than $\mathbb{F}_{2}$.   
We fix an integer $a \geq 1$ and a ordered tuple of non-negative integers $\mathbf{k} = (k_{1},k_{2},k_{3},k_{4})$ with $k_i \leq a$ for any $i = 1, \dotsc, 4$.  

To improve clarity of exposition, we continue to write $B := \mathbb{P}^{1}$ for the domain of our maps.  The space $N_{a} = \Mor(B,\mathbb{P}^{1})_a$ 
parametrizing degree $a$ morphisms is (by definition) the open sublocus of the linear system $|\mathcal{O}(a,1)| $ on $B \times \mathbb{P}^{1}$ that parametrizes sections.  We will identify $\mathbb{P}^{2a+1}$ with the linear system $|\mathcal{O}(a,1)|  = \mathbb {P}(H^0(B \times \mathbb P^1, \cO(a,1)))$.  We fix four $k$-points $p_{1},p_{2},p_{3},p_{4} \in \mathbb{P}^{1}$ and let $B_{1},B_{2},B_{3},B_{4}$ denote the corresponding fibers of the second projection map for $B \times \mathbb{P}^{1}$.  (The $p_{i}$ will eventually represent images of the singular fibers of $S \to \mathbb{P}^{1}$.)

\begin{defi}
We define the closed subscheme
\begin{equation*}
Z_{a, \mathbf{k}} \subset \mathbb{P}^{2a+1} \times \mathrm{Hilb}^{[k_1]}(B_1) \times \mathrm{Hilb}^{[k_2]}(B_2) \times \mathrm{Hilb}^{[k_3]}(B_3) \times \mathrm{Hilb}^{[k_4]}(B_4)
\end{equation*}
as the incidence correspondence
\[
Z_{a, \mathbf{k}} = \{([C], [T_{1}], [T_{2}], [T_{3}], [T_{4}])  | \, T_{i} \subset C \cap B_{i} \text{ for $i = 1, \dotsc, 4$}\}
\]
where we have identified $\mathbb{P}^{2a+1} \cong |\mathcal{O}(1,a)|$ on $B \times \mathbb{P}^{1}$.  We call $Z_{a, \mathbf{k}}$ a \textit{configuration cover}. 


We let $Z_{a, \mathbf{k}}^{\circ}$ denote the preimage of $N_{a} \subset \mathbb{P}^{2a+1}$ under the projection map. This is the space of degree $a$ maps $s : B \to \mathbb P^1$ together with divisors $T_1, \dotsc, T_4 \subset B$ such that $T_i \subset s^*(p_i)$.

\end{defi}

Our next goal is to study the properties of $Z_{a, \mathbf{k}}$ and $Z_{a, \mathbf{k}}^{\circ}$.


\begin{prop}
\label{prop:locallycompleteintersectionZ}
The space $Z_{a, \mathbf{k}}  \subset \mathbb P^{2a+1} \times \prod_{i = 1}^{4}\mathrm{Hilb}^{[k_i]}(B_i)$ is the zero locus of a section of a globally generated vector bundle of rank $\sum_{i = 1}^4k_i$. 
\end{prop}

\begin{proof}
For simplicity of notation we will write $Y = \mathbb P^{2a+1} \times \prod_{i = 1}^{r}\mathrm{Hilb}^{[k_i]}(B_i)$.
Let $\mathcal C$ be the universal family over $\mathbb{P}^{2a+1}$ parametrizing divisors of type $(a, 1)$ in $B \times \mathbb{P}^{1}$.  If we define $\mathcal L = \mathcal O_{B \times \mathbb{P}^{1} \times \mathbb P^{2a+1}}(a, 1, 1)$, then $\mathcal{C}$ is the vanishing locus of a section $s \in H^0(B \times \mathbb{P}^{1} \times \mathbb P^{2a+1}, \mathcal L)$.
We denote the projection $B \times \mathbb{P}^{1} \times Y \to B \times \mathbb{P}^{1} \times \mathbb P^{2a+1}$ by $q$.

Next let
\[
\mathcal U_i' \subset B_i \times \mathrm{Hilb}^{k_i}(B_i)
\]
be the universal family of the Hilbert scheme and let $\mathcal{U}_{i}$ be its base change to $B_i \times Y$.
We consider the projection $\rho_i : \mathcal U_i \to Y$.
Since this is a flat finite morphism of degree $k_i$ we conclude that $\mathcal E_i = (\rho_i)_*(q^*\mathcal L|_{\mathcal U_i})$ is a locally free sheaf of rank $k_i$.
Then $q^*s$ defines a global section of the locally free sheaf $\mathcal E = \oplus_{i = 1}^r \mathcal E_i$ whose zero locus is equal to $Z_{a, \mathbf{k}}$.



It only remains to show that $\mathcal{E}$ is globally generated.  It suffices to prove that each $\mathcal{E}_{i}$ is globally generated.  Note the fiber of $\mathcal{E}_{i}$ over a point $y \in Y$ is $H^{0}(T,\mathcal{O}(a))$ where $T \subset B_{i}$ is the length $k_{i}$ subscheme defined by the point in $\Hilb^{k_{i}}(B_{i})$ corresponding to $y$.
Thus the composition $H^{0}(Y,\mathcal{E}_{i}) \otimes \mathcal{O}_{Y} \to \mathcal{E}_{i} \to \mathcal{E}_{i}|_{y}$ can be identified with  
\[
H^0(B \times \mathbb{P}^{1} \times \mathbb{P}^{2a+1}, \mathcal L) = H^{0}(B \times \mathbb{P}^{1} \times Y,q^*\mathcal L) \to H^{0}(\mathcal U_{i},q^*\mathcal L|_{\mathcal U_i}) \to H^0(T, \mathcal O(a))
\]
which is the restriction map on global sections for $T \subset q(B_{i} \times \{ y \}) \subset B \times \mathbb{P}^{1} \times \mathbb{P}^{2a+1}$.  Since $k_{i} \leq a$ we see that this map is surjective, showing global generation of $\mathcal{E}_{i}$.
\end{proof}


\begin{coro} \label{coro:zacircequidim}
The space $Z_{a, \mathbf{k}}^{\circ}$ is equidimensional of dimension $2a+1$.
\end{coro}

\begin{proof}
\Cref{prop:locallycompleteintersectionZ} shows that every irreducible component of $Z_{a, \mathbf{k}}$ has dimension $\geq 2a+1$, and so the same is true for the open set $Z_{a, \mathbf{k}}^{\circ}$.  On the other hand, since the projection morphism $Z_{a, \mathbf{k}}^{\circ} \to \mathbb{P}^{2a+1}$ is quasi-finite we see that every irreducible component of $Z_{a, \mathbf{k}}^{\circ}$ has dimension $\leq 2a+1$.  
\end{proof}







We next study the restriction of the projection morphism:
\[
\phi_{a, \mathbf{k}} : Z_{a, \mathbf{k}} \to  \prod_{i = 1}^4 \mathrm{Hilb}^{[k_i]}(B_i).
\]


Note that for any $i = 1, \dotsc, 4$, $B_i$ is naturally identified with $B$ under the projection map. Using this identification we define the following Zariski open subset of $\prod_{i = 1}^{4} \mathrm{Hilb}^{[k_i]}(B_i)$:
\[
U_{\mathbf{k}} := \left\{ \left. [T_i] \in \prod_{i = 1}^{4} \mathrm{Hilb}^{[k_i]}(B_i) \,  \right| \, \text{for any $i \neq j$, the supports of $T_i$ and $T_j$ are disjoint} \right\}.
\]

\begin{lemm}
\label{lemm:configurationcover_fibration}
Assume that $2a \geq \sum_i k_i$.  Then every fiber of $\phi_{a,\mathbf{k}}: \phi_{a,\mathbf{k}}^{-1}(U_{\mathbf{k}}) \to U_{\mathbf{k}}$ is a projective space of dimension $\geq 2a + 1 - \sum_i k_i$.  Moreover we have
\[
\phi_{a, \mathbf{k}}(Z^{\circ}_{a, \mathbf{k}}) \subset U_{\mathbf{k}}.
\]
as a Zariski open subset, and the fibration
\[
\phi_{a, \mathbf{k}} : Z^{\circ}_{a, \mathbf{k}} \to \phi_{a, \mathbf{k}}(Z^{\circ}_{a, \mathbf{k}}) 
\]
is an open subset of a Zariski-locally trivial $\mathbb P^{2a + 1 - \sum_i k_i}$-bundle over $\phi_{a, \mathbf{k}}(Z^{\circ}_{a, \mathbf{k}})$.
\end{lemm}

\begin{proof}
For any $([T_i]) \in U_{\mathbf{k}}$ the linear subspace
\[
\{ [C] \in \mathbb P^{2a+1} \, | \, \text{for every $i = 1, \dotsc, 4$, $C\cap B_i$ contains $T_i$ as a closed subscheme.} \}
\]
has dimension $\geq 2a + 1 - \sum_{i = 1}^r k_i >0$, showing the first claim.  Next, for any irreducible curve $C$ in the linear series $|\mathcal{O}(1, a)|$ the supports of the $C \cap B_{i}$'s cannot share any point so that the image of $[C]$ lies in $U_{\mathbf{k}}$.  We claim that the morphism
\[
\phi_{a, \mathbf{k}}|_{Z_{a, \mathbf{k}}^\circ} : Z_{a, \mathbf{k}}^\circ \to U_{\mathbf{k}},
\]
is smooth.  Since $Z_{a, \mathbf{k}}^{\circ}$ is equidimensional by \cref{coro:zacircequidim}, smoothness follows from \cref{lemm:smoothnesscriterion} once we show that the fibers are smooth of the expected dimension.
Consider the exact sequence
\[
0 \to N_{C/B \times \mathbb P^1}(-T_1 - \dotsb -T_4) \to N_{C/B \times \mathbb P^1} \to \oplus_{i = 1}^4N_{T_i/B} \to 0.
\]
We have $N_{C/B \times \mathbb P^1}\cong \mathcal O_{C}(2a)$.  Since $2a - \sum k_{i} \geq 0$ we conclude that $h^{0}(C,N_{C/B \times \mathbb P^1}(-T_1 - \dotsb -T_4)) = 2a + 1 - \sum_{i = 1}^r k_i$ and $h^{1}(C,N_{C/B \times \mathbb P^1}(-T_1 - \dotsb -T_4)) = 0$.  In particular the obstruction space vanishes so that the moduli space of sections is smooth at $C$ of dimension $h^{0}$.  This concludes the proof of smoothness of $\phi_{a, \mathbf{k}}|_{Z^{\circ}_{a, \mathbf{k}}}$.  
Since $\phi_{a, \mathbf{k}}|_{Z^{\circ}_{a, \mathbf{k}}}$ is flat, $\phi_{a, \mathbf{k}}(Z^{\circ}_{a, \mathbf{k}})$ is an open subset of $U_{\mathbf{k}}$.   Then the natural morphism from $Z^{\circ}_{a, \mathbf{k}}$ to $\mathbb{P}^{2a+1} \times \phi_{a, \mathbf{k}}(Z^{\circ}_{a, \mathbf{k}})$ realizes each fiber as an open subset of a linear subspace of $\mathbb{P}^{2a+1}$.  This is also true of the generic fiber, thus $\phi_{a,\mathbf{k}}^{-1}( \phi_{a,\mathbf{k}}(Z^{\circ}_{a, \mathbf{k}}))$ is a Zariski-locally trivial projective bundle over $\phi_{a, \mathbf{k}}(Z^{\circ}_{a, \mathbf{k}})$.
\end{proof}

As an immediate consequence, we obtain: 

\begin{coro} \label{coro: Z_irreducible}
Suppose that $2a \geq \sum_{i} k_{i}$.  Then $Z_{a, \mathbf{k}}^{\circ}$ is smooth and geometrically irreducible of dimension $2a+1$.
\end{coro}







\subsection{Configuration covers and the Stein factorization}

We now return to our original setting: we would like to consider the Stein factorization of (a compactification of) $p_{*}:\Mor(B, S)_\alpha = M_{\alpha} \to N_{a} = \Mor(B, \mathbb P^1)_a$.  Recall that \cref{nota:bignota} describes the notation involving the nef curve class $\alpha$ and the constants $h,a,\mathbf{k}$.

Since $S$ is a split del Pezzo surface, the conic bundle $p: S \to \mathbb{P}^{1}$ will have four reducible fibers.  For $i=1,\dotsc,4$ we let $p_{i} \in \mathbb{P}^{1}$ denote the $k$-point which is the $p$-image of the exceptional divisor $E_{i}$.  We construct $Z_{a, \mathbf{k}}$ with respect to these four points as in the previous subsection.   We then define the morphism $\psi_{\alpha}: M_{\alpha} \to Z_{a, \mathbf{k}}^{\circ}$ by sending
\begin{equation*}
[s: B \to S] \mapsto ( [p \circ s], [s^{*}(E_1)], \dotsc, [s^{*}(E_4)] )
\end{equation*}
Note that we have a factoring $p_{*} = \pi \circ \psi_{\alpha}$ where $\pi: Z_{a, \mathbf{k}}^{\circ} \to \mathbb{P}^{2a+1}$ is the projection map.  In this subsection our goal is to study the morphism $\psi_{\alpha}$.



\begin{lemm} \label{lemm:psismooth}
The morphism $\psi_{\alpha}: M_{\alpha} \to Z_{a, \mathbf{k}}^{\circ}$ is smooth.
\end{lemm}

\begin{proof}

By \cref{lemm:smoothnesscriterion} it suffices to show that the fibers of $\psi_{\alpha}$ are smooth of the expected dimension.
We first analyze the fibers of $M_{\alpha} \to U_{\mathbf{k}}$.  Each fiber can be interpreted as the sublocus of $\Mor(B,S)_{\alpha}$ that sends a designated subscheme $T_{i}$ to $E_{i}$ for every $1 \leq i \leq 4$.  Thus the tangent space and obstruction space of the fiber at a point $s: B \to S$ are determined by the cohomology groups of $s^{*}T_{S}(- \log(E_{1} + E_{2} +E_{3} + E_{4}))$.  Using the birational map $\rho: S \to \mathbb{P}^{1} \times \mathbb{P}^{1}$ of \cref{nota:bignota} we can identify
\begin{align*}
s^{*}T_{S}(- \log(E_{1} + E_{2} +E_{3} + E_{4})) & \cong s^{*}\rho^{*}T_{\mathbb{P}^{1} \times \mathbb{P}^{1}}(-E_{1}-E_{2}-E_{3}-E_{4}) \\
& \cong \mathcal{O}_{B}(2a - \sum k_{i}) \oplus \mathcal{O}_{B}(2a' - \sum k_{i}).
\end{align*}
By the inequalities of \cref{nota:bignota} we see both direct summands have vanishing $H^1$. 
We conclude that $M_{\alpha} \to U_{\mathbf{k}}$ is smooth by \cref{lemm:smoothnesscriterion}.

The tangent spaces of the fibers of $Z^{\circ}_{a, \mathbf{k}} \to U_{\mathbf{k}}$ were computed in the proof of \cref{lemm:configurationcover_fibration}.  By comparing this lemma against the direct summand decomposition above, we conclude that the deformation theory of points in the fibers of $\psi_{\alpha}$ is controlled by the kernel of the map
\begin{equation*}
s^{*}T_{S}(- \log(E_{1} + E_{2} +E_{3} + E_{4})) \to s^{*}p^{*}T_{\mathbb{P}^{1}}(- \sum T_{i} ).
\end{equation*}
This map is projection onto the first factor in the direct summand decomposition above.  The kernel $\mathcal{O}_{B}(2a' - \sum k_{i})$ is a nef line bundle.  Again we are in a situation where obstructions vanish and thus can conclude smoothness by \cref{lemm:smoothnesscriterion}.
\end{proof}

\begin{defi}
We let $R_{\alpha} \subset Z_{a, \mathbf{k}}^{\circ}$ denote the open subset which is the image of the flat morphism $M_{\alpha} \to Z_{a, \mathbf{k}}^{\circ}$.  
We let $\pi_{\alpha}: R_{\alpha} \to N_{a}$ denote the restriction of the projection map $\pi: Z_{a, \mathbf{k}}^{\circ} \to N_{a} \subset \mathbb{P}^{2a+1}$.
\end{defi}

%We claim that $\pi_{\alpha}$ is a quasi-finite morphism of degree
%\[
%\prod_{i = 1}^{4} \binom{a}{k_i}.
%\]
%Indeed, it suffices to check this geometrically, so we may assume our ground field is algebraically closed.  A general point of $N_{a}$ will define a morphism $s: B \to \mathbb{P}^{1}$ which is unramified over $\{p_{1},p_{2},p_{3},p_{4}\}$.  Then $Y_{B} \to B$ has $4a$ singular fibers and the pullback of $E_{i}$ to $Y_{B}$ contains an irreducible component in $a$ of these fibers.  Any section representing a point of $M_{\alpha}$ must intersect exactly $k_{i}$ components of the pullback of $E_{i}$. Once we choose which components of the singular fibers our section intersects, the parameter space is irreducible.  Altogether, we obtain a total of $\prod_{i = 1}^{4} \binom{a}{k_i}$ different irreducible components of the fiber of $p_{*}$ over $[s]$.  

Before continuing we need an auxiliary construction.  


\begin{const} \label{cons:qalpha}
We have a morphism $p'_{*}: \Mor(B,S) \to \Mor(B,\mathbb{P}^{1})$ given by composing with the birational map $\rho: S \to \mathbb{P}^{1} \times \mathbb{P}^{1}$ and the second projection map $\mathbb{P}^{1} \times \mathbb{P}^{1} \to \mathbb{P}^{1}$.  We construct $Z_{a', \mathbf{k}}^{\circ}$ as in \cref{sect:compactza}; note that all results in this section hold equally well for $Z^{\circ}_{a', \mathbf{k}}$.  In particular, defining $Q_{\alpha} = R_{\alpha} \times_{U_{\mathbf{k}}} Z^{\circ}_{a', \mathbf{k}}$ we obtain an induced morphism
\begin{equation*}
i: M_{\alpha} \to Q_{\alpha}.
\end{equation*}
\end{const}


\begin{lemm} \label{lemm:malphaopenimmer}
The morphism $i$ is an open immersion realizing $M_{\alpha}$ as an open subset of a Zariski-locally trivial $\mathbb{P}^{h - 2a +1}$ bundle over $R_{\alpha}$.
\end{lemm}

\begin{proof}
Since both $M_{\alpha}$ and $Q_{\alpha}$ are smooth and have the same dimension, it suffices to show that $i$ is \'etale and set-theoretically injective.  We show that it is \'etale by computing the induced map on tangent spaces.  Recall from the proof of \cref{lemm:psismooth} that the relative tangent space of the map $M_{\alpha} \to U_{\mathbf{k}}$ is
\begin{equation*}
H^{0}(B,s^{*}T_{S}(-\log(E_{1}+E_{2}+E_{3}+E_{4}))) \cong s^{*}p^{*}T_{\mathbb{P}^{1}}(- \sum T_{i} ) \oplus s^{*}p'^{*}T_{\mathbb{P}^{1}}(- \sum T_{i} ).
\end{equation*}
In turn these two summands are the relative tangent spaces of $R_{\alpha}$ and $Z_{a', \mathbf{k}}^{\circ}$ over $U_{\mathbf{k}}$.  This shows that the induced map on tangent spaces is an isomorphism, so $i$ is \'etale.  Injectivity follows from the fact that $\rho_{*}: \Mor(B,S) \to \Mor(B,\mathbb{P}^{1} \times \mathbb{P}^{1})$ is a bijection on the set of morphisms which meet the open locus where $\rho$ is an isomorphism.
\cref{lemm:surjectivityphi} shows that $Z'_{a', \mathbf{k}}$ is an open subset of a Zariski-locally trivial projective bundle over $U_{\mathbf{k}}$, and thus by base change $M_{\alpha}$ has the analogous property over $R_{\alpha}$.
\end{proof}



Putting everything together, we obtain:

\begin{theo}
The morphism $p_{*}: M_{\alpha} \to N_{a}$ factors as $p_{*} = \pi_{\alpha} \circ \psi_{\alpha}$ where $\psi_{\alpha}: M_{\alpha} \to R_{\alpha}$ realizes $M_{\alpha}$ as an open subset of a Zariski-locally trivial $\mathbb{P}^{h - 2a +1}$ bundle and $\pi_{\alpha}$ is quasifinite.  In particular, $M_{\alpha}$ is smooth.
\end{theo}









\subsection{Dimension bounds}
Consider the chain of morphisms $M_{\alpha} \to Z_{a, \mathbf{k}}^{\circ} \to U_{\mathbf{k}}$.  Our final goal is to estimate the dimension of the complement of the image of $M_{\alpha}$.  We will do this in several steps; the first is to analyze the image of $Z_{a, \mathbf{k}}^{\circ} \to U_{\mathbf{k}}$.




\begin{lemm}
\label{lemm:surjectivityphi}  
Consider the sublocus of $U_{\mathbf{k}}$ parametrizing closed subschemes in $\sqcup_{i} B_{i} \subset B \times \mathbb{P}^{1}$ which are not contained in any irreducible section parametrized by $|\mathcal{O}(a, 1)|$.  This locus is empty if $\sum_{i = 1}^4 k_i \leq a$ 
and has dimension at most $2\sum k_i - (2a+1)$ otherwise.

In particular, the complement of $\phi_{a, \mathbf{k}}(Z_{a, \mathbf{k}}^{\circ})$ in $U_{\mathbf{k}}$ is empty if $\sum_{i = 1}^4 k_i \leq a$ and has dimension at most $2\sum k_i - (2a+1)$ otherwise.
\end{lemm}





\begin{proof}
By \cref{lemm:configurationcover_fibration} every fiber of $\phi_{a, \mathbf{k}}$ over a point of $U_{\mathbf{k}}$ is a projective space of dimension $\geq 2a + 1 -\sum_i k_i >0$ and in particular is non-empty.  Suppose $([T_i]) \in U_{\mathbf{k}}$ is a point which is not in the image of $Z_{a, \mathbf{k}}^{\circ}$.  Thus the general divisor contained in the fiber $\phi_{a, \mathbf{k}}^{-1}([T_i])$ will admit some $\pi_{1}$-vertical components.  We let $\ell_{1}$ (respectively $\ell_{2}$) denote the intersection of $\pi_{2}^{*}\mathcal{O}(1)$ with the union of all irreducible $\pi_{1}$-vertical components of a general divisor in the fiber which do not (respectively do) intersect some $T_{i}$.  Then the dimension of $\phi_{a, \mathbf{k}}^{-1}([T_i])$ is
\[
\max \left\{0, 2a +1 -2\ell_1 -\ell_2 - \sum_i k_i \right\} + \ell_1.
\]
This needs to be greater than or equal to $2a + 1 - \sum_i k_i$.  This is only possible when $2a +1 -2\ell_1 -\ell_2 - \sum_i k_i \leq 0$ so that the dimension is exactly $\ell_{1}$.  In particular
\[
\ell_1 \geq 2a + 1 - \sum_i k_i.
\]
On the other hand, for any $i = 1, \dotsc, 4$, by taking intersection of our divisors against $B_{i}$ we see that $a-\ell_1 \geq k_i$.
Altogether we have
\[
a-\max_i \{ k_i\} \geq \ell_1 \geq 2a + 1 - \sum_i k_i.
\]
This implies that $ \sum_i k_i - \max_i \{ k_i\} \geq a + 1$, proving the claim about emptiness.  



The dimension of the locus in $\mathbb{P}^{2a+1}$ parametrizing divisors such that the 
$\pi_{1}$-vertical components have degree $\ell_1 + \ell_{2}$ is
\[
2a - \ell_1 - \ell_2+1.
\]
Thus, the sublocus of $\phi_{a, \mathbf{k}}^{-1}(U_{\mathbf{k}})$ corresponding to such divisors is also bounded above by this number.  Since the argument above showed that the fiber over $([T_i])$ has dimension $\ell_1$, we have
\[
\dim_{[T_i]}(U_{\mathbf{k}} \setminus \phi_{a, \mathbf{k}}(Z_{a, \mathbf{k}}^{\circ})) \leq 2a - 2\ell_1 - \ell_2+1.
\]
Combining with the inequality
\[
\ell_1 \geq 2a+1 - \sum_i k_i,
\]
we obtain
\[
\dim(U_{\mathbf{k}} \setminus \phi_{a, \mathbf{k}}(Z_{a, \mathbf{k}}^{\circ})) \leq 2\sum_i k_i -2a -1. \qedhere
\]
\end{proof}



We next turn to the morphism $\psi_{\alpha}: M_{\alpha} \to Z_{a, \mathbf{k}}^{\circ}$.

\begin{prop}
\label{prop:surjectivity}
Consider the map $\psi_{\alpha}: M_{\alpha} \to Z_{a, \mathbf{k}}^{\circ}$.  The complement of $\psi_{\alpha}(M_{\alpha})$ is empty if $h-2a - \sum k_i \geq 0$ and has dimension at most $\sum k_{i} - (h - 2a + 1)$ otherwise.
\end{prop}


\begin{proof}
Choose a point $([C'], [T_{1}], [T_{2}], [T_{3}], [T_{4}]) \in Z_{a, \mathbf{k}}^{\circ}$ and define $Y_{C'} = C' \times_{\mathbb{P}^{1},p} S$.  Then $\rho_{\alpha}$ induces a birational morphism $\phi_{C'} : Y_{C'} \to C' \times \mathbb{P}^{1}$.  For every morphism $B \to S$ in the fiber of $M_{\alpha} \to Z_{a, \mathbf{k}}^{\circ}$ the graph can be identified with a section $C_{1}$ of $C' \times \mathbb{P}^{1}$ of relative anticanonical height $2a' = h-2a-\sum k_{i}$ such that $T_{i} \subset C_{1} \cap '(C' \times \{ p_{i} \})$.

Conversely, suppose we have a section $C_1$ of relative anticanonical height $2a'$ on $C' \times \mathbb{P}^{1}$ whose intersection with $C' \times \{ p_i\}$ contains $T_i$ for every $i$.  Then its strict transform on $Y_{C'}$ gives a section which in turn can be viewed as the graph of an element of $M_{\alpha}$.  Thus the dimension of the complement of $\psi_{\alpha}(M_{\alpha})$ is bounded by the dimension of the locus of $([T_{i}])$ which are not contained in an irreducible section of $C' \times \mathbb{P}^{1}$ of relative anticanonical height $2a'$.  \Cref{lemm:surjectivityphi} shows that this locus is empty if $\sum k_{i} \leq a'$ and has dimension at most $2 \sum k_{i} - (2a'+1)$ otherwise.  Using $a' = \frac{1}{2}(h - 2a +\sum k_{i})$ we obtain the statement.
\end{proof}

By combining \cref{lemm:surjectivityphi,prop:surjectivity} we obtain:

\begin{prop} \label{prop:finaldimestimate}
Consider the composition
\[
 \phi_{a, \mathbf{k}} \circ \psi_\alpha: M_{\alpha} \to Z_{a, \mathbf{k}}^{\circ} \to U_{\mathbf{k}}.
\]
Then the dimension of $U_{\mathbf{k}(\alpha)} \setminus  \phi_{a, \mathbf{k}} \circ \psi_\alpha(M_{\alpha})$ is at most 
\[
\max\left\{2 \sum_i k_i - (2a +1),2 \sum_i k_i  -(2a' +1) \right\}.
\]
\end{prop}






\subsection{Pointed morphisms} \label{sect:pointedmorzak}



In this section we reformulate the previous results in the setting of pointed morphisms.  Since the arguments are essentially the same, we will only outline the proofs.



In this section we let $B = \mathbb P^1$ denote our domain curve.  We fix base points $*_B$ and $*_{\mathbb P^1}$ on $B$ and $\mathbb P^1$ respectively.  For any $a \geq 0$ we let $\mathbb P^{2a}_{*}$ denote the linear system of divisors of type $(a, 1)$ in $B\times \mathbb P^1$ passing through $(*_B, *_{\mathbb P^1})$.  This is isomorphic to a hyperplane $\mathbb{P}^{2a}$ in $|(a,1)|$.
Suppose $p_1, \dotsc, p_{4} \in \mathbb P^1$ are distinct $k$-points on $\mathbb P^1$ which are different from $*_{\mathbb P^1}$.
Let $B_i = B\times \{p_i\}  \subset B \times\mathbb P^1 $.


For a fixed index $1 \leq i \leq 4$ and a fixed integer $0\leq k_i \leq a$ we define 
\[
Z_{a, i, k_i, *} = \{([C], [T]) \in \mathbb P^{2a}_* \times \mathrm{Hilb}^{[k_i]}(B_i)\, | \, T \subset C\} \subset \mathbb P^{2a}_* \times \mathrm{Hilb}^{[k_i]}(B_i).
\]
We define the configuration cover as
\[
Z_{a, \mathbf{k}, *} =  Z_{a, 1, k_1, *} \times_{\mathbb P^{2a}_*} \dotsb \times_{\mathbb P^{2a}_*} Z_{a, 4, k_4, *}\subset \mathbb P^{2a}_* \times \prod_{i = 1}^{4}\mathrm{Hilb}^{[k_i]}(B_i) 
\]
equipped with the projection $\pi_{a, \mathbf{k}, *}: Z_{a, \mathbf{k}, *} \to \mathbb P^{2a}_*$.  



We denote the open locus of $\mathbb P^{2a}_{*}$ parametrizing honest sections by $N_{a, *}$ and we denote its preimage in $Z_{a, \mathbf{k}, *}$ by $Z_{a, \mathbf{k}, *}^\circ$.
We first analyze the structure of $Z_{a, \mathbf{k}, *}^\circ$
using the fibration
\[
\phi_{a, \mathbf{k}, *} : Z^\circ_{a, \mathbf{k}, *} \to  U_{\mathbf{k}, *}
\]
where
\[
U_{\mathbf{k}, *} := \left\{ \left. [T_i] \in \prod_{i = 1}^{4} \mathrm{Hilb}^{[k_i]}(B_i) \,  \right| \begin{array}{c} \text{for every $i$, the support of $T_i$ does not contain } *_{B} \textrm{ and}\\ \text{for every $i \neq j$, the supports of $T_i$ and $T_j$ are disjoint} \end{array} \right\}.
\]




\begin{lemm}
\label{lemm:configurationcover_fibrationpointed}
Assume that $2a > \sum_i k_i$. 
Then every fiber of $\phi_{a,\mathbf{k}, *}: \phi_{a,\mathbf{k}, *}^{-1}(U_{\mathbf{k}, *}) \to U_{\mathbf{k}, *}$ is a projective space of dimension $\geq 2a  - \sum_i k_i$.  Moreover we have
\[
\phi_{a, \mathbf{k}, *}(Z^{\circ}_{a, \mathbf{k}, *}) \subset U_{\mathbf{k}, *}.
\]
as a Zariski open subset, and the fibration
\[
\phi_{a, \mathbf{k}, *} : Z^{\circ}_{a, \mathbf{k}, *} \to \phi_{a, \mathbf{k}}(Z^{\circ}_{a, \mathbf{k}, *}) 
\]
is an open subset of a Zariski-locally trivial $\mathbb P^{2a - \sum_i k_i}$-bundle over $\phi_{a, \mathbf{k}, *}(Z^{\circ}_{a, \mathbf{k}, *})$.

In particular $Z^{\circ}_{a, \mathbf{k}, *}$ is smooth and geometrically irreducible.
\end{lemm}



We next return to the surface $S$ and the morphism $p_{*}: M_{\alpha, *} \to N_{a, *}$.  As before, we construct $Z_{a,\mathbf{k}, *}$ with respect to the four $k$-points which are the images in $\mathbb P^1$ of the singular fibers.   We then define the morphism $\psi_{\alpha, *}: M_{\alpha, *} \to Z_{a,\mathbf{k}, *}^{\circ}$ by sending
\begin{equation*}
[s: B \to S] \mapsto ( [p \circ s], [s^{*}(E_1)], \dotsc, [s^{*}(E_4)] ).
\end{equation*}
If we assume that $2a > \sum k_{i}$ and $2a' > \sum k_{i}$, then the same argument as in \cref{lemm:psismooth} shows that $\psi_{\alpha,*}$ is smooth.  Under these assumptions we let $R_{\alpha,*} \subset Z_{a,\mathbf{k}, *}^{\circ}$ denote its image and let $\pi_{\alpha,*}: R_{\alpha, *} \to N_{a, *}$ denote the projection map.


\begin{theo}
Assume that $2a > \sum k_{i}$ and $2a' > \sum k_{i}$.  The morphism $p_{*}: M_{\alpha, *} \to N_{a, *}$ factors as $p_{*} = \pi_{\alpha, *} \circ \psi_{\alpha, *}$ where $\psi_{\alpha, *}: M_{\alpha, *} \to R_{\alpha, *}$ realizes $M_{\alpha, *}$ as an open subset of a Zariski-locally trivial $\mathbb{P}^{h - 2a}$-bundle over the Zariski open subset $R_{\alpha, *}$ and $\pi_{\alpha, *}$ is quasifinite.  In particular, $M_{\alpha, *}$ is smooth.
\end{theo}

Finally, we turn to dimension estimates.

\begin{lemm}
\label{lemm:surjectivityphipointed}  

Assume that $2a > \sum k_{i}$.
Consider the sublocus of $U_{\mathbf{k}, *}$ parametrizing closed subschemes in $\sqcup_{i} B_{i} \subset B \times \mathbb P^1$ which are not contained in any irreducible section parametrized by $|\mathcal{O}(a, 1)|$ passing through the base point.  This locus is empty if $\sum_{i = 1}^4 k_i < a$  and has dimension at most $2\sum k_i - 2a$ otherwise.



\end{lemm}




By applying \cref{lemm:surjectivityphipointed} twice -- once to the map $\phi_{a, \mathbf{k}, *}: \phi_{a, \mathbf{k}, *}^{-1}(U_{\mathbf{k}, *}) \to U_{\mathbf{k}, *}$ and once to the map  $\psi_{\alpha, *}: M_{\alpha, *} \to Z_{a, \mathbf{k}, *}^{\circ}$ -- we obtain:

\begin{prop}
\label{prop:dimensionestimatepointed}
Assume that $2a > \sum k_{i}$ and $2a' > \sum k_{i}$.  Consider the composition
\[
\phi_{a, \mathbf{k}, *}\circ  \psi_{\alpha, *} : M_{\alpha, *} \to Z_{a, \mathbf{k}, *}^{\circ} \to U_{\mathbf{k}, *}.
\]
Then the dimension of $U_{\mathbf{k}(\alpha), *} \setminus \phi_{a, \mathbf{k}, *} \circ \psi_{\alpha, *}(M_{\alpha, *})$ is at most 
\[
\max\left\{ 2\sum_i k_i - 2a, 2\sum_i k_i  - 2a' \right\}.
\]
\end{prop}

















\section{Stratifying the Hilbert scheme}
\label{sec:stratifying}





Suppose $B$ is a smooth projective curve.  Then $\mathrm{Hilb}(B)$ carries the structure of a poscheme where the relation $\leq$ corresponds to containment of closed subschemes.  \cite{DT24} studied the space $\mathrm{Hilb}(B)^{Q}$ of poset homomorphisms $Q \to \mathrm{Hilb}(B)$ and introduced a combinatorial stratification of this space.  In this section we recall their constructions and rephrase them in the setting of poschemes. The main new addition is the key example \S\ref{sect:keyexample}.   We will closely follow the exposition of  \cite[Section 3]{DT24}.  



\subsection{Poschemes of divisors}



Let $k$ be a perfect field and let $B$ be a smooth curve defined over $k$.
We denote the poscheme of all closed subschemes of $B$ by $\overline{\mathrm{Hilb}}(B)$. Note that this poscheme includes a maximal element which is a $k$-point corresponding to the entire scheme $B$ as well as a minimal element which is a $k$-point corresponding to the empty set.
We denote the poscheme of finite length subschemes of $B$ by $\mathrm{Hilb}(B)$ (i.e.~$\overline{\mathrm{Hilb}}(B)$ is obtained from $\mathrm{Hilb}(B)$ by adding in the maximal element $B$). 

\begin{defi}[{\cite[Definition 3.1]{DT24}}]
Let $Q$ be a finite \'etale poscheme over $k$ with a largest element $\hat{1}$ which is a $k$-rational point.  We set
\[
\widetilde{Q} = Q \setminus\{ \hat{1}\}.
\]
We denote the poscheme of homomorphisms $Q \to \overline{\mathrm{Hilb}}(B)$ which take $\hat{1}$ to $B$ by 
\[
\overline{\mathrm{Hilb}}(B)^Q.
\]
This means that for any $k$-scheme $T$, an element $x \in \overline{\mathrm{Hilb}}(B)^Q(T)$ consists of a collection of subschemes 
\[
\{ x_q \subset B\times T \}_{q \in Q(T)},
\]
such that each $x_{q}$ is a flat subscheme over $T$ for $q \in \widetilde{Q}(T)$, $x_{\hat{1}} = B \times T$, and $p \leq q$ implies $x_p \subset x_q$.
Note that one can realize $\overline{\mathrm{Hilb}}(B)^Q$ as a closed subscheme
\[
\overline{\mathrm{Hilb}}(B)^Q \subset \mathrm{Mor}(Q, \overline{\mathrm{Hilb}}(B)).
\]
We denote the subposcheme of $\overline{\mathrm{Hilb}}(B)^Q$ consisting of homomorphisms such that the preimage of $B$ is $\hat{1}$ by $\mathrm{Hilb}(B)^Q$. 
\end{defi}

Suppose we fix an element $x \in \mathrm{Hilb}(B)^Q(\overline{k})$. Then for each $c \in B(\overline{k})$, one can define a homomorphism of posets $\widetilde{g}_c : \widetilde{Q}(\overline{k}) \to \mathbb N$ by assigning to each $q \in \widetilde{Q}(\overline{k})$ the length of $x_q$ at $c$. In this way one can define a one-to-one correspondence between elements of $\mathrm{Hilb}(B)^Q(\overline{k})$ and the set of finitely supported functions:
\[
B(\overline{k}) \to \mathrm{Hom}( \widetilde{Q}(\overline{k}), \mathbb N).
\]
We say that a homomorphism $\widetilde{g}_c: \widetilde{Q}(\overline{k}) \to \mathbb N$ is trivial if $\widetilde{g}_c(q) = 0$ for every $q \in \widetilde{Q}(\overline{k})$. The support of a function $\widetilde{g} : B(\overline{k}) \to \mathrm{Hom}( \widetilde{Q}(\overline{k}), \mathbb N)$ is the set of $c \in B(\overline{k})$ such that $\widetilde{g}_c$ is non-trivial.
When $x \in \overline{\mathrm{Hilb}}(B)^Q(\overline{k})$, we can equivalently consider this element as a function
\[
g : B(\overline{k}) \to \mathrm{Hom}( Q(\overline{k}), \mathbb N \cup \{\infty\}),
\]
by assigning $g_c(q) = \infty$ whenever $x_q = B$.  


\subsubsection{A key example} \label{sect:keyexample}



We describe a key example for our analysis.  The geometric motivation for this example will be explained in \cref{subsec:blowups}.

Let $V_i$ $(i = 1, 2)$ be a $2$-dimensional vector space over $k$ and set
\[
V = V_1 \oplus V_2.
\]
We fix a non-negative integer $r$ and  for each $j = 1, 2$ we pick $r$ distinct $1$-dimensional subspaces $\ell_{i, j} \subset V_j (i = 1, \dotsc, r)$ which are defined over $k$.
Let $Q$ be the following set of subspaces of $V$: 
\begin{equation*}
%\label{eq:poschemeexam}
\{ V, V_1 \oplus \{0\}, \{0\} \oplus V_2,  0 \} \cup \{ \ell_{i, 1} \oplus \ell_{i, 2}, \ell_{i, 1} \oplus \{0\}, \{0\} \oplus \ell_{i, 2}  \}_{i=1,\dotsc,r}.
\end{equation*}

Under inclusion this becomes a finite \'etale poscheme that admits meets, i.e., the intersection of two subspaces in $Q$ is still contained in $Q$.  












\subsection{Essential saturated elements}

\subsubsection{Saturated elements}

We closely follow the discussion of \cite[Section 3.3]{DT24}.
First we introduce the following definition from \cite[Section 3.3]{DT24}:

\begin{defi}[{\cite[Definition 3.3]{DT24}}]  \label{defi:saturated}
Let $Q$ be a finite \'etale poscheme over $k$ and assume that every subset $S \subset Q(\overline{k})$ admits a meet $\wedge_{s \in S}s$. Let $B$ be a smooth projective curve over $k$. We say an element $\{x_q\}_{q \in Q(\overline{k})} \in \mathrm{Hilb}(B)^Q(\overline{k})$ is saturated if for any subset $S \subset Q(\overline{k})$, the natural containment yields an equality
\[
x_{\wedge_{s \in S} s} = \bigcap_{s \in S} x_s.
\]
In other words, the associated homomorphism $x : Q(\overline{k}) \to \mathrm{Hilb}(B)(\overline{k})$ preserves meets. Let $Q^{JB}(\overline{k}) \subset \mathrm{Hilb}(B)^Q(\overline{k})$ be the subposet of saturated elements, which is a Zariski open subset of $\mathrm{Hilb}(B)^Q(\overline{k})$.  
Then since $Q^{JB}(\overline{k})$ is Galois invariant, this open subscheme descends to the open subscheme $Q^{JB}\subset \mathrm{Hilb}(B)^Q$ defined over $k$.
\end{defi}

In terms of finitely supported functions $\widetilde{g}: B(\overline{k}) \to \mathrm{Hom}(\widetilde{Q}(\overline{k}), \mathbb N)$, being saturated means that for any $c \in B(\overline{k})$, $\widetilde{g}_c : \widetilde{Q}(\overline{k}) \to \mathbb N$ preserves meets. We write $g_c : Q(\overline{k}) \to \mathbb N\cup \{\infty\}$ for the extension of $\widetilde{g}_c : \widetilde{Q}(\overline{k}) \to \mathbb N$ by assigning $g_c(\widehat{1}) = \infty$. When $g_c$ preserves meets, its left adjoint $f_c : \mathbb N \cup \{\infty\} \to Q(\overline{k})$ is given by
\[
f_c(n) = \min\{ q\in Q(\overline{k}) \, |\, g_c(q) \geq n \}.
\]
The following definition describes the properties which characterize $f_{c}$.


\begin{defi}
Let $Q$ be a finite \'etale poscheme with meets and with a maximal element $\widehat{1}$.   A chain is a poset homomorphism $f : \mathbb N \cup \{\infty\} \to Q(\overline{k})$ with the following properties:
\begin{enumerate}
\item $f(0) = \widehat{0}$ is the minimal element of $Q$, and
\item $f$ preserves joins, i.e., for any $S \subset \mathbb{N} \cup \{\infty\}$ we have
\[
f(\vee S) = \vee f(S).
\]
This is equivalent to requiring that $f(n) = \widehat{1}$ for $n \gg 0$.
\end{enumerate}
We denote the set of chains by $\mathrm{ch}(Q(\overline{k}))$.  By the trivial chain, we will mean the chain with $f(0) = \widehat{0}$ and $f(n) = \widehat{1}$ for $n \geq 1$.  The trivial chain is denoted by $V$ or $\widehat{1}$.
\end{defi}



Given a $\widetilde{g}_c : \widetilde{Q}(\overline{k}) \to N$ that preserves meets, the corresponding $f_{c}$ constructed above is a chain.  Conversely, for any chain $f_{c}:   \mathbb N\cup \{\infty\} \to Q(\overline{k})$ its right adjoint $g_{c} : Q(\overline{k}) \to \mathbb N\cup \{\infty\}$ defined by
\[
g_{c}(q) = \max\{n \in \mathbb N \cup \{\infty\} \,|\, q \geq f_{c}(n)\}
\]
will have the property that $g_{c}^{-1}( \{ \infty \}) = \{ \widehat{1} \}$.
In this way, there is a one-to-one correspondence between the set of chains $f_{c}: \mathbb N \cup \{\infty\} \to Q(\overline{k})$ 
and the set of homomorphisms $\widetilde{g}_{c} : \widetilde{Q}(\overline{k}) \to \mathbb N$ preserving meets.


Next we recall the following definition from \cite[Section 3.3]{DT24}:

\begin{defi}[{\cite[Definition 3.8]{DT24}}]
The saturation function is the function
\[
\mathrm{sat} : \mathrm{Hilb}(B)^Q(\overline{k}) \to Q^{JB}(\overline{k}),
\]
which is the left adjoint to the inclusion functor of the subposet of saturated elements.
In other words, for any $D \in \mathrm{Hilb}(B)^Q(\overline{k})$, $\mathrm{sat}(D)$ is defined as the smallest saturated element greater than or equal to $D$. Note that this saturation function is Galois-equivariant.
In particular if $D$ is a $k$-rational point on $\mathrm{Hilb}(B)^Q$, then $\mathrm{sat}(D)$ is also a $k$-rational point on $Q^{JB}$.
\end{defi}

\begin{exam}
\label{exam:saturatedexample}
Let $Q$ be the finite \'etale poscheme defined in \cref{sect:keyexample} so that we have 
\begin{equation*}
%\label{eq:poschemeexam}
\{ V, V_1 \oplus \{0\}, \{0\} \oplus V_2,  0 \} \cup \{ \ell_{i, 1} \oplus \ell_{i, 2}, \ell_{i, 1} \oplus \{0\}, \{0\} \oplus \ell_{i, 2}  \}_{i=1,\dotsc,r}.
\end{equation*}
%\begin{equation}
%\label{eq:poschemeexam}
%\{ V, V_1 \oplus \{0\}, \{0\} \oplus V_2, \ell_{i, 1} \oplus \ell_{i, 2}, \ell_{i, 1} \oplus \{0\}, \{0\} \oplus \ell_{i, 2}  \, (i = 1, \dotsc, r), 0\}.
%\end{equation}
%\[
%Q = \{V, V_1\oplus \{0\}, \{0\}\oplus V_2, \dotsc, \ell_{i, 1}\oplus\ell_{i, 2}, \dotsc, \dotsc, \ell_{i, 1}\oplus\{0\}, \dotsc, \dotsc, \{0\} \oplus \ell_{i, 2}, \dotsc, 0\}.
%\]
In this case, an element $D$ of $\mathrm{Hilb}(B)^Q(\overline{k})$ consists of divisors 
\[
D_{V_1}, D_{V_2}, D_{\ell_{1, 1}\oplus \ell_{1, 2}}, \dotsc, D_{\ell_{r, 1}\oplus \ell_{r, 2}}, D_{\ell_{1, 1}}, \dotsc, D_{\ell_{r, 1}}, D_{\ell_{1, 2}}, \dotsc, D_{\ell_{r, 2}}, D_0.
\]
This element is saturated if and only if we have 
\[
D_0 = D_{V_1}\cap D_{V_2} = D_{\ell_{i, 1}\oplus \ell_{i, 2}} \cap D_{\ell_{j, 1}\oplus \ell_{j, 2}}  
\]
for any $i \neq j$ and
\[
D_{\ell_{i, j}} = D_{\ell_{i, 1}\oplus \ell_{i, 2}}\cap D_{V_j}
\]
for any $i, j$.
For any $D \in \mathrm{Hilb}(B)^Q(\overline{k})$, $D' = \mathrm{sat}(D)$ is given by
\begin{align*}
D_0' &= (D_{V_1}\cap D_{V_2}) \cup \bigcup_{i \neq j}(D_{\ell_{i, 1}\oplus \ell_{i, 2}} \cap D_{\ell_{j, 1}\oplus \ell_{j, 2}}),\\
D_{\ell_{i, j}}' &= D_0' \cup (D_{\ell_{i, 1}\oplus \ell_{i, 2}}\cap D_{V_j}),\\
D_{\ell_{i, 1}\oplus \ell_{i, 2}}' &= D_{\ell_{i, 1}\oplus \ell_{i, 2}} \cup D_0' \cup D_{\ell_{i, 1}}' \cup D_{\ell_{i, 2}}',\\
D_{V_j}' &= D_{V_j} \cup D_0' \cup \bigcup_{i = 1}^r D_{\ell_{i, j}}'.
\end{align*}

For $c \in B(\overline{k})$, the associated function $\widetilde{g}_c : \widetilde{Q}(\overline{k}) \to \mathbb N$ consists of values
\[
\widetilde{g}_c(V_1), \, \widetilde{g}_c(V_2), \, \widetilde{g}_c(\ell_{i, 1}\oplus \ell_{i, 2}), \, \widetilde{g}_c(\ell_{i, j}), \, \widetilde{g}_c(0),
\]
for $i = 1, \dotsc, r$ and $j = 1, 2$.
The function $\widetilde{g}_c : \widetilde{Q}(\overline{k}) \to \mathbb N$ is saturated if and only if:
\begin{itemize}
\item $\widetilde{g}_c(\ell_{i, j})$ is equal to the minimum of $\widetilde{g}_c(\ell_{i, 1}\oplus \ell_{i, 2})$ and $\widetilde{g}_c(V_j)$, and
\item $\widetilde{g}_c(0)$ is equal to the minimum of $\widetilde{g}_c(V_1)$ and $\widetilde{g}_c(V_2)$ and also equal to $\widetilde{g}_c(\ell_{i, 1}\oplus \ell_{i, 2})$ for every index $i$ but one (for which the value may be larger).
\end{itemize}

Let $\widetilde{g}_c : \widetilde{Q}(\overline{k}) \to \mathbb N$ be a saturated function.
For simplicity, let us assume that $\widetilde{g}_c(V_1) \geq \widetilde{g}_c(V_2)$ and $\widetilde{g}_c(\ell_{1, 1}\oplus \ell_{1, 2})$ is the maximum among $\widetilde{g}_c(\ell_{i, 1}\oplus \ell_{i, 2})$'s.
First let us assume that $\widetilde{g}_c(\ell_{1, 1}) = \widetilde{g}_c(V_1)$, i.e., $\widetilde{g}_c(V_1) \leq \widetilde{g}_c(\ell_{1, 1}\oplus \ell_{1, 2})$. Let $m_0 = \widetilde{g}_c(0)$ and $m_{\ell_{1, 1}}= \widetilde{g}_c(\ell_{1, 1}) - \widetilde{g}_c(0)$ and $m_{\ell_{1, 1}\oplus \ell_{1, 2}} = \widetilde{g}_c(\ell_{1, 1}\oplus \ell_{1, 2}) - \widetilde{g}_c(\ell_{1, 1})$. Then $f_c : \mathbb N\cup\{ \infty\} \to Q(\overline{k})$ is given by
\[
f_c(n) = 
\begin{cases}
0 & \text{ if } n \leq m_0\\
\ell_{1, 1} & \text{ if } m_0 < n \leq m_0 + m_{\ell_{1, 1}} \\
\ell_{1, 1}\oplus \ell_{1, 2} & \text{ if } m_0 + m_{\ell_{1, 1}} < n \leq m_0 + m_{\ell_{1, 1}} + m_{\ell_{1, 1}\oplus \ell_{1, 2}}\\
V & \text{ if } m_0 + m_{\ell_{1, 1}} + m_{\ell_{1, 1}\oplus \ell_{1, 2}} < n.
 \end{cases}
\]
We write this chain as $m_0[0] + m_{\ell_{1, 1}}[\ell_{1, 1}] + m_{\ell_{1, 1}\oplus \ell_{1, 2}}[\ell_{1, 1}\oplus \ell_{1, 2}]$. When we have $\widetilde{g}_c(\ell_{1, 1}) = \widetilde{g}_c(\ell_{1, 1}\oplus \ell_{1, 2})$, $f_c$ takes the form 
\[
f_c(n) = 
\begin{cases}
0 & \text{ if } n \leq m_0\\
\ell_{1, 1} & \text{ if } m_0 < n \leq m_0 + m_{\ell_{1, 1}} \\
V_1 & \text{ if } m_0 + m_{\ell_{1, 1}} < n \leq m_0 + m_{\ell_{1, 1}} + m_{V_1}\\
V & \text{ if } m_0 + m_{\ell_{1, 1}} + m_{V_1} < n,
 \end{cases}
\]
where $m_{V_1} = \widetilde{g}_c(V_1) -  \widetilde{g}_c(\ell_{1, 1})$. We write this chain as $m_0[0] + m_{\ell_{1, 1}}[\ell_{1, 1}] + m_{V_1}[V_1]$.
\end{exam}



\subsubsection{Essential saturated elements}

%Let $Q$ be a finite \'etale poscheme with $\widehat{1}$ and assume that every subset of $Q(\overline{k})$ admits a meet.
We next define a poset structure on the set of chains $\mathrm{ch}(Q(\overline{k}))$.  We emphasize that our ordering is opposite to the poset structure naturally induced by $Q(\overline{k})$; this choice guarantees that the ordering of chains is compatible with the ordering of saturated elements of $\mathrm{Hilb}(B)^Q(\overline{k})$ so that there is no confusion when passing between the two settings.


\begin{defi}[{\cite[Section 3.4]{DT24}}] 
Let $Q$ be a finite \'etale poscheme with $\widehat{1}$ and assume that every subset of $Q(\overline{k})$ admits a meet.
For any $f, f' \in \mathrm{ch}(Q(\overline{k}))$, we say $f \leq f'$ holds if for any $n \in \mathbb N \cup\{\infty\}$, we have $f'(n) \leq f(n)$ as elements in $Q(\overline{k})$.

Since $Q(\overline{k})$ has meets, $\mathrm{ch}(Q(\overline{k}))$ has joins, i.e., for any $f, f' \in \mathrm{ch}(Q(\overline{k}))$, the join $f\vee f'$ of $f$ and $f'$ is given by
\[
(f\vee f')(n) = f(n)\wedge f'(n),
\]
for any $n \in \mathbb N \cup \{\infty\}$.
We have a canonical injective homomorphism
\begin{align*}
Q(\overline{k})^{\mathrm{op}} & \hookrightarrow \mathrm{ch}(Q(\overline{k})) \\
q & \mapsto (0 \leq q \leq \widehat{1}\leq \widehat{1} \leq \dotsb)
\end{align*}
\end{defi}

Now we introduce the notion of essential saturated pairs which plays a crucial role in our analysis:

\begin{defi}[{\cite[Definition 3.11]{DT24}}] \label{defi:essentialtype}
Let $Q$ be a finite \'etale poscheme with $\widehat{1}$ and assume that every subset of $Q(\overline{k})$ admits a meet.
We also assume that the natural inclusion $Q(k) \hookrightarrow Q(\overline{k})$ is a bijection.

Let $f_0 \in \mathrm{ch}(Q(\overline{k}))$ be a chain. Let $\mathfrak S$ be the set of $f_s \in \mathrm{ch}(Q(\overline{k}))$ such that $f_0 \prec f_s$, i.e., $f_0 < f_s$ and there is no $f'\in \mathrm{ch}(Q(\overline{k}))$ satisfying $f_0 < f' < f_s$.

We say a pair of chains $f_0 \leq f$ is essential if $f$ can be obtained from $f_0$ by taking the join of some subset of $\mathfrak S$. 

Let $B$ be a smooth projective curve. 
Suppose that $W \subset Q^{JB}$ is a locally closed subset with the reduced scheme structure.
We say that $(w\leq x) \in (W\leq Q^{JB})(\overline{k})$ is essential if for every $c \in \mathrm{Supp}(w\leq x)(\overline{k})$ we have that $f_c^w \leq f_c^x$ is essential.
\end{defi}

In our setting, this notion can be made explicit:

\begin{exam}
\label{exam:essentialsaturatedexample}
Let $Q$ be the poscheme defined in \cref{sect:keyexample} and considered in \cref{exam:saturatedexample}.  We will describe the essential saturated pairs $f_{0} \leq f$ where $f_{0} = m_{\ell_{i, 1}\oplus \ell_{i, 2}}[\ell_{i, 1}\oplus \ell_{i, 2}]$.

First let us list pairs such that $f_0 \prec f$: 
\begin{align*}
m_{\ell_{i, 1}\oplus \ell_{i, 2}}[\ell_{i, 1}\oplus \ell_{i, 2}] &\prec (m_{\ell_{i, 1}\oplus \ell_{i, 2}} +1)[\ell_{i, 1}\oplus \ell_{i, 2}] \\
m_{\ell_{i, 1}\oplus \ell_{i, 2}}[\ell_{i, 1}\oplus \ell_{i, 2}] &\prec [\ell_{i, j}]  + (m_{\ell_{i, 1}\oplus \ell_{i, 2}}-1)[\ell_{i, 1}\oplus \ell_{i, 2}] \qquad (j=1,2) 
\end{align*}
Then the list of pairs $f_0 \leq f$ in $\mathrm{ch}(Q)(\overline{k})$ such that $f_0 \leq f$ is essential is the above list plus the following pairs:
\begin{align*}
m_{\ell_{i, 1}\oplus \ell_{i, 2}}[\ell_{i, 1}\oplus \ell_{i, 2}] &=m_{\ell_{i, 1}\oplus \ell_{i, 2}}[\ell_{i, 1}\oplus \ell_{i, 2}]  \\
m_{\ell_{i, 1}\oplus \ell_{i, 2}}[\ell_{i, 1}\oplus \ell_{i, 2}] &< [\ell_{i, j}]  +m_{\ell_{i, 1}\oplus \ell_{i, 2}}[\ell_{i, 1}\oplus \ell_{i, 2}] \qquad (j=1,2) \\
m_{\ell_{i, 1}\oplus \ell_{i, 2}}[\ell_{i, 1}\oplus \ell_{i, 2}] &< [0] + (m_{\ell_{i, 1}\oplus \ell_{i, 2}}-1)[\ell_{i, 1}\oplus \ell_{i, 2}]\\
m_{\ell_{i, 1}\oplus \ell_{i, 2}}[\ell_{i, 1}\oplus \ell_{i, 2}] &< [0] + m_{\ell_{i, 1}\oplus \ell_{i, 2}}[\ell_{i, 1}\oplus \ell_{i, 2}]
\end{align*}
One can perform a similar analysis for other chains $f_{0}$.  The other relevant example for us will be the trivial chain $f_{0} = V = (0\leq V \leq V \leq \dotsb)$; in this case the list of saturated $f$ such that $f_{0} \leq f$ is essential is: 
\begin{equation*}
V, \qquad [V_{j}],  \qquad  [\ell_{i,1} \oplus \ell_{i,2}], \qquad   [\ell_{i,j}], \qquad [0],
\end{equation*}
as we vary over $j = 1,2$ and $i=1,\dotsc,4$.
\end{exam}




The following proposition is the main motivation of introducing this notion in \cite{DT24}:

\begin{prop}[{\cite[Proposition 3.13]{DT24}}]
\label{prop:homotopyequivalence}
Let $Q$ be a finite \'etale poscheme with $\widehat{1}$ and assume that every subset of $Q(\overline{k})$ admits a meet.


For any $f_0 \in \mathrm{ch}(Q(\overline{k}))$, essential pairs in $(f_0 < \mathrm{ch}(Q(\overline{k})))$ form an initial subposet of the poset $(f_0 < \mathrm{ch}(Q(\overline{k})))$. In particular the inclusion from the nerve of the subposcheme of essential pairs to the nerve $N(f_0 < \mathrm{ch}(Q(\overline{k})))$ of the poscheme $(f_0 < \mathrm{ch}(Q(\overline{k})))$ induces isomorphisms of $\ell$-adic cohomologies.
\end{prop}

\begin{proof}
For any $f_0 < f \in \mathrm{ch}(Q(\overline{k}))$, the set of essential elements $f_{0} < g$ satisfying $g \leq f$ admits a maximal element $\mathrm{ess}(f)$.  Indeed, one can define $\mathrm{ess}(f)$ to be the join of all $f_{s}$ such that $f_{0} \prec f_{s} \leq f$.  %as explained in \cite[Proposition 3.13]{DT24}.
Because $\mathrm{ess}(-)$ is right adjoint to the inclusion of essential elements, the natural transformation from the identity functor to  $\mathrm{ess}(-)$ induces a deformation retraction from the nerve of the finite \'etale poscheme $(f_0 < \mathrm{ch}(Q(\overline{k})))$ to the nerve of the poscheme of essential pairs.  (Alternately, see \cite[Lemma 3.2.1]{DH24}, and note this retract is proper in the sense of \cite[Section 2.1.3]{DH24} and so  \cite[Lemma 2.2.2]{DH24} applies).
\end{proof}

\subsection{Combinatorial functions}
 Here we follow the exposition of \cite[Section 3.5]{DT24}.



\begin{defi}
Let $B$ be a smooth projective curve.
Let $Q$ be a finite \'etale poscheme with meets and $\widehat{1}$. Let $h : Q(\overline{k}) \to \mathbb N$ be a function satisfying $h(\widehat{1}) = 0$.  Then we extend this function to $h : \mathrm{ch}(Q(\overline{k})) \to \mathbb N$ by
\[
h(f) = \sum_{n \geq 1} h(f(n)).
\]
Note that this is a finite sum due to the fact that $h(\widehat{1}) = 0$.

Next let $x \in Q^{JB}(\overline{k})$ be a saturated element which corresponds to a finitely supported function
\[
B(\overline{k}) \to  \mathrm{ch}(Q(\overline{k})), \, c  \mapsto f_c.
\]
We extend the function $h : \mathrm{ch}(Q(\overline{k})) \to \mathbb N$ to $h : Q^{JB}(\overline{k}) \to \mathbb N$ by defining it as
\[
h(x) = \sum_{c \in B(\overline{k})}h(f_c).
\]
Again this is well-defined because for the trivial chain $f = \widehat{1}$, we have $h(f) = 0$.
We further extend $h$ to $h : \mathrm{Hilb}(B)^Q(\overline{k}) \to \mathbb N$ by composing with $\mathrm{sat} : \mathrm{Hilb}(B)^Q(\overline{k}) \to Q^{JB}(\overline{k})$.


Finally we extend $h$ to pairs by $h(w \leq x) = h(w) - h(x)$ or $h(x) - h(w)$ depending on the context.

\end{defi}

We construct several functions on $Q^{JB}(\overline{k})$ using this construction following \cite[Section 3.5]{DT24}.

\begin{exam}[{\cite[Example 3.14]{DT24}}]
We fix $q_0 \in \widetilde{Q}(\overline{k})$, and we denote the indicator function of $\{q_0\}$ by $m_{q_0}$.
We call the extended $m_{q_0} : Q^{JB}(\overline{k}) \to \mathbb N$ as the number of occurrences of $q_0$.
This notion coincides with the notion used in \cref{exam:saturatedexample}.

\end{exam}

\begin{exam}[{\cite[Example 3.15]{DT24}}]
\label{exam:rankfunction}
We assume that $Q(k) = Q(\overline{k})$.
Assume that $Q(\overline{k})$ is a graded poset, i.e., every maximal chain in $Q(\overline{k})$ has the same length.
We first define the function $\mathrm{rank} : Q(\overline{k}) \to \mathbb N$ which assigns to $q \in Q(\overline{k})$ the length of the maximal chain starting at $\widehat{1} \in \mathrm{ch}(Q(\overline{k}))$ and ending at $q \in \mathrm{ch}(Q(\overline{k}))$. 
Then we extend this to the function $\mathrm{rank} : Q^{JB}(\overline{k}) \to \mathbb N$. The value $\mathrm{rank}(f)$ for $f \in \mathrm{ch}(Q(\overline{k}))$ is the length of the maximal chain starting at $\widehat{1} \in \mathrm{ch}(Q(\overline{k}))$ and ending at $f \in \mathrm{ch}(Q(\overline{k}))$.  For any $x \in Q^{JB}(\overline{k})$, the value $\mathrm{rank}(x)$ is equal to the cohomological dimension of the simplicial scheme $N([\widehat{1}, x]\cap Q^{JB}(\overline{k}))$.
\end{exam}

\begin{exam}[{\cite[Example 3.16]{DT24}}]
\label{exam:supportfunction}
For any $x \in Q^{JB}(\overline{k})$, we define $|\mathrm{Supp}(x)|$ as the number of $c \in B(\overline{k})$ such that $f_c$ is non-trivial.
\end{exam}

\begin{exam}
\label{exam:codimensionfunction}
Let $Q$ be the poscheme defined in \cref{sect:keyexample} and considered in \cref{exam:saturatedexample,exam:essentialsaturatedexample}.
We have $\mathrm{rank}(\ell_{i, 1} \oplus \ell_{i, 2}) = 1$, $\mathrm{rank}(V_j) =  1$, $\mathrm{rank}(\ell_{i, j}) = 2$, and $\mathrm{rank}(0) = 3$. This poset is graded.
Next we define $\gamma : Q(\overline{k}) \to \mathbb N$ by
\[
\gamma(\widehat{1}) = 0, \, \gamma(\ell_{i, 1} \oplus \ell_{i, 2}) = 2, \, \gamma(V_j) = 2, \gamma(\ell_{i, j}) = 3, \, \gamma(0) = 4.
\]
This extends to a combinatorial function $\gamma : Q^{JB}(\overline{k}) \to \mathbb N$. In \cref{subsec:blowups} we will interpret $\gamma(x)$ as the expected codimension of the incidence condition imposed by $x \in Q^{JB}(\overline{k})$.
\end{exam}



\subsection{Combinatorial stratifications of $Q^{JB}$}
Let $Q$ be a finite \'etale poscheme with $\widehat{1}$ and meets and let $B$ be a smooth projective curve.
We describe combinatorial stratifications of $\mathrm{Hilb}(B)^Q$ and $Q^{JB}$ following the exposition of \cite[Section 4]{DT24}.



\subsubsection{Stratifications by combinatorial types}

We define combinatorial types of $x \in \mathrm{Hilb}(B)^Q(\overline{k})$ following \cite[Section 4.1]{DT24}:
\begin{defi}[{\cite[Section 4.1]{DT24}}] \label{defn:combinatorial-type}
Let $x \in \mathrm{Hilb}(B)^Q(\overline{k})$ which corresponds to a finitely supported function
\[
B(\overline{k}) \to \mathrm{Hom}(\widetilde{Q}(\overline{k}), \mathbb N), \, c \mapsto \widetilde{g}_c.
\]
Then the combinatorial type of $x$ is the multiset
\[
\mathrm{type}(x) = \{\widetilde{g}_{c_1}, \dotsc, \widetilde{g}_{c_\ell}\}
\]
where $\{c_i \in B(\overline{k} )\, | \, i = 1, \dotsc, \ell\}$ is the support of $x$.
The set of combinatorial types is the set of multisets of homomorphisms $\widetilde{g} : \widetilde{Q} \to \mathbb N$.

Note that $x \in \mathrm{Hilb}(B)^Q(\overline{k})$ is in $Q^{JB}(\overline{k})$ if and only if every $g : Q (\overline{k})\to \mathbb N\cup \{\infty\} \in \mathrm{type}(x)$ is meet preserving. In this situation, we say that the multiset $\mathrm{type}(x)$ is saturated. 
\end{defi}

Note that there is a canonical bijection between saturated types and multisubsets of $\mathrm{ch}(Q(\overline{k}))$. Also the combinatorial type of the saturation $\mathrm{sat}(x)$ of $x\in \mathrm{Hilb}(B)^Q(\overline{k})$ only depends on the combinatorial type of $x$ showing that we have the saturation function from the set of combinatorial types to the set of saturated types.

Using combinatorial types, we obtain stratifications of $\mathrm{Hilb}(B)^Q$:

\begin{defi}[{\cite[Definition 4.1]{DT24}}]
Let $T$ be a combinatorial type. Then we define a Zariski locally closed subset $\mathcal N_{T, \overline{k}} \subset \mathrm{Hilb}(B)^Q_{\overline{k}}$ such that $\mathcal N_{T, \overline{k}}(\overline{k})$ is equal to the subset of $x \in \mathrm{Hilb}(B)^Q(\overline{k})$ such that $\mathrm{type}(x) = T$. Since $\mathcal N_{T, \overline{k}}$ is Galois invariant, it descends to a Zariski locally closed subset $\mathcal N_T \subset \mathrm{Hilb}(B)^Q$ defined over $k$.
\end{defi}

Note that the locally closed subset $\mathcal N_T$ is isomorphic to a form 
of the configuration space $\mathrm{Conf}(B;T)$ of $B$ labeled by $T$. Also we have
\[
\mathcal N_T\cap Q^{JB}\neq \emptyset \iff \mathcal N_T\subset Q^{JB}\iff \text{ $T$ is saturated.}
\]

\begin{defi}[{\cite[Definition 4.2]{DT24}}]
Let $\{\widetilde{g}_1, \dotsc, \widetilde{g}_\ell\}, \{ \widetilde{h}_1, \dotsc, \widetilde{h}_s\}$ be two combinatorial types. We say $\{\widetilde{g}_1, \dotsc, \widetilde{g}_\ell\} \geq \{ \widetilde{h}_1, \dotsc, \widetilde{h}_s\}$ if there is a injective map $\sigma : \{1, \dotsc, s\} \to \{1, \dotsc, \ell\}$ such that for any $j \in \{1, \dotsc, s\}$, we have
\[
\widetilde{g}_{\sigma(j)} \geq \widetilde{h}_j.
\] 


We say $\{\widetilde{g}_1, \dotsc, \widetilde{g}_\ell\} \geq_+ \{ \widetilde{h}_1, \dotsc, \widetilde{h}_s\}$ if there is a surjective map $\sigma : \{1, \dotsc, \ell\} \to \{1, \dotsc, s\}$ such that for any $j \in \{1, \dotsc, s\}$, we have
\[
\sum_{i \in \sigma^{-1}(j)} \widetilde{g}_i \geq \widetilde{h}_j.
\] 
Also when $s = 0$, i.e., $\{ \widetilde{h}_1, \dotsc, \widetilde{h}_s\} = \emptyset$, we formally insist that we have $\{\widetilde{g}_1, \dotsc, \widetilde{g}_\ell\} \geq_+ \emptyset$.




\end{defi}

Note that with this definition, the set
\[
\bigcup_{T' \leq_+ T} \mathcal N_{T'},
\]
is closed in $\mathrm{Hilb}(B)^Q$ and is downward-closed with respect to the poscheme structure of $\mathrm{Hilb}(B)^Q$.

\begin{defi}[{\cite[Definition 4.5]{DT24}}]
Let $T$ be a saturated combinatorial type. We define
\[
\mathcal S_{T} = \bigcup_{T', \mathrm{sat}(T') = T} \mathcal N_{T'}.
\]
\end{defi}

Note that $\mathcal S_{T}$ agrees with the disjoint union $\sqcup_{T', \mathrm{sat}(T') = T} \mathcal N_{T'}$. This provides a coarse stratification of $\mathrm{Hilb}(B)^Q$.
We define the relation $\leq_{+, \mathrm{sat}}$ as the transitive closure of the following relation on the set of saturated combinatorial types: 
\[
T_1 \preceq_{+, \mathrm{sat}} T_2 \text{ if there exist types $T_1', T_2'$ with $T_1' \leq_+ T_2'$ and $\mathrm{sat}(T_i') = T_i$ for $i = 1, 2$.}
\]
This defines a poset structure on the set of saturated types, and the saturation function from the set of combinatorial types to the set of saturated combinatorial types is a homomorphism with respect to $\leq_+$ and $\leq_{+, \mathrm{sat}}$ (\cite[Proposition 4.6]{DT24}).

For any saturated type $T$, we define 
\[
\mathcal Z_T = \bigcup_{T' \text{ saturated}, T' \leq_{+, \mathrm{sat}} T} \mathcal S_{T'} = \bigcup_{\widetilde{T}, \, \mathrm{sat}(\widetilde{T})\leq_{+, \mathrm{sat}}T} \mathcal N_{\widetilde{T}}.
\]
It follows that $\mathcal Z_T$ is closed in $\mathrm{Hilb}(B)^Q$ and is downward-closed with respect to the poset structure of $\mathrm{Hilb}(B)^Q$. 
Also we have 
\[
\mathcal Z_{T_1} \subset \mathcal Z_{T_2} \iff T_1 \leq_{+, \mathrm{sat}} T_2,
\]
and 
\[
\mathcal Z_T \setminus \bigcup_{T' <_{+, \mathrm{sat}}T} \mathcal Z_{T'} = \mathcal S_T.
\]
See \cite[After Proposition 4.6]{DT24} for more details.



\subsection{Variants}
As usual $Q$ is a finite \'etale poscheme with $\widehat{1}$ and meets and $B$ is a smooth projective curve.



\noindent
{\bf Relative variant:}


In \cite[Section 4.3]{DT24}, the first and the fourth authors extended the notion of combinatorial types for the poscheme
\[
(\mathrm{Hilb}(B)^Q \leq \mathrm{Hilb}(B)^Q),
\]
consisting of pairs $(w \leq x)$ where $w, x \in \mathrm{Hilb}(B)^Q$.
Indeed, one may interpret this poscheme as $\mathrm{Hilb}(B)^{Q \times I}$ where $I$ is the poscheme consisting of two $k$-rational points $\widehat{0} \leq \widehat{1}$, and we give $Q \times I$ the product poscheme structure.
Any combinatorial type of this poscheme is a multiset of the form
\[
\{\widetilde{g}_{c_1}^w\leq \widetilde{g}_{c_1}^x,  \dotsc,  \widetilde{g}_{c_\ell}^w\leq \widetilde{g}_{c_\ell}^x\}.
\]
For each such combinatorial type $T$, we have a Zariski locally closed subset $\mathcal N_T \subset (\mathrm{Hilb}(B)^Q \leq \mathrm{Hilb}(B)^Q)$ defined over $k$.
We also have the relations $\leq_+$ and $\leq_{+, \mathrm{sat}}$ on the set of combinatorial types and the set of saturated types respectively. 
Let $W\subset \mathrm{Hilb}(B)^Q$ be a locally closed subset which is a finite union of locally closed subsets $\mathcal N_{T''}$ where $T''$ is a saturated type of $\mathrm{Hilb}(B)^Q$.  
Let $T$ be a saturated combinatorial type of $(W \leq \mathrm{Hilb}(B)^Q)$.
Then we define
\[
\mathcal Z_T =  \left(\bigcup_{T', \, \mathrm{sat}(T')\leq_{+, \mathrm{sat}}T} \mathcal N_{T'} \right)\cap (W < \mathrm{Hilb}(B)^Q),
\]
which is closed and downward-closed in $(W \leq \mathrm{Hilb}(B)^Q)$.


\noindent
{\bf Pointed variant:}

Assume that $B$ is pointed, i.e., we fix a $k$-rational point $* \in B$.
Since the Cohen-Jones-Segal conjecture addresses the space of pointed maps, we need to extend our definitions to pointed maps as explained in \cite[Section 4.4]{DT24}. A combinatorial type of $\mathrm{Hilb}(B, *)^Q$ is a multiset
\[
\{\widetilde{g}_{c_0}, \widetilde{g}_{c_1}, \dotsc, \widetilde{g}_{c_\ell}\},
\]
where $c_0 = *$. Note that $\widetilde{g}_{c_0}$ could be the trivial function.
We have
\[
\{\widetilde{g}_0, \widetilde{g}_1, \dotsc, \widetilde{g}_\ell\} \geq_+\{\widetilde{h}_0, \widetilde{h}_1, \dotsc, \widetilde{h}_s\}, 
\]
if there is a pointed surjective map $\sigma : \{0\} \cup \{1, \dotsc, \ell\} \to \{0\} \cup \{1, \dotsc, s\}$ such that 
for any $j \in \{0\}\cup \{1, \dotsc, s\}$ we have $h_j \leq \sum_{i \in \sigma^{-1}(j)} g_i$.
This induces $\leq_{+, \mathrm{sat}}$ and the stratification $\mathcal Z_T$ and $\mathcal S_T$.









\section{Our common set up: blow ups of a smooth quadric surface}
\label{subsec:blowups}

We next describe the common setup for the Cohen--Jones--Segal conjecture in \cref{sec:CJS} and for Manin's conjecture in \cref{sec:Manin}.  Recall from the introduction that we will think of a split degree $4$ del Pezzo surface $S$ as a blow-up of a quadric surface $\mathbb{P}^{1} \times \mathbb{P}^{1}$ at four points.  This section explains how to relate curves on $S$ and $\mathbb{P}^{1} \times \mathbb{P}^{1}$.


Throughout this section we assume that our ground field $k$ is a perfect field.  


\subsection{Blow-ups of quadric surfaces}




We consider a smooth quadric surface $\mathbb{P}^{1} \times \mathbb{P}^{1}$
with the projection maps $\pi_j:\mathbb{P}^{1} \times \mathbb{P}^{1} \to \mathbb P^1$ for $j = 1, 2$.
Let $r \geq 0$ be a positive integer and fix $r$ distinct $k$-rational points $(p_1, p_1'), \dotsc, (p_r, p_r')$ on $\mathbb{P}^{1} \times \mathbb{P}^{1}$.  Let $\rho_r : S_r \to \mathbb{P}^{1} \times \mathbb{P}^{1}$ be the blow up of $\mathbb{P}^{1} \times \mathbb{P}^{1}$ at $(p_1, p_1'), \dotsc, (p_r, p_r')$.  We will always make the following:

\begin{assu}
The points $\{ p_i \}_{i=1}^{r}$ are distinct and the points $\{ p'_i \}_{i=1}^{r}$ are distinct. 
\end{assu}

Note that this assumption is satisfied for any birational morphism $S \to \mathbb{P}^{1} \times \mathbb{P}^{1}$ from a split degree $4$ del Pezzo surface $S$.




For a fixed smooth projective curve $B$, our goal is to understand the cohomology of 
\[
\mathrm{Mor}(B, S_r).
\]
Let $E_1, \dotsc, E_r$ be the exceptional divisors above $(p_1, p_1') \dotsc, (p_r, p_r')$ and for $j=1,2$ let $F_j$ be a general fiber of $\pi_j \circ \rho_r : S_r \to \mathbb P^1$. By abuse of notation, we also denote a general fiber of $\pi_j$ by $F_j$ as well.

Given a nef curve class $\alpha$ on $S_r$, we define
\[
-K_{S_r}.\alpha = h(\alpha), \qquad a(\alpha) = F_1. \alpha, \qquad  a'(\alpha) = F_2.\alpha, \qquad E_i.\alpha = k_i(\alpha).
\]
Then we have
\[
h(\alpha) = 2a(\alpha) + 2a'(\alpha) -\sum_{i = 1}^r k_i(\alpha).
\]
Note that once we fix $a(\alpha), a'(\alpha), k_1(\alpha), \dotsc, k_r(\alpha)$, then the numerical class $\alpha$ is uniquely determined.  Furthermore this notation is consistent with the special case of degree $4$ del Pezzo surfaces established in \cref{nota:bignota}.


\subsection{Parametrizing curves}

Fix a smooth projective curve $B$ defined over $k$.  A morphism $f : B \to \mathbb{P}^{1} \times \mathbb{P}^{1}$ is exactly the same as a pair of morphisms from $B$ to the two $\mathbb{P}^{1}$ factors.  Thus there is a bijective correspondence between morphisms $f: B \to \mathbb{P}^{1} \times \mathbb{P}^{1}$ and equivalence classes of pairs of line bundles $L_{1},L_{2}$ on $B$ equipped with non-vanishing sections
\[
s \in H^0(B, L_1^{\oplus 2}), \, t \in H^0(B, L_2^{\oplus 2}),
\]
where the equivalence is defined by the rescaling action of $s$ and $t$ separately.  

Let us write $\mathbb{P}^{1} \times \mathbb{P}^{1} = \mathbb P(V_1) \times \mathbb P(V_2)$ where each $V_i$ is a $2$-dimensional vector space.  We fix two non-negative integers $a, a'$ and we set $\mathcal B = \Pic^a(B) \times \Pic^{a'}(B)$.
Let $\mathcal L_a, \mathcal L_{a'}$ be the line bundles on $B \times \mathcal B$ which are pullbacks of the universal line bundles on $B \times \Pic^a(B)$ and $B\times \Pic^{a'}(B)$ respectively. Then we set
\[
\mathcal V_1 = \mathcal L_a \otimes V_1, \, \mathcal V_2 = \mathcal L_{a'} \otimes V_2, \, \mathcal V = \mathcal V_1 \oplus \mathcal V_2,
\]
which we consider both as locally free sheaves on $B \times \mathcal B$ and as the corresponding vector bundles.  We define the scheme of sections $\Gamma(B, \mathcal V) \to \mathcal B$ which represents the functor
\[
(\phi : T \to \mathcal B) \mapsto \Gamma(B \times T, (\mathrm{id}, \phi)^*\mathcal V)
\]
There is a Zariski open subscheme of $\Gamma(B,\mathcal{V})$ parametrizing pairs of sections $(s,t) \in H^{0}(B,\mathcal{V}_{1} \oplus \mathcal{V}_{2})$ such that neither $s$ nor $t$ vanishes on $B$.  This open subscheme defines a $\mathbb{G}_{m}^{2}$-torsor over the moduli space of morphisms $f: B \to \mathbb{P}^{1} \times \mathbb{P}^{1}$ of bidegree $(a,a')$.



We next turn to morphisms $f': B \to S_{r}$.  For a nef curve class $\alpha$ on $S_{r}$, we let $M_{\alpha}$ denote the moduli space of morphisms $f': B \to S_{r}$ whose numerical class lies in $\alpha$.  Note that choosing a morphism $f' : B \to S_r$ such that $s'_*[B] = \alpha$ is equivalent to choosing a morphism $f : B \to \mathbb{P}^{1} \times \mathbb{P}^{1}$ such that
\begin{itemize}
\item $\deg \, f^*F_1 = a(\alpha)$;
\item $\deg \, f^*F_2 = a'(\alpha)$; and
\item for any $i = 1, \dotsc, r$, the local multiplicity of $f(B)$ at $(p_i, p_i')$ is given by $k_i(\alpha)$.
\end{itemize}
For each index $i=1,\dotsc,r$ there are $1$-dimensional subspaces $\ell_{i, 1} \subset V_1$ and $\ell_{i, 2} \subset V_2$ corresponding to $p_i$ and $p_i'$ respectively.  Then the local multiplicity $k_i(\alpha)$ of $f$ at $(p_i, p_i')$ is given by the length of the subscheme $(s, t)^{-1}(\ell_{i, 1}\oplus \ell_{i, 2})$ on $B$.  


Let $\widetilde{M}_\alpha$ denote the locally closed subscheme of $\Gamma(B,\mathcal{V})$ such that the fiber over $(L_{1},L_{2}) \in \mathcal{B}$ parametrizes all pairs of nonvanishing sections $(s,t) \in H^{0}(B,\mathcal{V}_{1} \oplus \mathcal{V}_{2})$ such that the length of the subscheme $(s, t)^{-1}(\ell_{i, 1}\oplus \ell_{i, 2})$ is $k_i(\alpha)$ for every $i = 1, \dotsc, r$. 
 Then we have a natural morphism
\[
\widetilde{M}_\alpha \to M_\alpha
\]
which is a $\mathbb G_m^2$-torsor over $M_\alpha$.



\subsection{Stratifying the space of sections}
\label{subsubsec:stratifyingthespace of sectons}


Finally, we define a stratification of $\Gamma(B,\mathcal{V})$.  Let $Q$ be the poscheme defined by the following set of subspaces of $V$ as in \cref{sect:keyexample}: 
\begin{equation*}
%\label{eq:poschemeexam}
\{ V, V_1 \oplus \{0\}, \{0\} \oplus V_2,  0 \} \cup \{ \ell_{i, 1} \oplus \ell_{i, 2}, \ell_{i, 1} \oplus \{0\}, \{0\} \oplus \ell_{i, 2}  \}_{i=1,\dotsc,r}.
\end{equation*}
%\begin{equation*}
%\{ V, V_1 \oplus \{0\}, \{0\} \oplus V_2, \ell_{i, 1} \oplus \ell_{i, 2}, \ell_{i, 1} \oplus \{0\}, \{0\} \oplus \ell_{i, 2}  \, (i = 1, \dotsc, r), 0\}.
%\end{equation*}
For any subspace $K_q \in Q$, we define the corresponding subbundle $\mathcal K_q \subset \mathcal V$ over $B \times \mathcal{B}$.
Since the poscheme $Q$ is closed under intersection, we have
\[
\mathcal K_{q_1} \cap \mathcal K_{q_2} = \mathcal K_{q_1 \wedge q_2},
\]
for any $q_1, q_2\in Q$.

For any $q \in Q$ we also have the universal divisor 
\[
\mathcal D_q' \subset B \times \mathrm{Hilb}(B)^Q
\]
such that the restriction of $\mathcal D_q'$ over $D \in \mathrm{Hilb}(B)^Q(T)$ is the divisor $D_q$ on $B \times T$.
We denote the pullback of $\mathcal D_q'$ via $B \times \mathcal B \times \mathrm{Hilb}(B)^Q \to B\times \mathrm{Hilb}(B)^Q$ by $\mathcal D_q$.
We also denote the projection $B \times \mathcal B \times\mathrm{Hilb}(B)^Q\to B \times \mathcal B$ by $p$.
Then we define $\Gamma_Q(B, \mathcal V)$ as the fiber product:  
\[
\xymatrix{
  \Gamma_Q(B, \mathcal V) \ar[r] \ar[d] & \prod_{q \in \widetilde{Q}}\Gamma(\mathcal D_q, p^*\mathcal K_q) \ar[d] \\
  \Gamma(B, \mathcal V) \times \mathrm{Hilb}(B)^Q \ar[r] & \prod_{q \in \widetilde{Q}}\Gamma(\mathcal D_q, p^*\mathcal V).
}
\]
Thus $\Gamma_Q(B, \mathcal V)$ is the closed subscheme of $\Gamma(B, \mathcal V) \times \mathrm{Hilb}(B)^Q$ such that the fiber over the point $\mathfrak{b} \in \mathcal{B}$ parametrizes pairs of a section $s \in \Gamma(B, \mathcal V_\mathfrak{b})$ and an element $(x_{q}) \in \mathrm{Hilb}(B)^Q$ satisfying $s(x_q) \subset (\mathcal K_q)_{\mathfrak{b}}$ for every $q \in Q$.
Note that the scheme $ \Gamma_Q(B, \mathcal V)$ is a $(\mathcal B \times \mathrm{Hilb}(B)^Q)$-scheme.
If we have $(x_{q}) \leq (x'_{q})$ in $ \mathrm{Hilb}(B)^Q$ so that we have containments $D_q \subset D'_q$ for every $q$, then for every $\mathfrak{b} \in \mathcal{B}$ we have 
\[
  \Gamma_Q(B, \mathcal V)_{\mathfrak b, x'} \subset  \Gamma_Q(B, \mathcal V)_{\mathfrak b, x}.
\]
In this way, $\Gamma(B, \mathcal V)$ admits a stratification parametrized by the poscheme $\mathrm{Hilb}(B)^Q$.  This stratification is insensitive to taking saturations, in the sense that for any $x \in \mathrm{Hilb}(B)^{Q}(k)$ and $\mathfrak{b} \in \mathcal{B}$ we have $\Gamma(B,\mathcal{V})_{\mathfrak{b},x} = \Gamma(B,\mathcal{V})_{\mathfrak{b},\mathrm{sat}(x)}$.

This stratification is compatible with the construction of moduli spaces of curves described above.  Suppose we fix a nef numerical class $\alpha$ on $S_{r}$.  Consider the sublocus $U_{\mathbf{k}(\alpha)} = \cup_{T} \mathcal{N}_{T}$ as $T$ varies over saturated combinatorial types of the form
\begin{equation*}
T = \left\{ m_{ij}[\ell_{i,1} \oplus \ell_{i,2}] \left| \sum_{j=1}^{t_{i}} m_{ij} = k_{i}(\alpha) \right. \right\}_{\substack{i=1,\dotsc,r \\ j=1,\dotsc,t_{i}}}.
\end{equation*}
Let $E \to \mathcal B \times U_{\mathbf{k}(\alpha)}$ be the restriction of $\Gamma_Q(B, \mathcal V) \to \mathcal B \times \mathrm{Hilb}(B)^Q$ to $ \mathcal B \times U_{\mathbf{k}(\alpha)}$.
Then the moduli space $\widetilde{M}_{\alpha}$ can be described as 
\begin{equation*}
\widetilde{M}_{\alpha} = \bigcup_{w \in U_{\mathbf{k}(\alpha)}}(E_w \backslash \left( \cup_{(w < x) \in (W_\alpha < \mathrm{Hilb}(B)^Q)} )\Gamma(B,\mathcal{V})_{x} \right),
\end{equation*}
where $E_w = \Gamma_Q(B, \mathcal V)_w$.















\section{Bar complexes over perfect fields}
\label{sec:barconstruction}

In this section we prove the main technical result that compares the cohomology of a space over $U_{\mathbf{k}}$ to the cohomology of an associated bar complex.  In particular we extend \cite[Theorem 5.4]{DT24} from $\mathbb{C}$ to arbitrary perfect fields.  While the treatment in \cite{DT24} relies on the geometric realizations of simplicial spaces, our discussion is based on simplicial schemes and their sheaf theoretic constructions.




\subsection{Stratifying the bar complex}
Let $B$ be a smooth projective curve with possibly a fixed base point.
We consider the non-pointed case and pointed case simultaneously.

Let $W\subset \mathrm{Hilb}(B)^Q$ be a locally closed set which is a finite union of locally closed subsets $\mathcal N_T$ where $T$ is a saturated type. We equip $W$ with the reduced scheme structure so that $W$ is a separated reduced scheme of finite type over $k$. Let $P \subset (W < \mathrm{Hilb}(B)^Q)$ be a closed and downward closed union of locally closed sets $\mathcal S_T$ for finitely many saturated types $T$ of $(W < \mathrm{Hilb}(B)^Q)$ equipped with the reduced scheme structure.
We assume that the projection $P \to W$ is proper.
Let $\mathcal B$ be a separated scheme of finite type over $k$ and let $U \subset \mathcal B \times W$ be an open subset. We write $(U \leq \mathrm{Hilb}(B)^Q)$ and $P_U \to U$ for the pullbacks of $(W \leq \mathrm{Hilb}(B)^Q) \to W$ and $P \to W$ by $U \subset \mathcal B \times W \to W$.

Suppose that we have a flat separated morphism $E \to U$ of finite type with irreducible geometric fibers which admits a stratification by the poset $(U \leq \mathrm{Hilb}(B)^Q)$ corresponding to the closed subscheme $Z \subset E\times_U (U \leq \mathrm{Hilb}(B)^Q)$.
We assume that for any $(\mathfrak b, w < x) \in (U < \mathrm{Hilb}(B)^Q)(\overline{k})$, the stratification $Z_{\mathfrak b, w<x} \subset E_{\mathfrak b, w}$ is an irreducible closed subscheme 
and that the inclusion
\[
Z_{\mathfrak b, w < x} \supset Z_{\mathfrak b, w < \mathrm{sat}(x)}
\]
is the equality. We also suppose that when we have two saturated elements $w \leq x_1$ and $w \leq x_2$, then we have
\[
Z_{\mathfrak b, w\leq x_1}\cap Z_{\mathfrak b, w \leq x_2} = Z_{\mathfrak b, w \leq x_1\vee x_2}.
\]

We are interested in the bar complex $B(P_U, Z_{P_U})$ with simplices
\[
\{ (\mathfrak b, w) \in U, w < x_0 \leq \dotsb \leq x_m \in \mathrm{Hilb}(B)^Q, z \in Z_{\mathfrak b, w < x_m}\, | \, (w < x_i) \in P \},
\]
with the augmentation morphism $\epsilon : B(P_U, Z_{P_U}) \to E_U$ given by
\[
((\mathfrak b, w) \in U, w < x_0 \leq \dotsb \leq x_m, z)\mapsto (\mathfrak b, w, z).
\]


\subsection{Spectral sequence}
Since $B(P_{U},Z_{P_U})$ is a bar complex, we can analyze its cohomology using the spectral sequence in \cref{subsec:spectralsequenceforstratifiedspaces}.  Our first task is to reinterpret the terms in this spectral sequence as the cohomology of certain complexes of sheaves on $Z|_{U \times_{W} \mathcal{N}_{T}}$.  The advantage of this perspective is that only the essential saturated types $T$ make a non-trivial contribution.


Let $\mathfrak T$ be the set of saturated combinatorial types in $P$ with ordering $\leq_+$.
We fix an injective homomorphism $h : \mathfrak T \to \mathbb N$.
Let $\mathcal Z_i = \cup_{h(T)\leq i} \mathcal Z_T$ and consider
\[
B_i = B(U \times_W \mathcal Z_i, Z_{P_U}) \subset B(P_U, Z_{P_U}).
\]  
The closed embeddings $\iota'_{i}: B_{i} \to B(P_U, Z_{P_{U}})$ define a stratification into closed subschemes. Retaining the notation of \cref{subsec:spectralsequenceforstratifiedspaces} to define a grading of $\underline{\mathbb{Z}}_{\ell}$ associated to this stratification, we obtain the following spectral sequence:
\[
\bigoplus_{i + j = n} E_1^{i, j} = \bigoplus_{i} H^{n}_{\text{\'et}, c}(B(P_U, Z_{P_U})_{\overline{k}}, \mathrm{Gr}_F^i \underline{\mathbb{Z}}_\ell) \implies H^{n}_{\text{\'et}, c}(B(P_U, Z_{P_U})_{\overline{k}}, \underline{\mathbb{Z}}_\ell).
\]
We consider $Z|_{U \times_W \mathcal N_{h^{-1}(i)}}$ and the associated nerve 
\[
\epsilon_i: (N(-\infty, Z|_{U\times_W \mathcal S_{h^{-1}(i)}} )< Z|_{U \times_W \mathcal N_{h^{-1}(i)}}) \to Z|_{U\times_W \mathcal N_{h^{-1}(i)}}
\]
which is defined to be the simplicial scheme over $Z|_{U \times_W \mathcal N_{h^{-1}(i)}}$ with $m$-th simplex given by 
\[
\{\mathfrak b, w < x_0\leq \dotsb \leq x_m < y, z \, | \, (\mathfrak b, w) \in U, (w < y)\in \mathcal N_{h^{-1}(i)}, (w < x_m) \in \mathcal Z_{h^{-1}(i)}  \setminus \mathcal S_{h^{-1}(i)},  z \in Z_{\mathfrak b, w < y} \},
\]
and the augmentation morphism $\epsilon_i : (N(-\infty, Z|_{U\times_W \mathcal S_{h^{-1}(i)}} )< Z|_{U \times_W \mathcal N_{h^{-1}(i)}})\to Z|_{U \times_W \mathcal N_{h^{-1}(i)}}$ is
\[
\epsilon_i : (\mathfrak b, w < x_0\leq \dotsb \leq x_m < y, z) \mapsto (\mathfrak b, w < y, z).
\]
We define the complex $\mu'(h^{-1}(i))[2] \in D^b(Z|_{U \times_W \mathcal N_{h^{-1}(i)}})$ to be the cone yielding the distinguished triangle
\[
 \underline{\mathbb Z}_\ell \to R\epsilon_{i*}\epsilon_i^*\underline{\mathbb Z}_\ell \to \mu'(h^{-1}(i))[2] \to \underline{\mathbb Z}_\ell[1] \to.
\]
Then we have the following proposition:
\begin{prop} \label{prop:ssforbarconstruction}
\[
H^{i + j}_{\text{\'et}, c}(B(P_U, Z_{P_U})_{\overline{k}}, \mathrm{Gr}_F^i\underline{\mathbb Z}_{\ell} ) \cong H^{i + j}_{\text{\'et}, c}((Z|_{U \times_W \mathcal N_{h^{-1}(i)}})_{\overline{k}}, \mu'(h^{-1}(i))[1]).
\]
\end{prop}



\begin{proof}
It suffices to show that we have
\[
R\epsilon_*\mathrm{Gr}_F^i\underline{\mathbb Z}_{\ell} \cong R\pi_{i!}\mu'(h^{-1}(i))[1],
\]
where $\epsilon$ is the augmentation morphism for $B(P_{U},Z_{P_U})$ and   $\pi_i : Z|_{U \times_W \mathcal N_{h^{-1}(i)}} \to E|_U$ is the projection.
Consider the relative poscheme $(-\infty,Z|_{U \times_W \mathcal N_{h^{-1}(i)}}]$ over $Z|_{U \times_W \mathcal N_{h^{-1}(i)}}$ as defined in \cite[Definition 3.1.3]{DH24}.
Let $\xi_i : N(-\infty, Z|_{U \times_W \mathcal N_{h^{-1}(i)}}] \to B_i$ 
be the morphism of simplicial schemes defined by 
\[
(w < x_0\leq \dotsb \leq x_m \leq y, z) \mapsto (w < x_0\leq \dotsb \leq x_m, z).
\]
We have an exact sequence on $B_{i}$:
\[
0 \to \mathrm{Gr}_F^i\underline{\mathbb Z}_{\ell}  \to \underline{\mathbb Z}_{\ell}|_{(B_{i})_{\overline{k}}} \to R\iota'_{i-1!}\underline{\mathbb Z}_{\ell}|_{(B_{i-1})_{\overline{k}}}  \to 0.
\]
Let $U_m = B_i([m]) \setminus B_{i-1}([m])$. We denote $U_m \hookrightarrow B_i([m])$ by $j_m$.  
The exact sequence above allows us to identify $(\mathrm{Gr}_F^i\underline{\mathbb Z}_{\ell})_m \cong Rj_{m!}j_m^*(\mathrm{Gr}_F^i\underline{\mathbb Z}_{\ell})_m$.  This implies that the natural morphism $\mathrm{Gr}_F^i\underline{\mathbb Z}_{\ell} \to R\xi_{i*}\xi_i^*\mathrm{Gr}_F^i\underline{\mathbb Z}_{\ell}$ is an isomorphism. Indeed this follows from the fact that the map
\[
\xi_i([m])^{-1}(U_m) \to U_m
\]
is an isomorphism because the inverse morphism is given by
\[
(w < x_0\leq \dotsb \leq x_m, z) \mapsto (w < x_0\leq \dotsb \leq x_m \leq \mathrm{sat}(x_m), z). 
\]
Then our assertion follows from the computation of \cite[Lemma 4.3.3]{DH24}
with $X = Z|_{U \times_W \mathcal N_{h^{-1}(i)}}$.
\end{proof}

Thus we have the following spectral sequence:
\begin{equation*}
\bigoplus_{i + j = n}E_1^{i, j} = \bigoplus_{T: \text{ saturated types of $P$}} H^{n}_{\text{\'et}, c}((Z|_{U \times_W\mathcal N_{T}})_{\overline{k}}, \mu'(T)[1]) \implies H^{n}_{\text{\'et}, c}(B(P_U, Z_{P_U})_{\overline{k}}, \mathbb Z_\ell).
\end{equation*}
Next we record a lemma regarding the complex $\mu'(\bullet)$. 
\begin{lemm}
When $T$ is not essential, we have $\mu'(T) \cong 0$.
\end{lemm}
\begin{proof}
Let $(\mathfrak b, w < y, z) : \Spec \, \kappa \to Z|_{U \times_W \mathcal N_T}$ be a geometric point.
Since $T$ is not essential, as explained in the proof of \cref{prop:homotopyequivalence} 
there is a maximum essential element $\mathrm{ess}(y)$ with $w < \mathrm{ess}(y) < y$ and $(w < \mathrm{ess}(y)) \not\in \mathcal S_T(\kappa)$. 
Indeed, $\mathrm{ess}(y)$ is defined as the join of $y'$ such that $w \prec y' \leq y$.
This implies that the nerve 
\[
(N(-\infty, Z|_{U \times_W \mathcal S_T}) < Z|_{U \times_W \mathcal N_T})_{(\mathfrak b, w < y, z)} \to \Spec \, \kappa
\]
admits a weak center in the sense of \cite[Definition 3.1.6]{DH24}. Thus it follows from \cite[Theorem 4.0.1]{DH24} that we have an isomorphism
\[
\underline{\mathbb Z}_\ell \cong R\epsilon_{T*}\epsilon_T^* \underline{\mathbb Z}_\ell,
\]
where $\epsilon_T : (N(-\infty, Z|_{U\times_W \mathcal S_{T}} )< Z|_{U \times_W \mathcal N_{T}}) \to Z|_{U\times_W \mathcal N_{T}}$ is the augmentation morphism.
Our assertion follows.
\end{proof}

Altogether we conclude the following theorem, extending an analogous statement over $\mathbb{C}$ proved by \cite[Theorem 5.3]{DT24}.

\begin{theo}
\label{theo:spectralsequenceforbar}
There is a spectral sequence:
\[
\bigoplus_{i + j = n} E_1^{i, j} = \bigoplus_{T: \text{ essential types of $P$}} H^{n}_{\text{\'et}, c}((Z|_{U \times_W \mathcal N_T})_{\overline{k}}, \mu'(T)[1]) \implies H^{n}_{\text{\'et}, c}(B(P_U, Z_{P_U})_{\overline{k}}, \mathbb Z_\ell).
\]
\end{theo}


Finally for a later application, we record the following lemma comparing saturated and non-saturated types.
\begin{lemm}
\label{lemm:deformationretract}
The following inclusion over $Z|_{U \times_W \mathcal N_{T}}$ 
\[
(N((-\infty, Z|_{U\times_W \mathcal S_{T}} ) \cap Q^{JB})< Z|_{U \times_W \mathcal N_{T}}) \hookrightarrow (N(-\infty, Z|_{U\times_W \mathcal S_{T}} )< Z|_{U \times_W \mathcal N_{T}})
\]
induces an isomorphism
\[
R\epsilon'_{T*}\epsilon_T'^*\underline{\mathbb Z}_\ell \cong R\epsilon_{T*}\epsilon_T^*\underline{\mathbb Z}_\ell ,
\]
where $\epsilon'_T : (N((-\infty, Z|_{U\times_W \mathcal S_{T}} )\cap Q^{JB})< Z|_{U \times_W \mathcal N_{T}}) \to Z|_{U\times_W \mathcal N_{T}}$ is the augmentation morphism.
%\begin{align*}
%H^i_{\text{\'et}, c}(N((w, \mathrm{sat}^{-1}(x)] \cap Q^{JB}(\overline{k})) \setminus N((w, \mathrm{sat}^{-1}(x))\cap Q^{JB}(\overline{k})), \mathbb Z_\ell) \\
%\cong H^i_{\text{\'et}, c}(N((w, \mathrm{sat}^{-1}(x)]) \setminus N((w, \mathrm{sat}^{-1}(x)), \mathbb Z_\ell).
%\end{align*}
\end{lemm}
\begin{proof}
A similar proof to \cref{prop:homotopyequivalence} will justify this. 
Indeed, for an algebraically closed field $\kappa$, the map
\begin{align*}
((-\infty, Z|_{U\times_W \mathcal S_{T}} )< Z|_{U \times_W \mathcal N_{T}})(\kappa) &\to (((-\infty, Z|_{U\times_W \mathcal S_{T}} ) \cap Q^{JB})< Z|_{U \times_W \mathcal N_{T}})(\kappa), \\
(\mathfrak b, w < x < y) &\mapsto (\mathfrak b, w < \mathrm{sat}(x)  < y),
\end{align*}
is a left adjoint functor to the inclusion functor 
\begin{equation*}
(((-\infty, Z|_{U\times_W \mathcal S_{T}} ) \cap Q^{JB})< Z|_{U \times_W \mathcal N_{T}})(\kappa)  \hookrightarrow ((-\infty, Z|_{U\times_W \mathcal S_{T}} )< Z|_{U \times_W \mathcal N_{T}})(\kappa).
\end{equation*}
Because nerves take adjoint functors to homotopy equivalences, it follows that for a geometric point $(\mathfrak b, w < y , z) \in Z|_{U \times_W \mathcal N_{T}}(\kappa)$, the inclusion functor between the nerves
\[
N(((w, (\mathfrak b, w) \times_W \mathcal S_T)\cap Q^{JB}) < y)(\kappa) \hookrightarrow N((w, (\mathfrak b, w) \times_W \mathcal S_T) < y)(\kappa)
\]
is a deformation retract (see \cite[Lemma 3.2.1]{DH24}). Thus \cite[Lemma 2.2.2]{DH24} shows that the inclusion induces an isomorphism on the level of stalks:
\[
(R\epsilon'_{T*}\epsilon_T'^*\underline{\mathbb Z}_\ell)_{(\mathfrak b, w < y , z)} \cong (R\epsilon_{T*}\epsilon_T^*\underline{\mathbb Z}_\ell)_{(\mathfrak b, w < y , z)}.
\]
Our assertion follows.
\end{proof}



\subsection{The main theorem on the bar complex}



Suppose that we have the codimension function for pairs
\[
\gamma: (W\leq \mathrm{Hilb}(B)^Q) \to \mathbb N,
\]
which is given by the formula $\gamma(w \leq x) = \gamma(x) - \gamma(w)$ where  $\gamma(x)$ only depends on the combinatorial type of $x$.
(In our applications, $Q$ is the poscheme defined in \cref{subsubsec:stratifyingthespace of sectons} and considered in \cref{exam:saturatedexample,exam:essentialsaturatedexample}.
Then the codimension function is given in \cref{exam:codimensionfunction}.)
Following \cite[Section 5.4]{DT24}, we say that $Z_{\mathfrak b, w \leq x}$ is unobstructed if its codimension in $E_{\mathfrak b, w}$ is given by $\gamma(w\leq x)$. Using this, we define a function $\kappa$ on the set of combinatorial types as
\begin{equation} \label{eq:kappadef}
\kappa(T) = 2\gamma (T) - \mathrm{rank}(T) - 2|\mathrm{Supp}(T)|.
\end{equation}
Here we use the definitions $\mathrm{rank}(w\leq x) = \mathrm{rank}(x) - \mathrm{rank}(w)$ and $|\mathrm{Supp}(w\leq x)| = |\mathrm{Supp}(x-w)|$ where $\mathrm{rank}$ and $|\mathrm{Supp}|$ are defined in \cref{exam:rankfunction,exam:supportfunction}, and $x-w$ is viewed as a $0$-cycle on $B$.
%and in the later definition $x-w$ is consider as a $0$-cycle on $B$. 
In the pointed case, our convention is that 
\[
|\mathrm{Supp}(g_0 \geq h_0, g_1 \geq h_1, \dotsc, g_\ell \geq h_\ell)| =  \#\{ i>0 | g_i > h_i\}.
\]
One may think of $\kappa(T)$ as the expected cohomological codimension of the contribution of $\mathcal S_T$. 

Let $R \subset(W\leq \mathrm{Hilb}(B)^Q)$ be a closed and downwards closed union of strata $\mathcal S_T$ for $T$ a saturated type.  
We assume that $R$ is initial in its closed upwards closure $\widetilde{P}$ in the following sense: there exists a morphism $\iota_R : \widetilde{P} \to \mathrm{Hilb}(B)^Q$ such that for any $(w<y) \in \widetilde{P}(\overline{k})$ 
the element $(w< \iota_R(w<y))$ is contained in $R(\overline{k})$ and is the maximal element of the set 
$\{ (w < y') \in R(\overline{k}) \, | \, y' \leq y \}$.
We denote the pullback of $Z$ via $P_U \to U$ by $Z_{P_U}$. We have the evaluation map $Z_{P_U} \to E|_U$ and we denote its image by $\mathrm{im}(Z_{P_U} \to E|_U)$. The following theorem was proved over $\mathbb C$ in \cite[Theorem 5.9]{DT24}. We extend this to arbitrary perfect fields using a similar approach.

\begin{theo}
\label{theo:5.4inDT}
Let $I \in \mathbb Q_{\geq 0 }$.  Assume that
\begin{enumerate}
\item $P \to W$ is proper and $P$ is downward closed;
\item for every pair $(\mathfrak b, w < x)\in P_U(\overline{k})$ with $x$ being saturated and every $y \in Q^{JB}(\overline{k})$ such that $x \prec y$, %and $w < y$ is essential, 
the fibers $Z_{b, w < x}$, $Z_{b, w < y}$ are unobstructed, and; 
\item we have $P \subset R$ and $P$ contains every $\mathcal S_T$ such that $\mathcal S_T \subset R$ and $\kappa(T) \leq I$.
\end{enumerate}
Then the map on compactly supported \'etale cohomology induced by 
$$
B(P_U, Z_{P_U}) \to \mathrm{im}(Z_{P_U} \to E|_U)
$$
is cohomology connected in codimension $I+2$, i.e., for all $i > 2\mathrm{dim}(E|_U) - \lfloor I \rfloor -2$, the map 
\[
H^i_{\text{\'et}, c}(\mathrm{im}((Z_{P_{U}})_{\overline{k}} \to (E|_{U})_{\overline{k}}), \mathbb Z_\ell) \to H^i_{\text{\'et}, c}(B(P_U, Z_{P_U})_{\overline{k}}, \mathbb Z_\ell),
\]
is an isomorphism, and for 
$i = 2\dim\, E|_U - \lfloor I \rfloor -2$, it is a surjection.
\end{theo}

\begin{proof}
We replace $I$ by $\lfloor I \rfloor$ so that $I$ is an integer.
We denote the augmentation morphism $B(P_U, Z_{P_U}) \to \mathrm{im}(Z_{P_U} \to E|_U)$ by $\epsilon$. Then since $P$ is proper over $W$, $\epsilon$ is also proper, showing that we have an induced morphism
\[
H^i_{\text{\'et}, c}(\mathrm{im}((Z_{P_{U}})_{\overline{k}} \to (E|_{U})_{\overline{k}}), \mathbb Z_\ell) \to H^i_{\text{\'et}, c}(B(P_U, Z_{P_U})_{\overline{k}}, \mathbb Z_\ell).
\]
We let $P'\supset P$ be the closure, downward closure, and the saturation closure of the set of $w < y$ such that there is a $(w < x) \in P$ such that $x\prec y$. (We take these closures over $\overline{k}$ and descend to $k$.)  Now $P'$ is closed, downward closed, and proper over $W$ and it is a union of finitely many $\mathcal S_T$ where $T$ is a saturated combinatorial type.
We will stratify $\mathrm{im}(Z_{P_{U}} \to E|_{U})$ using the poset of saturated combinatorial types of $P'$.

Consider the proper projection $\Psi: Z_{P'_U} \to E|_U$.
For every saturated combinatorial type $T$ of $P'$ we define $\overline{J}_T \subset E|_U$ as the closed subset $\Psi(\overline{Z|_{U \times_W \mathcal N_{T}}}) \subset E|_U$ where the closure is taking place in $Z_{P_U}$.  
Whenever we have $T \leq T'$ (note that this relation is neither $\leq_+$ nor $\leq_{+, \mathrm{sat}}$), we have $\overline{J}_T \supset \overline{J}_{T'}$. Let $J_T = \overline{J}_T \setminus \cup_{T < T'} \overline{J}_{T'}$. Note that this stratification may not satisfy the maximal element property stated in \cref{subsec:spectralsequenceforstratifiedspaces}.


Using the spectral sequence in \cref{eq:stratss}, it suffices to show that for any saturated combinatorial type $T$ of $P'$ and any open subset $J_T' \subset J_T$ the morphism $\epsilon : \epsilon^{-1}(J'_T) \to J'_T\cap \mathrm{im}(Z_{P_U} \to E|_U)$ is 
cohomology connected in codimension $I+2$.
We fix a geometric point $(\mathfrak b, w, z) : \Spec \, \kappa \to J'_T\cap \mathrm{im}(Z_{P_U} \to E|_U)$ such that $z \in J'_T \cap E_{\mathfrak b, w}$.
Then the fiber of $\epsilon$ at $(\mathfrak b, w, z)$ is the nerve 
\[
[n] \mapsto \{w < x_0 \leq \dotsb \leq x_n \, | \, x_i \in P, z \in Z_{\mathfrak b, w < x_n} \}.
\]

Suppose that $T$ is a saturated type of $P'$ such that $\iota_R(T)$ is a type of $P$. We show that under this assumption, the poscheme 
\[
\{ x \in P \, | \, z \in Z_{\mathfrak b, w < x} \} \to \Spec \, \kappa,
\] 
admits a terminal element. Once we have this, then $\epsilon : \epsilon^{-1}(J'_T) \to J'_T\cap \mathrm{im}(Z_{P_U} \to E|_U)$ is sufficiently cohomology connected, by proper base change and the contractibility of a nerve of a poset with a terminal element, or by \cite[Theorem 4.0.1]{DH24}. 
Let $y \in (Z|_{U \times_W \mathcal N_{T}})_{w, \kappa}$ be a generic point of a curve containing 
$z$ so that $z \otimes k(y) \in Z_{\mathfrak b\otimes k(y) , w\otimes k(y)  < \rho(y)}$ specializes to $z$
where $\rho : (Z|_{U \times_W \mathcal N_{T}})_{w, \kappa} \to (\mathcal N_{T})_{w, \kappa} \to \mathrm{Hilb}(B)^Q_\kappa$ is the projection.  If 
$(w < x) \in P'(\kappa)$ such that $z \in Z_{\mathfrak b, w < x}$, then we have 
\[
z\otimes k(y)  \in Z_{\mathfrak b\otimes k(y), w\otimes k(y) < x \otimes k(y) }\cap Z_{\mathfrak b\otimes k(y) , w\otimes k(y)  < \rho(y)}= Z_{\mathfrak b\otimes k(y) , w\otimes k(y)  < x\otimes k(y)  \vee \rho(y)}.
\] 
Thus we must have $x\otimes k(y)  \leq \rho(y)$ because otherwise we have  a generic point $y' \in (Z|_{U \times_W \mathcal N_{T'}})_{w,\kappa}$ with $T < T'$ such that $z\otimes k(y')  \in Z_{\mathfrak b\otimes k(y') , w\otimes k(y')  < \rho'(y')}$ which contradicts with the fact that $z \in J_T$. Since $\iota_R(T)$ is a type of $P$, we conclude that $\iota_R(\rho(y)) \in P$ so that its specialization is the terminal element of the above poscheme, proving the claim.

Now suppose that $\iota_R(T)$ is not a type of $P$.
In this situation, we will prove that we have
\[
H^i_{\text{\'et}, c}(\epsilon^{-1}(J'_T)_{\overline{k}}, \mathbb Z_\ell) = H^i_{\text{\'et}, c}((J'_T\cap \mathrm{im}(Z_{P_U} \to E|_U))_{\overline{k}}, \mathbb Z_\ell) = 0,
\]
for $i \geq 2\mathrm{dim} \, E|_U - I - 2$.
We will only explain the vanishing of the leftmost quantity as it is the more difficult of the two.  We claim that
\[
H^i_{\text{\'et}, c}(\epsilon^{-1}(J'_T)_{\overline{k}}, \mathbb Z_\ell)  = 0.
\]  
By arguing as in the proof of \cref{theo:spectralsequenceforbar}, 
we have a spectral sequence
\[
\bigoplus_{i + j = n} E_1^{i, j} = \bigoplus_{T': \text{ essential, saturated type}} H^{n}_{\text{\'et}, c}((J'_T\cap Z|_{U \times_W \mathcal N_{T'}})_{\overline{k}}, \mu''(T')[1]) \implies H^{n}_{\text{\'et}, c}(\epsilon^{-1}(J'_T)_{\overline{k}}, \mathbb Z_\ell),
\]
where $\mu''(T')$ is defined in a way analogous to the definition of $\mu'(T')$ using the nerve
\[
\epsilon''_{T'} : (N(-\infty, J'_T\cap Z|_{U\times_W \mathcal S_{T'}} )< J'_T\cap Z|_{U \times_W \mathcal N_{T'}}) \to J'_T\cap Z|_{U\times_W \mathcal N_{T'}}
\]
and $T'$ runs over essential saturated combinatorial types of $P$.
Thus it suffices to show that we have
\[
H^{i}_{\text{\'et}, c}((J'_T\cap Z|_{U \times_W \mathcal N_{T'}})_{\overline{k}}, \mu''(T')[1]) = 0,
\]
for $i \geq 2\mathrm{dim} \, E|_U - I - 2$.  This follows from 
\[
H^{i}_{\text{\'et}, c}((J'_T\cap Z|_{U \times_W \mathcal N_{T'}})_{\overline{k}}, R\epsilon''_{T'*}(\epsilon''_{T'})^*\underline{\mathbb Z}_\ell) =  H^{i}_{\text{\'et}, c}((J'_T\cap Z|_{U \times_W \mathcal N_{T'}})_{\overline{k}}, \mathbb Z_\ell) =0,
\]
for $i \geq 2\mathrm{dim} \, E|_U - I - 2$. 
Again we will only prove the vanishing of the leftmost quantity as it is the more difficult of the two.  Since
\[
H^{i}_{\text{\'et}, c}((J'_T\cap Z|_{U \times_W \mathcal N_{T'}})_{\overline{k}}, R\epsilon''_{T'*}(\epsilon''_{T'})^*\underline{\mathbb Z}_\ell)
= H^i_{\text{\'et}, c}((N(-\infty, J'_T\cap Z|_{U\times_W \mathcal S_{T'}} )< J'_T\cap Z|_{U \times_W \mathcal N_{T'}})_{\overline{k}}, \mathbb Z_\ell)
\]
it suffices to prove the right-hand side is $0$ for $i \geq 2\mathrm{dim} \, E|_U - I - 2$. 
If $T' \not\leq T$, then arguing as before using the generic point of a curve through $z$
we conclude $J'_T\cap Z|_{U \times_W \mathcal N_{T'}} = \emptyset$.
So let us assume that $T' \leq T$.
We take a maximal chain of saturated elements
\[
T' \prec T_1 \prec T_2 \prec \dotsb \prec \iota_R(T)
\]
Let $m$ be the minimum index such that $T_m$ is not a type of $P$.
Then it follows from (3) that $\kappa(T_m) > I$.
Now note that the cohomological dimension of $(N(-\infty, J'_T\cap Z|_{U\times_W \mathcal S_{T'}} )< J'_T\cap Z|_{U \times_W \mathcal N_{T'}})_{\overline{k}}$ is at most 
\begin{align*}
2\mathrm{dim}\, E|_U - 2\gamma(T_m) + \mathrm{rank}(T')-2 + 2|\mathrm{Supp}(T_m)| & \leq 2\mathrm{dim}\, E|_U - \kappa(T_m) -2 \\
& < 2\mathrm{dim}\, E|_U - I -2,
\end{align*}
because the cohomological dimension of the fiber $N(w, y)$ over $(J'_T\cap Z|_{U \times_W \mathcal N_{T'}})_{\overline{k}}$ is $\mathrm{rank}(T')-2$  and the dimension of $J'_T\cap Z|_{U \times_W \mathcal N_{T'}}$ is at most $2\mathrm{dim}\, E|_U - 2\gamma(T_m)+ 2|\mathrm{Supp}(T_m)|$.
This completes the proof.
\end{proof}


\subsection{The cohomological virtual bar complex}

Suppose that $E \to U$ is a finite rank vector bundle and $Z_{\mathfrak b, w < x} \subset E_w$ is a linear subspace.
As we discussed earlier, the fibers $Z_{\mathfrak{b},w<x}$ need not have the expected dimension.  For this reason, we must truncate the bar complex $B(P_{U},Z_{P_{U}})$ so that we only work with the locus of fibers whose dimensions we understand.  In this section, we define the ``cohomological virtual bar complex'' which records how the bar complex  would behave if every fiber $Z_{\mathfrak{b},w<x}$ had the expected dimension.  Note that we do not attempt to construct an actual space with this property; rather, we define a complex of sheaves which would compute the cohomology of such an object if it existed.  This construction interpolates between the ``actual'' behavior of moduli spaces of curves and the ``desired'' behavior predicted by Manin's Conjecture.

We work in the setting of \cref{subsubsec:stratifyingthespace of sectons}.
Let $T$ be a saturated combinatorial type of $(U_{\mathbf{k}} \leq \mathrm{Hilb}(B)^Q)$.
We fix a Zariski open subset $U \subset \mathcal B \times U_{\mathbf{k}}$.
Then we consider the following nerve
\[
(N(-\infty, U \times_W \mathcal S_T) < U \times_W \mathcal N_T),
\]
whose $m$-th simplex is given by
\[
\{\mathfrak b, w < x_0\leq \dotsb \leq x_m < y \, | \, (\mathfrak b, w) \in U, (w < y)\in \mathcal N_{T}, (w < x_m) \not\in \mathcal S_{T} \},
\]
with the augmentation morphism $\hat{\epsilon}_T :  (N(-\infty, U \times_W \mathcal S_T) < U \times_W \mathcal N_T) \to U \times_W \mathcal N_T$
\[
\hat{\epsilon}_T :  (\mathfrak b, w < x_0\leq \dotsb \leq x_m < y) \mapsto (\mathfrak b, w < y).
\]
We define the complex $\mu(T)[2]$ in $D^b(U \times_W \mathcal N_T)$ by 
\[
 \underline{\mathbb Z_\ell} \to R\hat{\epsilon}_{T*}\hat{\epsilon}_T^*\underline{\mathbb Z}_\ell \to \mu(T)[2] \to \underline{\mathbb Z}_\ell[1] \to.
\]
We define the cohomological virtual bar complex $\mathcal C(U)$ to be
\begin{align*}
\mathcal A_{a, a', \mathbf{k}}(U) &= \bigoplus_{T: \text{ essential type}} \mathcal A_{a, a', \mathbf{k}}(U, T) \\
&= \bigoplus_{T} \bigoplus_i H^i_{\text{\'et}, c}((U \times_W \mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1]\otimes \mathbb Q_\ell),
\end{align*}
where $n_{a, a', \mathbf{k}, T} = 2a + 2a' +4 -2\sum_i k_i -\gamma(T)$.
When $U =  \mathcal B \times W$, we write $\mathcal A_{a, a', \mathbf{k}} = \mathcal A_{a, a', \mathbf{k}}(U)$ and so on.


From now on we assume that our ground field $k$ is $\mathbb F_q$ and $U = \mathcal B \times U_{\mathbf{k}}$.  The following function plays a crucial role in our analysis:
\begin{defi}[M\"obius function]
Let $U_{\mathbf{k}}$ and $Q^{JB}$ be as before.
Let $w \in U_{\mathbf{k}}(k)$ and $w \leq x \in Q^{JB}(k)$.
Then we define the M\"obius function $\mu_k(w, x)$ using the following formula inductively:
\[
\mu_k(w, w) = 1, \, \mu_k(w, x) = -\sum_{w \leq y < x, y \in Q^{JB}(k)} \mu_k(w, y).
\]
\end{defi}

\begin{lemm}
\label{lemm:Mobius}
Let $w, w_1, w_2 \in U_{\mathbf{k}}(k)$ and $x, x_1, x_2 \in Q^{JB}(k)$ such that $w \leq x, w_1 \leq x_1, w_2 \leq x_2$.
Then we have the following properties:
\begin{enumerate}
\item Suppose that $x_1$ and $x_2$ have disjoint supports. Then we have
\[
\mu_k(w_1\vee w_2, x_1\vee x_2) = \mu_k(w_1, x_1)\mu_k(w_2, x_2).
\]
\item Suppose that $w \leq x$ is not essential. Then we have $\mu_k(w, x) = 0$.
\end{enumerate}
\end{lemm}

\begin{proof}
(1) This assertion follows from the fact that we have $[w_1\vee w_2, x_1\vee x_2] \cong [w_1, x_1]\times[w_2, x_2]$ and \cite[Proposition 1.2.1]{Wachs}.


(2) \Cref{prop:homotopyequivalence} shows that the subposet of essential elements $q$ with $w < q \leq x$ admits a maximal element $\mathrm{ess}(x)$.  
In particular, if $x$ is not essential then $(w,x)$ consists of the union of $(w,\mathrm{ess}(x)]$ with a chain from $\mathrm{ess}(x)$ to $x$, implying the desired result.
\end{proof}


Our goal here is to prove the following proposition:
\begin{prop}
\label{prop:virtualcount}
Let $T$ be an essential saturated type.
Then we have
\[
 \sum_i (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright \mathcal A_{a, a', \mathbf{k}}^i(T)) = -(\#\Pic^0(B)(k))^2q^{2a+ 2a'+4} \sum_{(w< x) \in \mathcal N_T(k)} \mu_k(w, x)q^{-\gamma(x)},
\]
where $\mathrm{Frob}$ is the Frobenius action. 
\end{prop}
\begin{proof}


We can apply the Grothendieck-Lefschetz trace formula to the perfect complex
\[
R\hat{\epsilon}_{T*}\hat{\epsilon}_T^*\underline{\mathbb Q}_\ell(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}];
\]
indeed, this is justified by the comparison theorem \cite[Proposition 5.5.4]{BS15} 
and then applying the standard Grothendieck--Lefschetz formula for $\ell$-adic constructible complexes.
This yields
\begin{multline*}
\sum_i (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((\mathcal B\times\mathcal N_T)_{\overline{k}}, R\hat{\epsilon}_{T*}\hat{\epsilon}_T^*\underline{\mathbb Q}_\ell(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}]))\\
= \sum_{(\mathfrak b, (w < x)) \in (\mathcal B \times \mathcal N_T)(k)} q^{2a+ 2a'+4 - \gamma(x)}\mathrm{Tr}(\mathrm{Frob} \curvearrowright (R\hat{\epsilon}_{T*}\hat{\epsilon}_T^*\underline{\mathbb Q}_\ell)_{(\mathfrak b, (w < x))})
\end{multline*}
where we have used the equality $\gamma(T) = \gamma(x) - 2\sum_i k_i$.
Now the fiber of the nerve
\[
\hat{\epsilon}_T :  (N(-\infty, \mathcal B \times \mathcal S_T) < \mathcal B \times \mathcal N_T) \to \mathcal B \times \mathcal N_T,
\]
at $(\mathfrak b, (w, x))$ is the nerve
\[
N(w < x) \to \Spec \, k.
\]
Then it follows from \cref{lemm:deformationretract} that
\begin{align*}
\mathrm{Tr}(\mathrm{Frob} \curvearrowright (R\hat{\epsilon}_{T*}\hat{\epsilon}_T^*\underline{\mathbb Q}_\ell)_{(\mathfrak b, (w < x))} &= \sum_i (-1)^i\mathrm{Tr}(\mathrm{Frob}\curvearrowright H^i_{\text{\'et}}(N(w < x)_{\overline{k}}, \mathbb Q_\ell))\\
&= \sum_i (-1)^i\mathrm{Tr}(\mathrm{Frob}\curvearrowright H^i_{\text{\'et}}(N((w < x)\cap Q^{JB})_{\overline{k}}, \mathbb Q_\ell)).
\end{align*}
Let $N_n(w, x) = \# \{ x_0 < \dotsb < x_n \in (N(w, x)\cap Q^{JB})(k)\}$. Then the Grothedieck-Lefschetz trace formula for simplicial schemes 
implies that we have 
\[
\sum_i (-1)^i\mathrm{Tr}(\mathrm{Frob}\curvearrowright H^i_{\text{\'et}}(N((w < x)\cap Q^{JB})_{\overline{k}}, \mathbb Q_\ell)
= \sum_i (-1)^i N_i(w, x).
\]
(This identity follows from \cref{Simplicial_Model} by computing the trace on the normalized cochain complex of the semisimplicial set $N((w < x)\cap Q^{JB})_{\overline{k}}$.)   Then it follows from \cite{Hall34} (see also \cite[(2.5) in p. 559]{Gree82}) that we have
\[
\sum_i (-1)^i N_i(w, x) = 1 + \mu_k(w, x).
\]
By Lang's theorem, the torsor $\Pic^d(B)$ is isomorphic to $\Pic^0(B)$. Thus when we sum over all $k$-points $(\mathfrak b, (w < x))$ we obtain $(\#\Pic^0(B)(k))^2$ times the sum over all $k$-points $(w<x)$.  We conclude that
\begin{multline*}
\sum_i (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((\mathcal B\times\mathcal N_T)_{\overline{k}}, R\hat{\epsilon}_{T*}\hat{\epsilon}_T^*\underline{\mathbb Q}_\ell(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}]))\\
= (\#\Pic^0(B)(k))^2\sum_{(w < x) \in \mathcal N_T(k)} q^{2a+ 2a'+4 - \gamma(x)}(1 + \mu_k(w, x))
\end{multline*}
Finally we consider the triangle: 
\begin{multline*}
 \underline{\mathbb Q_\ell}(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}] \to R\hat{\epsilon}_{T*}\hat{\epsilon}_T^*\underline{\mathbb Q}_\ell(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}] \to \\
 \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+2]\otimes \mathbb Q_\ell \to \underline{\mathbb Q}_\ell(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1].
\end{multline*}
The additivity of the alternating sums of the Frobenius traces in exact sequences proves our assertion.
\end{proof}

\subsection{Convergence}
In this section we obtain exponential bounds of the error term for cohomological virtual bar complex.
We denote by $\langle d \rangle$ the operation $(d)[2d]$ of shifting by $2d$ and twisting by $d$.

Given the poset $(U_{\mathbf{k}} \leq \mathrm{Hilb}(B)^Q)$, we have the 
cohomological virtual bar complex  associated to $\alpha = (a, a', k_1, \dotsc, k_r)$:  
$$\mathcal A_{\alpha} := \bigoplus_{T: \text{ essential type} } % of } (U_{\mathbf{k}} \leq \mathrm{Hilb}(B)^Q)}
H^*_{\text{\'et}, c}(\mathcal N_{T, \overline{k}}, \mu(T)[1]\otimes\mathbb Q_\ell \langle -{E}(\alpha) + 2\sum_{i} k_i(\alpha)+\gamma(T)\rangle),$$ where $E(\alpha)= 2(a + a') + 4 $ is  the 
dimension of the space of sections of the bundle $\mathcal O(a)^{\oplus 2} \oplus \mathcal O(a')^{\oplus 2}$ over $\mathbb P^1$.  


We wish to bound the $\mathsf L^1$-trace of Frobenius on the truncation into cohomological degrees $\leq  2{\rm edim}(\alpha) - I$,  where ${\rm edim}(\alpha) = -K_S.\alpha + 4$ and 
$I$ grows linearly in the degree of $\alpha$.    More precisely, we want to show that the sum of the absolute values of the generalized eigenvalues of the Frobenius is $o(q^{{\rm edim}(\alpha)})$.     
Since shifting homological degrees does not affect $\mathsf L^1$-traces,  it suffices to prove that the $\mathsf L^1$-trace of Frobenius on the truncation of the graded vector space 
\begin{multline*}
\mathcal A_{\alpha}\langle {\rm edim}(\alpha) \rangle\\
= \bigoplus_{T:  \text{ ess. type }}% of } (U_{\mathbf{k}} \leq \mathrm{Hilb}(B)^Q)}
H^*_{\text{\'et}, c}(\mathcal N_{T, \overline{k}}, \mu(T)[|\mathrm{Supp}(T)|]\otimes \mathbb Q_\ell \langle  \gamma(T) +2\sum_i k_i(\alpha) +  {\rm edim}(\alpha)  - E(\alpha)\rangle)
\end{multline*}
to cohomological degrees $\leq - I - |\mathrm{Supp}(T)|$ is $o(1)$.   Note that ${\rm edim}(\alpha) - E(\alpha)+2\sum_ik_i(\alpha)$ is equal to $\sum_{i} k_i$, and so this space is independent of $a, a'$.   

Accordingly, we rename it $\mathcal C_{\mathbf{k}, T}$, and summing over all  $\mathbf{k} = (k_1, \dotsc, k_r)$ and $T$ we obtain a bigraded vector space $\mathcal C := \bigoplus_{\mathbf{k}, T} \mathcal C_{\mathbf{k}, T}$ where  
the first grading is given by $\sum_{i = 1}^r k_i + |\mathrm{Supp}(T)|$ and the second grading is the homological grading.   We may decompose $\mathcal C$ into a sum over saturated types $T$ of $(\mathrm{Hilb}(B)^Q\leq\mathrm{Hilb}(B)^Q)$, where the summand associated to $T$ is either zero or $$H^*_{\text{\'et}, c}(\mathcal N_{T, \overline{k}}, \mu(T)[|\mathrm{Supp}(T)|]\otimes \mathbb Q_\ell (  \gamma(T) + k(T))[2(\gamma(T) + k(T) )],$$ placed in grade $k(T) + |\mathrm{Supp}(T)|$ where $k(T) = \sum_{i = 1}^rk_i$.


Recall that an essential saturated type $T$ corresponds to a multiset of elements in $(\mathrm{ch}(Q)\leq\mathrm{ch}(Q))$.  Suppose $T$ contains the elements $$(f^{w_1}\leq f^{x_1}), \dotsc, (f^{w_t} \leq f^{x_t}),$$ where $(f^{w_i} \leq f^{x_i})$ occurs with multiplicity $m_i$.  Then we have
$$\mathcal N_T \cong \mathrm{Conf}_{m_1 + \dotsb + m_t} \mathbb P^1/(S_{m_1} \times \dotsb \times S_{m_t}).$$
We have that the locally constant pro-\'etale sheaf on $\cN_T$
$$\mathbb H^*(\mu(T)[|\mathrm{Supp}(T)|]) := \bigoplus_{i} \mathbb H^i(\mu(T)[|\mathrm{Supp}(T)|])$$ 
pulls back to the constant local system $$\bigotimes_{i = 1}^t  H^*(\mu(w_i, x_i)[1])^{\otimes m_i},$$ on $\mathrm{Conf}_{m_1 + \dotsb + m_t} \mathbb P^1$,  which is $S_{m_1} \times \dotsb  \times S_{m_t}$-equivariant with respect to the Koszul sign rule.   Hence by Galois descent, we have 
\[\begin{multlined}[\displaywidth]
H^*_{\text{\'et}, c} (\mathcal N_{T, \overline{k}}, \mathbb H^*(\mu(T)[|\mathrm{Supp}(T)|]) \otimes \mathbb Q_\ell\langle  \gamma(T) + k(T)\rangle) = \\
 \left(H^*_{\text{\'et}, c}(\mathrm{Conf}_{m_1+ \dotsb + m_t} \mathbb P^1_{\overline{k}}, \mathbb Q_\ell) \otimes \bigotimes_{i = 1}^t  (H^*(\mu(w_i, x_i)[1]\otimes \mathbb Q_\ell)\langle \gamma(w_i \leq x_i) + k(w_i) \rangle  )^{\otimes m_i} \right)^{S_{m_1} \times \dotsb \times S_{m_t}}
 \end{multlined}\]
   where $k(w)$ denotes the length of $w$.  Note that to compute the $\mathsf L^1$-trace we may replace ${S_{m_1} \times \dotsb \times S_{m_t}}$-invariants by coinvariants since we are using characteristic zero coefficients. 

   Accordingly, for an essential pair $$(f^w \leq f^x) \in (\mathrm{ch}(Q)\leq \mathrm{ch}(Q)),$$ such that $f^w = k_i [\ell_{i,1} \oplus \ell_{i,2}]$, we define $$L(w \leq x) :=  H^*(\mu(w, x)[1]\otimes \mathbb Q_\ell) \langle  \gamma(w \leq x)  + k(w)\rangle.$$    We let $\mathcal J$ be the set of all such essential pairs excluding  
   $(V \leq V)$ and define $$L = \bigoplus_{w \leq x \in \mathcal J} L(w \leq x),$$ where the sum ranges over all such pairs.  We have that the first grading for $L$ is given by placing $L(w \leq x)$ in degree $k(w) + 1$ and the second grading is by homological degree.
   Then by taking the direct sum over $T$, we have that $\mathcal C$ is isomorphic to 
 \begin{multline*}
    \bigoplus_{m: \mathcal J \to \mathbb N \text{ fin. supp.}} \left(H^*_{\text{\'et}, c}(\mathrm{Conf}_{\sum_{j \in \mathcal{J}} m(j)} \mathbb P^1_{\overline{k}}, \mathbb Q_\ell) \otimes \bigotimes_{j \in \mathcal J} L(j)^{\otimes m(j)}\right)_{\prod_{j\in J} S_{m(j)}}  \\
    =  \bigoplus_{m \geq 0}  (H^*_{\text{\'et}, c}(\mathrm{Conf}_m \mathbb P^1_{\overline{k}}, \mathbb Q_\ell) \otimes L^{\otimes m})_{S_m}  .
 \end{multline*}

   We set $r = 4$ and apply \cref{CombinedBound}: we claim that the $\mathsf L^1$-trace of Frobenius on $L_{n,i}$ is bounded by $E d^n b^i$ and the $\mathsf L^1$-trace of Frobenius on $L_{\bullet, 2}$ is bounded by $D$ where 
   $$D = 4, d = 1, b= q^{-1/2}, \text{ and } E = c_1$$ 
   for some constant $c_1$ which is uniform. Indeed, for $L(w \leq x)$ the maximal cohomological degree is bounded above by $-2$ 
   and the minimum cohomological degree is bounded below by $-2(\gamma(w \leq x) + k(w))$. Note that $H^*(\mu(w,w))$ is the reduced cohomology of the empty set, so 
   only the $(-1)$-degree cohomology is non-trivial.  
As we vary over $(w \leq x) \in \mathcal{J}$, the posets $(w, x)$ only have finitely many isomorphism types.  Furthermore the number of pairs which contribute to $L_{n,i}$ is uniformly bounded.  Since everything is twisted by $q^{-(\gamma(w\leq x) + k(w))}$, one can find a uniformly bounded $c_{1}$ (using the dimensions of $H^i(\mu(w, x)[1]\otimes \mathbb Q_\ell)$ where $(w < x)$ are essential pairs, we can verify that $c_1 = 8$ works) such that $E = c_{1}$, $d = 1$, and $b= q^{-1/2}$ yield the bound on $|{\rm Frob},  L_{n,i}|$. 
   The part $L$ lying in cohomological degree $-2$ only comes from $w = x = [\ell_{i,1} \oplus \ell_{i,2}]$ and since there are four possible choices of $[\ell_{i,1} \oplus \ell_{i,2}]$ we see that $D = 4$ works as the desired upper bound for $|{\rm Frob},  L_{\bullet,2}|$.   Thus we conclude from \cref{CombinedBound} that 
   $$|{\rm Frob}, (\mathcal C)_{n,i}|  =O(i{d'}^n (4/\sqrt{q})^i),$$ for any $d' > \max\{4, 10c_1 \}$ independent of $q$. 
   (Here in the $O$-term we have absorbed the factor $n$ from \cref{CombinedBound} into the exponential term $d'^{n}$ at the cost of increasing $d'$ slightly.) Shifting, twisting back, and applying geometric series we obtain:

   \begin{theo}
   \label{theo:errorforvirtual}
   	Let $\alpha = (a, a', k_1, \dotsc, k_4)$ and fix any $0 < \eta < 1$.  
    For any constant $d' > 80$ we have that if $q$ is large enough so that $d'(4/\sqrt{q})^{(1-\eta)} < 1$ then for any $I > 0$ we have
	$$|{\rm Frob}, \tau_{\leq {2\rm edim}(\alpha)- I} \mathcal A_\alpha| =O\left(q^{{\rm edim}(\alpha)} (d')^{\sum_{i = 1}^4 k_i} (4/{\sqrt{q}})^{(1-\eta)I} \right),$$
    where $\tau$ is the truncation functor and the implied constants are independent of $\alpha, q$.

   \end{theo}







\section{Cohen-Jones-Segal Conjecture}
\label{sec:CJS}

In this section we prove \cref{theo:introcjs}.  We will adhere closely to the argument of \cite[Sections 6-9]{DT24}.  We prove the Cohen-Jones-Segal conjecture through a sequence of comparisons:
\begin{enumerate}
\item we compare $M_{\alpha,*}$ to the semi-topological model of \cite[Sections 6-7]{DT24};
\item we compare the semi-topological model to the space of pointed positive  continuous maps of \cite[Introduction]{DT24}; 
\item we compare the space of pointed positive continuous maps to the space of pointed continuous maps.
\end{enumerate}
Throughout we will focus on the pointed versions of moduli spaces of curves (although the arguments also work in the unpointed case as described in \cite{DT24}). In this section, we work over $\mathbb C$ with the Euclidean topology and all (co)homologies are singular (co)homologies.



\subsection{Comparing algebraic maps to semi-topological models}

One important contribution of \cite{DT24} is the introduction of semi-topological models for the space of maps.  Loosely speaking, these semi-topological models will parametrize continuous maps satisfying certain constraints on orders of vanishing near specified points.  In this section we compare the space of algebraic maps to a semi-topological model.  The key ingredient is our approximation result \cref{theo:algebraicvssemitopological}.


\subsubsection{Semi-topological models}

\begin{defi}[{\cite[Definition 6.1]{DT24}}]
Let $U \subset \mathbb C$ be an open subset with a coordinate $z$ and let $w : \mathfrak K \to \mathrm{Hilb}^{[n]}(U)$ be a continuous
family of divisors of $U$ parametrized by a compact set $\mathfrak K$. 
Fix a continuous family of polynomials $\rho_{w(\mathfrak k)}(z)$ such that for every $\mathfrak k \in \mathfrak K$, the divisor of zeros for $\rho_{w(\mathfrak k)}(z)$ coincides with the divisor $w(\mathfrak k)$.
We say that a family of functions $f_{\mathfrak k} : U \to \mathbb C, \mathfrak k \in \mathfrak K$ vanishes to order $\geq w$ if for every $u \in U$ and $\mathfrak k \in \mathfrak K$, there exists a constant $a_{u, \mathfrak k} \in \mathbb C$ such that $f_{\mathfrak k}(z) = a_{u, \mathfrak k}\rho_{w(\mathfrak k)}(z) + o(|\rho_{w(\mathfrak k)}(z)|)$ as $z \to u$ where $o(|\rho_{w(\mathfrak k)}(z)|)$ is uniform in $\mathfrak K$. If $a_{u, \mathfrak k} \neq 0$ for all $u \in U, \mathfrak k \in \mathfrak K$, we say that $f$
 vanishes to order exactly $w$. 



These notions are independent of the choice of polynomials $\rho_{w(\mathfrak k)}(z)$ and the choice of coordinate $z \in U \subset \mathbb C$ by \cite[Proposition 6.2.(2)]{DT24} and \cite[The proof of Proposition 6.4]{DT24}.
\end{defi}

\begin{rema}
Even when $f$ vanishes to order $\geq w$ there may not be a $w'$ with $w_{\mathfrak k}' \geq w_{\mathfrak k}$ for every $\mathfrak k \in \mathfrak K$ such that $f$ vanishes exactly to order $w'$.
\end{rema}




Next suppose we fix a Riemann surface $B$ and a family of divisors on $B$ parametrized by a continuous map $w : \mathfrak K \to \mathrm{Hilb}^{[n]}(B)$ where $\mathfrak K$ is a compact set. For each $\mathfrak k_0 \in \mathfrak K$, we can choose
\begin{itemize}
\item a neighborhood of $w(\mathfrak k_0)$ of the form $\prod_{i = 1}^s \mathrm{Hilb}^{[n_i]}(U_i)$ where the $U_i$'s are disjoint open subsets of $B$ which are biholomorphic to open subsets in $\mathbb C$ and $n = \sum_{i = 1}^s n_i$; and
\item an open neighborhood  $V$ of $\mathfrak k_0$ in $\mathfrak K$ such that $w|_V$ factors through $\prod_{i = 1}^s\mathrm{Hilb}^{[n_i]}(U_i)$ with $i$th component map denoted by $w_i: V \to \mathrm{Hilb}^{[n_i]}(U_i)$.
\end{itemize}
We say that $f : \mathfrak K \times B \to \mathbb C$ is a family of functions which vanish to order $\geq w$ if for every $\mathfrak k_0 \in \mathfrak K$ and for some (equivalently every) choice of neighborhoods $U_i$'s and $V$ as above, we have the property that for each $i$ and for every compact subset $\mathfrak K' \subset V$ the restriction $f|_{\mathfrak K' \times U_i} \to \mathbb C$ vanishes to order $\geq w_{i}$.  We define a family of functions which vanish to order exactly $w$ in the analogous way. %as functions which locally vanish to order exactly $w_{i}$ in the analogous way.


\begin{defi}[{\cite[Definition 6.5]{DT24}}]
Let $M$ be a complex manifold and $N \subset M$ be a complex submanifold of codimension $r$.
Let $B$ be a Riemann surface and let $w: \mathfrak K\to \mathrm{Hilb}^{[n]}(B)$ be a family of divisors parametrized by a compact subset $\mathfrak K$. Suppose that we have a continuous map
\[
f : \mathfrak K \times B \to M,
\]
such that for any $\mathfrak k \in \mathfrak K$ and any point $p$ in the support of $w(\mathfrak k)$, we have $f_{\mathfrak k}(p) \in N$.
For any $\mathfrak k_0 \in \mathfrak K$, one can obtain a collection of data:
\begin{itemize}
\item for every $p \in \mathrm{Supp}(w(\mathfrak k_0))$, there exists a neighborhood $\mathcal U_p \subset M$ of $f_{\mathfrak k_0}(p) \in N$ and holomorphic local coordinates $s_1^p, \dotsc, s_r^p$ on $\mathcal U_p$ whose vanishing locus is $N\cap \mathcal U_p$;
\item for the various $p \in \mathrm{Supp}(w(\mathfrak k_0))$ we can choose disjoint closed balls $\mathbb B_{p} \subset B$ with center $p$ and open subsets $U_{p} \subset \mathbb B_{p}$ containing $p$ such that $w(\mathfrak k_{0})$ has an open neighborhood of the form $\prod_{p} \mathrm{Hilb}^{[n_p]}(U_p)$ where $n_p$ is the multiplicity of $w(\mathfrak k_0)$ at $p$, and;

\item there is an open neighborhood $V \subset \mathfrak K$ of $\mathfrak k_0$ such that for any $\mathfrak k \in V$, we have $f_{\mathfrak k}(\mathbb B_p) \subset \mathcal U_p$ and $w|_V$ factors through $\prod_{p} \mathrm{Hilb}^{[n_p]}(U_p)$ with component maps $w_{p}: V \to \mathrm{Hilb}^{[n_p]}(U_p)$. 
\end{itemize}
We say that $f : \mathfrak K \times B \to M$ intersects $N$ to order $\geq w$ if for some (equivalently every) choice of $\mathcal U_p, \mathbb B_p, U_p, V$ and $s_1^p, \dotsc, s_r^p$, and every compact subset $\mathfrak K' \subset V$ , $s_i^{p}\circ (f|_{\mathfrak K' \times U_p})$ 
vanishes to order $\geq w_p$ for any $p$ and $i$.

Furthermore we say that $f$ intersects $N$ to order exactly $w$ if additionally for any $\mathfrak k \in \mathfrak K$, the support of $f_{\mathfrak k}^{-1}(N)$ is equal to the support of $w(\mathfrak k)$, and for every $p$, there exists $i$ such that $s_i^{p}\circ(f|_{\mathfrak K' \times U_p})$  
vanishes to order exactly $w_p$.

Finally, we say that $f$ intersects $N$ to order $>w$ if it intersects $N$ to order $\geq w$ but not to order exactly $w$.  (Note that this does not imply that $f$ intersects $N$ to order $\geq w'$ for some $w'$ such that $w'_{\mathfrak k} \geq w_{\mathfrak k}$ for every $\mathfrak k$.)


\end{defi}

Let $M$ be a complex manifold and $N_1, \dotsc, N_r \subset M$ be complex submanifolds. Consider the set
\[
\mathfrak X = \{ (w_i)_{i = 1}^r \in \prod_{i = 1}^r\mathrm{Hilb}^{[n_i]}(B), f \in \mathrm{Top}(B, M) \, | \, \text{ for any $i$, $f$ intersects $N_i$ to order $\geq w_i$.} \}.
\]
By \cite[Proposition 6.9]{DT24} there is a unique compactly generated topology on $\mathfrak X$ such that for all compact Hausdorff spaces $\mathfrak K$, continuous maps $f: \mathfrak K \to \mathfrak X$ are in bijection with pairs of continuous maps $f : \mathfrak K \times B \to M$ and $w_i : \mathfrak K \to \mathrm{Hilb}^{[n_i]}(B)$ such that $f$ intersects $N_i$ to order $\geq w_i$ for any $i = 1, \dotsc, r$. 


\subsubsection{Applying to blow-ups of $\mathbb{P}^{1} \times \mathbb{P}^{1}$}
\label{subsubsec:oursituation}

We consider the setup described in \cref{subsec:blowups}.
Let $U_{\mathbf{k}} \subset \prod_{i = 1}^r\mathrm{Hilb}^{[k_i]}(B)$ be the open set parametrizing tuples $(w_i)$ of effective divisors with disjoint supports. Consider the map $E^{\mathrm{top}} \to \mathcal{B} \times U_{\mathbf{k}}$ where $E^{\mathrm{top}}$ is
\[
E^{\mathrm{top}} = \{ ((L_1, L_2), w, \text{ sections $B \to \oplus_{j = 1}^2 L_j\otimes V_j$ intersecting $\oplus_{j = 1}^2 L_j \otimes \ell_{i, j}$ to order $\geq w_i$ for any $i$} )\}.
\]
Arguing as in \cite[Proposition 6.12]{DT24}, one can identify $E^{\mathrm{top}}$ as a locally trivial bundle of infinite dimensional separable Banach spaces over $\mathcal B \times U_{\mathbf{k}}$.  We define a stratification of this topological bundle: 


\begin{defi}[{\cite[Definition 6.13]{DT24}}]
For each $(L = (L_1, L_2), (w\leq x)) \in \mathcal B \times (U_{\mathbf{k}} \times \mathrm{Hilb}(B)^Q)$, let $Z_{L, w\leq x}$ be the subspace of $E_{L, w}$ consisting of sections $s \in E_{L, w}$ such that for all $c \in B$, we have
\begin{itemize}
\item if the length of $w_{\ell_{i, 1} \oplus \ell_{i, 2}}$ at $c$ is $l$ and the length of $x_{\ell_{i, 1} \oplus \ell_{i, 2}}$ at $c$ is greater than $l$, then $s$ intersects $\oplus_{j = 1}^2 L_j \otimes \ell_{i, j}$ to order $> l$;
\item if $x_{V_j}$ is supported at $c$, then our section $s_j$ vanishes at $c$ where $s_j$ is the section $s_j: B \to L_j \otimes V_j$ coming from $s$.  
\end{itemize}
\end{defi}
It is easy to see that we have (i) $Z_{L, w\leq x_1} \supset Z_{L, w \leq x_2}$ when $x_1 \leq x_2$, (ii) $Z_{L, w \leq x_1\vee x_2} = Z_{L, w \leq x_1} \cap Z_{L, w \leq x_2}$, and (iii) $Z_{L, w \leq x} = Z_{L, w \leq \mathrm{ess}(x)}$ when $x$ is saturated. Using the description of the saturation function in \cref{exam:saturatedexample}, one may also prove that $Z_{L, w \leq x} = Z_{L, w \leq \mathrm{sat}(x)}$.  Finally by arguing as in \cite[Proposition 6.14]{DT24}, one can prove that the subspace
\[
Z^{\mathrm{top}} =\{ L = (L_1, L_2), (w\leq x) \in (U_{\mathbf{k}}\leq \mathrm{Hilb}(B)^Q), s \in Z_{L, w \leq x}\}
\]
is a closed subset in $\mathcal B \times  (U_{\mathbf{k}}\leq \mathrm{Hilb}(B)^Q) \times_{\mathcal B \times U_{\mathbf{k}}} E^{\mathrm{top}}$ so that $Z^{\mathrm{top}}$ is a stratification of $E^{\mathrm{top}}$.

\subsubsection{Comparing algebraic maps and semi-topological models}
\label{subsec:algebraicvssemitopological}

Fix base points $*_B \in B$ and $*_S \in S$. We assume that $*_S$ is a general point on $S$. Let $Q$ be the poset described in \cref{subsubsec:stratifyingthespace of sectons}.
Let $Q_{r+1}\supset Q$ be the poset as in \cref{subsubsec:stratifyingthespace of sectons}, but with the additional $2$-dimensional vector space $\ell_{r + 1, 1}\oplus \ell_{r + 1, 2}$ corresponding to $*_S$.
Then we define
\[
U_{\mathbf{k}, *} \subset U_{\mathbf{k}} \times \{*_B\},
\]
as the Zariski open subset of pairs 
$(w, *_B)$ with disjoint supports.
Let $\overline{R} \subset \mathrm{Hilb}(B)^{Q_{r + 1}}$ be the closed subposet consisting of divisors $D$ such that $D_{\ell_{r + 1, 1}\oplus \ell_{r + 1, 2}} - D_{0}$ is supported on $*_B$ with multiplicity at most $1$ and $D_{\ell_{r + 1, j}} = D_0$ for $j = 1, 2$.
We define $R = (U_{\mathbf{k}, *} < \overline{R})$.
Note that $R$ is initial in   
$(U_{(\mathbf{k}, 1)} < \mathrm{Hilb}(B)^{Q_{r+1}})$, and this is one of the main reasons why the proof applies in this setting.



Let $\widetilde{\mathcal M}_{a, a', \mathbf{k}, *}$ be the space parametrizing tuples $L = (L_1, L_2) \in \mathcal B = \Pic^a(B) \times \Pic^{a'}(B)$, $w \in U_{\mathbf{k}, *}$, and a continuous section $s = (s_1, s_2) \in \Gamma^{\mathrm{top}}(B, L_1 \otimes V_1 \oplus L_2 \otimes V_2)$ intersecting to $\ell_{i, 1}\oplus \ell_{i, 2}$ to order exactly $w_i$ for any $i = 1, \dotsc, r$ and to order $\geq w_i$ for $i = r+1$.
This is an open subset of our topological bundle $E^{\mathrm{top}}_{U_{\mathbf{k}, *}}$. 
The $2$-dimensional torus $(\mathbb C^\times)^2$ acts on this space by acting as $(\lambda_1, \lambda_2)\cdot (L, w, s = (s_1, s_2)) = (L, w, (\lambda_1 s_1, \lambda_2 s_2))$, and we let
\[
\mathcal M_{a, a', \mathbf{k}, *} = \widetilde{\mathcal M}_{a, a', \mathbf{k}, *}/(\mathbb C^\times)^2.
\]
We also define $\widetilde{M}_{a, a', \mathbf{k}, *}$ as the space parametrizing tuples $L = (L_1, L_2) \in \mathcal B$, $w \in U_{\mathbf{k}}$, and a algebraic section $s = (s_1, s_2) \in \Gamma^{\mathrm{alg}}(B, L_1 \otimes V_1 \oplus L_2 \otimes V_2)$ intersecting to $\ell_{i, 1}\oplus \ell_{i, 2}$ to order exactly $w_i$ for any $i = 1, \dotsc, r$ and to order $\geq w_i$ for $i = r+1$. This variety is a Zariski open set of the algebraic fibration $E^{\mathrm{alg}}_{U_{\mathbf{k}, *}} \subset E^{\mathrm{top}}_{U_{\mathbf{k}, *}}$ over $\mathcal B \times U_{\mathbf{k}, *}$ parametrizing algebraic sections, and it admits an analogous algebraic stratification $Z^{\mathrm{alg}}_{R} = Z^{\mathrm{top}}_{R} \times_{E^{\mathrm{top}}} E^{\mathrm{alg}}$.  We also have
\[
M_{a, a', \mathbf{k}, *} \cong \widetilde{M}_{a, a', \mathbf{k}, *}/(\mathbb C^\times)^2.
\]

Before stating the main theorem of this section, let us recall the following definition:

\begin{defi}
   Let $I$ be a non-negative integer and $f : X \to Y$ be a continuous map of topological spaces. We say $f$ is homology $I$-connected if for any $i < I$, $f$ induces an isomorphism
   \[
   H_i^{\mathrm{sing}}(X, \mathbb Z) \cong H_i^{\mathrm{sing}}(Y, \mathbb Z),
   \]
   and when $i = I$, $f$ induces an surjection
   \[
   H_i^{\mathrm{sing}}(X, \mathbb Z) \hookrightarrow H_i^{\mathrm{sing}}(Y, \mathbb Z).
   \]
\end{defi}

The following theorem is essentially \cite[Theorem 7.4]{DT24}, but it is adapted to our situation:

\begin{theo}
\label{theo:algebraicvssemitopological}
Let $I \in \mathbb Q_{\geq 0}$. Let $P \subset R$ be a poset which is a closed and downward closed union of finitely many combinatorial types such that
\begin{itemize}
\item $P$ is proper over $U_{\mathbf{k}, *}$;
\item there exists a Zariski proper closed subset $F \subset U_{\mathbf{k}, *}$ such that the real codimension of $F$ in $U_{\mathbf{k}, *}$ is $> I$ and the real codimension of $\pi^{-1}(F)$ in $\mathrm{Mor}_*(B, S, (a, a', \mathbf{k}))$ is also $> I$ where $\pi : \mathrm{Mor}_*(B, S, (a, a', \mathbf{k}))  \to U_{\mathbf{k}, _*}$ is the projection. We set $V_{\mathbf{k}, *} = U_{\mathbf{k}, *}\setminus F$;
\item For every pair $w < x \in P\cap (V_{\mathbf{k}, *} \leq \mathrm{Hilb}(B)^Q)$ and every essential $w < y \in (V_{\mathbf{k}, *} \leq Q^{JB})$ such that $x \prec y$, $\Gamma^{\mathrm{alg}}(B, L_1\otimes V_1 \oplus L_2\otimes V_2)_y$ is unobstructed for every $L = (L_1, L_2) \in \mathcal B$, and;
\item $P$ contains all types $T$ with $\kappa(T)\leq I$ where $\kappa(T)$ is defined by \cref{eq:kappadef},
and all minimal types of $U_{\mathbf{k}} < \mathrm{Hilb}(B)^Q$, i.e., all $x \in \mathrm{Hilb}(B)^Q(\overline{k})$ such that $w \prec x$ for some $w \in U_{\mathbf{k}}(\overline{k})$. 
\end{itemize}
We also assume that $M_{a, a', \mathbf{k}, *}$ is smooth.
Then the map $M_{a, a', \mathbf{k}, *} \hookrightarrow \mathcal M_{a, a', \mathbf{k}, *}$ is homology $\lfloor I\rfloor$-connected.
\end{theo}


First we record the following lemma:

\begin{lemm}
If $\widetilde{M}_{a, a', \mathbf{k}, *} \hookrightarrow \widetilde{\mathcal M}_{a, a', \mathbf{k}, *}$ is homology $\lfloor I \rfloor$-connected, then the map 
$$
M_{a, a', \mathbf{k}, *} \hookrightarrow \mathcal M_{a, a', \mathbf{k}, *}
$$ 
is also homology $\lfloor I \rfloor$-connected.
\end{lemm}
\begin{proof}
For notational brevity let $G = (\mathbb{C}^\times)^2$.
Let $EG$ (as usual) be a contractible space with a free $G$ action and set $BG := EG/G$, e.g. $EG = (\mathbb{C}^\infty - 0)^2$,  making $BG = (\mathbb{C}P^\infty)^2$.
Since $\widetilde{M}_{a, a', \mathbf{k}, *} \to M_{a, a', \mathbf{k}, *}$ and $\widetilde{\mathcal{M}}_{a, a', \mathbf{k}, *} \to \mathcal{M}_{a, a', \mathbf{k}, *}$ are principal $G$-bundles, we can replace the quotients by the associated Borel constructions (which have the same homotopy type) to get a map of fiber bundles
\[(\widetilde{M}_{a, a', \mathbf{k}, *} \times EG)/G \to (\widetilde{\mathcal{M}}_{a, a', \mathbf{k}, *} \times EG)/G\]
over $BG$ with respective fibers $\widetilde{M}_{a, a', \mathbf{k}, *}$ and $\widetilde{\mathcal{M}}_{a, a', \mathbf{k}, *}$.
Now the required isomorphism follows from comparing the corresponding Serre spectral sequences.
\end{proof}




\begin{proof}[Proof of  \cref{theo:algebraicvssemitopological}:]
By the previous lemma it suffices to prove that $\widetilde{M}_{a, a', \mathbf{k}, *} \hookrightarrow \widetilde{\mathcal M}_{a, a', \mathbf{k}, *}$ is homology $\lfloor I \rfloor$-connected.
First note that $\widetilde{M}_{a, a', \mathbf{k}, *} \hookrightarrow \widetilde{\mathcal M}_{a, a', \mathbf{k}, *}$ is a $\mathcal B\times U_{\mathbf{k}, *}$-map. By comparing two Leray spectral sequences over $\mathcal B\times U_{\mathbf{k}, *}$ it suffices to show that for a basis of open sets $U \subset \mathcal B\times U_{\mathbf{k}, *}$, we have that
\[
\widetilde{M}_{a, a', \mathbf{k}, *}|_U \hookrightarrow \widetilde{\mathcal M}_{a, a', \mathbf{k}, *}|_U,
\]
is homology $\lfloor I \rfloor$-connected.

Next we consider the following diagram

\centerline{
\xymatrix{ 
\widetilde{M}_{a, a', \mathbf{k}, *}|_{U\cap V_{\mathbf{k}}}  \ar[d] \ar[r] & \widetilde{\mathcal M}_{a, a', \mathbf{k}, *}|_{U \cap V_{\mathbf{k}}} \ar[d] \\
\widetilde{M}_{a, a', \mathbf{k}, *a}|_U  \ar[r]& \widetilde{\mathcal M}_{a, a', \mathbf{k}, *}|_U
}
}
It follows from our assumptions that the vertical maps are homology $\lfloor I \rfloor$-connected. 
Indeed, the assertion for the left map follows from our smoothness and codimension assumptions.
The assertion for the right map follows from a similar argument after using \cite[Proposition 6.16]{DT24} to pass the computation to a finite rank subbundle of $E^{\mathrm{top}} \to {U_{\mathbf{k}, *}}$.
Thus it suffices to show that $\widetilde{M}_{a, a', \mathbf{k}, *}|_{U\cap V_{\mathbf{k}}}  \hookrightarrow  \widetilde{\mathcal M}_{a, a', \mathbf{k}, *}|_{U \cap V_{\mathbf{k}}}$ is homology $\lfloor I \rfloor$-connected.
Then the rest of the proof is same as the proof of \cite[Theorem 7.1]{DT24}: we can apply the same discussion starting from Step (3) of the proof of \cite[Theorem 7.1]{DT24}.  
\end{proof}

\subsection{Comparing semi-topological models to the space of positive continuous maps}

The next step is to compare semi-topological models to the space of pointed positive continuous maps.  
We first recall the notion of pointed positive continuous maps from \cite{DT24}.


\begin{defi}[{\cite[Introduction]{DT24}}]
Let $X$ be a smooth projective variety equipped with a finite set of disjoint smooth divisors $\{E_{i} \}$.  Fix a homological curve class $\alpha$.  We define $\Top_{*}^{+}(\mathbb{P}^{1},X)_{\alpha} \subset \Top_{*}(\mathbb{P}^{1},X)_{\alpha}$ to be the subspace consisting of pointed continuous maps $s: \mathbb{P}^{1} \to X$ such that:
\begin{enumerate}
\item $s^{-1}(E_{i})$ is discrete for every $i$, and
\item $s$ has positive local intersection multiplicity against $E_{i}$ at every point of $s^{-1}(E_{i})$.
\end{enumerate}
\end{defi}


Following \cite[Section 8]{DT24} we show that $\mathcal M_{a, a', \mathbf{k}, *}$ introduced in \cref{subsec:algebraicvssemitopological} is weakly homotopy equivalent to the space
$
\mathcal T_{a, a', \mathbf{k}, *},
$
parametrizing pairs $(w, s)$ of $w \in U_{\mathbf{k}}$ and pointed positive continuous maps $s : B \to S$ of the class $(a, a', \mathbf{k})$ such that
\begin{itemize}
\item for any $i = 1, \dotsc, r$, $s^{-1}(E_i)$ is discrete and the local intersection multiplicity at every point of $s^{-1}(E_i)$ is positive, and;
\item at a point of $s^{-1}(E_i)$ the local intersection multiplicity of $s$ along $E_i$ is equal to the multiplicity of $w$ at that point.
\end{itemize}

Let $\mathcal M'_{a, a', \mathbf{k}, *}$ be the space of pairs $(w, s)$ of $w \in U_{\mathbf{k}}$ and pointed continuous maps $s: B \to \mathbb P^1 \times \mathbb P^1$ of class $(a, a')$ such that $s$ intersects $(p_i, p'_i)$ to order exactly $w_i$. Then we have a canonical continuous map
\[
\mathcal M_{a, a', \mathbf{k}, *} \to \mathcal M'_{a, a', \mathbf{k}, *}.
\]
Let $\mathcal T'_{a, a', \mathbf{k}, *} \subset \mathcal T_{a, a', \mathbf{k}, *}$ be the space of pairs $(w, s)$ of $w \in U_{\mathbf{k}}$ and continuous maps $s : B \to S$ such that $s$ intersects $E_i$ to order exactly $w_i$.
Then by taking the strict transform, the argument of \cite[Proposition 8.3]{DT24} shows that $\mathcal M'_{a, a', \mathbf{k}, *}$ is homeomorphic to $\mathcal T'_{a, a', \mathbf{k}, *}$.
In this way we have a continuous map
\[
\mathcal M_{a, a', \mathbf{k}, *} \to \mathcal M'_{a, a', \mathbf{k}, *} \cong \mathcal T'_{a, a', \mathbf{k}, *} \hookrightarrow \mathcal T_{a, a', \mathbf{k}, *}.
\]
Then applying the arguments of \cite[Section 8.2]{DT24}, one can prove that
\[
\mathcal M_{a, a', \mathbf{k}, *} \to \mathcal T_{a, a', \mathbf{k}, *} 
\]
is a weak homotopy equivalence (see \cite[Theorem 8.2]{DT24}).

Finally arguing as in \cite[Proposition 8.11]{DT24} one can show that the projection
\[
\mathcal T_{a, a', \mathbf{k}, *}  \to \mathrm{Top}^+_*(B, S)_{a, a', \mathbf{k}}, \, (w, s) \mapsto s,
\]
is a homeomorphism. Thus we obtain the following theorem:
\begin{theo}[{\cite[Theorem 8.12]{DT24}}]
\label{theo:semitopologicalvstopological}
We have a weak homotopy equivalence
\[
\mathcal M_{a, a', \mathbf{k}, *}  \simeq \mathrm{Top}^+_*(B, S, (a, a', \mathbf{k})).
\]
\end{theo}


















