%{\bf The proof of Cohen--Jones--Segal conjecture}

\subsubsection{Homological stability and the space of positive continuous maps}
\label{subsubsec:homologicalstability}

%Here we prove our main theorems.
We assume that $r = 4$.
Let $a, a', \mathbf{k}$ be non-negative integers such that
\[
2a -\sum_{i = 1}^4k_i > 0, \, 2a' -\sum_{i = 1}^4k_i > 0
\]
We define $I \in \mathbb Q_{\geq 0}$ by
\[
I=   \frac{1}{8} \min\left\{2a -\sum_{i = 1}^4k_i,  2a' -\sum_{i = 1}^4k_i\right\} - \frac{1}{2}.
\]
For $w<x \in (U_{\mathbf{k}, *} < \overline{R})$ we define 
\[
E(w < x) := 4m_0(x)  +3 \sum_{i, j} m_{\ell_{i, j}}(x) + 2\sum_j m_{V_j}(x) +2\sum_i m_{\ell_{i, 1} \oplus \ell_{i, 2}}(x) - 2\sum k_i.
\]
Let $P \subset (U_{\mathbf{k}, *} < \overline{R})$ be the subposet consisting of $w < x$ such that $E(w < x) \leq 2I$.
The following lemma shows that $P$ is proper over $U_{\mathbf{k}}$:
\begin{lemm}
\label{lemm:Eproper}
For any positive constant $\mathfrak T$ the set of $x \in \mathrm{Hilb}(B)^Q$ such that $M(x) := 4m_0(x)  +3 \sum_{i, j} m_{\ell_{i, j}}(x) + 2\sum_j m_{V_j}(x) + 2\sum_i m_{\ell_{i, 1} \oplus \ell_{i, 2}}(x) \leq \mathfrak T$ is closed and downward closed. 
\end{lemm}
\begin{proof}
Downwards closure is immediate because the coefficient of $m_q$ in the linear function in the statement of the lemma increases as $q$ decreases.  
To prove that the set is closed, it suffices to show that if $x'$ is a specialization of $x$ then $M(x') \leq M(x)$.   We will do this via the geometric interpretation of $M(x)$ as a codimension of a kernel of a certain morphism between coherent sheaves.  

We may assume that the total multiplicity of the divisors appearing in $x$ is $N$.   (The same will hold for $x'$.)  Then choose $d \in \mathbb N$ sufficiently so large that 
$$\Gamma(B, \cO(d) \otimes V_1 \oplus \cO(d) \otimes V_2)\to \Gamma(D, \cO(d) \otimes V),$$ is surjective for all divisors $D$ of size $\leq N$. (For example we can take $d = N$.)   In this case we claim that $M(x)$ equals the codimension of $$\Gamma_Q(B,\cV)_x \subseteq \Gamma(B,\cO(d) \otimes V_1 \oplus \cO(d) \otimes V_2).$$   By construction of $\Gamma_Q(B,\cV)_x$ as the fiber product of morphisms between vector bundles, this codimension decreases on specialization, so the same will hold for $M(x)$.    

To establish the claim suppose that $x$ is supported at $p_1, \dotsc, p_r$ and the maximum of the divisors supported at $p_i$ is $\leq n_i$.    By our choice of $d$, we have that $\Gamma(B,\cO(d) \otimes V_1 \oplus \cO(d) \otimes V_2) $ surjects onto $\prod_{i =1}^r \Gamma(n_i p_i, V)$, so it suffices to determine the codimension of the space of incidence conditions imposed by $x$ on $\prod_{i =1}^r \Gamma(n_i p_i, V )$, which splits as a product over $p_i$. The incidence conditions imposed at a single point $p_i$ by $g^x_{p_i}$ only depend on ${\rm sat}(g^x_{p_i})$ which corresponds to a chain $f^x_{p_i}$.  Interpreting $\Gamma(n_i p_i, V)$ as the space of $n_i-1$ jets of $V$, we find that a section $s \in \Gamma(n_i p_i, V)$ satisfies the incidence conditions of $f^x_{p_i}$ if and only if the $l$-th Taylor coefficient of $s$ lies in $K_{f^x_{p_i}(l)}$ for all $l$.    Computing the codimension of this linear space and adding over all $p_i$ yields $M(x)$.  
\end{proof}





Let $M_{a, a', \mathbf{k}, *}$ be the space of pointed rational curves of class $(a, a', \mathbf{k})$ on $S$.
Then we have a natural projection
\[
M_{a, a', \mathbf{k}, *} \to U_{\mathbf{k}, *}.
\]
Let $F_1 \subset U_{\mathbf{k}, *}$ be the complement of the image of the above projection.
It follows from \cref{prop:dimensionestimatepointed} that the real codimension of $F_1$ is greater than $16I$.

Let $(w < x)$ be an element of $P$ and $(w < y)$ be an essential saturated pair such that $x \prec y$.
Let us consider the space
\[
\Gamma(B, \mathcal O(a)\otimes V_1 \oplus \mathcal O(a')\otimes V_2)_y.
\]
We define
\begin{align*}
a_y & = a- m_0(y) - m_{V_2}(y) - \sum_{i = 1}^4m_{\ell_{i, 2}}(y) \\
 a'_y &= a- m_0(y) - m_{V_1}(y) - \sum_{i = 1}^4m_{\ell_{i, 1}}(y) \\
 k_{y, i, j} & = m_{\ell_{i, j}}(y) + m_{\ell_{i, 1} \oplus \ell_{i, 2}}(y) \\
y_j(\ell_{i, j}) & =  \left(\sum_{c \in B} (m_{\ell_{i, j}}(f_{y, c}) + m_{\ell_{i, 1} \oplus \ell_{i, 2}}(f_{y, c}))[c] \right), \quad y_j(0) = \emptyset.
\end{align*}
Then the above space can be identified with
\begin{equation}
\label{equation:P^1incident}
\Gamma(B, \mathcal O(a_y)\otimes V_1)_{y_1}\oplus \Gamma(B, \mathcal O(a'_y)\otimes V_2)_{y_2},
\end{equation}
where $\Gamma(B, \mathcal O(a_y)\otimes V_1)_{y_1}$ is the space of sections $s \in \Gamma(B, \mathcal O(a_y)\otimes V_1)$ such that $s(y_1(\ell_{i, 1})) \subset \ell_{i, 1}\otimes \mathcal O(a_y)$ for any $i = 1, \dotsc, 4$ and we define $\Gamma(B, \mathcal O(a'_y)\otimes V_2)_{y_2}$ in a similar way.
We consider 
\[
E_j(w < y) = 2m_0(y) + 2m_{V_{j'}}(y) +2 \sum_{i = 1}^4m_{\ell_{i, j'}}(y) + \sum_{i = 1}^4 (m_{\ell_{i, j}}(y) + m_{\ell_{i, 1} \oplus \ell_{i, 2}}(y)) - \sum k_i
\]
where $\{j, j'\} = \{1, 2\}$. Since this function is monotone increasing with respect to $y$ we have $E_1(w < y) \geq 0$ and $E_2(w < y)\geq 0$. Moreover we have $E = E_1 + E_2$. Thus we have $E_j \leq 2I + 2$,
\begin{align*}
&2a_y - \sum_{i = 1}^4 k_{y, i, 1}\\ 
&= 2a - \sum k_i -\left(2m_0(y) + 2m_{V_2}(y) +2 \sum_{i = 1}^4 m_{\ell_{i, 2}}(y) + \sum_{i = 1}^4 (m_{\ell_{i, 1}}(y) + m_{\ell_{i, 1} \oplus \ell_{i, 2}}(y)) - \sum k_i\right) \\ 
&\geq 6I+2,
\end{align*}
and 
\begin{align*}
&2a'_y - \sum_{i = 1}^4 k_{y, i, 2}\\ 
&= 2a - \sum k_i -\left(2m_0(y) + 2m_{V_1}(y) +2 \sum_{i = 1}^4 m_{\ell_{i, 1}}(y) + \sum_{i = 1}^4 (m_{\ell_{i, 2}}(y) + m_{\ell_{i, 1} \oplus \ell_{i, 2}}(y)) - \sum k_i\right)\\
&\geq 6I+2.
\end{align*}
The space $\Gamma(B, \mathcal O(a_y)\otimes V_1)_{y_1}$ is unobstructed if $y_1$ is contained in the image of 
\[
Z_{a_y, \mathbf{k}_{y, 1}}^\circ \to U_{\mathbf{k}_{y,1}}.
\]
By combining the equations above with \cref{prop:dimensionestimatepointed} we see that the complement of the image has dimension at most $\sum_{i = 1}^{4} k_{y_1, i, 1} -6I-2$. Thus the dimension of the set $w$ such that $w < y$ where $y$ corresponds to a point $y_{1}$ in the complement of the image of $Z_{a_y, \mathbf{k}_{y, 1}}^\circ \to U_{\mathbf{k}_{y,1}}$ is at most
\[
m_0(y) + m_{V_1}(y) + m_{V_2}(y) +  \sum_{i = 1}^4m_{\ell_{i, 2}}(y) + \sum_{i = 1}^4k_{y, i, 1} -6I-2 \leq \sum k_i - 4I.
\]
Let $F_2$ be the union of closures of such loci while $T$ runs over all combinatorial types we consider. Note that the real codimension of $F_2$ in $U_{\mathbf{k}}$ is greater than or equal to $8I$.
Similarly we construct $F_3$ for the space $\Gamma(B, \mathcal O(a'_y)\otimes V_2)_{y_2}$.
Let $F = F_1 \cup F_2 \cup F_3$. 

Next we analyze $\kappa(T)$ in our situation defined by \cref{eq:kappadef}.  
It follows from our definition that we have
\[
2\gamma(T) = 8m_0(T) + 6 \sum_{i, j} m_{\ell_{i, j}(T)} + 4\sum_j m_{V_j}(T) + 4\sum_{i} m_{\ell_{i, 1} \oplus \ell_{i, 2}}(T), 
\]
and
\[
\mathrm{rank}(T) = 3m_0(T) + 2 \sum_{i, j} m_{\ell_{i, j}}(T) + \sum_j m_{V_j}(T) + \sum_{i} m_{\ell_{i, 1} \oplus \ell_{i, 2}}(T).
\]
Thus we have
\[
\kappa(T) = 5m_0(T) + 4 \sum_{i, j} m_{\ell_{i, j}}(T) + 3\sum_j m_{V_j}(T) + 3\sum_{i} m_{\ell_{i, 1} \oplus \ell_{i, 2}}(T) - 2|\mathrm{Supp}(T)|.
\]
Using this one can prove that when we have $x_1 \prec x_2$, we have $\kappa(x_2) \geq \kappa(x_1) + 1$. This shows that $\kappa(T) \geq \mathrm{rank}(T)$.  
Thus we have $E(T) \leq 2 \, \mathrm{rank}(T) \leq 2\kappa (T)$.  
By applying \cref{theo:algebraicvssemitopological,theo:semitopologicalvstopological} we conclude the following theorem:
\begin{theo}
\label{theo:mainCJS}
Let $B = \mathbb P^1$ and $S$ be a del Pezzo surface of degree $4$.
We fix an integral nef class $\alpha$ on $S$.
Suppose that we have a birational morphism $\beta : S \to \mathbb P^1 \times \mathbb P^1$ satisfying
\[
2a -\sum_{i = 1}^4k_i > 0, \, 2a' -\sum_{i = 1}^4k_i > 0.
\]
We define $I \in \mathbb N$ by
\[
I = \frac{1}{8} \min\left\{2a -\sum_{i = 1}^4k_i,  2a' -\sum_{i = 1}^4k_i\right\} -\frac{1}{2}.
\]
Then $M_{\alpha, *} \hookrightarrow \mathrm{Top}^+_*(B, S)_{\alpha}$ is homology $\lfloor I \rfloor$-connected.
\end{theo}

Finally we prove the Cohen--Jones--Segal conjecture for rational curves on quartic del Pezzo surfaces. 
To compare the topology of the space of pointed positive continuous maps and the space of pointed continuous maps, we will deform $S$ to a smooth toric surface where the desired comparison can be done more easily.  The comparison result for toric surfaces will be proved in \cref{appe:toric}.

\begin{proof}[Proof of \cref{theo:introcjs}] 
Let $B = \mathbb{P}^{1}$.  
Let $\ell(\alpha) = \min\{\lfloor I \rfloor -1, k_{i}(\alpha) \, | \, i = 1, \dotsc, 4\}$.
By \cref{theo:mainCJS} it suffices to show that
\[
\mathrm{Top}^+_*(B, S)_{\alpha} \hookrightarrow \mathrm{Top}_*(B, S)_{\alpha},
\]
induces isomorphisms of homology groups in degree $\leq \min\{k_i(\alpha)\}$.
\Cref{prop:alphainvariance} shows that we may prove the desired property after replacing $\alpha$ by $\alpha + \gamma$ where $\gamma$ is the class of a nef curve on $S$ that is disjoint from each of the four exceptional divisors.  In particular, by repeatedly adding on the nef classes $F_{\alpha}, F'_{\alpha}$ defined in \cref{nota:bignota}, we may assume that
\[
a - k_1 - k_2, a - k_3 - k_4, a'-k_1 - k_3, a' - k_2 - k_4,
\]
are all positive.
Let $Y$ be the toric surface obtained by blowing up the four torus invariant points on $\mathbb P^1 \times \mathbb P^1$.  By considering a continuous deformation of the four blown-up points we can construct a homeomorphism from $Y$ to $S$ that identifies the four exceptional divisors $E_{1,1},E_{1,2},E_{2,1},E_{2,2}$ on $Y$ with the four exceptional divisors $E_{1},E_{2},E_{3},E_{4}$ on $S$.  Moreover this homeomorphism preserves the orientations of these real fourfolds as well as their exceptional divisors.  
By \cref{theo:torichomequiv}, the inclusion
\[
\mathrm{Top}^+_*(B, Y)_{\alpha} \hookrightarrow \mathrm{Top}_*(B, Y)_{\alpha},
\]
induces isomorphisms of homology groups of degree $\leq \min\{k_i(\alpha)\}$.  Since $Y$ and $S$ admit a homeomorphism that is compatible with the exceptional divisors, our assertion follows.
\end{proof}






\section{Manin's Conjecture}
\label{sec:Manin}

Finally, we turn to a proof of \cref{theo:intromaninconj}.  Throughout this section we work over a finite field $k = \mathbb{F}_{q}$.  We refer to \cref{nota:bignota} for our standard notations involving curve classes on our surface.


Suppose that $S$ is a split degree $4$ del Pezzo surface and that $\alpha$ is a nef curve class on $S$.  For convenience of notation we set $B = \mathbb P^1$.  We define the counting function as
\[
N(B, S, -K_S, d) = \sum_{\alpha \in \Nef_{1}(S)_{\mathbb Z},\, -K_S.\alpha \leq d} \# M_{\alpha}(k).
\]
Note that by working with nef curve classes we have removed the exceptional set consisting of $(-1)$-curves.  Given any subcone $\mathcal{C} \subset \Nef_{1}(X)$, we also define
\[
N^{\mathcal{C}}(B, S, -K_S, d) = \sum_{\alpha \in \mathcal{C}_{\mathbb Z},\, -K_S.\alpha \leq d} \# M_{\alpha}(k).
\]

\subsection{Upper bounds}
We first prove a uniform upper bound on $\# M_{\alpha}(k)$ of the expected order (but not necessarily with the expected leading constant).


\begin{lemm}
\label{lemm:upperboundsofpointcountingI}
Let $S$ be a split degree $4$ del Pezzo surface over a finite field $k = \mathbb F_q$ and let $\alpha$ be a nef curve class on $S$.  %Using \cref{nota:bignota} we furthermore assume that $a(\alpha) \geq 3$.
Then
\[
\# M_{\alpha}(k) \leq \frac{1}{(1-q^{-1})^{6}}q^{h(\alpha) + 2}.
\]
\end{lemm}

\begin{proof}
First we consider the following fibration:
\[
\psi_\alpha : M_{\alpha} \to Z_{a(\alpha), \mathbf{k}(\alpha)}^{\circ}.
\]
For each $k$-rational point $x$ on $\psi_\alpha(M_{\alpha})$, the fiber $\psi_{\alpha}^{-1}(x)$ is a Zariski open subset of the projective space of dimension $h(\alpha) -2a(\alpha) + 1$ by \cref{lemm:malphaopenimmer}. This implies that we have
\[
\# M_{\alpha}(k) \leq \#Z_{a(\alpha), \mathbf{k}(\alpha)}^{\circ}(k) \frac{q^{h(\alpha) -2a(\alpha) + 2}-1}{q-1}\leq \#Z_{a(\alpha), \mathbf{k}(\alpha)}^{\circ}(k)q^{h(\alpha) -2a(\alpha) +1}\frac{1}{1-q^{-1}}
\]
Next we consider
\[
\phi_{a(\alpha), \mathbf{k}(\alpha)} : Z_{a(\alpha), \mathbf{k}(\alpha)}^{\circ} \to U_{\mathbf{k}(\alpha)}.
\]
For any $k$-rational point $x$ on $\phi_{a(\alpha), \mathbf{k}(\alpha)}(Z_{a(\alpha), \mathbf{k}(\alpha)}^{\circ} )$, the fiber $\phi_{a(\alpha), \mathbf{k}(\alpha)}^{-1}(x)$ is a Zariski open subset of the projective space of dimension $2a(\alpha) + 1 - \sum_{i = 1}^r k_i(\alpha)$ by \cref{lemm:configurationcover_fibration}. Thus we conclude 
\[
\#Z_{a(\alpha), \mathbf{k}(\alpha)}^{\circ}(k) \leq \# U_{\mathbf{k}(\alpha)}(k)q^{2a(\alpha) + 1 - \sum_{i = 1}^r k_i(\alpha)}\frac{1}{1-q^{-1}}.
\]
Finally $U_{\mathbf{k}(\alpha)}$ is a Zariski open subset of $\prod_{i = 1}^{4} \mathrm{Hilb}^{[k_i(\alpha)]}(B)$, hence we conclude
\[
\# U_{\mathbf{k}(\alpha)}(k) \leq q^{\sum_{i = 1}^{4} k_i(\alpha)}\frac{1}{(1-q^{-1})^4}.
\]
Altogether our assertion follows.
\end{proof}



By taking a sum as we vary $\alpha$, we can obtain an upper bound on the counting function.  We first need to recall the definition of the $\alpha$-constant introduced in this context by \cite{Peyre}.  We will use the description given in \cite[5.2 Definition]{Jahnel14} but will use $N_{1}(X)_{\mathbb{Z}}$ instead of the dual lattice $N^{1}(X)_{\mathbb{Z}}^{\vee}$.

\begin{defi}[{\cite[5.2 Definition]{Jahnel14}}] \label{defi:alphaconstant}
Let $k$ be a field and $X$ be a smooth Fano variety defined over $k$. Consider $N_{1}(X)$ with the lattice $\Lambda := N_1(X)_{\mathbb Z}$.  We equip $N_{1}(X)$ with the Lebesgue measure normalized so that the fundamental domain for $\Lambda$ has volume $1$.  For any closed rational polyhedral subcone $\mathcal{C} \subset \Nef_{1}(X)$, we define the $\alpha$-constant as 
\[
\alpha(-K_X,\mathcal{C}) = \rho(X) \vol \{ \alpha \in \mathcal{C} \, | \, -K_X.\alpha \leq 1\}.
\]
This is equal to the top coefficient of the Ehrhart quasi-polynomial of the polytope $\mathcal{C}_{-K_X = 1}$.  When we apply this definition to the entire nef cone, we will simply write $\alpha(-K_{X})$.  
\end{defi}

\begin{theo}
\label{theo:Upperbounds}
Let $S$ be a smooth split degree $4$ del Pezzo surface and let $\mathcal{C} \subset \Nef_{1}(X)$ be a closed rational polyhedral subcone. Then we have
\[
\limsup_{d\to \infty}\frac{N^{\mathcal{C}}(B, S, -K_S, d) }{ q^{d}d^{5}} \leq \frac{\alpha(-K_S,\mathcal{C})q^2}{(1-q^{-1})^{7}}
\]

\end{theo}
\begin{proof}
It follows from \cref{lemm:upperboundsofpointcountingI} %and \cref{lemm:quarticdelPezzo}
that  %this counting function is bounded by
\[
N^{\mathcal{C}}(B, S, -K_S, d)  \leq \frac{q^2}{(1-q^{-1})^{6}}\sum_{\alpha \in \mathcal{C}_{\mathbb Z},\, -K_S.\alpha \leq d} q^{-p^*K_S.\alpha}.
\]
%Then our assertion follows from a standard argument using the Ehrhart polynomial.
%See \cite[Proposition 4.3]{LRT23} for such an argument.  
Let $V \subset N_{1}(X)$ denote the affine hyperplane $V =  \{ \alpha \subset N_{1}(X) | -K_{X} \cdot \alpha = 1 \}$ equipped with the $\mathbb{Z}$-structure coming from $\Lambda \cap V$.  Let $P(d)$ denote the Ehrhart quasi-polynomial for the compact rational polyhedron $\mathcal{C} \cap V$; thus $P(d)$ is a quasi-polynomial of degree $\dim(V) = 5$ and with constant leading coefficient $\alpha(-K_{X},\mathcal{C})$.  We have
\begin{align*}
\frac{q^2}{(1-q^{-1})^{6}}\sum_{\alpha \in \mathcal{C}_{\mathbb Z},\, -K_S.\alpha \leq d} q^{-K_S.\alpha} & = \frac{q^2}{(1-q^{-1})^{6}} \sum_{j = 1}^{d} q^{j} P(j) \\
& \leq \frac{q^{d+2}}{(1-q^{-1})^{7}} \sup_{j = 1,\dotsc,d} \{ P(j) \}.
\end{align*}
Dividing by $q^{d}d^{5}$ and letting $d$ go to infinity we obtain the desired statement.  
\end{proof}

\subsection{Stratifications in the algebraic settings}
Let $(w < x) \in (U_{\mathbf{k}} < \mathrm{Hilb}(B)^Q)(\overline{k})$. We define a linear space $Z_{w < x}^{\mathrm{alg}}$ as
\[
Z_{w < x}^{\mathrm{alg}} := \Gamma(B_{\overline{k}}, \mathcal O(a)\otimes V_1 \oplus \mathcal O(a')\otimes V_2)_x \subset E_w = \Gamma(B_{\overline{k}}, \mathcal O(a)\otimes V_1 \oplus \mathcal O(a')\otimes V_2)_w,
\]
where $\Gamma(B_{\overline{k}}, \mathcal O(a)\otimes V_1 \oplus \mathcal O(a')\otimes V_2)_x$ is the space of $(s, t) \in \Gamma(B_{\overline{k}}, \mathcal O(a)\otimes V_1 \oplus \mathcal O(a')\otimes V_2)$ such that for any $q\in Q$, $(s, t)(x_q) \subset \mathcal K_q$.
As $(w<x)$ vary, these assemble into a stratification
\[
Z^{\mathrm{alg}} = \{ ((w < x), z) \,| \, (w < x) \in (U_{\mathbf{k}} < \mathrm{Hilb}(B)^Q), z \in Z^{\mathrm{alg}}_{w < x} \}  \subset (U_{\mathbf{k}} < \mathrm{Hilb}(B)^Q) \times_{U_{\mathbf{k}}} E,
\]
where $E \to U_{\mathbf{k}}$ is the fibration parametrizing $E_w$ for $w \in U_{\mathbf{k}}$.
Note that this stratification is different from the one defined in \cref{sec:CJS}. However, when $(w < x)$ is essential, we have
\[
Z^{\mathrm{alg}}_{w < x} = Z^{\mathrm{top}}_{w < x} \cap E^{\mathrm{alg}}_{w}.
\]
For this reason, the two stratifications are essentially the same from the point of view of the inclusion-exclusion principle.


\subsection{Counting curves via the bar complex }
\label{subsec:countingcurves}

Here we follow the discussion of \cref{subsubsec:homologicalstability}.  Let $h, a, a', \mathbf{k}$ be non-negative integers such that
\[
h = 2a + 2a' -\sum_i k_i, \, 2a -\sum_{i = 1}^4k_i > 0, \, 2a' -\sum_{i = 1}^4k_i > 0
\]
We define $I \in \mathbb Q_{\geq 0}$ by
\[
I = \frac{1}{8} \min\left\{2a -\sum_{i = 1}^4k_i,  2a'  -\sum_{i = 1}^4k_i\right\} - \frac{1}{2}.
\]
Define
\[
E(w < x) := 4m_0(x)  +3 \sum_{i, j} m_{\ell_{i, j}}(x) + 2\sum_j m_{V_j}(x) +2\sum_i m_{\ell_{i, 1} \oplus \ell_{i, 2}}(x) - 2\sum k_i
\]
and let $P \subset (U_{\mathbf{k}} < \mathrm{Hilb}(B)^Q)$ be the subposet consisting of $(w < x)$ such that $E(w<x) \leq 2I$.
\Cref{lemm:Eproper} shows that $P$ is proper over $U_{\mathbf{k}}$.
Let $M_{a, a', \mathbf{k}}$ be the space of rational curves of class $(a, a', \mathbf{k})$ on $S$.
Then we have a natural projection
\[
M_{a, a', \mathbf{k}} \to U_{\mathbf{k}}
\]
Let $F_1 \subset U_{\mathbf{k}}$ be the complement of the image of the above projection.
It follows from \cref{prop:finaldimestimate} that the codimension of $F_1$ is greater than $8I$.

Let $(w < x)$ be a saturated element of $P(\overline{k})$ and $(w < y)$ be a saturated pair such that $x \prec y$.
Let us consider the space
\[
\Gamma(B_{\overline{k}}, \mathcal O(a)\otimes V_1 \oplus \mathcal O(a')\otimes V_2)_y.
\]
We define
\begin{align*}
a_y &= a- m_0(y) - m_{V_2}(y) - \sum_{i = 1}^4m_{\ell_{i, 2}}(y), \\
a'_y &= a- m_0(y) - m_{V_1}(y) - \sum_{i = 1}^4m_{\ell_{i, 1}}(y), \\
k_{y, i, j} &= m_{\ell_{i, j}}(y) + m_{\ell_{i, 1} \oplus \ell_{i, 2}}(y),
\end{align*}
as before.
We also define
\[
y_j (\ell_{i, j})= \left(\sum_{c \in B(\overline{k})} (m_{\ell_{i, j}}(f_{y, c}) + m_{\ell_{i, 1} \oplus \ell_{i, 2}}(f_{y, c}))[c] \right), \, y_j(0) = \emptyset.
\]
Then the space $\Gamma(B_{\overline{k}}, \mathcal O(a)\otimes V_1 \oplus \mathcal O(a')\otimes V_2)_y$ is identified with
\[
\Gamma(B_{\overline{k}}, \mathcal O(a_y)\otimes V_1)_{y_1}\oplus \Gamma(B_{\overline{k}}, \mathcal O(a'_y)\otimes V_2)_{y_2}, 
\]
where the definition of this space can be found in \eqref{equation:P^1incident}.
We consider 
\[
E_j(w < y) = 2m_0(y) + 2m_{V_{j'}}(y) +2 \sum_{i = 1}^4 m_{\ell_{i, j'}}(y) + \sum_{i = 1}^4 (m_{\ell_{i, j}}(y) + m_{\ell_{i, 1} \oplus \ell_{i, 2}}(y)) - \sum k_i
\] 
where $\{j, j'\} = \{1, 2\}$. Since this function is monotone increasing with respect to $y$ we have $E_1(w < y) \geq 0$ and $E_2(w < y)\geq 0$. Moreover we have $E = E_1 + E_2$. Thus we have $E_j \leq 2I+2$. Following the discussion of \cref{subsubsec:homologicalstability}, we have
\[
2a_y - \sum_{i = 1}^r k_{y, i, 1} \geq 6I + 2, \quad
2a'_y - \sum_{i = 1}^r k_{y, i, 2}  \geq 6I + 2
\]
The space $\Gamma(B_{\overline{k}}, \mathcal O(a_y)\otimes V_1)_{y_1}$ is unobstructed if $y_1$ is contained in the image of 
\[
Z_{a_y, \mathbf{k}_{y, 1}}^\circ \to U_{\mathbf{k}_{y,1}}.
\]
The complement of the image of this map has dimension at most $\sum_{i = 1}^4k_{y, i, 1} -6I-2$. Arguing as in \cref{subsubsec:homologicalstability}, the loci of the corresponding $w$ such that $w < y$ has dimension at most $\sum k_i - 4I.$
Let $F_2$ be the union of the Galois orbits of the closures of all such loci over $\overline{k}$ while $T$ runs over all combinatorial types we consider.  
Note that the codimension of $F_2$ in $U_{\mathbf{k}}$ is greater than or equal to $4I$.
Similarly we construct $F_3$ for the space $\Gamma(B_{\overline{k}}, \mathcal O(a'_y)\otimes V_2)_{y_2}$.
Let $F = F_1 \cup F_2 \cup F_3$. Also note that as in  \cref{subsubsec:homologicalstability}  we have $E(T) \leq 2\kappa (T)$.

Let $\widetilde{M}_{a, a', \mathbf{k}} \to M_{a, a', \mathbf{k}}$ be the $\mathbb G_m^2$-torsor as before.
We are interested in
\[
\#M_{a, a', \mathbf{k}}(k) = (q-1)^{-2}\#\widetilde{M}_{a, a', \mathbf{k}}(k).
\]
By the Grothendieck--Lefschetz trace formula, we have
\[
\#\widetilde{M}_{a, a', \mathbf{k}}(k) = \sum_{i} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((\widetilde{M}_{a, a', \mathbf{k}})_{\overline{k}}, \mathbb Q_\ell)).
\]
The goal of this subsection is to estimate this quantity.  When $i$ is small, we bound the Frobenius trace using the general results of Sawin and Shusterman in \cref{appendix-main}.  When $i$ is large, we will first compare these cohomology groups to the bar complex, then to the cohomological virtual bar complex, at the cost of adding error terms at each step.  Our desired statement (\cref{theo:Maincountingbybar}) arises naturally from the cohomological virtual bar complex via \cref{prop:virtualcount}.

Since a degree $4$ del Pezzo surface $S$ is the intersection of two quadrics in $\mathbb{P}^{4}$, the constant in the proof of \cref{appendix-main} is $C_1 = 2^{32}$.  Then by combining the result of Sawin and Shusterman in \cref{appendix-main}, Deligne's estimates, and Leray's spectral sequence, we have
\begin{equation} \label{eq:mtildesmalli}
\left|\sum_{i< 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((\widetilde{M}_{a, a', \mathbf{k}})_{\overline{k}}, \mathbb Q_\ell)) \right| = O(q^{2a + 2a' - \sum k_j -I/2 + 5} C^h_1).
\end{equation}
Let $U = U_{\mathbf{k}} \setminus F$. Then since the codimension of $F$ is greater than or equal to $4I$ and since $\widetilde{M}_{a,a',\mathbf{k}}$ is flat over $U_{\mathbf{k}}$, the inclusion $\widetilde{M}_{a,a',\mathbf{k}}|_{U} \to \widetilde{M}_{a,a',\mathbf{k}}$ induces an isomorphism on \'etale cohomology with compact support in codimension $\leq 8I-2$.  In particular, 
we have
\begin{multline*}
\sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((\widetilde{M}_{a, a', \mathbf{k}})_{\overline{k}}, \mathbb Q_\ell))\\ =  \sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((\widetilde{M}_{a, a', \mathbf{k}}|_U)_{\overline{k}}, \mathbb Q_\ell)).  
 \end{multline*} 

 Then assuming $I \geq 1$ we have
\[
E|_U = (\widetilde{M}_{a, a', \mathbf{k}}|_U) \sqcup \mathrm{im}(Z^{\mathrm{alg}}_{P_U} \to E|_U).
\]
This implies that we have
\begin{equation}\label{eq:splittingtildem}
\begin{multlined}[0.9\displaywidth] 
\sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((\widetilde{M}_{a, a', \mathbf{k}}|_U)_{\overline{k}}, \mathbb Q_\ell))\\
\begin{multlined}=\sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((E|_U)_{\overline{k}}, \mathbb Q_\ell)) \\
 \phantom{=} - \sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}(\mathrm{im}(Z^{\mathrm{alg}}_{P_U} \to E|_U)_{\overline{k}}, \mathbb Q_\ell)) \\
  + O(q^{2a + 2a' - \sum_j k_j -I/2 +6} C^h_1),
  \end{multlined}
\end{multlined}
\end{equation}
where the last error term is coming from a bound on the Frobenius trace of a subspace of $$H^{4a + 4a' -2\sum_j k_j -\lceil I \rceil + 10}_{\text{\'et}, c}((\widetilde{M}_{a, a', \mathbf{k}}|_U)_{\overline{k}}, \mathbb Q_\ell)$$ obtained by applying \cref{appendix-main}.  
Let us analyze
\[
\sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}(\mathrm{im}(Z^{\mathrm{alg}}_{P_U} \to E|_U)_{\overline{k}}, \mathbb Q_\ell)).
\]
By \cref{theo:5.4inDT} with $R = P$, this quantity is equal to
\[
 \sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}(B(P_U, Z^{\mathrm{alg}}_{P_U})_{\overline{k}}, \mathbb Q_\ell)).
\]
By \cref{prop:ssforbarconstruction} we have a spectral sequence:
\begin{align*}
\bigoplus_{i + j = n} E_1^{i, j} &= \bigoplus_{T: \text{ essential type of $P$}} H^{n}_{\text{\'et}, c}((Z^{\mathrm{alg}}|_{U \times_{U_{\mathbf{k}}} \mathcal N_T})_{\overline{k}}, \mu'(T)[1])\\ 
& \implies H^{n}_{\text{\'et}, c}(B(P_U, Z^{\mathrm{alg}}_{P_U})_{\overline{k}}, \mathbb Z_\ell).
\end{align*}
It follows from \cref{lemm:spectral} that
\begin{equation*}
\begin{multlined}[\displaywidth]
\Big| \sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}(B(P_U, Z^{\mathrm{alg}}_{P_U})_{\overline{k}}, \mathbb Q_\ell))- \\ 
 \sum_{T: \text{ ess. type of $P$}}   \sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^{i}_{\text{\'et}, c}((Z^{\mathrm{alg}}|_{U \times_{U_{\mathbf{k}}} \mathcal N_T})_{\overline{k}}, \mu'(T)[1]\otimes\mathbb Q_\ell))\Big|  \leq N
\end{multlined}
\end{equation*}
where $N$ is the sum of the absolute values of eigenvalues of the Frobenius for
\[
\bigoplus_{T: \text{ essential type of $P$}} H^{ \lceil 4a + 4a' -2\sum_j k_j -I +10\rceil}_{\text{\'et}, c}((Z^{\mathrm{alg}}|_{U \times_{U_{\mathbf{k}}} \mathcal N_T})_{\overline{k}}, \mu'(T)[1]\otimes\mathbb Q_\ell).
\]
Our next goal is to bound $N$.  Since $Z^{\mathrm{alg}}$ has the expected codimension over $U \times_{U_{\mathbf{k}}} \mathcal N_T$, for any $i \geq 4a + 4a' -2\sum_j k_j -I+10$ we have
\[
H^{i}_{\text{\'et}, c}((Z^{\mathrm{alg}}|_{U \times_{U_{\mathbf{k}}} \mathcal N_T})_{\overline{k}}, \mu'(T)[1]\otimes \mathbb Q_\ell) = H^i_{\text{\'et}, c}((U \times_{U_{\mathbf{k}}} \mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1]\otimes \mathbb Q_\ell)
\]
where as before $n_{a, a', \mathbf{k}, T} = 2a + 2a' +4 -2\sum_i k_i -\gamma(T)$.
The cohomological dimension of
\[
H^i_{\text{\'et}, c}((F \times_{U_{\mathbf{k}}} \mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1]\otimes \mathbb Q_\ell)
\]
is at most
\begin{multline*}
2\sum_j k_j - 8I + 2|\Supp(T)| + \mathrm{rank}(T) + 4a + 4a' + 9 - 4\sum_j k_j - 2\gamma(T)\\ 
\leq 4a + 4a' - 2\sum_j k_j - \kappa(T) - 8I +9
\end{multline*}
This implies that for $i \geq 4a + 4a' -2\sum_j k_j -I+10$, we have
\begin{multline*}
H^i_{\text{\'et}, c}((U \times_{U_{\mathbf{k}}} \mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1]\otimes \mathbb Q_\ell)\\ 
\cong H^i_{\text{\'et}, c}((\mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1] \otimes \mathbb Q_\ell).
\end{multline*}
Thus the following proposition follows from \cref{theo:errorforvirtual} applied with $\eta = 1/2$ combined with the inequality $h \geq \max \{ \sum_{i=1}^{4} k_{i}, I \}$: 
\begin{prop}
For any constants $C_2 > 160$ and $C_3 > (160)^{4}$ if $q > C_3$ we have
\[
N = O( q^{2a + 2a' - \sum_j k_j -I/4 +4} C^h_2).
\]
\end{prop}
Thus we conclude that 
\begin{multline*}
\sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}(B(P_U, Z^{\mathrm{alg}}_{P_U})_{\overline{k}}, \mathbb Q_\ell)) \\ 
= \sum_{T: \text{ ess. type of $P$}}   \sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^{i}_{\text{\'et}, c}(((\mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1])\otimes \mathbb Q_\ell)\\
+ O(q^{2a + 2a' - \sum_j k_j -I/4+6} \max\{C_1, C_2\}^h).
\end{multline*}
When $T$ is an essential type which is not a type of $P$, we have $\kappa (T) > I$. This implies that the cohomological dimension of 
\[
H^{i}_{\text{\'et}, c}(((\mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1]\otimes \mathbb Q_\ell)
\]
is at most
\[
4a + 4a' + 9 - 2\sum_j k_j -2\gamma(T) + \mathrm{rank}(T) + 2|\Supp(T)| < 4a + 4a' + 9- 2\sum_j k_j -I.
\]
We conclude that 
\begin{align*}
&\sum_{T: \text{ ess. type of $P$}}   \sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^{i}_{\text{\'et}, c}(((\mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1]\otimes \mathbb Q_\ell))\\
&= \sum_{T: \text{ ess. type}}   \sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^{i}_{\text{\'et}, c}(((\mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1]\otimes \mathbb Q_\ell)).
\end{align*}
Then using \cref{theo:errorforvirtual} again, we obtain
\begin{multline*}
\sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}(B(P_U, Z^{\mathrm{alg}}_{P_U})_{\overline{k}}, \mathbb Q_\ell))\\
= \sum_{T: \text{ essential type}} \sum_i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((\mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1]\otimes \mathbb Q_\ell))\\
+ O(q^{2a + 2a' - \sum_j k_j -I/4 +6} \max\{C_1, C_2\}^h).
\end{multline*}
Now it follows from \cref{prop:virtualcount} that 
\begin{multline*}
\sum_{T: \text{ essential type}} \sum_i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((\mathcal N_T)_{\overline{k}}, \mu(T)(-n_{a, a', \mathbf{k}, T})[-2n_{a, a', \mathbf{k}, T}+1]\otimes \mathbb Q_\ell))\\
\begin{split}
&= \sum_{T: \text{ essential type}}-q^{2a+ 2a'+4} \sum_{(w< x) \in \mathcal N_T(k)} \mu_k(w, x)q^{-\gamma(x)} \\
&= -q^{2a+ 2a'+4} \sum_{(w< x) \in (U_{\mathbf{k}} < Q^{JB})(k)} \mu_k(w, x)q^{-\gamma(x)},
\end{split}
\end{multline*}
We conclude that
\begin{multline*}
\sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}(B(P_U, Z^{\mathrm{alg}}_{P_U})_{\overline{k}}, \mathbb Q_\ell))\\
\qquad \qquad = -q^{2a+ 2a'+4} \sum_{(w< x) \in (U_{\mathbf{k}} < Q^{JB})(k)} \mu_k(w, x)q^{-\gamma(x)} + O(q^{2a + 2a' - \sum_j k_j -I/4 +6} \max\{C_1, C_2\}^h).
\end{multline*}
Similarly, one can prove that
\begin{multline*}
\sum_{i \geq 4a + 4a' -2\sum_j k_j -I + 10} (-1)^i \mathrm{Tr}(\mathrm{Frob} \curvearrowright H^i_{\text{\'et}, c}((E|_U)_{\overline{k}}, \mathbb Q_\ell)) \\ 
= q^{2a+ 2a'+4}\sum_{w \in U_{\mathbf{k}}(k)} q^{-\gamma(w)} + O(q^{2a + 2a' - \sum_j k_j -I/4 +6} \max\{C_1, C_2\}^h).
\end{multline*}
Combining the previous two equations with \cref{eq:mtildesmalli,eq:splittingtildem}, we obtain:
\begin{theo}
\label{theo:Maincountingbybar}
Assume that $q > C_3$.
Then we have
\[
\#\widetilde{M}_\alpha(k) = q^{2a + 2a'+4} \sum_{(w\leq x) \in (U_{\mathbf{k}} \leq Q^{JB})(k)} \mu_k(w, x)q^{-\gamma(x)} + O(q^{2a + 2a' - \sum_j k_j -I/4 +6} \max\{C_1, C_2\}^h),
\]
where the implied constant does not depend on $q, a, a', \mathbf{k}$.

\end{theo}




\subsection{The residue of the virtual bar complex}
\label{subsec:virtualpointcounts}


We work with the set up described in \cref{sec:barconstruction}.
We assume that our ground field $k$ is a finite field $\mathbb F_q$ and that $B = \mathbb{P}^{1}_{k}$.


Let $\alpha$ be an ample curve class on a split quartic del Pezzo surface $S$ such that $\alpha$ lies in the interior of the region $\mathcal T_{\alpha}$ defined in \cref{nota:bignota}.  Using the invariants $a(\alpha), a'(\alpha), k_i(\alpha)$ of \cref{nota:bignota}, we have:
\[
2a(\alpha) - \sum_{i = 1}^4 k_i(\alpha) > 0, 2a'(\alpha) - \sum_{i = 1}^4 k_i(\alpha) > 0.
\]




By \cref{theo:Maincountingbybar}, we would like to understand the limiting behavior of
\[
q^{2a + 2a' +4} \sum_{(w\leq x) \in (U_{\mathbf{k}} \leq Q^{JB})(k)} \mu_k(w, x)q^{-\gamma(x)}
\]
as $a, a', k_i \to \infty$. To this end, we consider the following virtual height zeta function: 
\begin{equation*}
\mathsf Z(\mathbf{t}) = \sum_{k_1, \dotsc, k_4 = 0}^\infty q^{\sum_{i = 1}^4k_i}\left( \sum_{(w\leq x) \in (U_{\mathbf{k}} \leq Q^{JB})(k)} \mu_k(w, x)q^{-\gamma(x)} \right)t_1^{k_1}t_2^{k_2}t_3^{k_3}t_4^{k_4}.
\end{equation*}
It follows from \cref{lemm:Mobius}.(1) that the above zeta function can be rewritten as the following convergent Euler product: 
\begin{align*}
&\mathsf Z(\mathbf{t}) \\ &= \prod_{c \in |B|}\left(\sum_{x \in \mathrm{ch}(Q(k))} \mu_k(\hat{1}, x)q^{-\gamma (x)|c|} + \sum_{i = 1}^4\sum_{d_i = 1}^\infty (qt_i)^{|c|d_i}\sum_{x \in \mathrm{ch}(Q(k)), \,  d_i[\ell_{i, 1} \oplus \ell_{i, 2}]\leq x} \mu_k(d_i[\ell_{i, 1} \oplus \ell_{i, 2}], x)q^{-\gamma (x)|c|} \right)
\end{align*}
where $|B|$ is the set of closed points on $B$ and $|c|$ is the degree $[k(c):k]$. Then it follows from \cref{lemm:Mobius}.(2) and \cref{exam:essentialsaturatedexample} that the above Euler product is equal to
\begin{equation*}
\prod_{c \in |B|}\left( 1 - 6q^{-2|c|} + 8q^{-3|c|} -3q^{-4|c|}+ \sum_{i = 1}^4\sum_{d_i = 1}^\infty (qt_i)^{|c|d_i} (q^{-2d|c|}  - 2q^{-(2d_i+1)|c|} + 2q^{-(2d_i + 3)|c|} - q^{-(2d_i + 4)|c|})\right).
\end{equation*}
It is clear from the formula that this Euler product absolutely converges when there is a $\delta > 0$ such that $|t_i| \leq q^{-\delta}$ for $i = 1, \dotsc, 4$. The following proposition verifies the basic properties of $\mathsf Z(\mathbf{t})$.

\begin{prop}
\label{prop:formalheightzeta}

We have the following Euler product:
\begin{multline*}
\prod_{i = 1}^4Z_{\mathbb P^1}(q^{-1}t_i)^{-1}\mathsf Z(\mathbf{t}) \\
 = \prod_{c \in |B|}\left(1 +O(q^{-2|c|})(1 + \sum_i t_i^{|c|})+  \sum_{\substack{\ell_1, \ell_2, \ell_3, \ell_4 \in \{0,1\} \\ \ell_1+\ell_2 + \ell_3 + \ell_4 > 1}}O(q^{-( \ell_1 + \ell_2 + \ell_3 + \ell_4)|c|})t_1^{|c|\ell_1}t_2^{|c|\ell_2}t_3^{|c|\ell_3}t_4^{|c|\ell_4} \right),
\end{multline*}
where $Z_{\mathbb P^1}(t)$ is the Hasse--Weil zeta function for $\mathbb P^1$.
In particular if $0 < \delta < 1/2$ then this Euler product absolutely converges when $|t_i|\leq q^{\delta}$ for $i = 1, \dotsc, 4$.
Furthermore we have
\[
\lim_{t_i \to 1} \prod_{i = 1}^4 (1-t_i) \cdot \mathsf Z(\mathbf{t}) = (1-q^{-1})^{-4}\prod_{c \in |B|}(1-q^{-|c|})^6(1+6q^{-|c|} + q^{-2|c|}).
\]
\end{prop}










\begin{proof}

First we have
\begin{align*}
&\begin{multlined}\prod_{i = 1}^4 Z_{\mathbb P^1}(q^{-1}t_i)^{-1}
\\ \qquad \times\prod_{c \in |B|}\left( 1 - 6q^{-2|c|} + 8q^{-3|c|} -3q^{-4|c|}+ \sum_{i = 1}^4\sum_{d_i = 1}^\infty t_i^{|c|d_i}q^{-d_i|c|} (1  - 2q^{-|c|} + 2q^{-3|c|} - q^{-4|c|}) \right)\end{multlined}\\
&\begin{multlined}=\prod_{c \in |B|}\prod_{i = 1}^4(1-t_i^{|c|}q^{-|c|}) \\ 
\qquad \times \left( 1 - 6q^{-2|c|} + 8q^{-3|c|}-3q^{-4|c|}+ \sum_{i = 1}^4\frac{t_i^{|c|}q^{-|c|}}{1-t_i^{|c|}q^{-|c|}} (1  - 2q^{-|c|} + 2q^{-3|c|} - q^{-4|c|})\right)\end{multlined}\\
&\begin{multlined}=\prod_{c \in |B|}\Bigg( \left(\prod_{i = 1}^4(1-t_i^{|c|}q^{-|c|}) \right)(1 - 6q^{-2|c|} + 8q^{-3|c|}-3q^{-4|c|})\\
\qquad + \sum_{i = 1}^4\left(\prod_{j \neq i}(1-t_j^{|c|}q^{-|c|})\right)t_i^{|c|}q^{-|c|}(1  - 2q^{-|c|} + 2q^{-3|c|} - q^{-4|c|})\Bigg).\end{multlined}
\end{align*}
The first assertion follows from this expression.
Also one can compute the leading term as
\begin{multline*}
\lim_{t_i \to 1} \prod_{i = 1}^4 (1-t_i)Z_{\mathbb P^1}(q^{-1}t_i)\\ 
\times \prod_{c \in |B|}(1-q^{-|c|})^4
 \left( 1 - 6q^{-2|c|} + 8q^{-3|c|} -3q^{-4|c|}+ \frac{4q^{-|c|}}{1-q^{-|c|}} (1  - 2q^{-|c|} + 2q^{-3|c|} - q^{-4|c|})\right)\\
= (1-q^{-1})^{-4}\prod_{c \in |B|}(1-q^{-|c|})^6(1+6q^{-|c|} + q^{-2|c|}). \qedhere
\end{multline*}
\end{proof}

Next we expand the product: 
\begin{equation*}
\prod_{i = 1}^4 (1-t_i)\mathsf Z(\mathbf{t}) = \sum_{j_1, j_2, j_3, j_4 = 0}^\infty B_{j_1j_2j_3j_4}t_1^{j_1}t_2^{j_2}t_3^{j_3}t_4^{j_4}.
\end{equation*}
We fix $\delta$ satisfying $0 < \delta < 1/2$.  Assume that $|t_i|\leq q^\delta$ for $i = 1, 2, 3, 4$.
Then \cref{prop:formalheightzeta} shows that the above series absolutely converges.
This implies that $|B_{j_1j_2j_3j_4}| = O(q^{-\eta_1(j_1 + j_2 + j_3 + j_4)})$ for any $0 < \eta_1 < \delta$.
%which does not depend on $\mathbf{k}, q$.
This leads to the following proposition:


\begin{prop}
\label{prop:expectedbar}
There exists $\eta_1 > 0$ which does not depend on $\mathbf{k}, q$ such that  
\[
q^{\sum_i k_i}\sum_{(w\leq x) \in (U_{\mathbf{k}} \leq Q^{JB})(k)} \mu_k(w, x)q^{-\gamma(x)} = (1-q^{-1})^{-4}\prod_{c \in |B|}(1-q^{-|c|})^6(1+6q^{-|c|} + q^{-2|c|}) + O(q^{-\eta_1 \min\{k_i\}}),
\]
where the implied $O$-constant does not depend on $\mathbf{k}, q$. 
\end{prop}
\begin{proof}
Recall that $\mathsf{Z}(\mathbf{t})$ can be obtained from the power series $\sum B_{j_{1}j_{2}j_{3}j_{4}} t_{1}^{j_{1}}t_{2}^{j_{2}}t_{3}^{j_{3}}t_{4}^{j_{4}}$ by multiplying by $\prod_{i=1}^{4}(1-t_{i})^{-1}$.  Comparing coefficients, we see that
\[
q^{\sum_i k_i}\sum_{(w\leq x) \in (U_{\mathbf{k}} \leq Q^{JB})(k)} \mu_k(w, x)q^{-\gamma(x)} = \sum_{j_i \leq k_i} B_{j_1j_2j_3j_4.}
\]
\Cref{prop:formalheightzeta} shows that 
\begin{multline*}
\lim_{k_i \to \infty}q^{\sum_i k_i}\sum_{(w\leq x) \in (U_{\mathbf{k}} \leq Q^{JB})(k)} \mu_k(w, x)q^{-\gamma(x)} 
\\ = \sum_{j_1, j_2, j_3, j_4 = 0}^\infty B_{j_1j_2j_3j_4} = (1-q^{-1})^4\prod_{c \in |B|}(1-q^{-|c|})^6(1+6q^{-|c|} + q^{-2|c|})
\end{multline*}
Thus the error term in the proposition statement is given by 
\[
\sum_{j_1 > k_1}|B_{j_1j_2j_3j_4}| + \sum_{j_2 > k_2} |B_{j_1j_2j_3j_4}|+ \sum_{j_3 > k_3}|B_{j_1j_2j_3j_4}| + \sum_{j_4 > k_4} |B_{j_1j_2j_3j_4}| = \sum_{i = 1}^4O(q^{-\eta_1 k_i})
\]
for some $\eta_1 > 0$ and our assertion follows.
\end{proof}


\subsection{Peyre's constant}

Finally, to get an explicit formula for the counting function we must compute Peyre's constant explicitly.  We follow the presentation of \cite{Peyre} and \cite{BT}.
Let $S$ be a split degree $4$ del Pezzo surface over $\mathbb{F}_{q}$ with the anticanonical height.  \cite{Peyre} and \cite{BT} define
\begin{equation*}
c(\mathbb P^1, S, -K_S) = (1-q^{-1})^{-1}\alpha(-K_{S}) \beta(S) \tau_{-K_{S}}(S)
\end{equation*}
where $\alpha(-K_{S})$ is defined as in \cref{defi:alphaconstant}, $\beta(S) = \# H^{1}(\mathbb{F}_{q}(t),\Pic(S_{\overline{\mathbb{F}_{q}(t)}}))$, and $\tau_{-K_{S}}(S)$ is the Tamagawa constant.  The value $\alpha(-K_{S}) = \frac{1}{180}$ is computed by \cite[Theorem 4]{Derenthal07}.  Due to the splitness assumption $\beta(S) = 1$.  Since we are working with a trivial family of split surfaces, the constant $\tau_{-K_{S}}(S)$ has the following simple form:
\begin{equation*}
\tau_{-K_{S}}(S) = q^{2} \left(1 - q^{-1} \right)^{-6} \left( \prod_{c \in |B|} \left( 1- q^{-|c|} \right)^6  \frac{\# S(\mathbb F_{q^{|c|}})}{q^{2|c|}} \right) % \lim_{s \to 1} \left( (s-1)^{6} \zeta_{\mathbb{F}_{q}(t)}(s)^6 \right) % \\
%& = q^{2} \left( \prod_{\textrm{places } \nu \textrm{ of }\mathbb{F}_{q}(t)}  1 - \frac{5}{\# \kappa_{v}} + \frac{5}{\# \kappa_{v}^{2}} - \frac{1}{\# \kappa_{v}^{3}}    \right) \lim_{s \to 1} \left( (s-1)^{6} \zeta_{\mathbb{F}_{q}(t)}(s) \right)
\end{equation*}
as $c \in |B|$ varies over all places where $|c|$ denotes $[k(c):k]$. 
Using $\# S(\mathbb{F}_{q^{|c|}}) = q^{2|c|} + 6 q^{|c|} + 1$, we obtain 
\begin{equation*}
c(\mathbb P^1, S, -K_S) = \frac{q^{2}}{180} \left(1 - q^{-1} \right)^{-7} \left( \prod_{c \in |B|} \left( 1- q^{-|c|} \right)^6  \left( 1 + 6q^{-|c|} + q^{-2|c|} \right)  \right)
\end{equation*}



\subsection{The proofs of the main theorems}

In this section we prove \cref{theo:intromaninconj}. Let $S$ be a split quartic del Pezzo surface over $k = \mathbb F_q$ as before.

%Let $\Nef_1(S) = \cup_{i=1}^{960} \mathcal T_{i}$
%be the chamber decomposition introduced in \cref{defi:regions}.  Our results allow us to estimate point counts precisely for all curve classes in the interior of $\mathcal{T}_{i}$.  
%Furthermore, we have an upper bound of the expected order for point counts for arbitrary curve classes.  
%We obtain an asymptotic formula by counting curve classes which are $\epsilon$ away from the boundary of some $\mathcal{T}_{i}$.

%Let $\mathcal{T}_{i,-K_{S}=1}$ denote the intersection of $\mathcal{T}_{i}$ with the hyperplane $\{-K_S.\alpha = 1\}$.   
%We also fix a metric on $N_{1}(S)_{\mathbb{R}}$ by choosing an isomorphism $N_{1}(S)_{\mathbb{Z}} \cong \mathbb{Z}^{6}$ and using it to pass the max norm from $\mathbb{R}^{6}$ to $N_{1}(S)_{\mathbb{R}}$.  For any rational $\epsilon > 0$, we let $\mathcal L_{i, \epsilon}$ be the cone generated by $\mathcal T_{i, -K_S = 1} \cap N_\epsilon$ where $N_\epsilon$ is the set of points  inside the hyperplane $\{-K_S.\alpha = 1\}$ whose distance to the boundary of $\mathcal T_{i, -K_S = 1}$ is less than $\epsilon$. 
%Finally let $\mathcal T_{i, \epsilon} = \mathcal T_i \setminus \mathcal L_{i, \epsilon}$.  Note that $\mathcal{T}_{i,\epsilon}$ is a closed rational polyhedral cone.

Let $\mathfrak P$ be the set of birational morphisms $\rho : S \to \mathbb P^1 \times \mathbb P^1$.
For such a birational morphism $\rho : S \to \mathbb P^1 \times \mathbb P^1$, we define $F, F', E_1, \dotsc, E_4$ as \cref{nota:bignota}.
For each class $\alpha \in \mathrm{Nef}_1(S)$, we define
\[
\mathfrak I_\rho(\alpha) = \frac{1}{32}\min \{ 2F.\alpha - \sum_{i = 1}^4 E_i.\alpha, 2F'.\alpha - \sum_{i = 1}^4 E_i.\alpha\},
\]
and 
\[
\mathfrak R_\rho(\alpha) = \min_i \{ E_i.\alpha\}.
\]
Then we define a rational continous homogeneous piecewise linear function $\ell$ on $\mathrm{Nef}_1(S)$ by
\[
\ell(\alpha) = \max_{\rho \in \mathfrak P} \{\min \{\mathfrak I_\rho(\alpha), \mathfrak R_\rho(\alpha)\}\}.
\]
Then it follows from \cref{prop:nefexpression} that $U = \{ \alpha \in \mathrm{Nef}_1(S) \, | \, \ell(\alpha) > 0\}$ is a dense open cone in $\mathrm{Nef}_1(S)$. 



\begin{proof}[Proof of \cref{theo:intromaninconj}:] 
Our goal is to understand the asymptotic formula for
\[
N^{\Nef_1(S)_{\ell, \epsilon}}(B, S, -K_S, d) = \sum_{\alpha \in \Nef_1(S)_{\ell, \epsilon, \mathbb Z},\, -K_S.\alpha \leq d} \# M_{\alpha}(k),
\]
where $\epsilon > 0$ is a small rational number and $\Nef_1(S)_{\ell, \epsilon}$ is the rational polyhedral cone consisting of $\alpha \in \Nef_1(S)$ satisfying $\ell(\alpha) \geq -\epsilon K_S.\alpha$.
We write
\begin{align*}
\frac{N^{\Nef_1(S)_{\ell, \epsilon, \mathbb Z}}(B, S, -K_S, d)}{q^dd^5} &=  (q^dd^5)^{-1}\sum_{\alpha \in \Nef_1(S)_{\ell, \epsilon}, -K_S.\alpha \leq d} \# M_{\alpha}(k)\\
&=  (q^dd^5)^{-1}\sum_{\alpha \in \Nef_1(S)_{\ell, \epsilon, \mathbb Z}, -K_S.\alpha \leq d} q^{-2}(1-q^{-1})^{-2}\# \widetilde{M}_{\alpha}(k)
\end{align*}
We next estimate the sum.  By construction, for any $\alpha \in \Nef_1(S)_{\ell, \epsilon, \mathbb Z}$ we have $$\frac{1}{32}\min\{ 2a(\alpha) - \sum_ik_i( \alpha), 2a'(\alpha) - \sum_ik_i( \alpha), k_i(\alpha)\} \geq \epsilon h(\alpha) = - \epsilon K_S.\alpha,$$
where we choose a birational morphism $\rho : S \to \mathbb P^1 \times \mathbb P^1$ according to \cref{nota:bignota}.
Assume that we have $q^\epsilon > C = \max\{C_1, C_2\}$ and $q > C_3$ where $C_1, C_2, C_3$ are constants defined in \cref{subsec:countingcurves}. (One can take $C = 2^{32}$ and $C_3 > (160)^4$.)
It follows from \cref{theo:Maincountingbybar} that
\begin{equation*}
\begin{multlined}[\displaywidth]
\sum_{\alpha \in \Nef_1(S)_{\ell, \epsilon, \mathbb Z}, -K_S.\alpha \leq d} q^{-2}(1-q^{-1})^{-2}\# \widetilde{M}_{\alpha}(k) = (1-q^{-1})^{-2}\times \\ 
\left( \sum_{\alpha \in \Nef_1(S)_{\ell, \epsilon, \mathbb Z}, -K_S.\alpha \leq d} \left(q^{h(\alpha) + 2+ \sum_i k_i(\alpha)}\left( \sum_{(w\leq x) \in (U_{\mathbf{k}(\alpha)} \leq Q^{JB})(k)} \mu_k(w, x)q^{-\gamma(x)}\right) + O(q^{(1-\delta\epsilon) h(\alpha)}) \right)\right),
\end{multlined}
\end{equation*}
for some $0 < \delta < 1$.
Thus  using \cref{prop:expectedbar} we obtain 
\begin{multline*}
 \sum_{\alpha \in \Nef_1(S)_{\ell, \epsilon, \mathbb Z}, -K_S.\alpha \leq d} q^{-2}(1-q^{-1})^{-2}\# \widetilde{M}_{\alpha}(k)
 \\=  \sum_{\alpha \in \Nef_1(S)_{\ell, \epsilon, \mathbb Z}, -K_S.\alpha \leq d} \left(\tau_{-K_S}(S)q^{h(\alpha)}   + O(q^{(1-\delta'\epsilon )h(\alpha)})\right),
\end{multline*}
for some $0 < \delta' < \min\{\delta, \eta_1\delta\}$ where $\eta_1$ is a constant coming from \cref{prop:expectedbar}.
Thus by using arguemtns using the Ehrhart quasi-polynomials as Theorem~\ref{theo:Upperbounds}, we conclude
\begin{equation*}
\lim_{d\to+ \infty}\frac{N^{\Nef_1(S)_{\ell, \epsilon}}(B, S, -K_S, d)}{q^dd^5} =  (1-q^{-1})^{-1}\alpha(-K_S, \Nef_1(S)_{\ell, \epsilon})\tau_{-K_S}(S). \qedhere
\end{equation*}
\end{proof}



\begin{proof}[Proof of \cref{coro:weakmaninconj}:]
Fix any prime power $q$.  \cref{theo:Upperbounds} shows that for $d$ sufficiently large we have
\begin{equation*}
0 \leq N(\mathbb{P}^{1},S,-K_{S},d) \leq 2 \frac{\alpha(-K_S, \Nef_{1}(X))}{(1-q^{-1})^{7}} q^{d+2}d^{5}
\end{equation*}
In particular, for any finite set of prime powers $q$ we can ensure that \cref{coro:weakmaninconj} holds by choosing $R$ large enough.  Thus it suffices to prove \cref{coro:weakmaninconj} for sufficiently large prime powers $q$.

Fix a constant $C$ as in \cref{theo:intromaninconj}.  Fix a sufficiently large prime power $q$ and let $\epsilon$ be a rational number satisfying $\log(C)/\log(q) < \epsilon < 2\log(C)/\log(q)$.  We define the cone $\Nef_1(S)_{\ell, \epsilon}$ as before and set
\begin{equation*}
\mathcal{C} := \overline{\Nef_{1}(S) \backslash \Nef_1(S)_{\ell, \epsilon}}.
\end{equation*}
\Cref{theo:Upperbounds} shows that for $d$ sufficiently large we have
\begin{equation*}
N^{\Nef_1(S)_{\ell, \epsilon}}(\mathbb{P}^{1},S,-K_{S},d) \leq N(\mathbb{P}^{1},S,-K_{S},d) \leq N^{\Nef_1(S)_{\ell, \epsilon}}(\mathbb{P}^{1},S,-K_{S},d) + 2\frac{\alpha(-K_S,\mathcal{C})q^2}{(1-q^{-1})^{7}} q^{d}d^{5}
\end{equation*}
and thus by \cref{theo:intromaninconj}
\begin{multline*}
\limsup_{d \to \infty}\left| \frac{N(\mathbb P^1, S, -K_S, d)}{q^{d+2} d^{5}}  - (1-q^{-1})^{-1}q^{-2}\alpha(-K_S, \Nef_{1}(S))\tau_{-K_S}(S) \right| \\
\begin{aligned}& \leq \left| \alpha(-K_{S},\Nef_1(S)_{\ell, \epsilon}) - \alpha(-K_S, \Nef_{1}(S) ) \right| \cdot (1-q^{-1})^{-1} q^{-2} \tau_{-K_S}(S) + 2\frac{\alpha(-K_S,\mathcal{C})}{(1-q^{-1})^{7}} \\
& = \alpha(-K_S,\mathcal{C}) \frac{q^{7}}{(q-1)^{7}} \left( 2 + \left( \prod_{c \in |B|} \left( 1- q^{-|c|} \right)^6  \frac{\# S(\mathbb F_{q^{|c|}})}{q^{2|c|}} \right) \right) \\
& \leq \alpha(-K_S,\mathcal{C}) 2^{7} \left( 2 + \left( \prod_{c \in |B|} \left( 1- 2^{-|c|} \right)^6  \frac{\# S(\mathbb F_{2^{|c|}})}{2^{2|c|}} \right) \right)
\end{aligned}
\end{multline*}
Note that when $\epsilon$ is sufficiently small then $\alpha(-K_{S},\mathcal{C})$ is bounded above by a linear function of $\epsilon$ (determined by the shape of $\Nef_{1}(S)$ independently of $q$).  Thus when $q$ is sufficiently large $\alpha(-K_{S},\mathcal{C})$ is bounded by a linear function in $1/\log(q)$.  Altogether, we see that there is an $R$ (not depending on $q$) yielding the desired inequality.
\end{proof}





