\section{Results for degree \texorpdfstring{$4$}{4} toric surfaces} \label{appe:toric}



Suppose that our ground field is $\mathbb C$ and let $Y$ denote the toric surface obtained by blowing up $\mathbb{P}^{1} \times \mathbb{P}^{1}$ at the four torus-invariant points denoted by $(p_i, p_j)$ for $i, j = 1, 2$. We denote the exceptional divisor above $(p_{i},p_{j})$ by $E_{i, j}$.  In this section we analyze the moduli spaces of rational curves on $Y$.  Note that spaces of rational curves on toric varieties have been well-studied both from the perspective of homological stability (\cite{Guest}) and from the perspective of point counting (\cite{BTtoric98, Bourqui03, Bourqui11}).  However, we need a specific result -- a homology equivalence between the spaces of positive pointed maps and the space of continuous pointed maps -- that does not directly follow from the literature.

\begin{theo} \label{theo:torichomequiv}
For any integral nef curve class $\alpha \in \Nef_1(Y)$, the inclusion
\begin{equation*}
\Top^{+}_{*}(\mathbb{P}^{1},Y)_{\alpha} \to \Top_{*}(\mathbb{P}^{1},Y)_{\alpha}
\end{equation*}
induces isomorphisms of homology groups of degree $\leq \min_{i, j}\{E_{i, j}.\alpha\}$.
\end{theo}

Our plan is as follows.  For any $\alpha \in \Nef_{1}(Y)$, let $M_{\alpha,*}$ denote the moduli space of pointed algebraic morphisms of class $\alpha$.  By mimicking the material in \cref{sec:CJS}, we show that the inclusion $M_{\alpha,*} \to \Top^{+}_{*}(\mathbb{P}^{1},Y)_{\alpha}$ induces an equality of homology groups in some range.  In turn, by \cite{Guest} we also know that the inclusion $M_{\alpha,*} \to \Top_{*}(\mathbb{P}^{1},Y)_{\alpha}$ induces an equality of homology groups in some range.  By combining these two statements we obtain \cref{theo:torichomequiv}.

\subsection{Set-up}

We identify $\mathbb{P}^{1} \times \mathbb{P}^{1} \cong \mathbb{P}(V_{1}) \times \mathbb{P}(V_{2})$ for rank $2$ vector spaces $V_{1},V_{2}$.  For $j=1,2$ we let $\ell_{1,j}, \ell_{2,j}$ denote respectively the lines corresponding to the points $0, \infty$ in $\mathbb{P}(V_{j})$.  Letting $V = V_{1} \oplus V_{2}$, we define the $k$-poscheme
\begin{equation*}
Q' = \{ V, V_1 \oplus \{0\}, \{0\} \oplus V_2\}\cup\{\ell_{i,1} \oplus \ell_{i,2}, \ell_{i,1} \oplus \ell_{3-i,2}, \ell_{i, 1} \oplus \{0\}, \{0\} \oplus \ell_{i, 2}, 0\}_{i \in \{1,2\}}.
\end{equation*}




\subsection{Rational curves on the degree $4$ toric surface over $\mathbb P^1 \times \mathbb P^1$}

Recall that we realize our degree $4$ toric surface $Y$ as a blow-up
\[
\rho : Y \to \mathbb P^1 \times \mathbb P^1.
\]
Let $E_{i, j}$ be the exceptional divisor of $\rho$ at $(p_i, p_j')$ for  $(i, j = 1, 2)$ and $F, F'$ be general fibers of the two conic fibrations coming from $\mathbb P^1 \times \mathbb P^1$. Also recall that for any nef class $\alpha \in \Nef_1(Y)$, we define
\[
a(\alpha) = F.\alpha, \quad a'(\alpha) = F'. \alpha, \quad k_{i, j}(\alpha) = E_{i, j}.\alpha,
\]
for $i, j = 1, 2$.
Note that being nef is equivalent to require all of 
\[
a -k_{i, 1} - k_{i, 2}, a' - k_{1, j} - k_{2, j}, k_{i, j} \qquad (i, j = 1, 2)
\]
are non-negative.

We define $U_{\mathbf{k},*}$ and $Z_{a, \mathbf{k}, *}^{\circ}$ as in \cref{sect:pointedmorzak}.  Using the discussions in \cref{sec:curvesandconicbundle}, one can prove the following propositions:

\begin{prop}
Assume that $2a > \sum k_{i, j}$ and $2a' > \sum k_{i, j}$.  Then the composition
\[
 \phi_{a, \mathbf{k}, *} \circ\psi_{\alpha, *}: M_{\alpha, *} \to Z_{a, \mathbf{k}, *}^{\circ} \to U_{\mathbf{k}, *}.
\]
is smooth, and its restriction over $\phi_{a, \mathbf{k}, *}\circ\psi_{\alpha, *} (M_{\alpha, *} )$ is a Zariski open subset of a bundle of the product $\mathbb P^{2a -\sum k_{i, j}} \times \mathbb P^{2a' - \sum k_{i, j}}$ over $\phi_{a, \mathbf{k}, *}(\psi_{\alpha, *} (M_{\alpha, *} ))$.
\end{prop}


\begin{prop}
\label{prop:dimensionestimatepointed_toric}
Assume that $2a > \sum k_{i, j}$ and $2a' > \sum k_{i, j}$.  Consider the composition
\[
 \phi_{a, \mathbf{k}, *}\circ\psi_{\alpha, *}  : M_{\alpha, *} \to Z_{a, \mathbf{k}, *}^{\circ} \to U_{\mathbf{k}, *}.
\]
Then the dimension of $U_{\mathbf{k}, *} \setminus  \phi_{a, \mathbf{k}, *}\circ\psi_{\alpha, *} (M_{\alpha, *})$ is at most 
\[
\max\left\{\sum_{i, j = 1, 2} 2k_{i, j} - 2a, \sum_{i, j = 1, 2} 2k_{i, j} - 2a' \right\}.
\]
\end{prop}




\subsection{Homological stability and the space of positive continuous maps}

\subsubsection{Semi-topological models and the spaces of positive maps.}

Here we follow the discussion of \cref{sec:CJS}. We work over $\mathbb C$. For $a, a', \mathbf{k}$ as before, we define the space of rational curves $M_{a, a', \mathbf{k}}$ and its torsor $\widetilde{M}_{a, a', \mathbf{k}}$. One can also define their semi-topological models $\mathcal M_{a, a', \mathbf{k}}$ and $\widetilde{\mathcal M}_{a, a', \mathbf{k}}$ as \cref{sec:CJS}. Then \cref{theo:algebraicvssemitopological,theo:semitopologicalvstopological} are valid in this settings of the toric surface $Y$ and their proofs are exactly the same. We do not repeat these in this section.

\subsubsection{A proof of \cref{theo:torichomequiv}}

Let $a, a', \mathbf{k}$ be non-negative integers such that
\[
a -k_{i, 1} - k_{i, 2} > 0, \, a' - k_{1, i} - k_{2, i} > 0, k_{i, j} > 0,
\]
for $i, j = 1, 2$.
We define $I \in \mathbb N$ by
\[
I=   \frac{1}{8} \min\left\{2a -\sum_{i, j}k_{i, j},  2a' -\sum_{i, j}k_{i, j}\right\} - \frac{1}{2}.
\]
Define
\[
E(w < x) := 4m_0(x)  +3 \sum_{i, j} m_{\ell_{i, j}}(x) + 2\sum_j m_{V_j}(x) +2\sum_{i, j} m_{\ell_{i, 1} \oplus \ell_{j, 2}}(x) - 2\sum_{i, j} k_{i, j}
\]
and let $P \subset (U_{\mathbf{k}, *} < \overline{R})$ be the subposet consisting of $w < x$ such that $E(w < x) \leq 2I$.
Repeating the argument for \cref{lemm:Eproper}, we see that $P$ is proper over $U_{\mathbf{k}}$:
\begin{lemm}
\label{lemm:Eproper_toric}
For any positive constant $\mathfrak{T}$ the set of $x \in \mathrm{Hilb}(B)^Q$ such that $4m_0(x)  +3 \sum_{i, j} m_{\ell_{i, j}}(x) + 2\sum_j m_{V_j}(x) + 2\sum_{i, j} m_{\ell_{i, 1} \oplus \ell_{j, 2}}(x)\ \leq \mathfrak{T}$ is closed and downward closed.
\end{lemm}
%\begin{proof}
%One may argue as in \cref{lemm:Eproper}.
%\end{proof}

Let $M_{a, a', \mathbf{k}, *}$ be the space of pointed rational curves of class $(a, a', \mathbf{k})$ on $Y$.
Then we have a natural projection
\[
M_{a, a', \mathbf{k}, *} \to U_{\mathbf{k}, *}
\]
Let $F_1 \subset U_{\mathbf{k}}$ be the complement of the image of the above projection.
It follows from \cref{prop:dimensionestimatepointed_toric} that the real codimension of $F_1$ is greater than $16I$.

Let $(w < x)$ be an element of $P$ and $w < y$ be a essential pair such that $x \prec y$.
Let us consider the space
\[
\Gamma(B, \mathcal O(a)\otimes V_1 \oplus \mathcal O(a')\otimes V_2)_y.
\]
We define
\begin{align*}
a_y & = a- m_0(y) - m_{V_2}(y) - \sum_{i = 1}^2m_{\ell_{i, 2}}(y) \\
 a'_y &= a- m_0(y) - m_{V_1}(y) - \sum_{i = 1}^2m_{\ell_{i, 1}}(y) \\
 k_{y, i, 1} & = m_{\ell_{i, 1}}(y) + m_{\ell_{i, 1} \oplus \ell_{1, 2}}(y) +m_{\ell_{i, 1} \oplus \ell_{2, 2}}(y)\\
  k_{y, i, 2} & = m_{\ell_{i, 2}}(y) + m_{\ell_{1, 1} \oplus \ell_{i, 2}}(y) +m_{\ell_{2, 1} \oplus \ell_{i, 2}}(y)\\
y_j(\ell_{i, 1}) & =  \left(\sum_{c \in B} (m_{\ell_{i, 1}}(f_{y, c}) + m_{\ell_{i, 1} \oplus \ell_{1, 2}}(f_{y, c}) + m_{\ell_{i, 1} \oplus \ell_{2, 2}}(f_{y, c}))[c] \right)_i\\
y_j(\ell_{i, 2}) & =  \left(\sum_{c \in B} (m_{\ell_{i, 2}}(f_{y, c}) + m_{\ell_{1, 1} \oplus \ell_{i, 2}}(f_{y, c}) + m_{\ell_{2, 1} \oplus \ell_{i, 2}}(f_{y, c}))[c] \right)_i.
\end{align*}
Then the above space can be identified with
\[
\Gamma(B, \mathcal O(a_y)\otimes V_1)_{y_1}\oplus \Gamma(B, \mathcal O(a'_y)\otimes V_2)_{y_2}.
\]
We consider 
\[
E_j(w < y) = 2m_0(y) + 2m_{V_{j'}}(y) +2 \sum_{i = 1}^2 m_{\ell_{i, j'}}(y) + \sum_{i = 1}^2 k_{y, i, j} - \sum_{i, j= 1}^2 k_{i, j}
\]
where $\{j, j'\} = \{1, 2\}$. Then since this is monotone increasing with respect to $y$ we have $E_1(w < y) \geq 0$ and $E_2(w < y)\geq 0$. Moreover we have $E = E_1 + E_2$. Thus we have $E_j \leq 2I + 2$. This implies
\[
2a_y - \sum_{i = 1}^2 k_{y, i, 1}  \geq 6I+2, \qquad
2a'_y - \sum_{i = 1}^2 k_{y, i, 2} \geq 6I+2.
\]
The space $\Gamma(B, \mathcal O(a_y)\otimes V_1)_{y_1}$ is unobstructed if $y_1$ is contained in the image of 
\[
Z_{a_y, \mathbf{k}_{y, 1}}^\circ \to U_{\mathbf{k}_{y,1}}.
\]
Then the complement of the image has dimension at most $\sum_{i = 1}^2k_{y_1, i, 1} -6I-2$. Thus the dimension of the set $w$ such that $w < y$ where $y$ corresponds to a point $y_{1}$ in the complement of the image of $Z_{a_y, \mathbf{k}_{y, 1}}^\circ \to U_{\mathbf{k}_{y,1}}$ is at most
%the loci of the corresponding $w$ such that $w < y$ has dimension at most
\[
m_0(y) + m_{V_1}(y) + m_{V_2}(y) +  \sum_{i = 1}^2m_{\ell_{i, 2}}(y) + \sum_{i = 1}^2k_{y, i, 1} -6I-2 \leq \sum k_i - 4I.
\]
Let $F_2$ be the union of closures of such loci while $T$ runs over all combinatorial types we consider. Note that the real codimension of $F_2$ in $U_{\mathbf{k}}$ is greater than or equal to $8I$.
Similarly we construct $F_3$ for the space $\Gamma(B, \mathcal O(a'_y)\otimes V_2)_{y_2}$.
Let $F = F_1 \cup F_2 \cup F_3$. 

Next we analyze $\kappa(T)$ in our situation.
It follows from our definition that we have
\[
2\gamma(T) = 8m_0(T) + 6 \sum_{i, j} m_{\ell_{i, j}(T)} + 4\sum_j m_{V_j}(T) + 4\sum_{i, j} m_{\ell_{i, 1} \oplus \ell_{j, 2}}(T), 
\]
and
\[
\mathrm{rank}(T) = 3m_0(T) + 2 \sum_{i, j} m_{\ell_{i, j}}(T) + \sum_j m_{V_j}(T) + \sum_{i, j} m_{\ell_{i, 1} \oplus \ell_{j, 2}}(T).
\]
Thus we have
\[
\kappa(T) = 5m_0(T) + 4 \sum_{i, j} m_{\ell_{i, j}}(T) + 3\sum_j m_{V_j}(T) + 3\sum_{i, j} m_{\ell_{i, 1} \oplus \ell_{j, 2}}(T) - 2|\mathrm{Supp}(T)|.
\]
Using this one can prove that when we have $x_1 \prec x_2$, we have $\kappa(x_2) \geq \kappa(x_1) + 1$. This shows that $\kappa(T) \geq \mathrm{rank}(T)$. 
Thus we have $E(T) \leq 2\kappa (T)$. Thus by applying versions of \cref{theo:algebraicvssemitopological,theo:semitopologicalvstopological} for $Y$ we conclude the following theorem:
\begin{theo}
\label{theo:maintoric}
Let $B = \mathbb P^1$ and $Y$ be the toric surface of degree $4$.
We fix an integral nef class $\alpha$ on $S$.
Suppose that we have a birational morphism $\beta : S \to \mathbb P^1 \times \mathbb P^1$ satisfying
\[
2a -\sum_{i, j}k_{i, j} > 0, \, 2a' -\sum_{i, j}k_{i, j} > 0.
\]
We define $I \in \mathbb N$ by
\[
I = \frac{1}{8} \min\left\{2a -\sum_{i, j}k_{i, j},  2a' -\sum_{i, j}k_{i, j}\right\} -\frac{1}{2}.
\]
Then $M_{\alpha, *} \hookrightarrow \mathrm{Top}^+_*(B, S)_{\alpha}$ is homology $\lfloor I \rfloor$-connected.
\end{theo}

Here we record one proposition:

\begin{prop}[{\cite[Proof of Corollary 1.2]{DT24}}] \label{prop:alphainvariance}
Let $X$ be a smooth projective variety, let $\{ E_{i} \}$ be a finite set of disjoint smooth divisors on $X$, and let $\eta: S^{2} \to X$ denote a pointed curve such that $\eta(S^{2}) \cap E_{i} = \emptyset$ for every $i$ and $\eta$ sends at least two points to the basepoint of $X$.

Let $s: C \to X$ be a pointed continuous map.  Suppose we fix a disc around the basepoint $*_{C}$ and let $\pi: C \to S^{2} \vee C$ denote the contraction of the boundary of the disc.  Then the stabilization morphism $s \mapsto (\eta \vee s) \circ \pi$ defines homotopy equivalences
\begin{align*}
\Top^{+}_{*}(C,X)_{\alpha} & \xrightarrow{\eta \vee} \Top^{+}_{*}(C,X)_{\alpha + \eta_{*}\mathbb{P}^{1}} \\
\Top_{*}(C,X)_{\alpha} & \xrightarrow{\eta \vee} \Top_{*}(C,X)_{\alpha + \eta_{*}\mathbb{P}^{1}}
\end{align*}
\end{prop}



\begin{proof}
We can think of $\eta$ as a homotopy from the constant map $S^{1} \to *_{X}$ to itself.  Let $\bar{\eta}$ denote the reversed homotopy, also considered as a map $\bar{\eta}: S^{2} \to X  - (\cup_{i} E_{i})$.  Then the map $\vee \bar{\eta}$ defines a homotopy inverse to $\vee \eta$, since the map
\begin{equation*}
S^{2}  \to S^{2} \vee S^{2} \xrightarrow{\eta \vee \bar{\eta}} X - (\cup_{i} E_{i})
\end{equation*}
is null-homotopic.
\end{proof}


Now we prove our main theorem of this section.

\begin{proof}[Proof of \cref{theo:torichomequiv}]
Let $J = \min\{ k_{i, j}, a -k_{i, 1} - k_{i, 2}, a' - k_{1, j} - k_{2, j}\}$.
By \cite[Theorem 4.1]{Guest}, for any $i \leq J$, we have an isomorphism
\[
H_i^{\mathrm{sing}}(M_{\alpha, *}, \mathbb Z) \cong H_i^{\mathrm{sing}}(\mathrm{Top}_*(B, S)_{\alpha})
\]
which is induced by the inclusion $M_{\alpha, *} \hookrightarrow \mathrm{Top}_*(B, S)_{\alpha}$.
Thus if we let
\[
\ell(\alpha) = \min\{\lfloor I \rfloor -1, J \},
\]
then the inclusion $\mathrm{Top}^+_*(B, S)_{\alpha} \hookrightarrow \mathrm{Top}_*(B, S)_{\alpha}$
is homology isomorphic up to degree $\ell(\alpha)$.
However, by \cref{prop:alphainvariance}, the homotopy types of $\mathrm{Top}^+_*(B, S)_{\alpha}$ and $\mathrm{Top}_*(B, S)_{\alpha}$ do not depend on $a, a'$. If we fix $\{ k_{i,j} \}$ and make $a,a'$ sufficiently large then $\ell(\alpha) = \min\{ k_{i,j} \}$ and our assertion follows.
\end{proof}



