\section{Betti number bounds for the moduli space of maps from a rational curve}
 \label{appendixSS}

\smallskip
\begin{center} \textsc{Will Sawin, \ Mark Shusterman\footnote{The Dr. A. Edward Friedmann Career Development Chair in Mathematics}} \end{center}
\medskip


Let $k$ be a separably closed field. Let $X$ be a projective variety over $k$. Fix a very ample line bundle $L$ on $X$. Say a map $g\colon \mathbb P^1 \to X$ has degree $e$ if the pullback of $L$ to $\mathbb P^1$ by $g$ has degree $e$. Let $\Mor(\mathbb P^1,X)$ be the moduli space parameterizing morphisms of degree $e$ from $\mathbb P^1$ to $X$. The goal of this appendix is to prove the following theorem.

\begin{theo}\label{appendix-main} There exists a constant $C$ such that, for $\ell$ a prime invertible in $k$, we have
\[ \sum_{i=0}^\infty \dim H^i_c ( \Mor(\mathbb P^1, X), \mathbb Q_\ell) \leq C^{e+1}.\]
The constant $C$ depends only on $\dim H^0(X, L)$ and the self-intersection $c_1(L)^{\dim X}$. \end{theo}

To prove this, we will use Betti number bounds of Katz for the compactly supported cohomology of intersections of hypersurfaces in affine space. We are faced with the difficulty that $\Mor(\mathbb P^1, X)$ is not usually an intersection of hypersurfaces in affine space. We will replace $\Mor(\mathbb P^1, X)$ by an intersection of hypersurfaces in affine space in two steps: First defining an affine space bundle $\tMor(\mathbb P^1, X)$ on $\Mor(\mathbb P^1, X)$ and then a stratification of $\tMor(\mathbb P^1, X)$ into strata $\tMor^j(\mathbb P^1, X)$, which will be intersections of hypersurfaces in affine space. It is possible to control the way Betti numbers change under these operations, leading to a Betti number bound for $\Mor(\mathbb P^1, X)$.

 First, observe that $L$ defines an embedding $X \to \mathbb P^n$ for the natural number 
 \[
 n = \dim H^0(X,L)-1.
 \]

\begin{lemm}\label{bounded-polynomial-degree} Inside $\mathbb P^n$, $X$ is the vanishing locus of some homogeneous polynomials $f_1,\dotsc,f_r$ of degrees $d_1,\dotsc,d_r$ in $n+1$ variables, with $d_1\leq \dotsb \leq d_r$, such that $r$ and $d_r$ are bounded in terms of $\dim H^0(X,L)$ and $c_1(L)^{\dim X}$. 
\end{lemm}
\begin{proof}Inside $\mathbb P^n$,  $X$ is a closed subscheme of degree $c_1(L)^{\dim X}$. Being a closed subscheme, it is the vanishing locus of some homogeneous polynomials. By changing the order of these polynomials, we may assume their degrees are nondecreasing. Using the Chow variety, one sees that all smooth closed $X \subseteq \mathbb P^n$ of degree $c_1(L)^{\dim X}$ are parameterized by a scheme of finite type. One can see that the number $r$ of polynomials defining $X$ and the degrees $d_1,\dotsc, d_r$ of these polynomials are bounded only in terms of $\dim H^0(X, L)$ and the self-intersection $c_1(L)^{\dim X}$ by a Noetherian induction argument over this scheme.
\end{proof}

By Lemma \ref{bounded-polynomial-degree}, it suffices to prove Theorem \ref{appendix-main} where the constant $C$ depends only on $n$ and $d_r$.

We view $\mathbb P^{(n+1)(e+1)-1}$ as the space parameterizing $n+1$-tuples of polynomials $g_0,\dotsc, g_n$ of degree $\leq e$ in the variable $T$, not all $0$, up to scalar multiplication of all polynomials. Here the coordinates of $\mathbb P^{(n+1)(e+1)-1}$ are the coefficients of the polynomials.
\begin{lemm}\label{mor-coordinates} $\Mor(\mathbb P^1, X)$ is isomorphic to the locally closed subscheme of $\mathbb P^{(n+1)(e+1)-1}$ consisting of tuples of polynomials $g_0,\dotsc,g_n$ such that  $f_i(g_0,\dotsc,g_n)=0$ for $i$ from $1$ to $r$, at least one of $g_0,\dotsc, g_n$ has degree $e$, and $g_0,\dotsc, g_n$ share no common factors.  \end{lemm}
\begin{proof} We first construct the map $\Mor(\mathbb P^1,X) \to \mathbb P^{(n+1)(e+1)-1}$.  For  $g \colon \mathbb P^1 \to X$ of degree $e$, the pullback $g^* L$ is necessarily isomorphic to $\mathcal O_{\mathbb P^1}(e)$.  If we fix an isomorphism $g^* L \cong \mathcal O_{\mathbb P^1}(e)$ we obtain a linear map $H^0( X, L) \to H^0( \mathbb P^1, \mathcal O_{\mathbb P^1}(e))$.

Choosing a basis for $H^0( X, L)$, we obtain $n+1$ elements of $H^0( \mathbb P^1, \mathcal O_{\mathbb P^1}(e))$, which cannot all be zero. We can express $H^0( \mathbb P^1, \mathcal O_{\mathbb P^1}(e))$ as the space of polynomials of degree $\leq e$ in one variable $T$ (for example, by first expressing $H^0( \mathbb P^1, \mathcal O_{\mathbb P^1}(e))$  as the space of homogeneous polynomials of degree $e$ in two variables $u,v$ and then sending $u$ to $1$ and $v$ to $T$). This gives a tuple $g_0,\dotsc, g_n$ of polynomials of degree $\leq e$. Varying the isomorphism $g^* L \cong \mathcal O_{\mathbb P^1}(e)$ acts by scalar multiplication on this tuple of polynomials, so the resulting point of $\mathbb P^{(n+1)(e+1)-1}$ is well-defined.

Since the tuple $g_0,\dotsc,g_n$ determines the map $g$, this map is an immersion.



%There is a locally closed embedding $\Mor(\mathbb P^1, X) \to \mathbb P^{(n+1) (e+1)-1}$. To construct this embedding, observe that for $g \colon \mathbb P^1 \to X$ of degree $e$, the pullback $g^* L$ is necessarily isomorphic to $\mathcal O_{\mathbb P^1}(e)$. If we fix an isomorphism $g^* L \cong \mathcal O_{\mathbb P^1}(e)$ we obtain a linear map $H^0( X, L) \to H^0( \mathbb P^1, \mathcal O_{\mathbb P^1}(e))$, which is a map from an $n+1$-dimensional vector space to an $e+1$-dimensional vector space, and thus can be expressed as an $(n+1)\times (e+1)$ matrix, which is never identically zero. Varying the isomorphism $f^* L \cong \mathcal O_{\mathbb P^1}(e)$ acts by scalar multiplication on this matrix, so that the entires of the matrix define a map $\Mor(\mathbb P^1, X) \to \mathbb P^{(n+1) (e+1)-1}$.

%It is more convenient to fix a basis for $H^0(X,L)$ and express $H^0( \mathbb P^1, \mathcal O_{\mathbb P^1}(e))$ as the space of polynomials of degree $e$ in a $T$. A map $g\colon \mathbb P^1 \to X$ then defines a tuple $g_0,\dotsc, g_n$ of polynomials of degree $\leq e$ in $T$, given by the coordinates of this map, well-defined up to multiplying all the polynomials by the same constant, and hence a point in $\mathbb P^{(n+1) (e+1)-1}$. It is straightforward to check that the tuple $g_0,\dotsc, g_n$ determines $g$ and so this map is an immersion.

Finally, the image of $\Mor(\mathbb P^1, X) $ inside $ \mathbb P^{(n+1) (e+1)-1}$ consists of tuples of polynomials such that $f_i(g_0,\dotsc,g_n)=0$ for $i$ from $1$ to $r$, at least one of $g_0,\dotsc, g_n$ has degree $e$, and $g_0,\dotsc, g_n$ share no common factors. Indeed the conditions that at least one of $g_0,\dotsc,g_n$ has degree $e$ and $g_0,\dotsc,g_n$ share no common factors are necessary and sufficient for $g_0,\dotsc, g_n$ to define a map $\mathbb P^1 \to \mathbb P^n$ of degree $e$, and this map has image in $X$ if and only if $g_0,\dotsc,g_n$ satisfy the equations of definition $f_1,\dotsc, f_r$ of $X$. \end{proof}



We now define a space $\tMor(\mathbb P^1,X)$, which will be a subscheme of 
\begin{equation} \label{QuotientScheme}
\left ( \left(\mathbb A^{(n+1)(e+1)}- \{0\} \right) \times \mathbb A^{(n+1) e} \right)/\mathbb G_m. 
\end{equation}
We think of $\mathbb A^{(n+1)(e+1)}$ as parameterizing tuples  $g_0,\dotsc, g_n$ of polynomials of degree $\leq e$ in $T$. We think of $\mathbb A^{(n+1)e}$ as parameterizing tuples $h_0,\dotsc, h_n$ of polynomials of degree $\leq e-1$ in $T$. We let $\mathbb G_m$ act by multiplication on the coordinates of $\mathbb A^{(n+1)(e+1)}$ and inverse multiplication on the coordinates of $\mathbb A^{(n+1)e}$, in other words by scalar multiplication on $g_0,\dotsc, g_n$ and inverse scalar multiplication on $h_0,\dotsc,h_n$.

We define $\tMor(\mathbb P^1,X)$ as the locally closed subscheme of \ref{QuotientScheme} defined by the equations $f_i( g_0,\dotsc,g_n)=0$ for $i=1,\dotsc, r$, the equation $\sum_{j=0}^n g_i h_i=1$, and the condition that at least one of the $g_i$ has degree exactly $e$. Observe that the first two conditions are closed and the last condition is open.  The fact that the $f_i$ are homogeneous means that the first condition is invariant under the $\mathbb G_m$ action, and the fact that $\sum_{j=0}^n g_j h_j=1$ has each $g_j$ appearing multiplied by an $h_j$ means that the second condition is invariant under the $\mathbb G_m$ action.

Note that the conditions defining $\tMor(\mathbb P^1,X)$ already imply that $g_0,\dotsc,g_n$ are not all zero. The only reason we use $\mathbb A^{(n+1)(e+1)}- \{0\} $ instead of $\mathbb A^{(n+1)(e+1)}$ in the definition is to express $\tMor(\mathbb P^1,X)$ as a subscheme of a scheme and not a substack, that happens to also be a scheme, of a stack.

\begin{lemm}\label{map-exists} 
There exists a map $\tMor(\mathbb P^1, X)\to \Mor(\mathbb P^1, X)$ given by 
\[
((g_0,\dotsc,g_n),(h_0,\dotsc,h_n)) \mapsto (g_0,\dotsc,g_n).
\] 
\end{lemm}
\begin{proof}It suffices to check that if $g_0,\dotsc,g_n, h_0,\dotsc,h_n$ satisfy the conditions of $\tMor(\mathbb P^1, X)$ then $g_0,\dotsc,g_n$ satisfy the conditions of $ \Mor(\mathbb P^1, X)$. The only condition for which this is not immediate is the condition that $g_0,\dotsc,g_n$ have no common factors, but the  condition  $\sum_{j=0}^n g_j h_j=1$ ensures that $g_0,\dotsc,g_n$ have no common factors. \end{proof}

We say a map $Z \to Y$ is an affine space bundle of relative dimension $d$ if it is locally in the Zariski topology on $Y$ isomorphic to $\mathbb A^d\times Z \to Z$, with transition maps affine transformations.

We will check that the map of Lemma \ref{map-exists} is an affine space bundle of relative dimension $(n-1)e$, using a series of lemmas. We first explain the utility of affine space bundles to us, by the following lemma.

\begin{lemm}\label{affine-bundle-cohomology} Let $\pi \colon Z \to Y$ be an affine space bundle of relative dimension $d$. Then we have $H^i_c ( Y, \mathbb Q_\ell) = H^{i+2d}_c(Z,\mathbb Q_\ell(d))$ for all $i$. \end{lemm}
\begin{proof} We have a natural trace map $R \pi_! \mathbb Q_\ell \to \mathbb Q_\ell [ -2d](d)$. We can check that this map is an isomorphism locally, which reduces to the case that $Z = \mathbb A^d \times Y$, where proper base change reduces us to the case that $Y$ is a point, which is just the computation of compactly supported cohomology of affine space. This isomorphism together with the Leray spectral sequence with compact supports gives $H^i_c ( Y, \mathbb Q_\ell) = H^{i+2d}_c(Z,\mathbb Q_\ell(d))$. \end{proof}



Let $\hMor(\mathbb P^1,X)$ be the subset of \ref{QuotientScheme} consisting of points satisfying the conditions that $f_i(g_0,\dotsc,g_n)=0$ for $i$ from $1$ to $r$, at least one of $g_0,\dotsc, g_n$ has degree $e$, and $g_0,\dotsc, g_n$ share no common factors.

\begin{lemm}\label{easier-map-bundle} The map $\hMor(\mathbb P^1,X)\to \Mor(\mathbb P^1,X)$ sending $((g_0,\dotsc,g_n),(h_0,\dotsc,h_n))$ to $(g_0,\dotsc,g_n)$ is an affine space bundle of relative dimension $(n+1)e$. \end{lemm}

\begin{proof} Over the intersection of $\Mor(\mathbb P^1,X)$ with any standard affine open in $\mathbb P^{(n+1) (e+1)-1}$, the space $\hMor(\mathbb P^1,X)$ becomes isomorphic to $\mathbb A^{(n+1)e}  \times \Mor(\mathbb P^1,X)$ via the coordinates $h_0,\dotsc,h_n$, and the change of coordinates is given by scalar multiplication which is an affine transformation. \end{proof}

\begin{lemm}\label{inverse-image-affine} Let $Y$ be a scheme, $Z$ an affine space bundle on $Y$ of relative dimension $a$, and $Z'$ an affine space bundle on $Y$ of relative dimension $b$. Let $q \colon Z\to Z'$ a map over $Y$ and $s$ a section of $Z'$. If the map $q$ is fiberwise surjective then  $q^{-1}(s)$ is an affine space bundle on $Y$ of relative dimension $a-b$.\end{lemm}

\begin{proof} Working locally, we may assume $Z= \mathbb A^a \times Y$ and $Z'= \mathbb A^b\times Y$, so the map $q$ is given by an $ a\times b$ matrix together with an additional $1\times b$ vector giving the translation. Fiberwise surjectivity at a point is witnessed by the nonvanishing of one of the $b\times b$ minors of the matrix. Over an open neighborhood of that point where the same $b\times b$ minor is nonvanishing, we can use the $a-b$ coordinates not appearing in the minor as coordinates for $q^{-1}(s)$, giving an isomorphism of $q^{-1}(s)$ to affine space. The remaining coordinates are given by affine functions of these coordinates, showing that the transition maps are affine.\end{proof}


\begin{lemm}\label{map-is-bundle} The map $\tMor(\mathbb P^1, X)\to \Mor(\mathbb P^1, X)$ of Lemma \ref{map-exists} is an affine space bundle of relative dimension $(n-1)e$. \end{lemm}

\begin{proof} View $\mathbb A^{2e}$ as the space parameterizing polynomials of degree $\leq 2e-1$. There is a map 
\[
q \colon \hMor(\mathbb P^1 ,X) \to  \mathbb A^{2e} \times \Mor(\mathbb P^1,X)
\]
given by
\[ 
q((g_0,\dotsc,g_n),(h_0,\dotsc,h_n)) = \left(\sum_{j=0}^n g_j h_j, (g_0,\dotsc,g_n)\right).  
\]


Since $\tMor(\mathbb P^1,X)$ is by definition the inverse image of the section $1$ under this map, by Lemmas \ref{easier-map-bundle} and \ref{inverse-image-affine} it suffices to check that $q$ is fiberwise surjective.

For this purpose, fix a tuple of polynomials $g_0,\dotsc,g_n$, one of degree $e$, with no common factors.  

Choose $j_0$ such that $g_{j_0}$ has degree exactly $e$. Then all polynomials of degree $\leq 2e - 1$ that are multiples of $g_{j_0}$ have the form $g_{j_0} h$ for $h$ of degree $\leq e-1$. Since $g_0,\dotsc, g_n$ have no common factors, every polynomial may be written as $\sum_{j=0}^n g_j h_j$ for some $h_j$, not necessarily of degree $\leq e-1$. The image of $\sum_{j=0}^n g_j h_j$ in $k[T]/g_{j_0}$ is determined only by $h_j$ mod $g_{j_0}$. We may replace $h_j$ by a polynomial of degree $<e$ with the same residue mod $g_{j_0}$ by long division with remainder. It follows that every polynomial is congruent mod $g_{j_0}$ to a polynomial of the form  $\sum_{j=0}^n g_j h_j$ for some $h_j$ of degree $\leq e-1$. If the original polynomial has degree $2e-1$, the difference between that polynomial and $\sum_{j=0}^n g_j h_j$ is a multiple of $g_{j_0}$ of degree $\leq 2e-1$, hence of the form $g_{j_0} h$ for some $h$ of degree $\leq e-1$, and subtracting $h$ from $h_{j_0}$ gives the needed $h_0,\dotsc, h_n$ to check surjectivity. \end{proof}


Using Lemmas \ref{affine-bundle-cohomology} and \ref{map-is-bundle}, we will reduce to bounding the cohomology  of $\tMor(\mathbb P^1,X)$. 


To do this, we will further stratify $\tMor(\mathbb P^1,X)$.

Let $\tMor^j(\mathbb P^1,X)$ be the subset of $\tMor(\mathbb P^1,X)$ consisting of tuples $(g_0,\dotsc,g_n),(h_0,\dotsc,h_n)$ where $g_0,\dotsc, g_{j-1}$ have degree $<e$ and $g_j$ has degree exactly $e$. The union of $\tMor^j(\mathbb P^1,X)$ for $j$ from $m$ to $n+1$ is a closed subset of $\tMor(\mathbb P^1,X)$ for each $m$, so this indeed gives a stratification.

\begin{lemm}\label{stratification-bound}
We have
\[ \sum_{i=0}^\infty \dim H^i_c ( \tMor(\mathbb P^1,X), \mathbb Q_\ell)  \leq  \sum_{j=0}^n \sum_{i=0}^\infty \dim H^i_c ( \tMor^j(\mathbb P^1,X), \mathbb Q_\ell). \] \end{lemm}
\begin{proof} This follows immediately from the spectral sequence associated to the stratification of $\tMor(\mathbb P^1,X)$ into $\tMor^j(\mathbb P^1,X)$. In other words, this is the spectral sequence associated to the filtration of  $H^i_c ( \tMor(\mathbb P^1,X), \mathbb Q_\ell) $ into $H^i_c ( \bigcup_{j=m}^n \tMor^j (\mathbb P^1,X), \mathbb Q_\ell) $ whose associated graded is calculated using the excision long exact sequence. \end{proof}

\begin{lemm}\label{is-complete-intersection} $\tMor^j(\mathbb P^1,X)$ is isomorphic to the vanishing locus in $\mathbb A^{ (n+1)(2e+1)-1-j}$ of 
\[
2e+ \sum_{i=1}^r (d_i e+1)
\]
equations of degree $\leq \max(d_r,2)$. \end{lemm}

\begin{proof} Each point of $\tMor^j(\mathbb P^1,X)$ corresponds to an orbit of tuples $g_0,\dotsc, g_n, h_0,\dotsc,h_n$ under the $\mathbb G_m$-action, but since by definition of $\tMor^j(\mathbb P^1,X)$ the coefficient of $T^e$ in $g_j$ is nonzero, this orbit has a unique member where the coefficient of $T^e$ in $g_j$ is $1$. We can thus express a point of $\tMor^j(\mathbb P^1,X)$ using coordinates the coefficients of the polynomials $g_0,\dotsc, g_n, h_0,\dotsc, h_n$, except that we do not need to include the coefficients of $T^e$ in $g_0,\dotsc, g_{j-1}$ (as these are always $0$) or the coefficient of $T^e$ in $g_j$ (as this is always $1$). This gives an embedding of $\tMor^j(\mathbb P^1,X)$ into $\mathbb A^{ (n+1) (e+1)-1-j + (n+1)e}$. Inside $\mathbb A^{ (n+1) (e+1)-1-j + (n+1)e}$, $\tMor^j(\mathbb P^1,X)$ is defined by the conditions that $f_i(g_0,\dotsc,g_n)=0$ for $i$ from $1$ to $r$ and that $\sum_{j=0}^n g_j h_j=1$. These are both closed conditions.

More precisely, the condition that $f_i(g_0,\dotsc, g_n)=0$ may be expressed as $d_i e +1 $ equations in the coefficients of $g_0,\dotsc,g_n$ of degree $\leq d_i$, since $f_i(g_0,\dotsc,g_n)$ is a polynomial of degree $\leq d_i e$ and each of its coefficients is a polynomial of degree $\leq d_i$ in the coefficients of $g_0,\dotsc,g_n$ which must be set to $0$. Similarly, the condition that $\sum_{j=0}^n g_j h_j=1$ may be expressed as $2e$ equations in the coefficients of $g_0,\dotsc, g_n, h_0,\dotsc,h_n$ of degree $\leq 2$, since $\sum_{j=0}^n g_j h_j$ is a polynomial of degree $\leq 2e-1$ and each of its coefficients is a polynomial of degree $\leq 2$ in the coefficients of $g_0,\dotsc, g_n, h_0,\dotsc,h_n$ which must be set to either $0$ or $1$.

Combining these, $\tMor^j(\mathbb P^1,X)$ is the intersection in $\mathbb A^{ (n+1) (e+1)-1-j + (n+1)e} = \mathbb A^{ (n+1)(2e+1)-1-j}$ of  $2e+ \sum_{i=1}^r (d_i e+1)$ equations of degree $\leq \max(d_r,2)$.\end{proof}

\begin{lemm}\label{fundamental-betti-bound}We have \[ \sum_{i=0}^\infty \dim H^i_c ( \tMor^j(\mathbb P^1,X), \mathbb Q_\ell)  \leq 3 (\max(d_r,2)+2)^{ (n+1)(2e+1)-1-j  + 2e+ \sum_{i=1}^r (d_i e+1)}.\] 
\end{lemm}

\begin{proof} This follows from \cite[Theorem 12]{katzbetti}, taking the polynomial $f$ of Katz to vanish, the polynomials $F_1,\dotsc,F_r$ to be the equations defining $\tMor^j(\mathbb P^1,X)$ described by Lemma \ref{is-complete-intersection}, and $s=0$ so that there are no polynomials $G_1,\dotsc,G_s$.  \end{proof}

\begin{prop}\label{TildeBound} We have
\[ \sum_{i=0}^\infty \dim H^i_c( \tMor(\mathbb P^1,X), \mathbb Q_\ell) \leq 4 (\max(d_r,2)+2)^{n +r}  \left( (\max(d_r,2)+2)^{ 2n+4 + \sum_{i=1}^r d_i} \right)^e  .\]
\end{prop}

\begin{proof}By Lemmas \ref{stratification-bound}, and \ref{fundamental-betti-bound}, we have
\begin{equation*}
\begin{split}
\sum_{i=0}^\infty \dim H^i_c( \tMor(\mathbb P^1,X), \mathbb Q_\ell) &\leq   \sum_{j=0}^n \sum_{i=0}^\infty \dim H^i_c ( \tMor^j(\mathbb P^1,X), \mathbb Q_\ell) \\
&\leq \sum_{j=0}^n  3 (\max(d_r,2)+2)^{ (n+1)(2e+1)-1-j  + 2e+ \sum_{i=1}^r (d_i e+1)} \\
&\leq  \sum_{j=0}^\infty 3 (\max(d_r,2)+2)^{ (n+1)(2e+1)-1-j  + 2e+ \sum_{i=1}^r (d_i e+1)} \\
&= \frac{3 }{ 1- (\max(d_r,2)+2)^{-1}} (\max(d_r,2)+2)^{ (n+1)(2e+1)-1  + 2e+ \sum_{i=1}^r (d_i e+1)} \\
&\leq 4 (\max(d_r,2)+2)^{ (n+1)(2e+1)-1  + 2e+ \sum_{i=1}^r (d_i e+1)} \\
&=  4 (\max(d_r,2)+2)^{n +r}  \left( (\max(d_r,2)+2)^{ 2n+4 + \sum_{i=1}^r d_i} \right)^e.
\end{split}
\end{equation*}
 \end{proof}

\begin{proof}[Proof of Theorem \ref{appendix-main}] 
This follows from Lemmas \ref{TildeBound}, \ref{affine-bundle-cohomology}, \ref{map-is-bundle}, and \ref{bounded-polynomial-degree} if we take  
\[
C = \max ( (\max(d_r,2)+2)^{ 2n+4 + \sum_{i=1}^r d_i} ,  4 (\max(d_r,2)+2)^{n +r} ). 
\]
In fact, since $d_1,\dotsc,d_r\geq 1$, the ratio 
\[
\frac{(\max(d_r,2)+2)^{ 2n+4 + \sum_{i=1}^r d_i}}{  4 (\max(d_r,2)+2)^{n +r}}
\]
 is at least 
 \[
 \frac{(\max(d_r,2)+2)^{n+4}}{ 4} \geq \frac{4^5}{ 4} > 1
 \]
 so $(\max(d_r,2)+2)^{ 2n+4 + \sum_{i=1}^r d_i} $ is larger and we can simply take \[C=(\max(d_r,2)+2)^{ 2n+4 + \sum_{i=1}^r d_i} .\qedhere\] \end{proof}

One can try to improve the value of $C$ using ideas from \cite{WanZhang}.

