We denote by $\Lambda$ the vector space of symmetric functions over the fraction field $\QQ(q,t)$ in an alphabet of variables $X:=x_1+x_2+\dotsm$. 
\begin{defi}\label{def:decorated_paths}
	Let $\gamma\in\bR_\beta$ be an alternating
	path. We associate to $\gamma$ the \emph{valley weight}
	\begin{equation}\label{eq:valley_weight_PMAP}
		\vweight_\beta(\gamma)=\prod_{V\in\Valley(\gamma)}(qt)^{\height_\beta(V)},  
	\end{equation}
	the product being taken over the valleys of $\gamma$. We associate to $\gamma$ the linear operator $\mcO(\gamma)\colon \Lambda \rightarrow \Lambda$ as follows:  if $\gamma$ has steps $(\gamma_1,\dots,\gamma_{2l})$ then 
	\begin{equation*}
		\label{eq:decorated_path}
		\mcO_\beta(\gamma):=\vweight_\beta(\gamma)\mcO(\gamma_1)\dots \mcO(\gamma_{2l}),
	\end{equation*}
	where for any integer $m$ we define
	\begin{equation}\label{eq:def_step_operator}
		\mcO(m):=\left\{
		\begin{array}{ll}
			(-1)^me_{m}[X]=h_{m}[-X]   & \text{ if } m>0  \\
			h^\perp_{-m}[MX]   & \text{ if } m<0\\
			1 &\text{ if } m=0,
		\end{array}
		\right.  
	\end{equation}
    	with $M:= (1-q)(1-t)$.
	Finally, we define  
	\begin{equation*}\label{eq:def_path_operators}
		\mcR_{\beta}:=\sum_{\gamma\in\bR_{\beta}}\mcO_\beta\left(\gamma\right).
	\end{equation*}	

\end{defi}
We use a standard notation where square brackets $[\cdot]$ denote the plethystic substitution, the operator $e_{m}$ is to be understood as the multiplication by the symmetric function $e_{m}$, and similarly $h_m^\perp$ denotes the adjoint of the multiplication by $h_m$ with respect to the Hall scalar product; see~\cref{sec:Prelim} for more details.

\begin{rmk}
	\label{rem:remark_path_op}
	Since the set $\bR_{\beta}$ is infinite, it might not be immediately clear that $\mcR_{\beta}\colon \Lambda \rightarrow \Lambda$ is a well-defined endomorphism of $\Lambda$. It is indeed well-defined since for any $f \in \Lambda$ there are only finitely many paths $\gamma \in \bR_{\beta}$ such that $f \notin \ker(\mcO_\beta(\gamma))$. This is a consequence of the property that for any sequence $(\gamma_1,\dots,\gamma_\ell) \in \ZZ^\ell$ such that the partial sum $\sum_{i =j}^\ell \gamma_i$ is smaller than $-m$ for some $1 \leq j \leq \ell$, the operator $\mcO(\gamma_1)\cdots \mcO(\gamma_\ell)$ annihilates the space $\Lambda^i$ of homogeneous symmetric functions of degree $i \leq m$:
	\[  \bigoplus_{i=0}^m \Lambda^i \subset \ker \left( \mcO(\gamma_1)\cdots \mcO(\gamma_\ell)\right).\] 
\end{rmk}

\begin{example}
	The operator associated to the path $\gamma$ of \cref{fig:alternating_path} is given by
	\[\mcO_{(1,-2,1,3)}(\gamma)=(qt)^{1+0+1} \cdot(-1)^{3+0+2+3}e_{3}[X]h^\perp_{1}[MX]h^\perp_{3}[MX]e_{2}[X]e_{3}[X]h^\perp_{1}[MX].\]
\end{example}

\subsection{Product formula in terms of \texorpdfstring{$D$}{D}-operators and connection to the shuffle algebra}

We prove that the path operators $\mcR_\beta$ have a simple expression using the vertex operator algebra (VOA) formalism involving the series $D(z)$ introduced in~\cite{GarsiaHaimanTesler1999}. As a corollary we deduce that the path operators are the images of the so-called Negut elements via a representation of the shuffle algebra acting on the space of symmetric functions. Consequently, we find a new explicit combinatorial formula for this representation of the Negut elements.

We say that a formal expression
\[ F(z) := \sum_{n \in \ZZ}a_n z^{n} \in \End[\Lambda]\llbracket z,z^{-1}\rrbracket\]
is a \emph{field} if for any $f \in \Lambda$, there exists $N$ such that $f \in \ker(a_n)$ for all $n < N$ (see \cite{Kac2017}). It is well-known (one can use a similar reasoning as in \cref{rem:remark_path_op}) that whenever $F_1,\dots,F_\ell$ are fields, then the coefficients of the following Laurent series in $z_1,\dots,z_\ell$ are well-defined endomorphisms of $\Lambda$:
\[ \frac{F_1(z_1) \dotsm F_\ell(z_{\ell})}{\prod_{i=1}^{\ell-1} \bigl(1-z_{i+1}/z_i\bigr)} \in \End[\Lambda]\llbracket z_1,z_1^{-1},\dots,z_\ell,z_\ell^{-1}\rrbracket, \quad \bigl(1-z_{i+1}/z_i\bigr)^{-1} := \sum_{n \geq 0}z_{i+1}^n \cdot z_i^{-n}.\]
We recall (see~\cref{sec:Prelim} for more details) that the field $D(z)$ is defined as follows:
\[ D(z) := \sum_{n \in \ZZ} D_n z^n = \sum_{n\geq 0} (-1)^n e_n[X] z^n \cdot \sum_{n\geq 0} h_n^\perp[(1-q)(1-t)X] z^{-n} = \sum_{n \in \ZZ} \mcR_{(n)} z^n,\]
and it satisfies the following commutation relation:
\begin{equation} \label{CommutationD}
	\omega(z_1/z_2) D(z_1) D(z_2) = \omega(z_2/z_1) D(z_2) D(z_1),
	\quad \omega(x) := \frac{(1-x)(1-qtx)}{(1-qx)(1-tx)}.
\end{equation}
Following this formalism, we prove the following VOA expression for the path operators.
\begin{thm}\label{thm:R_vertex_op}
	Fix $\beta=(\beta_1,\dots,\beta_\ell)\in\ZZ^{\ell}$, then
	\begin{equation}\label{eq:R_vertex_formula}
		\mcR_\beta = [z_1^{\beta_1} \dotsm z_{\ell}^{\beta_{\ell}}] \frac{D(z_1) \dotsm D(z_{\ell})}{\prod_{i=1}^{\ell-1} \bigl(1-qt z_{i+1}/z_i\bigr)}.
	\end{equation}
\end{thm}

The shuffle algebra $S$ \cite{FeiginTsymbaliuk2011,Negut2014} is the graded algebra $S = \oplus_{n\geq 0} S_n$ where $S_0 = \QQ(q,t)$,  and for $n\geq 1$ an element $F$ of $S_n$ is of the form
\begin{equation*}
	F(z_1, \dotsc, z_n) = f(z_1, \dotsc, z_n) \prod_{1\leq i\neq j\leq n} \frac{z_i-z_j}{(z_i-qz_j)(z_i-tz_j)},
\end{equation*}
where $f(z_1, \dotsc, z_n) \in \QQ(q,t)[z_1, z_1^{-1}, \dotsc, z_n,z_n^{-1}]^{\mathfrak{S}_n}$ is a symmetric Laurent polynomial which satisfies the \emph{wheel condition}
\begin{equation*}
	f(z_1, \dotsc, z_n) = 0\qquad \text{whenever} \quad \left\{\frac{z_1}{z_2}, \frac{z_2}{z_3}, \frac{z_3}{z_1}\right\} = \left\{q, t, \frac{1}{qt}\right\}.
\end{equation*}
In particular, $S_1 = \QQ(q,t)[z_1,z_1^{-1}]$.

The shuffle algebra $S$ is equipped with the following product: for $F\in S_n, G\in S_m$, then $F*G\in S_{n+m}$ with
\begin{equation*}
	(F*G)(z_1, \dotsc, z_{n+m}) = \frac{1}{n!m!} \operatorname{Sym}\left( F(z_1, \dotsc, z_n) G(z_{n+1}, \dotsc, z_{n+m}) \prod_{i=1}^n \prod_{j=n+1}^{n+m} \omega(z_j/z_i)\right),
\end{equation*}
where $\operatorname{Sym}$ denotes the symmetrization with respect to the variables $z_1, \dotsc, z_{n+m}$.

We will use the following action of the shuffle algebra on the ring of symmetric functions. We refer to \cite{FeiginHashizumeHoshinoShiraishiYanagida2009,FeiginTsymbaliuk2011} for more details.
\begin{defi}\label{def:shuffle_algebra}
The shuffle algebra $S$ acts on $\Lambda$ through the following representation $F\mapsto \hat{F}$ 
which maps $F\in S_n$ to an operator $\hat{F} \in \End(\Lambda)$ and defined on the generators $z^a$ by
\begin{equation*}
    \widehat{z^a}=D_{-a}=[z^0]z^aD(z),\quad \forall a\in \ZZ.
\end{equation*}
It follows then from \cref{CommutationD} that for any $F\in S$,
\begin{equation*}
	\hat{F}:= [z_1^{0} \dotsm z_n^{0}] F(z_1, \dotsc, z_n) \frac{D(z_1) \dotsm D(z_n)}{\prod_{1\leq i<j\leq n} \omega(z_j/z_i)}.
\end{equation*}
\end{defi}


 In \cite{Negut2014}, Negut introduced specific elements
\begin{equation*}
	X_{\beta}(z_1, \dotsc, z_\ell):= \operatorname{Sym}\left(\frac{z_1^{-\beta_1} \dotsm z_\ell^{-\beta_\ell}}{\prod_{i=1}^{\ell-1} (1-qtz_{i+1}/z_i)} \prod_{1\leq i<j\leq \ell} \omega(z_j/z_i)\right) \quad \in S_\ell,
\end{equation*}
for $\beta = (\beta_1, \dotsc, \beta_\ell)\in \ZZ^\ell$. Using the relations of \cref{CommutationD} of the $D$-operators, a straightforward calculation shows that $\hat{X}_\beta$ coincides with the RHS of \cref{eq:R_vertex_formula}. Thus, we have the following corollary from \Cref{thm:R_vertex_op}.
\begin{cor}
\label{cor:Negut}
Fix $\beta = (\beta_1, \dotsc, \beta_\ell)\in\ZZ^\ell$. Then we have
\[	\hat{X}_\beta = \mcR_\beta. \]
\end{cor}

Blasiak {\it et al} \cite{BlasiakHaimanMorsePunSeelinger2023,BlasiakHaimanMorsePunSeelinger2023b} used these distinguished elements (also called Negut elements) to prove some generalizations of the shuffle and delta conjectures. Remarkably, our analysis of path operators leads to a combinatorial proof of Theorem 4.4.1 from \cite{BlasiakHaimanMorsePunSeelinger2023b}, which is the authors' key reformulation of the symmetric function side of the extended delta conjecture. It comes out as a corollary of the following theorem, which itself follows from \Cref{thm:R_vertex_op}.

\begin{thm}\label{thm:explicit_formula}
	Fix $\beta=(\beta_1,\dots,\beta_\ell)$ of size $n\geq 0$. 
	For any partition $\lambda$ of size $n$ and for the alphabet $Z =
	z_1+\dotsm+z_\ell$ we have
	\begin{multline}
		(-1)^n [s_\lambda[X]] \mcR_{\beta}\cdot 1\\
		=\left[z_1^{\beta_1} \dotsm z_\ell^{\beta_\ell}\right]
		s_{\lambda'}[Z]\prod_{1\leq i<j\leq \ell} \frac{1-z_j/z_i}{(1-qz_j/z_i)(1-tz_j/z_i)}
		\prod_{1\leq i<j-1<\ell} (1-qtz_j/z_i),
	\end{multline}
	where 
	$\lambda'$ is the transpose of $\lambda$, and 
	the rational functions in the RHS should be expanded as formal series in $z_j/z_i$ for $j>i$.
\end{thm}	
Similar formulas hold for $(-1)^n [m_\lambda[X]] \mcR_{\beta}\cdot 1$ and $(-1)^n[e_\lambda[X]] \mcR_{\beta}\cdot 1$, as given in \cref{subsec:NormalOrdering}.

We will also give versions of \Cref{thm:R_vertex_op} and \Cref{thm:explicit_formula} for products of path operators, i.e $\mcR_{\bfbeta} \coloneqq \mcR_{\beta^{(1)}}\dotsm \mcR_{\beta^{(\ell)}}$, with $\bfbeta = (\beta^{(1)}, \dotsc, \beta^{(\ell)})$ where each $\beta^{(i)}\in\ZZ^{\ell_i}$ is a sequence of integers.

\subsection{The \texorpdfstring{$(q,t)$}{(q,t)}-tau function}
Consider two infinite sequences of variables $U = u_1,u_2,\dotsc$ and $V = v_1,v_2,\dotsc$, and define $\KK$ as the ring of formal power series in these variables with coefficients in $\QQ(q,t)$ 
\[	\KK:=\QQ(q,t)\llbracket U,V \rrbracket. \]
Let  
\[G_1(\hbar) := 1+\sum_{n=1}^\infty u_n \hbar^n \in \QQ[U,V]\llbracket \hbar \rrbracket,\quad  G_2(\hbar) :=  1+\sum_{n=1}^\infty v_n \hbar^n \in \QQ[U,V]\llbracket \hbar \rrbracket.\]
Let $G(\hbar) := G_1(\hbar) \cdot G_2^{-1}(\hbar) \in \QQ[U,V]\llbracket \hbar \rrbracket$, and note that the substitution $ G(q^{j} t^{i}) := \frac{G_1(q^{j} t^{i})}{G_2(q^{j} t^{i})} \in \KK$ is well-defined for all $i,j\geq 0$. The \emph{$G$-weighted $(q,t)$-tau function} is the series in $\Lambda^\KK_X\otimes\Lambda^\KK_Y\llbracket z\rrbracket$ defined by:
\begin{equation*}
	\label{eq:GWeightedDoubleTau}
	\tau_G(z,X,Y) :
	= \sum_{\lambda\in\mathbb
		Y}z^{|\lambda|}\frac{\tH_\lambda[X]\tH_\lambda[Y]}{\normH{\lambda}}\prod_{(i,j)\in\lambda} G(q^{j-1} t^{i-1}),
\end{equation*}
where $\tH_\lambda$ are modified Macdonald polynomials, and $\Lambda^\KK_A$ is the algebra of symmetric functions in the alphabet $A = X,Y$ with coefficients in $\KK$. The notation $\normH{\lambda}$ is the squared norm of the modified Macdonald polynomial $\tH_\lambda$  (see \cref{sub:MacdonaldPrel} for the details).

Beyond it being a natural $(q,t)$-deformation of the tau
functions for the $G$-weighted $b$-Hurwitz numbers of \cite{ChapuyDolega2022}, this function has appeared as an important generating series in enumerative geometry and
mathematical physics for specific cases of the weight $G$. When $G(\hbar) = \prod_{i=1}^n(1-\hbar u_i)$, the plethystic
logarithm of $\tau_G(z,X,Y)$ was conjectured by
Hausel--Lettelier--Rodriguez-Villegas~\cite{HauselLetellierRodriguezVillegas2011} to be the generating series of
the mixed Hodge polynomials of character varieties of the Riemann
sphere. When $G(\hbar) = (1-u\hbar)^{-1}$, the specialization $Y =
1$ corresponds to the Whittaker vector for the
deformed Virasoro algebra from the $5D$ $\mathcal{N} = 1$ pure
$\SU(2)$ case of the AGT conjecture~\cite{Yanagida2016}. Finally, the
case $G(\hbar)=\hbar$ has appeared in the recent work of
Bourgine and Garbali~\cite{BourgineGarbali2024} as a tau function of a $(q,t)$-extension of the
2D Toda hierarchy\footnote{In
	\cite{BourgineGarbali2024,Yanagida2016} the authors worked with the
	$P$-version of Macdonald polynomials. We define our $(q,t)$-tau
	function in terms of the modified Macdonald polynomials, as such a function seems
	to have much more interesting combinatorial structure that is
	partially supported by the conjecture of Hausel--Lettelier--Rodriguez-Villegas.}. 

Our main result is a construction of a system of functional equations which uniquely characterizes the $G$-weighted $(q,t)$-tau function. These equations involve some families of path operators parametrized by non-negative sequences $\beta$. It will be convenient to describe these operators by the distances between unit increments, rather than the number of unit increments in each position given by $\beta$. This list of distances, which we denote by $\psi(\beta)$, is obtained from $\beta$ by applying a simple reparametrization bijection $\psi$ (see \cref{sub:path_op} for a precise definition). We then denote by $\mcQ$ the operators obtained from $\mcR$ by this reparametrization:
\[\mcQ_{\psi(\beta)} := \mcR_\beta.\]
Then for $F(\hbar) =1+\sum_{i\geq 1} a_i \hbar^i \in \{G_1, G_2\}$, let
\begin{equation}\label{eq:PathOperatorsA}
  \A_F^{(\ell)} = \sum_{\alpha} a_\alpha \mcQ_\alpha, 
\end{equation}
where the sum is taken over $\alpha \in \ZZ_{\geq 0}^{\ell}$, and $a_\alpha := \prod_{i=1}^\ell a_{\alpha_i}$. We have the following characterization of the $G$-weighted $(q,t)$-tau function.

\begin{thm}\label{thm:dif_eq'}
	For any $\ell\geq 1$ we have
	\begin{equation}\label{eq:diff_eq}
		z^\ell\A^{(\ell)}_{G_1}(X)\cdot\tau_G(z,X,Y)=\left(\A^{(\ell)}_{G_2}(Y)\right)^*\cdot\tau_G(z,X,Y),
	\end{equation}
	where $\left(\A_{G_2}^{(\ell)}\right)^*$ is the adjoint of $\A_{G_2}^{(\ell)}$ with respect to the star scalar product (see \cref{sub:MacdonaldPrel}).
	Moreover, $\tau_G(z,X,Y)$ is the unique function $\Phi_G\in\Lambda^\KK_X\otimes\Lambda^\KK_Y\llbracket z\rrbracket$ that satisfies these equations and such that $[z^0]\Phi_G(z,X,Y)=1$.
\end{thm}
We briefly describe the main steps of the proof of this theorem:
\begin{itemize}
    \item We prove that all the operators $\A_F^{(\ell)}$ can be recursively built from commutators of two elementary operators, $e_1$ and $D_0$. This part of the proof is purely combinatorial and will be carried out in \cref{sec:path_op}.
    \item We use the commutation relations established in the first step and the fact that the operators $e_1$ and $D_0$ act nicely on the function $\tau_G$ to prove \cref{eq:diff_eq} by induction on $\ell$. This will be the main goal of \cref{sec:fun_eq}.
\end{itemize}

\subsection{Outline of the paper}
In Section \ref{sec:PathOperators}, we describe path operators in details and prove some explicit expressions such as those of \Cref{thm:R_vertex_op} and \Cref{thm:explicit_formula}. In Section \cref{sec:fun_eq}, we introduce the $G$-weighted $(q,t)$-tau function and prove a version of the functional equation \eqref{eq:diff_eq} where the operators acting on the LHS and RHS are not defined in terms of path operators. In Section \ref{sec:path_op} we conclude the proof of \Cref{thm:dif_eq'} by showing that these operators are indeed the path operators defined in \cref{eq:PathOperatorsA}.

\section{Path operators and the \texorpdfstring{$D$}{D}-operator} \label{sec:PathOperators}
\subsection{Preliminaries}
\label{sec:Prelim}

Let $\Lambda$ denote the algebra of symmetric functions in the alphabet $X = x_1+x_2+\dotsb$ with coefficients in $\QQ(q,t)$. We denote the classical bases such as monomial, elementary, homogeneous, power-sum, and Schur symmetric functions by $m_\lambda,e_\lambda,h_\lambda,p_\lambda, s_\lambda$, where $\lambda$ is an integer partition, which we denote by $\lambda \in \YY$. The \emph{dominance order} $\leq$ is the partial order on $\YY$ defined by 
$$\mu\leq\lambda \iff |\mu|=|\lambda| \text{ and }\hspace{0.3cm} \mu_1+...+\mu_i\leq \lambda_1+...+\lambda_i \text{ for } i\geq1.$$

For $i\geq 1$, we denote $m_i(\lambda)$ the number of parts of size $i$ in $\lambda$. We then set 
\begin{equation*}\label{eq zlambda}
z_\lambda:=\prod_{i\geq1}m_i(\lambda)!i^{m_i(\lambda)}.  
\end{equation*}

The \emph{Hall scalar product}  $\langle.,.\rangle$ on $\Lambda$ is defined by 
\begin{equation*}\label{eq scalar product}
  \langle p_\mu,p_\nu\rangle=\delta_{\mu,\nu}z_\mu, \qquad \text{for any $\mu,\nu\in\YY$,} 
\end{equation*}
where $\delta_{\mu,\nu}$ is the Kronecker delta. We also have $\langle m_\mu,h_\nu\rangle=\delta_{\mu,\nu}$, for  $\mu,\nu\in\YY$. If $f\in\Lambda$, then we denote $f^\perp$ the dual of the multiplication by $f$, with respect to this scalar product.

For any symmetric function $f \in \Lambda$ and an expression $A$ involving indeterminates, we define the plethystic substitution $f[A]$ by first defining it on the basis of power-sum symmetric functions $p_k[A]$ by the substitution $a \mapsto a^k$ for each indeterminate $a$ occurring in $A$, and then extending on the whole algebra of symmetric functions so that $f \mapsto f[A]$ is a homomorphism. For instance $p_k[X] := \sum_{i \geq 1} x_i^k$ and 
\begin{align*}
	p_k[aX] &= a^kp_k[X] \quad \text{for $a\in\{q,t\}$}\\
	p_k[cX] &= cp_k[X] \quad \text{for $c\in\QQ$}.
\end{align*} 
An expression we will encounter often is $M:=(1-q)(1-t) \in \QQ(q,t)$ and hence $p_k[MX] = (1-q^k)(1-t^k)p_k[X]$.

For an expression A, define the associated \emph{plethystic exponential} by
\[\Omega[A]: = \sum_{n\geq 0} h_n[A] = e^{\sum_{i>0}\frac{p_i[A]}{i}}.\]
In particular, the Cauchy and dual Cauchy kernels are respectively given by
$$\Omega[X]=\sum_{n\geq 0} h_n[X] = \prod_{k\geq 1}\frac{1}{1-x_k},\qquad\text{and}\qquad\Omega[-X]=\sum_{n\geq 0} (-1)^n e_n[X] = \prod_{k\geq 1}(1-x_k).$$

Following \cite{GarsiaHaimanTesler1999}, we consider the operators that act on $f[X]\in\Lambda$ like
\begin{equation*}
	\begin{aligned}
	\mcP_Y f[X] &= \Omega[XY] f[X],\\
	\mcT_Y f[X] &=\sum_{k\geq 0}h^\perp_{k}[Y]f[X]= f[X+Y].
	\end{aligned}
\end{equation*} 
We have the following commutation relations between operators acting on
$\Lambda_X$ (see \cite[Theorem 1.1 and Proposition 1.2]{GarsiaHaimanTesler1999}):
\begin{equation}\label{eq:mcT-mcP'}
 \mcT_Y\cdot \mcP_Z=\Omega[YZ]\mcP_Z\cdot \mcT_Y,   
\end{equation}
An important role in the theory of Macdonald polynomials is played by the operators $D_k$, $k\in\mathbb{Z}$ from \cite{GarsiaHaimanTesler1999}. They are defined by the following equality of formal series
\[D(z) = \sum_{k\in\mathbb{Z}} D_k z^k = \mcP_{-z} \mcT_{M/z}.\]
Since $\mcP_{-z} = \sum_{n\geq 0} (-1)^n e_n[X] z^n$ and $\mcT_{M/z} = e^{\sum_{i>0} \frac{z^{-i}}{i} p_i^\perp[MX]} = \sum_{n\geq 0} h_n^\perp[MX] z^{-n}$, it comes that
\begin{equation}
\label{eq:Dk}
	D_k = \sum_{\substack{m, n\geq 0\\ m-n=k}} (-1)^m e_m[X] h_n^\perp[MX].
\end{equation}
In particular, $D_k$ is equal to the path operator $\mcR_{(k)}$ defined in \cref{def:decorated_paths}:
\begin{equation} \label{2steps}
	\mcR_{(k)} = \sum_{\substack{m, n\geq 0\\ m-n=k}} \mcO(m) \mcO(-n) = \sum_{\substack{m, n\geq 0\\ m-n=k}} (-1)^m e_m[X] h_n^\perp[MX] = D_k.
\end{equation}

\subsection{Decomposition at fixed valley heights and proof of Theorem \texorpdfstring{\ref{thm:R_vertex_op}}{}}
Fix a sequence $\beta=(\beta_1,\dots,\beta_\ell)\in\mathbb{Z}^\ell$. If $\gamma\in\bR_\beta$ has steps $(\gamma_1, \dotsc, \gamma_{2\ell})$, define
\[r_j(\gamma) = \gamma_{2j-1}+\gamma_{2j},
\]
for $j=1, \dotsc, \ell$. These quantities are the increments between the heights of consecutive valleys (including the endpoint). Equivalently, if $\gamma$ has points $(w_0, \dotsc, w_{2\ell})$ with coordinates $w_j = (j, y_j)$, then $r_j(\gamma) = y_{2j}-y_{2j-2}$ for $j=1, \dotsc, \ell$. Clearly, the set of possible values $(r_1,\dots,r_\ell)\in\ZZ^\ell$ such that there exists a path $\gamma\in\mcR_\beta$ with $r_j(\gamma) = r_j$ for all $j=1, \dotsc, \ell$ is
\begin{multline}\label{eq:VI}
	\VI_\beta=\left\{(r_1,\dots,r_\ell)\in\ZZ^\ell\big| \sum_{1\leq i\leq j}r_i\geq \sum_{1\leq i\leq j}\beta_i \text{ for $1\leq j< \ell$,} \text{ and }\sum_{1\leq i\leq \ell}r_i= \sum_{1\leq i\leq \ell}\beta_i.\right\}  
\end{multline}
and the set of corresponding paths is denoted $\bR_\beta(r_1, \dotsc, r_\ell)$. The valley weights of those paths, as defined in \cref{eq:valley_weight_PMAP}, only depend on $(r_1,\dots,r_\ell)$, so we define
\[\vweight_\beta(r_1,\dots,r_\ell) \coloneqq \vweight_\beta(\gamma) = \prod_{1\leq j\leq \ell}(qt)^{\sum_{1\leq i\leq j}(r_i-\beta_i)}.
\]
for any path $\gamma\in\bR_\beta(r_1, \dotsc, r_\ell)$.
\begin{exe}
    The list of increments of the valley heights of the path $\gamma$ given in \cref{fig:alternating_path} is $(2,-3,2,2)$. Since $\gamma\in \bR_{(1,-2,1,3)}$, this implies that $(2,-3,2,2)\in\VI_{(1,-2,1,3)}$.
\end{exe}
We have the following formula for the operator $\mcR_\beta$, where instead of summing over all paths we sum over valley increments.
\begin{prop}\label{prop:Qalpha_D}
	For any $\beta\in \ZZ_{\ell}$,
	\[\mcR_\beta = \sum_{(r_1,\dotsc,r_\ell)\in\VI(\beta)} \vweight_{\beta}(r_1,\dots,r_\ell) [z_1^{r_1}\dotsm z_\ell^{r_\ell}]D(z_1)\dotsm D(z_\ell).
	\]
\end{prop}

\begin{proof}
	We start from
	\[
	\begin{aligned}
		\mcR_\beta &= \sum_{(r_1,\dotsc,r_\ell)\in\VI(\beta)} \sum_{\gamma\in\bR_\beta(r_1, \dotsc, r_\ell)} \vweight_\beta(\gamma) \mcO(\gamma_1)\dotsm \mcO(\gamma_{2\ell})\\
		&= \sum_{(r_1,\dotsc,r_\ell)\in\VI(\beta)} \vweight_\beta(r_1, \dotsc, r_\ell) \sum_{\gamma\in\bR_\beta(r_1, \dotsc, r_\ell)} \mcO(\gamma_1)\dotsm \mcO(\gamma_{2\ell}).
	\end{aligned}
	\]
	Then we can perform the sum over the heights of peaks at fixed valley heights by using the following (see \cref{2steps})
	\[\sum_{\substack{\gamma_{2j-1}\geq 0, \gamma_{2j}\leq 0\\ \gamma_{2j-1} + \gamma_{2j}= r_j}} \mcO(\gamma_{2j-1}) \mcO(\gamma_{2j}) = D_{r_j} = [z^{r_j}] D(z).\qedhere
	\]
\end{proof}

We will use the following straightforward lemma.
\begin{lem}\label{lem:LargerPart}
	Let $n\in\ZZ$, and let $\mcO(z)=\sum_{i\in\ZZ}z^i\mcO_i$ be a field. Then
	\[ [z^n] \frac{\mcO(z)}{1-qt\frac{w}{z}} = \sum_{i\geq n}(qtw)^{i-n} \mcO_i \]
	where the denominator on the LHS is a series in $w/z$.
\end{lem}

\begin{proof}[Proof of \cref{thm:R_vertex_op}]
	We will prove the theorem by induction on $\ell$. The case $\ell=1$ corresponds to \cref{2steps}, so suppose that $\ell >1$ and define for $1\leq m< \ell$ the set of all possible $m$ first valley increments
	\[\VI^{(m)}_\beta = \left\{(r_1, \dotsc, r_m)\in\ZZ^m \big| \sum_{1\leq i\leq j} r_i \geq \sum_{1\leq i\leq j} \beta_k\text{ for } 1\leq j\leq m\right\}. \]
	Let us consider for $1\leq m\leq \ell-1$ the intermediate operators
	\[\mcR_{\beta}^{(m)}(w) = \sum_{(r_1, \dotsc, r_m)\in\VI_\beta^{(m)}} D_{r_1} (qt)^{r_1-\beta_1} D_{r_2} (qt)^{r_1+r_2-\beta_1-\beta_2} \dotsm D_{r_{m}} (qtw)^{\sum_{k=1}^{m} (r_k - \beta_k)}.\]
	Such an operator can be thought of as the operator obtained by considering only the possible first $2m$ steps of paths in $\bR_\beta$ counted with an extra weight $w^j$, where $j\geq 0$ is the $\beta$-height of the $m$-th valley.

	For $m=1$, we have $$\mcR_{\beta}^{(1)}(z_2) = \sum_{r_1\geq \beta_1}(qtz_2)^{r_1-\beta_1} D_{r_1}  = [z_1^{\beta_1}] \frac{D(z_1)}{1-qt\frac{z_2}{z_1}}$$ by \cref{lem:LargerPart}. By induction, one finds 
	$$\mcR_\beta^{(m+1)}(z_{m+2}) = \sum_{k\geq \beta_{m+1}}z_{m+2}^{k-\beta_{m+1}}[z_{m+1}^k]\mcR_\beta^{(m)}(z_{m+1})D(z_{m+1})=[z_{m+1}^{\beta_{m+1}}] \frac{\mcR_\beta^{(m)}(z_{m+1})D(z_{m+1})}{(1-qtz_{m+2}/z_{m+1})}$$ 
	for any $1\leq m\leq \ell-2$. Here, we used \cref{lem:LargerPart} with $\mcO(z)=\mcR_\beta^{(m)}(z_{m+1})D(z_{m+1}).$  In particular, for $m=\ell-2$,
	\[\mcR_{\beta}^{(\ell-1)}(z_{\ell}) = [z_1^{\beta_1} \dotsm z_{\ell-1}^{\beta_{\ell-1}}] \frac{D(z_1) \dotsm D(z_{\ell-1})}{\prod_{i=1}^{\ell-1} \bigl(1-qt z_{i+1}/z_i\bigr)}.\]
	Finally, we get
	\[\mcR_\beta = [z_\ell^{\beta_\ell}] \mcR_\beta^{(\ell-1)}(z_\ell) D(z_\ell) = [z_1^{\beta_1} \dotsm z_{\ell}^{\beta_{\ell}}] \frac{D(z_1) \dotsm D(z_{\ell})}{\prod_{i=1}^{\ell-1} \bigl(1-qt z_{i+1}/z_i\bigr)},\]
	where the first equality follows from \cref{prop:Qalpha_D}.	This finishes the proof of the theorem.
\end{proof}


\subsection{Concatenation of paths}
We now give a VOA formula for a composition of path operators. 
Fix an integer $m\geq 1$, and $\ell_1, \dotsc, \ell_m \geq 0$ and consider a concatenation of $m$ sequences of respective lengths $(\ell_1,\ell_2,\dots,\ell_m)$,
$$\bfbeta=(\beta^{(1)},\beta^{(2)},\dots,\beta^{(m)})\in \ZZ^{\ell_1}\times\dotsb\times \ZZ^{\ell_m}.$$ 
Such concatenation can be written
$\bfbeta=(\beta_1,\dots,\beta_\ell),$
where $\ell:=\ell_1+\dots+\ell_m$. We call \emph{the total size}  of $\bfbeta$ the integer $\sum_{1\leq i\leq \ell}\beta_i$.


We define 
\[\bR_{\bfbeta}:=\bR_{\beta^{(1)}}\times\dots\times\bR_{\beta^{(m)}}\]
the set of sequences of $m$ paths $(\gamma^{(1)},\dotsc,\gamma^{(m)})$ with $\gamma^{(i)}\in\bR_{\beta^{(i)}}$. Similarly, we define the composition of operators
$$\mcR_{\bfbeta}:=\mcR_{\beta^{(1)}}\dotsm\mcR_{\beta^{(m)}}=\sum_{(\gamma^{(1)},\dotsc,\gamma^{(m)})\in \bR_{\bfbeta}} \mcO_{\beta^{(1)}}(\gamma^{(1)})\dotsm\mcO_{\beta^{(m)}}(\gamma^{(m)})$$
and the valley increments associated to $\bfbeta$
$$\VI_{\bfbeta}:=\VI_{\beta^{(1)}}\times\dots\times\VI_{\beta^{(m)}},$$
and we extend the valley weight defined in \eqref{eq:valley_weight_PMAP} by multiplicativity.

We have the following immediate corollary from \Cref{thm:R_vertex_op}.
\begin{cor}\label{cor:R_vertex_op}
	Fix $\bfbeta=(\beta^{(1)},\beta^{(2)},\dots,\beta^{(m)})=(\beta_1,\dots,\beta_\ell)$, and let $L_k := \sum_{i=1}^k \ell_i$ with the convention $L_0 = 0$. Then
	\begin{equation}\label{eq:R_vertex_op}
		\mcR_{\bfbeta} :=\mcR_{\beta^{(1)}}\dotsm\mcR_{\beta^{(m)}}= [z_1^{\beta_1} \dotsm z_{\ell}^{\beta_{\ell}}] \frac{D(z_1) \dotsm D(z_{\ell})}{\prod_{k=1}^{m}\prod_{i=L_{k-1}+1}^{L_k-1} \bigl(1-qt z_{i+1}/z_i\bigr)}.    	\end{equation}
\end{cor}

\subsection{Normal ordering and non-consecutive indices}
\label{subsec:NormalOrdering}
Recall that $D(z) = \mcP_{-z} \mcT_{M/z}$ where $\mcP_{-z}$ acts by multiplication and $\mcT_{M/z}$ by translation. Normal ordering a product of $D$-operators consists in rewriting it such that all the translation operators are on the right of the multiplication operators. The elementary relation for normal ordering follows from \eqref{eq:mcT-mcP'} and is given by
\begin{equation*}
	\label{eq:NormalOrd}
	\mcT_{M/z} \mcP_{-w} = \omega(w/z) \mcP_{-w} \mcT_{M/z},
\end{equation*}
with $\omega(x)$ being the following series in $x$, 
\[\omega(x) = \Omega[-Mx] = \frac{(1-x)(1-qtx)}{(1-qx)(1-tx)}.\]
This gives
\begin{equation} \label{NormalOrdering}
	D(z) D(w) = \omega(w/z) \mcP_{-w-z} \mcT_{M/z+M/w}.
\end{equation}


Before plugging the above formula into \Cref{cor:R_vertex_op}, we define the set of \emph{non-consecutive indices} $\mcNI_{\bfbeta}$ of $\bfbeta$ as the set of pairs $(i,j)$ with $i<j$ that are not consecutive as integers, i.e. $j>i+1$, or that belong to two different sequences $\beta^{(n_i)}$ and $\beta^{(n_j)}$ in $\bfbeta$. More formally: 
\begin{multline}
	\mcNI_{\bfbeta}:=
	\left\{(i,j)|1\leq i<j\leq \ell, \text{ such that }i<j-1 \right.\\
	\left.\text{ or } (i=j-1 \text{ and }i\leq L_k<j \text{ for some }1\leq k\leq m)\right\},  
\end{multline}
where we denote the partial sums $L_k=\sum_{i=1}^k \ell_i$. In other terms, $\mcNI_{\bfbeta}$ is defined so that \eqref{eq:R_vertex_op} can be rewritten as
\begin{equation}
	\label{eq:R_vertex_opPrim}
	\mcR_{\bfbeta} = [z_1^{\beta_1} \dotsm z_{\ell}^{\beta_{\ell}}] \frac{D(z_1) \dotsm D(z_{\ell})}{\prod_{\substack{1 \leq i < j \leq \ell\colon\\ (i,j) \notin \mcNI_{\bfbeta}}} \bigl(1-qt z_{j}/z_i\bigr)}.
\end{equation}
Note that $\mcNI_{\bfbeta}$ depends only on the sequence $(\ell_1,\ell_2,\dots,\ell_m)$ and not $\bfbeta$ itself.
\begin{exe}
	If $\bfbeta=((2,0,0),(3))$, then $\mcNI_{\bfbeta}=\left\{\right(1,3),(1,4),(2,4),(3,4)\}.$
\end{exe}

\begin{thm}\label{thm:explicit_formula2}
	We set $\bM:=q+t-1$. Fix $\bfbeta=(\beta^{(1)},\beta^{(2)},\dots,\beta^{(m)})=(\beta_1,\dots,\beta_\ell)$. Then 
	\begin{equation}\label{eq:explicit_formula}
		\mcR_{\bfbeta}\cdot1 = \left[z_1^{\beta_1}\dotsm z_\ell^{\beta_\ell}\right]\Omega\left[\bM\sum_{1\leq i< j\leq \ell}z_j/z_i-qt\sum_{(i,j)\in\mcNI_{\bfbeta}}z_j/z_i-\sum_{1\leq i\leq \ell}z_iX\right].
	\end{equation}
\end{thm}

\begin{proof}
	We use \eqref{NormalOrdering} to normal order $D(z_1) \dotsm D(z_{\ell})$ in \cref{eq:R_vertex_op},
	\begin{equation*}
		D(z_1) \dotsm D(z_{\ell}) = \biggl(\prod_{1\leq i<j\leq \ell} \omega(z_j/z_i)\biggr) \mcP_{-z_1-\dotsb-z_\ell}\mcT_{M/z_1+\dotsb+M/z_\ell}. 
	\end{equation*}
	Applying this equation on 1, we get
	\begin{equation*}
		D(z_1) \dotsm D(z_{\ell})\cdot 1 = \biggl(\prod_{1\leq i<j\leq \ell} \omega(z_j/z_i)\biggr) \Omega\left[-\sum_{1\leq i\leq \ell}z_i X\right]
	\end{equation*}
	since $\mcT_x \cdot 1 = 1$ and $\mcP_x \cdot 1 = \Omega[x]$.
Plugging it into \eqref{eq:R_vertex_opPrim}, we get
	\begin{equation*}
		\mcR_{\bfbeta}\cdot 1 = [z_1^{\beta_1} \dotsm z_{\ell}^{\beta_{\ell}}] \prod_{1\leq i<j\leq \ell} \frac{(1-z_j/z_i) }{(1-qz_j/z_i)(1-tz_j/z_i)} \prod_{(i,j)\in\mcNI_\beta} (1-qtz_j/z_i) \Omega\left[-\sum_{1\leq i\leq \ell}z_i X\right]
	\end{equation*}
	which is equivalent to the plethystic exponentials in the Theorem.
\end{proof}

We deduce from \cref{thm:explicit_formula2} the expansion for the family $\mcR_{\bfbeta}\cdot 1$ in the Schur basis, the elementary basis, and the monomial basis.
\begin{cor}\label{cor:explicit:formula}
	Fix $\bfbeta=(\beta^{(1)},\beta^{(2)},\dots,\beta^{(m)})=(\beta_1,\dots,\beta_\ell)$ of total size $n\geq 0$. For any partition $\lambda$ of size $n$ and for the alphabet $Z =
    z_1+\dotsm+z_\ell$, we have
	\begin{align*}
		(-1)^n [s_\lambda[X]] \mcR_{\bfbeta}\cdot 1
		=&\left[z^{\bfbeta}\right]
		s_{\lambda'}[Z]\prod_{1\leq i<j\leq \ell}
		\frac{1-z_j/z_i}{(1-qz_j/z_i)(1-tz_j/z_i)}\prod_{(i,j)\in\mcNI_{\bfbeta}}
		(1-qtz_j/z_i),
	\end{align*}
	and 
	\begin{align*}
		(-1
		)^n[m_\lambda[X]] \mcR_{\bfbeta}\cdot 1
		=&\left[z^{\bfbeta}\right]
		e_{\lambda}[Z]\prod_{1\leq i<j\leq \ell}
		\frac{1-z_j/z_i}{(1-qz_j/z_i)(1-tz_j/z_i)}\prod_{(i,j)\in\mcNI_{\bfbeta}}
		(1-qtz_j/z_i),  
	\end{align*}
	and
	\begin{align*}
	 (-1)^n[e_\lambda[X]] \mcR_{\bfbeta}\cdot 1
	=&\left[z^{\bfbeta}\right]
	m_\lambda[Z]\prod_{1\leq i<j\leq \ell}
	\frac{1-z_j/z_i}{(1-qz_j/z_i)(1-tz_j/z_i)}\prod_{(i,j)\in\mcNI_{\bfbeta}}
	(1-qtz_j/z_i).
	\end{align*}
\end{cor}
\begin{proof}
	Each formula is a consequence of \cref{eq:explicit_formula} and one of the dual Cauchy formulas:
	\begin{align*}
		\Omega\left[-ZX\right]=\sum_{\lambda\in\YY}(-1)^{|\lambda|}s_{\lambda'}[Z]s_\lambda[X]=\sum_{\lambda\in\YY}(-1)^{|\lambda|}e_{\lambda}[Z]m_\lambda[X]=\sum_{\lambda\in\YY}(-1)^{|\lambda|}m_\lambda[Z]e_{\lambda}[X].
	\end{align*}
	where $\lambda'$ is the transpose of $\lambda$.
\end{proof}
Note that \cref{thm:explicit_formula} is then obtained from \cref{cor:explicit:formula} by taking $m=1$.

\section{Functional equations for the \texorpdfstring{$(q,t)$}{(q,t)}-tau function}
\label{sec:fun_eq}

\subsection{Preliminaries}
\label{sub:MacdonaldPrel}

Recall (see~\cite{GarsiaHaimanTesler1999}) that a ring of symmetric functions $\Lambda$ on the alphabet $X$ possesses a distinguished basis of the so-called modified Macdonald polynomials $\tH_\lambda[X]$. We will need two well-known properties of modified Macdonald polynomials.

\begin{thm}
	\label{thm:Macdonald}
	We have the following:
	\begin{enumerate}
		\item[(i)] \textbf{Pieri Rule \cite{Macdonald1995}:} There exist coefficients $d^{\mu,\lambda}\in \QQ(q,t)$ such that
		\begin{equation*}
			-e_1[X]\tH_\mu=\sum_{\mu\nearrow\lambda}d^{\mu,\lambda}\tH_\lambda
		\end{equation*}
		where the sum is taken over partitions $\lambda$ obtained from $\mu$ by adding exactly one cell.
		\item[(ii)] \textbf{Macdonald operator $D_0$ \cite[Theorem~1.2]{GarsiaHaimanTesler1999}:} The modified Macdonald polynomials are eigenfunctions of the operator $D_0 = [z^0] D(z)$ defined in~\eqref{eq:Dk}
		\begin{equation*}
			D_0\cdot \tH_{\lambda}=\biggl(1-M\sum_{(i,j)\in\lambda} q^{j-1} t^{i-1}\biggr)\tH_{\lambda},\quad \text{for any $\lambda\in \YY$,}
		\end{equation*}
        where the sum is taken over all cells $(i,j)$ of the Young diagram $\lambda$.
	\end{enumerate}
\end{thm}

Recall that the Macdonald Cauchy kernel can be written as follows
\begin{equation*}
    \Omega\left[-\frac{XY}{M}\right]=\exp\left(\sum_{i \geq 1} \frac{p_i[X]p_i[Y]}{i p_i[-M]}\right) = \sum_{\mu\in\YY}\frac{p_{\mu}[X]p_{\mu}[Y]}{z_\mu p_\mu[-M]},
\end{equation*}
which motivates the definition of the \emph{star scalar product} $\langle .,.\rangle_*$ as the deformation of the Hall scalar product given by 
$$\langle p_\mu,p_\nu\rangle_*=z_\mu\delta_{\mu,\nu}p_\mu[-M]=(-1)^{\ell(\mu)}z_\mu\delta_{\mu,\nu}\prod_{1\leq i\leq \ell(\mu)}\left(1-q^{\mu_i}\right)\left(1-t^{\mu_i}\right), \quad \text{for any $\mu,\nu\in\YY$.} $$
Modified Macdonald polynomials are orthogonal with respect to the star scalar product:
\begin{equation}\label{eq:orthogonality_Macdonald}
  \langle \tH_\lambda,\tH_\rho\rangle_*=\delta_{\lambda,\rho}\normH{\lambda},  
\end{equation}
we refer to \cite[Chapter VI]{Macdonald1995} for a combinatorial formula of the squared norm $\normH{\lambda}$. The following Cauchy formula then holds:
\begin{equation}\label{eq:Cauchy}
    \Omega\left[-\frac{XY}{M}\right]=\sum_{\lambda\in\YY}\frac{\tH_\lambda[X]\tH_\lambda[Y]}{\normH{\lambda}}.
\end{equation}

Recall that we denote $\Lambda^\KK_A$ the algebra of symmetric functions in the alphabet $A = X,Y$ with coefficients in $\KK :=\QQ(q,t)\llbracket U,V \rrbracket$, where $U = u_1,u_2,\dotsc$ and $V = v_1,v_2,\dotsc$ are two infinite sequences of variables. Then the $G$-weighted $(q,t)$-tau function is the series in $\Lambda^\KK_X\otimes\Lambda^\KK_Y\llbracket z\rrbracket$ defined by:
\begin{equation*}
	\tau_G(z,X,Y) :
	= \sum_{\lambda\in\mathbb
		Y}z^{|\lambda|}\frac{\tH_\lambda[X]\tH_\lambda[Y]}{\normH{\lambda}}\prod_{(i,j)\in\lambda} G(q^{j-1} t^{i-1}),
\end{equation*}
where 
\[ G_1(\hbar) := 1+\sum_{n=1}^\infty u_n \hbar^n \in \QQ[U,V]\llbracket \hbar \rrbracket,\quad  G_2(\hbar) :=  1+\sum_{n=1}^\infty v_n \hbar^n \in \QQ[U,V]\llbracket \hbar \rrbracket,\]
and $G(q^{j} t^{i}) := \frac{G_1(q^{j} t^{i})}{G_2(q^{j} t^{i})} \in \KK$.

There is an equivalent way of defining the $G$-weighted $(q,t)$-tau function, which is closer in spirit to the setting used in~\cite{GarsiaHaimanTesler1999}. Let $G(\hbar) \in \KK \llbracket \hbar \rrbracket$ be a series such that the substitution $G(q^j t^i)$ is a well-defined element of $\KK$ for all $j,i \geq 0$.

For an alphabet $A = X,Y$ we define the linear operator $\Pi^A_G \colon \Lambda_A^\KK \rightarrow \Lambda_A^\KK$ by its action on the basis of Macdonald polynomials
\begin{equation*}\label{eq:Pi_Operator}
  \Pi^A_G\cdot \tH_\lambda[A] := \prod_{(i,j)\in\lambda} G(q^{j-1} t^{i-1}) \tH_\lambda[A],\qquad \forall \lambda\in\YY.
\end{equation*}
Then, it is immediate from the Cauchy identity~\cref{eq:Cauchy} that
\[ \tau_G(z,X,Y) = \Pi^X_G\Omega\left[-\frac{zXY}{M}\right] = \Pi^Y_G\Omega\left[-\frac{zXY}{M}\right].\]

\subsection{Functional equations}
Throughout the paper, the series $F$ will be $F=G_1$ or $F=G_2$, with expansion $F(\hbar)=\sum_{i \geq 0}a_i \hbar^i$ ($a_i=u_i$ in the first case and $a_i=v_i$ in the second one and with the convention $a_0 = 1$). We will use
\begin{equation}
	\label{eq:A_F}
	\A_F \coloneqq \sum_{i \geq 0}a_i \ad^i_{\frac{D_0}{-M}}(-e_1[X]), \quad \text{with $\ad_{A}(B) := [A,B] = AB-BA$}
\end{equation}
for any operators $A$ and $B$. Then define the family of operators
\begin{equation}
	\label{def:AFell}
	\A^{(1)}_F := \ad_{\frac{D_0}{-M}} \left(\A_F\right),\qquad \A^{(\ell)}_F =
	\ad^{\ell-1}_{\A_F/M}(\A^{(1)}_F),\quad \text{for $\ell \geq 2$}.
\end{equation}

\begin{rmk}
Note that we have already used the notation $\A^{(\ell)}_F$ in \cref{thm:dif_eq'} for operators that were defined in terms of path operators. This is not a conflict in notation, as we will prove in \cref{sec:path_op} that the operators $\A^{(\ell)}_F$ defined by \eqref{def:AFell} can be expressed in terms of the path operators as stated in~\cref{thm:dif_eq'}. For now, however, we will only use the definition~\eqref{def:AFell}. 
\end{rmk}

\begin{rmk}\label{rmk:diff_op}
Recall that $\Lambda^\KK$ is isomorphic to the polynomial ring $\KK[z_1,z_2,\dots]$, where $z_1,z_2,\dots$ are generators of $\Lambda$; for instance $e_1,e_2,\dots$, $h_1,h_2,\dots$, or $p_1,p_2,\dots$. Then $\A_{F}^{(\ell)}$ are differential operators in the sense that
\[ \A_{F}^{(\ell)} \colon \KK[z_1,z_2,\dots] \rightarrow \KK[z_1,z_2,\dots],\quad \A_{F}^{(\ell)} = \sum_{\alpha,\beta} a_{\alpha}^\beta z^\alpha \partial_{z^\beta},\quad a_{\alpha}^\beta \in \KK,\]
where we sum over multi-indices $\alpha,\beta$ with finitely many non-zero terms, and $z^\alpha := z_1^{\alpha_1} z_2^{\alpha_2} \dotsc$, $\partial_{z^\beta} := \partial_{z_1}^{\beta_1} \partial_{z_2}^{\beta_2} \dotsc$. This can be checked using the expansion of $D_0 = \sum_{n\geq 0} (-1)^n e_n[X] h_n^\perp[MX]$ and expanding $h_n^\perp$ in terms of $p_k^\perp=\frac{k\partial}{\partial p_k}$.
\end{rmk}


We start with the following functional equation (or PDE by \cref{rmk:diff_op}) satisfied by the $(q,t)$-tau function.
\begin{thm}\label{thm:dif_eq}
	For any $\ell\geq 1$ we have
	\begin{equation}\label{eq:diff_eq2}
		z^\ell\A^{(\ell)}_{G_1}(X)\cdot\tau_G(z,X,Y)=\left(\A^{(\ell)}_{G_2}(Y)\right)^*\cdot\tau_G(z,X,Y).  
	\end{equation}
where $\left(\A_{G_2}^{(\ell)}\right)^*$ is the adjoint of $\A_{G_2}^{(\ell)}$ with respect to the star scalar product.
\end{thm}

In order to prove \cref{thm:dif_eq}, we need to find how the operators $\A^{(\ell)}_F$ act on modified Macdonald polynomials, starting with $\ad^i_{D_0/M}(-e_1[X])$, which is possible by~\cref{thm:Macdonald}. Remarkably, no explicit expression of the coefficients $d^{\mu,\lambda}$ appearing in the Pieri rule (\cref{thm:Macdonald}(i)) is required in our work, only the fact that they vanish if $\lambda$ is not obtained from $\mu$ by the addition of one cell.


For a skew diagram $\lambda/\mu$, we use the notation $F(\lambda/\mu):=\prod_{(i,j)\in\lambda/\mu}F(q^{j-1}t^{i-1}).$

\begin{lem}\label{lem:DeltaG_A+}
	For any $\ell\geq 1$, we have	\[\Pi_G\cdot \A^{(\ell)}_{G_2}\cdot \Pi_G^{-1}=\A^{(\ell)}_{G_1}.\] 
\end{lem}
\begin{proof}
	From \cref{thm:Macdonald} and the defining formula~\eqref{eq:A_F} for $\A_F$ we find
	\begin{equation*} \label{eq:A_PonMacdonald}
		\A_F \tH_\mu = \sum_{\mu\nearrow\lambda} d^{\mu,\lambda} F(\lambda/\mu) \tH_\lambda.
	\end{equation*}
With the definition of $\Pi_G$, this gives 
\begin{equation}\label{eq:A_PI}
    \Pi_G \A_{G_2}\Pi^{-1}_G=\A_{G_1}.
\end{equation}
Commuting \cref{eq:A_PI} with $\frac{-D_0}{M}$ gives the lemma for $\ell=1$. Then for $\ell\geq 2$, one has $\A^{(\ell)}_F = \frac{1}{M}[\A_F, \A_F^{(\ell-1)}]$, so the lemma is obtained from \cref{eq:A_PI} by induction.
\end{proof}

\noindent We obtain \Cref{thm:dif_eq} by combining \cref{lem:DeltaG_A+} and the following lemma.
\begin{lem}\label{lem:diff_eq}
	Let $\mcO_1$ and $\mcO_2$ be two operators on $\Lambda^\KK$ which have the same homogeneous degree $\ell\geq0$. Then
	\begin{equation*}\label{eq:diff_DeltaG}
		z^\ell\mcO_2(X)\cdot \tau_G(z,X,Y)=\mcO_1^{*}(Y)\cdot \tau_G (z,X,Y)\ \Longleftrightarrow\ \Pi_G\cdot \mcO_1\cdot \Pi_G^{-1}=\mcO_2.  
	\end{equation*}
\end{lem}

\begin{proof}
		Since Macdonald polynomials are a basis of $\Lambda^\KK$, we have the equivalence
		\begin{align*}
			z^\ell\mcO_2(X)&\cdot \tau_G(z,X,Y)=\mcO_1^{*}(Y)\cdot \tau_G (z,X,Y)\Longleftrightarrow \\
			 &\forall \lambda, \quad \langle z^\ell \mcO_2(X)\cdot \tau_G(z,X,Y), \tH_\lambda(Y)\rangle_*=\langle \tau_G(z,X,Y),\mcO_1(Y)\cdot \tH_\lambda(Y)\rangle_*.
		\end{align*}
        		Here the scalar product is taken with respect to the variables $Y$.
		For $1\leq i \leq 2$, define the coefficients $a^{(i)}_{\lambda,\xi}$ by
	$$\mcO_i\cdot \tH_\lambda=\sum_{\xi\vdash |\lambda|+\ell}a^{(i)}_{\lambda,\xi} \tH_\xi.$$
Using the orthogonality of Macdonald polynomials \cref{eq:orthogonality_Macdonald}, we get
		\begin{align*}
			 z^\ell&\mcO_2(X)\cdot \tau_G(z,X,Y)=\mcO_1^{*}(Y)\cdot \tau_G (z,X,Y) 
			 \Longleftrightarrow \\
			 &\forall \lambda,\quad G(\lambda)\sum_{\xi\vdash
			   |\lambda|+\ell}a^{(2)}_{\lambda,\xi}\, \tH_\xi =  \sum_{\xi\vdash
			   |\lambda|+\ell}G(\xi) a^{(1)}_{\lambda,\xi}\, \tH_\xi \Longleftrightarrow\\
			 &\forall \lambda,\quad \sum_{\xi\vdash
			   |\lambda|+\ell}a^{(2)}_{\lambda,\xi}\, \tH_\xi =  \sum_{\xi\vdash
			   |\lambda|+\ell}G(\xi) a^{(1)}_{\lambda,\xi} G^{-1}(\lambda) \, \tH_\xi \Longleftrightarrow\\
		  &\forall \lambda,\quad \mcO_2\,
			\tH_\lambda = \Pi_G\cdot \mcO_1\cdot \Pi_G^{-1}\,\tH_\lambda, 
		\end{align*}
	which finishes the proof.
	\end{proof}

\subsection{Uniqueness}

\cref{thm:dif_eq} implies that if $\tau(z) \in \Lambda_X^\KK\otimes\Lambda_Y^\KK\llbracket z \rrbracket$ is equal to $\tau_G(z,X,Y)$, then $\tau(z)$ is a solution of a system of PDEs. We prove that the converse is also true, i.e. $\tau(z)$ is uniquely determined by the functional equations.
\begin{thm}\label{thm:uniqueness}
	Let $\tau(z) \in \Lambda_X^\KK\otimes\Lambda_Y^\KK\llbracket z \rrbracket$ be a function which satisfies the functional equations of \cref{thm:dif_eq}, and $\tau(z) = 1 + O(z)$. Then $\tau(z) = \tau_G(z,X,Y)$.
\end{thm}

It turns out that we can construct a basis of $\Lambda^\KK$ by repeatedly acting on $1$ with the operators $\A_F^{(\ell)}$. This construction leads to \cref{thm:uniqueness}.
We define for $\lambda\in \YY$
\begin{equation*}\label{eq:def_aaa}
  \aaa_{F,\lambda}:=\A_F^{(\lambda_1)}\cdot \A_F^{(\lambda_2)}\dotsm \A_F^{(\lambda_{\ell(\lambda)})}\cdot 1
\end{equation*}
which is a symmetric function of degree $|\lambda|$.
\begin{rmk}
    Since the operators $(\A_F^{(\ell)})_{\ell\geq 1}$ do not commute in general, taking a different order on the parts of $\lambda$ in the previous definition would lead to a different definition of the functions $\aaa_{F,\lambda}$.
\end{rmk}
\begin{prop}\label{prop:basis_a_lambda}
    For $F\in\left\{G_1,G_2\right\}$, the family $(\aaa_{F,\lambda})_{\lambda\in\YY}$ is a basis of $\Lambda^\KK$.
\end{prop}
Before proving this proposition, let us explain how it implies~\cref{thm:uniqueness}. 

For any partition $\lambda$, the differential equations \cref{eq:diff_eq2} allow us to write
\begin{multline*}
  z^{|\lambda|}\A_{G_1}^{(\lambda_1)}(X)\cdot \A_{G_1}^{(\lambda_2)}(X)\cdots \A_{G_1}^{(\lambda_{\ell(\lambda)})}(X)\cdot \tau(z)\\
  =\left(\A_{G_2}^{(\lambda_{\ell(\lambda)})}(Y)\right)^*\cdots  \left(\A_{G_2}^{(\lambda_2)}(Y)\right)^* \cdot\left(\A_{G_2}^{(\lambda_1)}(Y)\right)^*\cdot\tau(z).  
\end{multline*}
 We now extract the coefficient of $z^{|\lambda|}p_\emptyset[Y] =
 z^{|\lambda|}$. On the left-hand side we get
 \begin{align*}
    \A_{G_1}^{(\lambda_1)}(X)\cdots
   \A_{G_1}^{(\lambda_{\ell(\lambda)})}(X)\cdot\left[z^0 \right]\tau(z)
    &=\A_{G_1}^{(\lambda_1)}(X)\cdots \A_{G_1}^{(\lambda_{\ell(\lambda)})}(X)\cdot 1\\
    &=\aaa_{G_1,\lambda}(X).
 \end{align*}
 On the right-hand side, we obtain 
 \begin{align*}
   \left[z^{|\lambda|}p_\emptyset[Y] \right]&\left(\A_{G_2}^{(\lambda_{\ell(\lambda)})}(Y)\right)^*\cdots  \left(\A_{G_2}^{(\lambda_2)}(Y)\right)^* \cdot\left(\A_{G_2}^{(\lambda_1)}(Y)\right)^*\cdot \tau(z)\\
   &=\left\langle p_\emptyset[Y], \left[z^{|\lambda|}\right]\left(\A_{G_2}^{(\lambda_{\ell(\lambda)})}(Y)\right)^*\cdots  \left(\A_{G_2}^{(\lambda_2)}(Y)\right)^* \cdot\left(\A_{G_2}^{(\lambda_1)}(Y)\right)^*\cdot \tau(z)\right\rangle_*\\
   &=\left\langle \A_{G_2}^{(\lambda_1)}(Y)\cdot
   \A_{G_2}^{(\lambda_2)}(Y)\cdots \A_{G_2}^{(\lambda_{\ell(\lambda)})}(Y)\cdot 1, \left[z^{|\lambda|}\right]\tau(z)\right\rangle_*\\
   &=\left\langle \aaa_{G_2,\lambda}(Y), \left[z^{|\lambda|}\right]\tau(z)\right\rangle_*,
 \end{align*}
 where the scalar product is taken with respect to the alphabet $Y$. Let $\bbb_{F,\lambda}$ denote the dual basis of $\aaa_{F,\lambda}$, i.e.
 $$\left\langle\aaa_{F,\lambda}, \bbb_{F,\mu}\right\rangle_*=\delta_{\lambda,\mu}, \quad \text{for any $\lambda$ and $\mu$.}$$
Therefore, the differential equations imply that for any $\lambda$
\begin{equation*}
    \aaa_{G_1,\lambda}(X)=\left[z^{|\lambda|}\bbb_{G_2,\lambda}(Y)\right]\tau(z).
  \end{equation*}
  In other terms,
\begin{equation*}\label{eq:tau_G_formula}
	\tau(z)=\sum_{\lambda\in\YY}z^{|\lambda|}\aaa_{G_1,\lambda}(X)\bbb_{G_2,\lambda}(Y).  
\end{equation*}
This proves that $\tau(z)$ is completely determined  by the equations \cref{eq:diff_eq'}, and therefore $\tau(z)=\tau_G(z,X,Y)$.
\begin{rmk}
    Note that when $G_1=G_2$, the function $\tau_G(z,X,Y)$ corresponds to the Cauchy kernel (see \cref{eq:Cauchy}), and the previous equation follows from the fact that $\aaa_{G_1}$ and $\bbb_{G_1}$ are dual with respect to the star scalar product.
\end{rmk}

In order to conclude the proof of \cref{thm:uniqueness}, we need to prove \cref{prop:basis_a_lambda}. The proof of the latter is a direct consequence of the combinatorial expression for $\A_F^{\ell}$ is terms of the path operators, which we prove in \cref{sec:path_op}. This expression, together with \cref{thm:dif_eq} and \cref{thm:uniqueness} gives us our main \cref{thm:dif_eq'}.

\subsection{Rewriting in terms of path operators}
\label{sub:path_op}

Recall that for any $\beta \in \ZZ^\ell$ we denote $\bR_\beta$ the set of alternating paths that start and end at the same points as $\gamma_\beta$ (i.e. have the same length and degree) and that stay weakly above $\gamma_\beta$. 

From now on, we will be working with sequences $\beta \in \ZZ_{>0}\times \ZZ_{\geq 0}^{\ell-1}$ and we will use an alternative description of path operators as \emph{paths decorated with particles}: we think of a path $\gamma\in \bR_\beta$ as an alternating path starting at $(0,0)$ ending at $(2\ell,\sum_{1\leq i\leq \ell}\beta_i)$ and such that:
\begin{itemize}
    \item  the $i$-th peak is decorated with $\beta_i$ particles, 
    \item for each valley $V$ of $\gamma$, the $y$-coordinate is at least the number of particles sitting on peaks on the left of $V$. The $\beta$-height of $V$ (as defined in \cref{eq:def_height}) is given by the difference between these two integers.
\end{itemize}
Notice that the condition $\beta \in \ZZ_{>0}\times \ZZ_{\geq 0}^{\ell-1}$ implies that there is always  at least one particle on the first peak.

We are now ready to give our second parametrization of path operators. If $\beta$ is a sequence of size $n$, we define $\alpha := \psi(\beta) \in \ZZ_{\geq 0}^n$ as the sequence consisting of the distances between consecutive particles of a path $\gamma\in\bR_\beta$, where the distance is interpreted as the number of peaks between the particles. By convention, $\alpha_n$ is the number of peaks after the last particle. We refer to~\cref{fig:RtoQ} for an example.


Equivalently, $\alpha=\psi(\beta)$ is the sequence obtained from $\beta$ as follows: we start from the empty sequence $\alpha=\emptyset$, and we read the sequence $\beta$ from left to right; each time we read an integer $i$ we add a sequence of $i$ zeroes, and we increase the right-most integer of $\alpha$ by 1, except at the end of the procedure -- in which case we only add a sequence of $i$ zeroes. We refer to \cref{fig:RtoQ} for an example.

\begin{figure}[h]
	\centering
	\includegraphics[width = \linewidth]{Path7.pdf}
	\caption{A path $\gamma$ belonging to $\bR_{(1,2,0,1)}$ with the associated path $\gamma_\beta$ on the left. On the right we visualize vector $\beta = (1,2,0,1)$ by placing particles over the peaks, and we reparametrize the set $\bR_{(1,2,0,1)}$ as $\bQ_{(1,0,2,0)}$ by interpreting $(1,0,2,0) = \psi(1,2,0,1)$ as the distances between the particles.}
	\label{fig:RtoQ}
\end{figure}

This defines a bijection $\psi$ between sequences in $\ZZ_{>0}\times \ZZ_{\geq 0}^{\ell-1}$ with size $n$ and sequences in $\ZZ_{\geq 0}^{n}$ with size $\ell-1$. Therefore, for any $\alpha \in \ZZ_{\geq 0}^{n}$ we can reparametrize the set $\bR_\beta$ as $\bQ_\alpha$, where $\beta := \psi^{-1}(\alpha)$, and similarly
\begin{equation}\label{eq:Q^alpha-Q_alpha}
	\mcQ_{\alpha}:=\mcR_{\psi^{-1}(\alpha)}=\sum_{\bfgamma\in\bR_{\psi^{-1}(\alpha)}}\mcO_{\psi^{-1}(\alpha)}(\gamma).  
  \end{equation}

\begin{exe}\label{exe:R_k}
For any $r\geq 0$, we have $\mcQ_{(r)}=\mcR_{(1,0^r)}$ and $\mcQ_{(0^r)}=\mcR_{(r)}$.    
\end{exe}

Our goal is to show that for $F(\hbar) = \sum_{i\geq 0} a_i \hbar^i \in \{G_1, G_2\}$, one has the following expression for the operator $\A_F^{(\ell)}$ (as defined on \cref{def:AFell}):
\begin{thm}\label{thm:dif_eq''}
	For any $\ell\geq 1$, we have
	\begin{equation}\label{eq:diff_eq'}
		\A_F^{(\ell)} = \sum_{\alpha} a_\alpha \mcQ_\alpha,
	\end{equation}
	where the sum is taken over $\alpha \in \ZZ_{\geq 0}^{\ell}$, and $a_\alpha := \prod_{i=1}^\ell a_{\alpha_i}$.
\end{thm}
Informally, $\A_F^{(\ell)}$ corresponds then to the sum over all path operators with $\ell$ particles, with an extra weight $a_i$ for a distance $i\geq 0$ between two particles. 

We devote the whole \cref{sec:path_op} to proving this theorem. Before we present the proof, let us show how \cref{thm:dif_eq''} implies \cref{prop:basis_a_lambda}, and thus \cref{thm:uniqueness} and \cref{thm:dif_eq'}.

\begin{proof}[Proof of Proposition \ref{prop:basis_a_lambda}]

	We start by proving that $\aaa_{F,\lambda}$ is a basis when $q=t=1$. In this case, $M=0$ and the derivative parts of the path operators (defined in \cref{eq:def_step_operator}) become
	$$\mcO(m)_{\big|q=t=1}=\left\{\begin{array}{cc}
		 1&\text{if } m=0   \\
	   0&\text{if } m<0.
	\end{array}\right.$$
	As a consequence, only paths with no down steps contribute to the expansion of a path operator $\mcQ_\alpha$ \cref{eq:Q^alpha-Q_alpha}, and all paths operators becomes multiplicative. More precisely, for $\alpha\in\ZZ_{\geq 0}^\ell$ we have
	$${\mcQ_{\alpha}}_{\big|q=t=1}=(-1)^{\ell}e_{\ell}+\sum_{\substack{\mu \vdash \ell\\{\ell(\mu)>1}}}c_\mu e_\mu,$$
	for some coefficients $c_\mu$. Indeed, the term in $e_{\ell}$ corresponds to paths for which all steps are flat except for the first one which has size $\ell$. We deduce that the coefficient of this term in the operator $\A_{F}^{(\ell)}$ is given by
	\begin{equation}
	  (-1)^\ell[e_\ell]\A_{F}^{(\ell)}\cdot 1_{\big | q=t=1}=\sum_{\alpha\in\ZZ_{\geq 0}^\ell} a_\alpha=\left(\sum_{k\geq 0} a_k\right)^\ell.
	\end{equation}
	Note that this quantity is well defined and invertible in the space of formal power series $\KK$ since $a_0=1$ for $F\in\{G_1, G_2\}$.
	We deduce the expansion of $\aaa_\lambda$ in the elementary basis:
	$$(-1)^{|\lambda|}\aaa_{F,\lambda} {}_{\big | q=t=1}=e_\lambda\prod_{1\leq i\leq \ell(\lambda)}\sum_{\alpha \in \ZZ_{\geq 0}^{\lambda_i}} a_\alpha+\sum_{\mu<\lambda}d_{\mu}e_\mu,$$
	for some coefficients $d_\mu \in \KK$, and the rightmost sum is over partitions $\mu$ smaller than $\lambda$ with respect to the dominance order.
	By triangularity, we deduce that $\aaa_{F,\lambda}$ is a basis for $\Lambda$, when $q=t=1$.


	 Let $\mathcal{M}_n$ be the matrix of $(\aaa_{F,\lambda})_{\lambda\vdash n}$ in the elementary basis $(e_\mu)_{\mu\vdash n}$. Since the evaluation $\aaa_{F,\lambda}(q=t=1)$ is a basis, then $\det(\mathcal{M}_n)(q=t=1)$ is invertible in $\KK$. In particular,  
	$\det(\mathcal{M}_n)$ is also invertible in $\KK$, which finishes the proof.
	\end{proof}

\section{Building the path operators}
\label{sec:path_op}


In order to prove \cref{thm:dif_eq''}, we will study commutation relations between more and more complicated operators, starting from very simple ones. These commutation relations will have a natural interpretation in terms of extending simpler paths to more complicated ones.

The section is organized as follows: in \cref{ssec:path_prel} we give some preliminary results about $q$-integers and path operators. \cref{ssec:first_comm_rel} is devoted to commutation relations of operators with only one particle giving a combinatorial interpretation of the operators $\A_F$ (\cref{eq:A_F}). In \cref{ssec:second_comm_rel} we prove a family of commutation relations for symmetrized version of the operators $\mcQ_\alpha$ (see \cref{thm:P_commutation}).  Finally, we finish the proof of \cref{thm:dif_eq''} in \cref{ssec:proof_comb_formula}.
\subsection{Preliminaries}\label{ssec:path_prel}

We use the usual notation for $q$-integers;
$$[m]_q:=
\left\{
\begin{array}{cc}
    1+q+\dots+q^{m-1} & \text{if $m>0$}  \\
    -(1+q+\dots+q^{-m-1}) & \text{if $m<0$}\\
    0 & \text{if $m=0$}.
\end{array}\right.$$

\begin{lem}\label{lem:h_specialized}
  Let $n > 0$. We have
  \begin{align*}
    \frac{h_n\left[M\right]}{M} &= [n]_{qt},\\
    \frac{h_n\left[-M\right]}{-M} &= t^{n-1}[n]_{qt^{-1}} = q^{n-1}[n]_{tq^{-1}}. 
\end{align*}
  \end{lem}
  \begin{proof}
    This is an easy computation which relies on the following identities:
    \[ h_n[1+qt] = [n+1]_{qt}, \qquad h_n[q+t] = t^{n}[n+1]_{qt^{-1}} =
    q^{n}[n+1]_{tq^{-1}},\]
    for the homogeneous functions,
    \[e_n[1+qt] = \begin{cases} 1 &\text{ if } n = 0,\\
        1 +qt &\text{ if } n = 1,\\
        qt &\text{ if } n = 2,\\
      0 &\text{ if } n >2,\end{cases}, \qquad e_n[q+t] = \begin{cases} 1 &\text{ if } n = 0,\\
        q +t &\text{ if } n = 1,\\
        qt &\text{ if } n = 2,\\
        0 &\text{ if } n >2,\end{cases},\]
    for elementary functions, and the following recursions:
    \begin{align*}
        h_n\left[(1-t)(1-q)\right]
        &=\sum_{0\leq i\leq n}(-1)^{n-i}e_{n-i}\left[q+t\right]h_i\left[1+qt\right],\\
        h_n\left[-(1-t)(1-q)\right]
        &=\sum_{0\leq i\leq n}(-1)^{n-i}e_{n-i}\left[1+qt\right]h_i\left[q+t\right].\qedhere
    \end{align*}
\end{proof}

Recall the following commutation relation of \cref{eq:mcT-mcP'}:
 \begin{equation}\label{eq:mcT-mcP}
  \mcT_Y\cdot \mcP_Z=\Omega[YZ]\mcP_Z\cdot \mcT_Y,   
 \end{equation}
or equivalently
\begin{equation}\label{eq:mcT-mcP2}
\Omega[-YZ]\mcT_Y\cdot \mcP_Z=\mcP_Z\cdot \mcT_Y.
\end{equation}
Define $k \wedge r := \min(k,r), k \vee r := \max(k,r)$. We start from the following commutation relations for the one step operators $\mcO(k)$ defined in \cref{eq:def_step_operator}.

\begin{lem}\label{lem:com_h}
For any $k,r\geq 0$ we have
\begin{align}\label{eq:com_h2}
    \left[\mcO(-k),\mcO(r)\right]
        &=-M\sum_{1\leq i\leq k\wedge r} t^{i-1}[i]_{qt^{-1}}\cdot \mcO(r-i)\mcO(-(k-i))\\
        &=-M\sum_{1\leq i\leq k\wedge r} [i]_{qt}\cdot \mcO(-(k-i))\mcO(r-i).\label{eq:com_h}
    \end{align}
\end{lem}


\begin{proof}

    We take $Y=-z_1$ and $Z=M/z_2$ in \cref{eq:mcT-mcP} and \cref{eq:mcT-mcP2} respectively, and we extract the coefficient of $z_1^rz_2^{-k}$.
    We get
      \begin{align*}
    \left[h^\perp_k[MX],(-1)^r e_r[X]\right]
        =\sum_{1\leq i\leq k\wedge r} h_{i}[-M]\cdot (-1)^{r-i}e_{r-i}[X]h^\perp_{k-i}[MX]\\
        =-\sum_{1\leq i\leq k\wedge r} h_{i}[M]\cdot h^\perp_{k-i}[MX](-1)^{r-i}e_{r-i}[X].
    \end{align*}
    We conclude using the identities of \cref{lem:h_specialized} and the definition of the operators $\mcO(i)$ (\cref{eq:def_step_operator}).
\end{proof}

\subsection{First commutation relation}\label{ssec:first_comm_rel}
The main purpose of this section is to prove a first commutation relation, which gives a formula for the operator $\A_F$ (see \cref{eq:A_F}) in terms of path operators\footnote{We will give in \cref{prop:D0_P} an analog of this result for any operator $\mcQ_\alpha$.}.

 \begin{thm}[First commutation relation]\label{thm:A_n-P_n}
The following relations hold:
$$\frac{-1}{M}\left[D_{0},-e_1[X]\right] = \mcQ_{0},\qquad \frac{-1}{M}\left[D_{0},\mcQ_{n-1}\right] = \mcQ_{n},$$
for all $n \geq 1$. As a consequence,
    $$\A_F = -e_1[X]+\sum_{n \geq 0}a_{n+1}\mcQ_n.$$
\end{thm}

Without further mention, all paths in this section are one particle operators i.e paths decorated with only one particle on the first peak. In other terms, they belong to a set $\bR_{1,0^{n}}=\bQ_{n}$ for some $n\geq 0$.

The first step is to interpret combinatorially the commutation relations of \cref{lem:com_h}. We introduce the following definition.
\begin{defi}\label{def:path_extension}
    Consider an alternating path $\gamma=(\gamma_1,\gamma_2,\dots,\gamma_{2n})$. Let $1\leq j\leq 2n$ such that $r:=\gamma_j\neq 0$.

    We say that a path $\gamma'$ of length $2n+2$ is obtained by extending the $j$-th step of $\gamma$ and we write $\gamma\nearrow_j\gamma'$, if the step $\gamma_j$ is replaced by three steps $\gamma'_j,\gamma'_{j+1},\gamma'_{j+2}$ as follows.
    \begin{itemize}
        \item If $r>0$, then $(\gamma'_j,\gamma'_{j+1},\gamma'_{j+2})=(k,-(k-i),r-i)$, for some integers $k>0$ and $0<i\leq k\wedge r$.
        \item If $r<0$, then $(\gamma'_j,\gamma'_{j+1},\gamma'_{j+2})=(r+i,k-i,-k)$ for some
          integers $k>0$ and $0<i\leq k\wedge -r$.
    \end{itemize}
    These two cases are illustrated in \cref{fig:add_valley}. 
    The ordered pair of valleys involved in this extension (given from left to right) will be denoted $\Valley(\gamma\nearrow_j\gamma')$. In other terms,
    $\Valley(\gamma\nearrow_j\gamma')=(V,V')$
    where $V$ and $V'$ are the valleys of $\gamma'$ with respective $x$-coordinates $2\lfloor\frac{j}{2} \rfloor$ and $2\lfloor \frac{j}{2}\rfloor+2$). 

    When $\gamma_j=0$, the extension set $\gamma\nearrow_j\gamma'$ will be empty by convention.
\end{defi}
Note that when the $j$-th step of $\gamma$ is extended, the indices of the steps on its right increase by 2: $\gamma_l=\gamma'_{l+2}$ for any $i<l\leq 2n$. Moreover, if the step $\gamma_j$ is incident to a valley $V$, the extension operation creates a valley $\tilde V$ whose $y$-coordinate is larger than the $y$-coordinate of $V$. 



\begin{exe}
    Consider the following alternating paths
    \begin{equation*}
        \left\{\begin{array}{l}
    \gamma=(3,-2,4,-2), \\
    \gamma'=(3,-2,6,-5,3,-2),\\
    \gamma''=(3,0,0,-2,4,-2).
        \end{array}\right.
    \end{equation*}

    Then $\gamma'$ is obtained form $\gamma$ by extending the third step of $\gamma$, and $$\Valley(\gamma\nearrow_5\gamma')=((2,1),(4,2)).$$
    Moreover, $\gamma''$ can be obtained by extending either the first or the second step of $\gamma$.
\end{exe}

\begin{rmk}\label{rmk:extension_parity}
Note that the extension valleys $\Valley(\gamma\nearrow_j\gamma')=(V,V')$ (from left to right) always have different $y$-coordinates. Furthermore, $y_{V'}>y_{V}$ if and only if the step extended is an up step ($j$ is odd). 
\end{rmk}


