It turns out that commuting one particle operators with $\frac{-D_0}{M}$ corresponds to extending paths. 
\begin{lem}\label{lem:com_path_D0}
    Let $\gamma=(\gamma_1,\dots \gamma_{2n}) \in \bQ_{(n-1)} = \bR_{(1,0^{n-1})}$. Then
    \begin{equation*}\label{eq:cometa1}
		\ad_{\frac{D_0}{-M}}\left(\mcO_{(1,0^{n-1})}(\gamma)\right)=\sum_{1\leq i\leq 2n}\sum_{\gamma\nearrow_i\gamma'}\left([y_{V'}]_{(qt)^{-1}}-[y_{V}] _{(qt)^{-1}}\right)\mcO_{(1,0^{n})}(\gamma'),
    \end{equation*}
    where the second sum is taken over all paths $\gamma'$ obtained by extending the $i$-th step of $\gamma$, and where $\Valley(\gamma\nearrow_i\gamma')=(V,V').$
\end{lem}



\begin{proof}
Fix $r>0$. Then by \cref{lem:com_h}, we have
\begin{align*}
  \left[D_0,\mcO(r)\right]
  &=\sum_{k\geq 0}\Big[\mcO(k) \cdot \mcO(-k),\mcO(r)\Big]\\
  &=\sum_{k\geq 0}\mcO(k)\cdot \Big[\mcO(-k),\mcO(r)\Big]\\
  &=-M\cdot \sum_{k\geq 0}\sum_{1\leq i\leq k\wedge r}\left[i\right]_{qt}\mcO(k)\cdot \mcO(-(k-i))\mcO(r-i).
\end{align*}

Similarly if $r<0$, we have
\begin{align*}
  \left[D_0,\mcO(r)\right]
  &=\sum_{k\geq 0}\Big[\mcO(k)\cdot \mcO(-k),\mcO(r)\Big]\\
  &=\sum_{k\geq 0}\Big[\mcO(k),\mcO(r)\Big]\mcO(-k)\\
  &=-M\cdot\sum_{k\geq 0}\sum_{1\leq i\leq k\wedge -r}[-i]_{qt}\mcO(r+i)\cdot \mcO(k-i)\cdot \mcO(-k).
\end{align*}

Note that the summands in these equations correspond precisely to the possible ways of extending a step of degree $r$ in an alternating path as in \cref{def:path_extension}. More precisely, we have
\begin{align*}
	\ad_{\frac{D_0}{-M}}\left(\mcO_{(1,0^{n-1})}(\gamma)\right)
&=\frac{-1}{M}\sum_{1\leq i \leq 2n}\vweight_{(1,0^{n-1})}(\gamma)\mcO(\gamma_1)\dots \mcO(\gamma_{i-1})[D_0,\mcO(\gamma_i)]\mcO(\gamma_{i+1})\dots \mcO(\gamma_{2n})\\
&=\sum_{1\leq i \leq 2n}
\sum_{\gamma\nearrow_i\gamma'}[y_{V'}-y_V]_{qt}\vweight_{(1,0^{n-1})}(\gamma)\mcO(\gamma'_1)\dots  \mcO(\gamma'_{2n+2}).
\end{align*}
Notice that 
$$\vweight_{(1,0^{n})}(\gamma')=(qt)^{\height_{(1,0^{n})}(W)}\vweight_{(1,0^{n-1})}(\gamma),$$
where $W$ 
is the valley with the larger height among $(V,V'):=\Valley(\gamma\nearrow_i\gamma')$. As a consequence,
$$\vweight_{(1,0^{n})}(\gamma')=(qt)^{\max(\height_{(1,0^{n})}(V),\height_{(1,0^{n})}(V'))}\vweight_{(1,0^{n-1})}(\gamma)=(qt)^{\max(y_V,y_{V'})-1}\vweight_{(1,0^{n-1})}(\gamma).$$
We then have
\begin{align*}
	\ad_{\frac{D_0}{-M}}\left(\mcO_{(1,0^{n-1})}(\gamma)\right)
&=\sum_{1\leq i \leq 2n}
\sum_{\gamma\nearrow_i\gamma'}[y_{V'}-y_V]_{qt}(qt)^{1-\max(y_V,y_{V'})}\vweight_{(1,0^{n})}(\gamma')\mcO(\gamma'_1)\dots  \mcO(\gamma'_{2n+2})\\
&=\sum_{1\leq i \leq 2n}
\sum_{\gamma\nearrow_i\gamma'}[y_{V'}-y_V]_{qt}(qt)^{1-\max(y_V,y_{V'})}\mcO_{(1,0^{n})}(\gamma').
\end{align*}
We conclude using the fact that 
\begin{equation*}
  [y_{V'}-y_V]_{qt}(qt)^{1-\max(y_V,y_{V'})}=[y_{V'}]_{(qt)^{-1}}-[y_V]_{(qt)^{-1}}.\qedhere
\end{equation*}
\end{proof}



\begin{proof}[Proof of \cref{thm:A_n-P_n}]
We have
\begin{multline*}
	\frac{-1}{M}\left[D_{0},-e_1[X]\right]
        =\frac{-1}{M}\Big[\sum_{k\geq 0}\mcO(k)\cdot \mcO(-k),-e_1[X]\Big]\\
               =\sum_{k\geq 1}\mcO(k)\cdot \mcO(-(k-1))
               =\sum_{\gamma\in\bQ_{(0)}} \mcO_{(1)}(\gamma)
               =\mcQ_0,
             \end{multline*}
where the second equation is a consequence of~\eqref{eq:com_h}. 
Let $n\geq 1$. From \cref{lem:com_path_D0}, we have
 \[ \frac{-1}{M}\left[D_{0},\mcQ_{n-1}\right]
        =\sum_{\gamma \in \bQ_{(n-1)}} \ad^i_{\frac{D_0}{-M}}(\mcO_{(1,0^{n-1})}(\gamma))\\
        =\sum_{\gamma \in \bQ_{(n-1)}} \sum_{1\leq i\leq 2n} \sum_{\gamma\nearrow_i\gamma'} \left([y_{V'}]_{qt}-[y_{V}]_{qt}\right)\mcO_{(1,0^{n})}(\gamma'),\]
where $V$ and $V'$ are the two points of $\Valley(\gamma\nearrow_i\gamma')$ from left to right.
    \medskip

We now invert the two sums in the previous equation. To this purpose,
we note that for a fixed $\gamma'\in\bQ_{(n)}$ there is a one-to-one correspondence between:
\begin{itemize}
  \item pairs
$(V_j,V_{j+1})\subset
  \Valley(\gamma')$ of consecutive valleys of $\gamma'$ with different $y$-coordinates ($0\leq j\leq n$),
\item pairs $(\gamma, i)$, where $\gamma \in
  \bQ_{(n-1)}$, $1\leq i\leq 2n$ satisfying $\gamma \nearrow_i \gamma'$,
  \end{itemize}
  such that $\Valley(\gamma\nearrow_i\gamma')=(V,V').$ This correspondence is given by 
  \begin{equation*}
  \left\{
      \begin{array}{ll}
        i=1   & \text{if $j=0$}, \\
         i=2n  & \text{if $j=n$}\\
         i\in \left\{2j,2j+1\right\} &\text{if $1\leq j\leq n-1$},
      \end{array}\right.
  \end{equation*}
and the parity of $i$ is fixed by \cref{rmk:extension_parity}.
We then get
$$\frac{-1}{M}\left[D_{0},\mcQ_{n-1}\right]=\sum_{\gamma' \in \bQ_{(n)}}\mcO_{(1,0^n)}(\gamma')\sum_{0\leq j\leq n}\left([y_{V_{j+1}}]_{qt}-[y_{V_j}]_{qt}\right),$$
where $V_j$ is the valley $\gamma'$ with $x$-coordinate $2j$. Since $y_{V_0}=0$ and $y_{V_{n+1}}=1$, we deduce that
\begin{equation}\label{eq:com_D0_Pn}
	\frac{-1}{M}\left[D_{0},\mcQ_{n-1}\right] = \mcQ_{n} 
\end{equation}
as required.
\end{proof}

\subsection{Second commutation relation}\label{ssec:second_comm_rel}

We now prove a second commutation relation allowing us to obtain path operators with $\ell$ particles from path operators with $\ell-1$ particles.
Let $\alpha \in \mathbb{Z}_{\geq 0}^\ell$, and define the symmetrized operator:
$$\Qsym_\alpha:=\sum_{\sigma\in\mathfrak{S}_{\ell}}\mcQ_{\sigma(\alpha)},  
$$
where we denote the sequence $\sigma(\alpha):=(\alpha_{\sigma(1)},\dots,\alpha_{\sigma(\ell))})$. Let us introduce two simple operations on vectors $\alpha \in
\mathbb{Z}_{\geq 0}^\ell$: for $1\leq i\leq \ell$, we denote 
\begin{itemize}
  \item $\alpha^{\downarrow i}:=(\alpha_1,\dots,\alpha_{i-1},\alpha_{i+1},\dots,\alpha_\ell),$
\item $\alpha^{+ i} :=
  (\alpha_1,\dots,\alpha_{i-1},\alpha_{i}+ 1,\alpha_{i+1},\dots,\alpha_\ell).$
  \end{itemize}

The main result of this section is the following recursive formula for the operators $\Qsym_\alpha$.
\begin{thm}[Second commutation relation]\label{thm:P_commutation}
Let $\alpha \in \mathbb{Z}_{\geq 0}^\ell$ be a sequence of non-negative integers of length $\ell\geq2$. We then have
$$\Qsym_\alpha=\frac{1}{M}\sum_{1\leq i\leq \ell}\left[\ad^{\alpha_i}_{\frac{D_0}{-M}}\left(-e_1[X]\right),\Qsym_{\alpha^{\downarrow i}}\right].$$
\end{thm}
\begin{rmk}
we know from the first commutation relation (\cref{thm:A_n-P_n}), that if $\alpha_i>0$ then
$$\ad^{\alpha_i}_{\frac{D_0}{-M}}\left(-e_1[X]\right)=\mcQ_{\alpha_i-1}.$$
Intuitively, one can then think of the second commutation relation as follows: the symmetrized operator $\Qsym_\alpha$ is obtained by removing (in all possible ways) a part $\alpha_i$ from $\alpha$, and then commuting the operator obtained with $\mcQ_{\alpha_i-1}/M$.
\end{rmk}

To simplify notation,  we will write in this section
$$[n]:= [n]_{(qt)^{-1}}.$$

\begin{lem}\label{lem:com_path_e1}
Fix an alternating path $\gamma \in \bR_{\beta}$ of length $2n+2$. Then
\begin{equation*}\label{eq:come_1}
        \left[\frac{e_1[X]}{-M}, \mcO_{\beta}(\gamma)\right]=\sum_{1\leq i\leq n+1}\mathbbm{1}_{\gamma_{2i}<0}\mcO_{\beta^{+i}}(\gamma^{+i}),
    \end{equation*}
    where $\gamma^{+i} \in \bR_{\beta^{+i}}$ is the alternating path obtained from
    $\gamma$ by replacing the $2i$-th step by $\gamma^{+i}_{2i}=\gamma_{2i}+1$ if possible (i.e if $\gamma_{2i}\neq 0$).
\end{lem}
\begin{exe}
Consider the path $\gamma=(3,-1,2,-1,1,0,1,-1)\in \bR_{(1,2,0,1)} = \bQ_{(1,0,2,0)}$ given in~\cref{fig:RtoQ}.
    Then the path $\gamma^{+2}=(3,-1,2,0,1,0,1,-1) \in \bR_{(1,3,0,1)} = \bQ_{(1,0,0,2,0)}$ is well defined, while $\gamma^{+3}$ is not.
\end{exe}
\begin{proof}[Proof of \cref{lem:com_path_e1}]
    This is a consequence of the fact that
$$\vweight_{\beta}(\gamma)=\vweight_{\beta^{+i}}(\gamma^{+i}),$$
	and of the following commutation relation, obtained by taking $r=1$ in \cref{eq:com_h2}:
    \begin{equation*}
      \left[\frac{e_1[X]}{-M},\mcO(m)\right]=\left\{\begin{array}{ll}
         \mcO(m+1)&\text{if $m<0$},  \\
         0 & \text{if $m\geq 0$.}
    \end{array}\right.\qedhere  
    \end{equation*}
\end{proof}

 Recall from \cref{sub:path_op} that for any $\alpha \in \ZZ^n_{\geq 0}$ one has $\bQ_\alpha = \bR_{\psi^{-1}(\alpha)}$, where $\psi$ is a bijection between sequences in $\ZZ_{>0}\times \ZZ_{\geq 0}^{\ell-1}$ with size $n$ and sequences in $\ZZ_{\geq 0}^{n}$ with size $\ell-1$. This bijection switches from the parametrization by the number of particles over peaks to the distances between particles. Since we always have at least one particle over the first peak, the first particle will be always thought of as a \textit{frozen} particle. All the other particles are \textit{non-frozen}.

The following lemma allows us to relate some series of path operators where we have moved the position of one marked non-frozen particle by one step.
\begin{lem}\label{lem:move_peak}
For any $\alpha \in \mathbb{Z}_{\geq 0}^\ell$ and $1\leq i\leq \ell-1$, we have
\begin{equation}\label{eq:move_peak}
\sum_{\gamma \in\bQ_{\alpha^{+i}}}\left([\height_{\beta}(V_i)+1]-1\right)\mcO_{\beta}(\bfgamma) =\sum_{\gamma\in\bQ_{\alpha^{+(i+1)}}}[\height_{\beta'}(V_i')+1]\mcO_{\beta'}(\bfgamma),
\end{equation}
where $V_i$ (resp. $V'_i$) is the valley preceding (resp. succeeding) the $i+1$-th particle, $\beta = \psi^{-1}(\alpha^{+i})$, and $\beta' = \psi^{-1}(\alpha^{+(i+1)})$.
\end{lem}

\begin{proof}
First, notice that $\bQ_{\alpha^{+(i+1)}} \subset \bQ_{\alpha^{+i}}$. This is obvious, when we think that $\bQ_{\alpha^{+i}}$ is obtained from $\bQ_{\alpha^{+(i+1)}}$ by moving the
$i+1$-th particle to the right (note that this is well defined since the length between the $i+1$-th and the
$i+2$-th particle in $\bQ_{\alpha^{+(i+1)}}$ given by $\left(\alpha^{+(i+1)}\right)_{i+1}$ is at least $1$; see~\cref{fig:move_marked_peak}). In particular $\beta ' = \psi^{-1}(\alpha^{+(i+1)}) = (\beta_1,\dots,\beta_{k}+1,\beta_{k+1},\dots,\beta_{n+1})$ for some $1 \leq k \leq n$, and $\beta = \psi^{-1}(\alpha^{+i}) = (\beta_1,\dots,\beta_{k},\beta_{k+1}+1,\dots,\beta_{n+1})$, so that
$$\vweight_{\beta}(\gamma)=qt\cdot \vweight_{\beta'}(\gamma)$$
for any $\gamma\in \bQ_{\alpha^{+(i+1)}}$.
We deduce that 
\begin{equation}\label{eq:move_peak_2}
\mcO_{\beta}(\gamma)=qt\cdot \mcO_{\beta'}(\gamma).
\end{equation}


Moreover,
$\bQ_{\alpha^{+i}}\backslash\bQ_{\alpha^{+(i+1)}}$
consists of paths in $\bQ_{\alpha^{+i}}$ such that the valley
preceding the $i+1$-th particle has minimal $\beta$-height, i.e.~$\height_{\beta}(V_i)=0$.
In particular, $([\height_{\beta}(V_i)+1]-1) = 0$, so that the contribution of all these paths
in the sum on the left-hand side
of~\cref{eq:move_peak} is zero. Therefore this sum can be rewritten as
\begin{align*}
\sum_{\gamma \in \bQ_{\alpha^{+(i+1)}}}\left([\height_\beta(V_i)+1]-1\right)\mcO_\beta(\gamma)
&=\sum_{\gamma \in \bQ_{\alpha^{+(i+1)}}}\left([\height_{\beta'}(V'_i)+2]-1\right)\mcO_\beta(\gamma)\\
&=\sum_{\gamma \in \bQ_{\alpha^{+(i+1)}}} qt\left([\height(V'_i)_{\beta'}+2]-1\right)\mcO_{\beta'}(\gamma).
\end{align*}
We used here the fact that $\height_\beta(V_i)=\height_{\beta'}(V'_i)+1$ and \cref{eq:move_peak_2}. We conclude with the fact that $qt\left([n+1]-1\right)=[n]$, for any $n\geq 0$.\qedhere
\end{proof}

