\begin{prop}\label{prop:D0_P}
    Let $\alpha \in \left(\mathbb{Z}_{\geq 0}\right)^{\ell}$.
    Then $$\left[-D_{0}/M,\mcQ_{\alpha}\right]=\sum_{1\leq i \leq \ell}\mcQ_{\alpha^{+i}}.$$
\end{prop}
Notice that \cref{eq:com_D0_Pn} corresponds to the special case of paths with one decorating particle (i.e $\ell=1$) in the previous proposition.


Before proving this proposition we define path extensions for path decorated with arbitrarily many particles. This definition generalizes \cref{def:path_extension} in which we treated the one-particle case. We recall that in this case a path is extended  by ``inserting'' two steps following some rules, and the first particle is always on the first peak. 

\begin{defi}
    Let $\gamma \in \bR_{\beta}$ be an alternating path of length $2n$. We say that a pair $(\gamma',\beta')$ is obtained by extending the $i$-th step of the pair $(\gamma,\beta)$ and we write $(\gamma,\beta)\nearrow_i(\gamma',\beta')$, if we have an extension for the underlying paths $\gamma\nearrow_i\gamma'$ as in \cref{def:path_extension}, and if $\beta'$ is given by
    \begin{equation*}
        \beta'=\left\{\begin{array}{ll}
          (1,\beta_1-1,\beta_2,\dots,\beta_n)      &  \text{if $i=1$}\\
              (\beta_1,\dots,\beta_{\lfloor \frac{i}{2}\rfloor},0,\beta_{\lfloor \frac{i}{2}\rfloor+1},\dots,\beta_{n})& \text{if $i > 1$.}
        \end{array}\right.
    \end{equation*}
    In terms of particles, this means that the (non-frozen) particles are moved with respect to the following rules (see \cref{fig:add_marked_peak}): 
\begin{itemize}
    \item when we extend an up-step connected to a peak decorated by $s$ non-frozen particles, these particles all go to the right peak after the extension,
    \item when we extend a down-step connected to a peak decorated by $s$ particles, all of them go to the left peak after the extension.
\end{itemize}
Note that these rules for particle positions are in such a way that the created valley has always a non-negative $\beta'$-height, and in particular $\gamma'\in \bR_\beta$.
\end{defi}

\begin{proof}[Proof of \cref{prop:D0_P}]
Let $2n:=2|\alpha|+2$ be the length of a path in $\bQ_\alpha = \bR_\beta$. Recall also that $\ell=\ell(\alpha)$ is the number of particles of such path.
Using the same arguments as in
\cref{lem:com_path_D0}, we get that for any $\gamma\in \bQ_\alpha$
$$\left[-D_0/M, \mcO_\beta(\gamma)\right]=\sum_{1\leq i\leq
2n}\sum_{(\gamma,\beta)\nearrow_i(\gamma',\beta')}\mcO_{\beta'}(\gamma')\left([\theight_{\beta'}(V')]-[\theight_{\beta'}(V)]\right),$$
where $(V,V')=\Valley(\gamma\nearrow_i\gamma')$ and 
\begin{align*}
  \theight_{\beta')}(V)
  &=y_V-\#\text{non-frozen particles on the left of $V$}\\
  &=\left\{
\begin{array}{cc}
     \height_{\beta'}(V)+1&  \text{if $x_V>0$} \\
     0 &\text{if $x_V=0$}. 
\end{array}
\right.  
\end{align*}
We now sum over $\gamma\in\bQ_\alpha$ and we invert the sums as in the proof of \cref{thm:A_n-P_n}. We get
$$\left[-D_0/M, \mcQ_{\alpha}\right]=\sum_{\substack{1\leq i\leq
    \ell:\\ \alpha_i > 0 \text{ or } i\in\{1,\ell\} }}\left(\sum_{\gamma\in\bQ_{\alpha^{+i}}}\mcO_{\psi^{-1}(\alpha^{+i})}(\gamma)\sum_{(V,V')}\left([\theight_{\psi^{-1}(\alpha^{+i})}(V')]-[\theight_{\psi^{-1}(\alpha^{+i})}(V)]\right)\right),$$
where the third sum runs over all pairs of consecutive valleys
$(V,V')$ (in this order) lying:
\begin{itemize}
    \item before the second particle if $i=1$,
    \item after the last particle if $i=\ell$,
    \item between the $i$-th and the $i+1$-th particle if $1<i<\ell$.
\end{itemize}
 Note that
this set is not empty, because $(\alpha^{+i})_i >1$ whenever $\alpha_i>0$. The telescopic sum gives
\[ \sum_{(V,V')}\left([\theight_{\psi^{-1}(\alpha^{+i})}(V')]-[\theight_{\psi^{-1}(\alpha^{+i})}(V)]\right) =
  [\theight_{\psi^{-1}(\alpha^{+i})}(V_i)]-[\theight_{\psi^{-1}(\alpha^{+i})}(V'_{i-1})]\]
where $V_i$ (resp. $V'_i$) is the valley preceding (resp. succeeding) the $i+1$-th particle, $\beta = \psi^{-1}(\alpha^{+i})$, and $\beta' = \psi^{-1}(\alpha^{+(i+1)})$, with the convention that
$V_0' = (0,0)$, and $V_\ell = (2n,\ell)$ are respectively the first and the last valleys. Hence,
\begin{align*}
\left[-D_{0}/M,\mcQ_{\alpha}\right]&=\sum_{\substack{1\leq i\leq
    \ell,\\\alpha_i > 0 \text{ or } i\in\{1,\ell\}}} \left(\sum_{\gamma\in\bQ_{\alpha^{+i}}}\left([\theight_{\psi^{-1}(\alpha^{+i})}(V_i)]-[\theight_{\psi^{-1}(\alpha^{+i})}(V'_{i-1})]\right)\mcO_{\psi^{-1}(\alpha^{+i})}(\gamma)\right).
\end{align*}
Notice that the condition $\alpha_i > 0$ can be dropped. Indeed,
when $1<i<\ell$, $\alpha_i = 0$ and $\gamma\in\bQ_{\alpha^{+i}} $ we have $V_i =
V'_{i-1}$. Therefore
\begin{align*}
  \left[-D_{0}/M,\mcQ_{\alpha}\right]=&\sum_{\gamma\in\bQ_{\alpha^{+\ell}}}[1]\mcO_{\psi^{-1}(\alpha^{+\ell})}(\gamma)-\sum_{\gamma\in\bQ_{\alpha^{+1}}}[0]\mcO_{\psi^{-1}(\alpha^{+1})}(\gamma)\\
  &+\sum_{1\leq
     i\leq\ell-1}\bigg(\sum_{\gamma\in\bQ_{\alpha^{+i}}}[\theight_{\psi^{-1}(\alpha^{+i})}(V_i)]\mcO_{\psi^{-1}(\alpha^{+i})}(\gamma)\\
	 &-\sum_{\gamma\in\bQ_{\alpha^{+(i+1)}}}[\theight_{\psi^{-1}(\alpha^{+(i+1)})}(V'_i)]\mcO_{\psi^{-1}(\alpha^{+(i+1)})}(\gamma)\bigg)\\
     =& \sum_{1\leq
i\leq\ell}\sum_{\gamma\in\bQ_{\alpha^{+i}}}\mcO_{\psi^{-1}(\alpha^{+i})}(\gamma),
\end{align*}
where we used \cref{lem:move_peak} to obtain the last equality. This finishes the proof of the proposition.
\end{proof}
