\begin{prop}\label{prop:commutation_P}
   Fix two integers $m\geq 0, \ell \geq 1$, and let $\alpha\in\ZZ_{\geq 0}^\ell$ be a sequence of non-negative integers. Then 
    \begin{multline*}
      \frac{1}{-M}\left[\ad^{m}_{\frac{D_0}{-M}}\left(-e_1[X]\right),\mcQ_{\alpha}\right]=
      \sum_{1\leq i\leq\ell-1} \mcQ_{\alpha_1,\dots,\alpha_i,m,\alpha_{i+1},\dots,\alpha_\ell}
      \\+\sum_{1\leq i \leq\ell}\sign(m-\alpha_i-1)\sum_{\substack{r_1,r_2\geq m\wedge(\alpha_i+1)\\{r_1+r_2=m+\alpha_i}}}\mcQ_{\alpha_1,\dots,\alpha_{i-1},r_1,r_2,\alpha_{i+1},\dots,\alpha_\ell}.  
    \end{multline*}
  \end{prop}
\begin{proof}
We start by proving the case $m=0$ and then we use \cref{prop:D0_P} to
prove by induction the proposition for any $m$.

\medskip

Let us consider the following sum
\[ \sum_{1\leq i\leq \ell}\sum_{\substack{r_1,r_2\geq
    0\\{r_1+r_2=\alpha_i}}}\mcQ_{\alpha_1,\dots,\alpha_{i-1},r_1,r_2,\alpha_{i+1},\dots,\alpha_{\ell}}.\]
We can interpret it combinatorially as follows: for each $1 \leq i\leq
\ell$ we add a new particle between two old particles
separated by $\alpha_i$ peaks in all possible places, including a
particle over the first old particle, and a
particle below the second old particle, which gives $\alpha_i+1$ possible
places. This gives in total $\sum_{1 \leq i \leq \ell}(\alpha_i+1) =
|\alpha|+\ell$ possible positions. \cref{lem:com_path_e1} implies that
the commutation of $\mcO_{\psi^{-1}(\alpha)}(\gamma)$ with $-e_1[X]/M$ corresponds to
adding a new particle to all the peaks, which gives $|\alpha|+1$
positions. The difference between these two interpretations comes from
the fact that in the first sum we always add a particle below the
second old particle separated by $\alpha_i$ and over the first particle
separated by $\alpha_{i+1}$, which is the same particle. Therefore the
correct quantity corresponding to the
commutator $\left[\frac{e_1[X]}{M},\mcQ_{\alpha}\right] $ is equal
to the following correction of the first sum:
  \begin{align*}
\left[\frac{e_1[X]}{M},\mcQ_{\alpha}\right]
   =\sum_{1\leq i\leq\ell-1} \mcQ_{\alpha_1,\dots,\alpha_i,0,\alpha_{i+1},\dots,\alpha_\ell}-\sum_{1\leq i\leq \ell}\sum_{\substack{r_1,r_2\geq 0\\{r_1+r_2=\alpha_i}}}\mcQ_{\alpha_1,\dots,\alpha_{i-1},r_1,r_2,\alpha_{i+1},\dots,\alpha_{\ell}}.   
  \end{align*}
This finishes the proof of the proposition for $m=0$.

We now fix $m\geq 0$ and we assume that the proposition holds for $m$. The Jacobi identity gives:
\begin{align*}
	\left[\frac{\ad^{m+1}_{\frac{D_0}{-M}}\left(-e_1[X]\right)}{-M},\mcQ_{\alpha}\right]
  =&\left[\left[\frac{D_0}{-M},\frac{\ad^{m}_{\frac{D_0}{-M}}\left(-e_1[X]\right)}{-M}\right],\mcQ_{\alpha}\right]\\
  =&\left[\frac{D_0}{-M},\left[\frac{\ad^{m}_{\frac{D_0}{-M}}\left(-e_1[X]\right)}{-M},\mcQ_{\alpha}\right]\right]-\left[\frac{\ad^{m}_{\frac{D_0}{-M}}\left(-e_1[X]\right)}{-M},\left[\frac{D_0}{-M},\mcQ_{\alpha}\right]\right].
\end{align*}
Combining the recurrence assumption and \cref{prop:D0_P}, we obtain
\begin{multline*}
	\frac{1}{-M}\left[\ad^{m}_{\frac{D_0}{-M}}\left(-e_1[X]\right),\mcQ_{\alpha}\right]=
  \sum_{1\leq i\leq\ell-1}\mcQ_{\alpha_1,\dots,\alpha_i,m+1,\alpha_{j+1},\dots,\alpha_\ell}+\sum_{1\leq i \leq\ell}\sign(m-\alpha_i-1)\\
  \sum_{\substack{r_1,r_2\geq m\wedge(\alpha_i+1)\\{r_1+r_2=m+\alpha_i}}}\left(\mcQ_{\alpha_1,\dots,\alpha_{i-1},r_1+1,r_2,\alpha_{i+1},\dots,\alpha_\ell}+\mcQ_{\alpha_1,\dots,\alpha_{i-1},r_1,r_2+1,\alpha_{i+1},\dots,\alpha_\ell}\right)\\
  -\sum_{1\leq i \leq\ell}\sign(m-\alpha_i-2)\sum_{\substack{r_1,r_2\geq m\wedge(\alpha_i+2)\\{r_1+r_2=m+\alpha_i+1}}}\mcQ_{\alpha_1,\dots,\alpha_{i-1},r_1,r_2,\alpha_{i+1},\dots,\alpha_\ell}.
\end{multline*}
By distinguishing the four cases $\alpha_i>m-1$, $\alpha_i=m-1$, $\alpha_i=m-2$ and $\alpha_i<m-2$, one check that we obtain the required formula:
\begin{align*}
	\frac{1}{-M}\left[\ad^{m}_{\frac{D_0}{-M}}\left(-e_1[X]\right),\mcQ_{\alpha}\right]
=&\sum_{1\leq i\leq\ell-1}\mcQ_{\alpha_1,\dots,\alpha_i,m+1,\alpha_{i+1},\dots,\alpha_\ell}\\
  &+\sum_{1\leq i \leq\ell}\sign(m-\alpha_i)\sum_{\substack{r_1,r_2\geq (m+1)\wedge(\alpha_i+1)\\{r_1+r_2=m+1+\alpha_i}}}\mcQ_{\alpha_1,\dots,\alpha_{i-1},r_1,r_2,\alpha_{i+1},\dots,\alpha_\ell}.
\end{align*}
This finishes the proof of the proposition.
\end{proof}

Let us now prove \cref{thm:P_commutation}, which gives the second commutation relation announced at the beginning of the section.
\begin{proof}[Proof of \cref{thm:P_commutation}]

Fix $\ell \geq2$ and $\alpha\in\ZZ_{\geq 0}^{\ell}$. We have
\begin{align*}
        \frac{1}{M}\sum_{1\leq i\leq \ell}\left[\ad^{\alpha_i}_{\frac{D_0}{-M}}\left(-e_1[X]\right),\Qsym_{\alpha^{\downarrow i}}\right]
        &=\frac{1}{M}\sum_{1\leq i\leq \ell}\sum_{\sigma\in\mathfrak{S}_{\ell-1}}\left[\ad^{\alpha_i}_{\frac{D_0}{-M}}\left(-e_1[X]\right),\mcQ_{\sigma(\alpha^{\downarrow i})}\right]\\
        &=\frac{1}{M}\sum_{\sigma\in\mathfrak{S}_\ell}\left[\ad^{\alpha_{\sigma(\ell)}}_{\frac{D_0}{-M}}\left(-e_1[X]\right),
        \mcQ_{\sigma(\alpha^{\downarrow \ell})}\right].
\end{align*}
Applying \cref{prop:commutation_P}, this is also equal to
\begin{multline*}
	-\sum_{\sigma\in\mathfrak{S}_{\ell}} \sum_{1\leq j\leq \ell-2}\mcQ_{\alpha_{\sigma(1)},\dots,\alpha_{\sigma(j)},\alpha_{\sigma(\ell)},\alpha_{\sigma(j+1)},\dots,\alpha_{\sigma(\ell-1)}}\\
-\sum_{\sigma\in\mathfrak{S}_{\ell}}
        \sum_{1\leq j\leq \ell-1}
        \sign\left(\alpha_{\sigma(\ell)}-1-\alpha_{\sigma(j)}\right)
        \sum_{\substack{r_1,r_2\geq \alpha_{\sigma(\ell)} \wedge\left(\alpha_{\sigma(j)}+1\right)\\{r_1+r_2=\alpha_{\sigma(\ell)}+\alpha_{\sigma(j)}}}}\mcQ_{\alpha_{\sigma(1)},\dots,\alpha_{\sigma(j-1)},r_1,r_2,\alpha_{\sigma(j+1)},\dots}. \label{eq:thm:comP}
    \end{multline*}
The first term on the RHS gives 
$$-\sum_{1\leq j\leq
  \ell-2}\sum_{\sigma\in\mathfrak{S}_{\ell}}\mcQ_{\sigma \cdot (\ell, \ell-1,\dots,j+1)(\alpha)}
= -(\ell-2)\sum_{\sigma\in\mathfrak{S}_{\ell}}
\mcQ_{\sigma(\alpha)}=-(\ell-2)\Qsym_{\alpha},$$
where $(\ell, \ell-1,\dots,j+1)$ is the permutation of $\mathfrak{S}_\ell$ with cyclic notation.
Let us now compute the second term. For a fixed $1\leq j\leq \ell-1$,
define a bijection $\mathfrak{S}_{\ell} \rightarrow
\mathfrak{S}_{\ell}$ given by $\sigma \mapsto \sigma' := \sigma(j,\ell)$, where
$(j,\ell)$ is the transposition exchanging $j$ and $\ell$. It is easy
to check that a contribution to the second term in the RHS that comes from
$\sigma$ and the associated $\sigma'$ is equal to
$$\mcQ_{\sigma\cdot(\ell,\ell-1,\dots,j+1)(\alpha)}+\mcQ_{\sigma\cdot(\ell,\ell-1,\dots,j+1,j)(\alpha)}.$$
As a consequence, the sum over
all permutations $\sigma$ contributing to the second term on the RHS
with a fixed $1\leq j\leq \ell-1$ is equal to $\Qsym_{\alpha}$, so
that the total contribution is equal to $(\ell-1) \Qsym_{\alpha}$. In conclusion, 
        \begin{equation*}
			\frac{1}{M}\sum_{1\leq i\leq \ell}\left[\ad^{\alpha_i}_{\frac{D_0}{-M}}\left(-e_1[X]\right),\Qsym_{\alpha^{\downarrow i}}\right]=\big(-(\ell-2)+(\ell-1)\big)\Qsym_{\alpha}=\Qsym_{\alpha}
        \end{equation*}
        as claimed.
\end{proof}

\subsection{Combinatorial formula in terms of path operators}\label{ssec:proof_comb_formula}

We are ready to prove the combinatorial formula for the operators $\A_F^{(\ell)}$ announced in \cref{thm:dif_eq''}.

\begin{proof}[Proof of \cref{thm:dif_eq''}]

		We prove the theorem by induction. For $\ell=1$, we know from \eqref{def:AFell} and \cref{thm:A_n-P_n}, that
	\begin{equation*}\label{eq:A-Q}
	  \A_F^{(1)}=a_0\mcQ_0+a_1\mcQ_{1}\dots  
	\end{equation*}
	giving the theorem for $\ell=1$.


		We now assume that \eqref{eq:diff_eq'} holds for some $\ell\geq 1$. We then have from \eqref{def:AFell} and the induction assumption
		\begin{align*}
	   \A_F^{(\ell+1)}
		  =\frac{1}{M}\left[\A_{F},\A_F^{(\ell)}\right]
		  &=\frac{1}{M}\sum_{j\geq 0}\sum_{\alpha \in \ZZ_{\geq 0}^\ell}
		  a_{j} a_\alpha\left[\ad^j_{\frac{D_0}{-M}}(e_1[X]),\mcQ_{\alpha}\right],  
		\end{align*}
		where we use \cref{thm:A_n-P_n} to obtain the last equality. This can be written as follows
		\begin{align*}
		  \A_F^{(\ell+1)}
		  &=\frac{1}{M}\sum_{0\leq \nu_1\leq\dots\leq \nu_{\ell+1}}
			\frac{1}{|\Aut(\nu)|} a_\nu \sum_{\sigma\in\mathfrak
S_{\ell+1}}\left[\ad^{\nu_{\sigma(\ell+1)}}_{\frac{D_0}{-M}}(e_1[X]),\mcQ_{\sigma (\nu^{\downarrow(\ell+1)})}\right],
		\end{align*}		
  where $\Aut(\nu)<\mathfrak{S}_{\ell+1}$ is the stabilizer of the partition $\nu$.

		Applying \cref{thm:P_commutation}, we get
	\[      \A_F^{(\ell+1)}=\sum_{0\leq \nu_1\leq\dots\leq \nu_{\ell+1}}\frac{1}{|\Aut(\nu)|}a_\nu\sum_{\sigma\in\mathfrak
			S_{\ell+1}}\mcQ_{\sigma (\nu)}=\sum_{\alpha \in
			\mathbb{Z}_{\geq 0}^{\ell+1}}a_{\alpha}\mcQ_{\alpha}. \]
		This finishes the proof of the theorem.
	\end{proof}

\section{Applications: relation to the extended delta conjecture}\label{sec:relation_delta}

Define the operators $\Delta_{h_n}$ and $\Delta_{e_n}$ by their generating series:
\begin{equation*}
\label{eq:Pi-Delta}
	\Pi_{1+uz}=\sum_{n\geq 0}u^{n}\Delta_{e_n}, \quad \Pi_{(1-vz)^{-1}}=\sum_{n\geq 0}v^{n}\Delta_{h_n}.
\end{equation*}
In particular, they act diagonally on the basis of transformed Macdonald polynomials.
Define also the operator
\[ \Delta'_{e_n} = \sum_{i=0}^n (-1)^i\Delta_{e_{n-i}}.\]
We prove that the symmetric function $\Delta_{h_l}\Delta_{e_{k-1}}\cdot e_{n}$, which is the main object of interest in the extended delta conjecture, has an explicit formula in terms of the action of the path operators on $1$. This result together with \cref{thm:explicit_formula2} is equivalent to the key result~\cite[Theorem 4.4.1]{BlasiakHaimanMorsePunSeelinger2023b} in proving the extended delta conjecture. The proof in~\cite{BlasiakHaimanMorsePunSeelinger2023b} is based on the intermediate results describing the structure of the elliptic Hall algebra and its representation on $\Lambda$. We give a new proof that relies directly on combinatorial properties of path operators.

\begin{thm}\label{thm:ExtDelta}
    Fix three integers $l \geq 0$ and $0 < k \leq n$, and define the function $F\in S_{k+l}$
    $$F:=\operatorname{Sym}\left(\frac{z_1 \dotsm z_{k+l}}{\prod_{i=1}^{l+k-1} (1-qtz_{i+1}/z_i)}h_{n-k}(z_1,\dots,z_{k+l})e_l(z_2^{-1},\dots,z_{l+k}^{-1}) \prod_{1\leq i<j\leq \ell} \omega(z_j/z_i)\right).$$
    We have
    \begin{align}\label{eq:extended_delta_conj}
      (-1)^{n}\Delta_{h_l}\Delta'_{e_{k-1}}\cdot e_{n}=\sum_{\substack{\beta \in \ZZ_{\geq 0}^{k+l-1},\\|\beta| = n-k}}\sum_{\substack{\beta' \in \{0,1\}^{k+l-1},\\|\beta'| = l}}\mcR_{\beta+1^{k+l}-(0,\beta')}\cdot 1
      =\widehat{F}\cdot 1,
    \end{align}
       where $\widehat{F}$ is the operator on $\Lambda$ given by the action of the shuffle algebra (see \cref{def:shuffle_algebra}). 
\end{thm}

\begin{proof}
Notice that
\[(-1)^{n}e_{n}=D_{n}\cdot 1=\mcQ_{0^{n}}\cdot 1.\]
Therefore, we can rewrite $\Delta_{h_l}\Delta'_{e_{k-1}}\cdot e_{n}$ as follows:
$$(-1)^{n}\Delta_{h_l}\Delta'_{e_{k-1}}\cdot e_{n}=\sum_{i=1}^{k}(-1)^{i-1}[v^{l}u^{k-i}]\Pi_{\frac{1+uz}{1-vz}}\cdot \mcQ_{0^{n}}\cdot\left(\Pi_{\frac{1+uz}{1-vz}}\right)^{-1}\cdot 1.$$
Moreover, we know from \cref{thm:dif_eq''} that $\mcQ_{0^{n}}=\A_{K}^{(n)}$, where $K(z)=1$ is the constant polynomial. \cref{lem:DeltaG_A+} implies that 
$\Pi_G\cdot \A_{K}^{(n)}\cdot \Pi_G^{-1}=\A_{KG}^{(n)}=\A_{G}^{(n)}.$  We then get 
\begin{equation}\label{eq:extended_delta}
  (-1)^{n}\Delta_{h_l}\Delta'_{e_{k-1}}\cdot e_{n}=\sum_{i=1}^{k}(-1)^{i-1}[v^{l}u^{k-i}]\A_{\frac{1+uz}{1-vz}}^{(n)}\cdot 1.  
\end{equation}
By reapplying \cref{thm:dif_eq''}, we have that
\[ [v^{l}u^{k-i}]\A_{\frac{1+uz}{1-vz}}^{(n)}\cdot 1=\sum_{\substack{\alpha \in \ZZ_{\geq 0}^n,\\|\alpha| = l}}\sum_{\substack{\alpha' \in \{0,1\}^n,\\|\alpha'| = k-i}}\mcQ_{\alpha+\alpha'}\cdot 1 = \sum_{\substack{\alpha_1,\dots,\alpha_{n} \geq 0,\\|\alpha| = l+k-i}}\binom{\ell(\alpha^+)}{k-i}\mcQ_{\alpha_1,\dots,\alpha_{n}}\cdot 1,\]
where we use the notation $\ell(\alpha^+)$ to denote the number of non-zero parts of $\alpha$. Recall the map $\psi$ introduced in \cref{sub:path_op} that relates the operators $\mcQ_\alpha = \mcR_\beta$, where $\psi^{-1}(\alpha)=:\beta \in \ZZ_{>0}\times \ZZ^{l+k-i}_{\geq 0}$ for $\alpha$ such that $|\alpha|=l+k-i$. Notice that 
\begin{itemize}
	\item if $\alpha_{n} = 0$, then $\ell(\alpha^+) = \ell(\beta^+)-1$, and $\beta_{l+k-i+1} > 0$,
	\item if $\alpha_{n} > 0$, then $\ell(\alpha^+) = \ell(\beta^+)$, and $\beta_{l+k-i+1} = 0$.
\end{itemize}
Therefore $[v^{l}u^{k-i}]\A_{\frac{1+uz}{1-vz}}^{(n)}\cdot 1$ can be rewritten as follows:
\begin{multline*}
	\sum_{\substack{\beta_1,\beta_{l+k-i+1}>0,\\ \beta_2,\dots,\beta_{l+k-i} \geq 0,\\|\beta| = n}}\binom{\ell(\beta^+)-1}{k-i}\mcR_{\beta_1,\dots,\beta_{l+k-i+1}}\cdot 1  + \sum_{\substack{\beta_1>0,\\ \beta_2,\dots,\beta_{l+k-i} \geq 0,\\|\beta| = n}}\binom{\ell(\beta^+)}{k-i}\mcR_{\beta_1,\dots,\beta_{l+k-i},0}\cdot 1\\
	= \sum_{\substack{\beta_1>0,\\ \beta_2,\dots,\beta_{l+k-i+1} \geq 0,\\|\beta| = n}}\binom{\ell(\beta^+)-1}{k-i}\mcR_{\beta_1,\dots,\beta_{l+k-i+1}}\cdot 1+\sum_{\substack{\beta_1>0,\\ \beta_2,\dots,\beta_{l+k-i} \geq 0,\\|\beta| = n}}\binom{\ell(\beta^+)-1}{k-i-1}\mcR_{\beta_1,\dots,\beta_{l+k-i}}\cdot 1.
\end{multline*}
The second equality comes from the binomial identity
\[ \binom{\ell(\beta^+)}{k-i} = \binom{\ell(\beta^+)-1}{k-i}+\binom{\ell(\beta^+)-1}{k-i-1}\]
and from the fact that $\mcR_{\beta,0}\cdot 1 = \mcR_{\beta}\cdot 1$, which is a consequence of the identity $\mathcal{O}(-k) \cdot 1 = \delta_{k,0}$ for $k \geq 0$. Applying this in \cref{eq:extended_delta}, we end up with the following formula:
\begin{align*}
	(-1)^{n}\Delta_{h_l}\Delta'_{e_{k-1}}\cdot e_{n} 
    &= \sum_{\substack{\beta_1>0,\\ \beta_2,\dots,\beta_{l+k} \geq 0,\\|\beta| = n}}\binom{\ell(\beta^+)-1}{k-1}\mcR_{\beta_1,\dots,\beta_{l+k}}\cdot 1\\
    &= \sum_{\substack{\beta \in \ZZ_{\geq 0}^{k+l},\\|\beta| = n-k}}\sum_{\substack{\beta' \in \{0,1\}^{k+l-1},\\|\beta'| = l}}\mcR_{\beta+1^{k+l}-(0,\beta')}\cdot 1.
\end{align*}
To obtain the second part of \cref{eq:extended_delta_conj}, we use \cref{cor:Negut} to write:
$$\sum_{\substack{\beta \in \ZZ_{\geq 0}^{k+l},\\|\beta| = n-k}}\sum_{\substack{\beta' \in \{0,1\}^{k+l-1},\\|\beta'| = l}}\mcR_{\beta+1^{k+l}-(0,\beta')}=\widehat{F},$$
with 
$$F=\sum_{\substack{\beta \in \ZZ_{\geq 0}^{k+l},\\|\beta| = n-k}}\sum_{\substack{\beta' \in \{0,1\}^{k+l-1},\\|\beta'| = l}}\operatorname{Sym}\left(\frac{z^{\beta+1^{k+l}-(0,\beta')}}{\prod_{i=1}^{l+k-1} (1-qtz_{i+1}/z_i)} \prod_{1\leq i<j\leq \ell} \omega(z_j/z_i)\right),$$
where $z^\alpha:=z_1^{\alpha_1}\dots z_{l+k}^{\alpha_{l+k}}.$
We conclude using the definitions of homogeneous and elementary symmetric functions.
\end{proof}

Notice that there is an extra factor $(-1)^n$ in \cref{thm:ExtDelta} compared to \cite{BlasiakHaimanMorsePunSeelinger2023} due to the fact that our conventions for the operators $D_a$ differ by a factor $(-1)^a$. 


\begin{rmk}
In~\cite[Definition 4.3.1]{BlasiakHaimanMorsePunSeelinger2023b}, the authors use lattice paths (different from the ones we consider here) to define an involutive correspondence between some sequences of nonnegative integers. It is not very hard to see that this correspondence is precisely the map $\psi$ introduced in \cref{sub:path_op}. Using the notation from \cite{BlasiakHaimanMorsePunSeelinger2023b}, they introduce the transposed Negut elements $E_\alpha$, and they prove in~\cite[Proposition 4.3.3]{BlasiakHaimanMorsePunSeelinger2023b} that $E_\alpha = D_\beta$, where $\psi(\beta) = \alpha$. Thus, \cref{cor:Negut} implies that $\mcQ_{\beta} = (-1)^{|\beta|}E_{\beta}$, and consequently we also have an explicit combinatorial formula for the representation of the transposed Negut elements.
\end{rmk}

