The following presents some basic facts about the relationships between the subbrace and ideal structure of a skew brace and the subgroup structure of its associated large trifactorised group.


\begin{prop}[{\cite[Proposition 5.2(1)]{ballesterbolinches2025categoriesskewleftbraces}}]
A subset $L$ of $K$ is a subbrace of $B$ if and only if $LD\cap LC$ is a subgroup of $G$.
\end{prop}

The large trifactorised group associated with a subbrace of $B$ is given in the following. 


\begin{prop}[{\cite[Proposition 5.4]{ballesterbolinches2025categoriesskewleftbraces}}]\label{prop-3factAss-SubBr}
Let $L\subseteq K$ be a subbrace of $B$. Then $T=L\sigma^{-1}(L) = LD\cap LC$ is a subgroup of $G$ and 
$$(LD\cap LC,L, LC\cap D,LD\cap C)$$
is the large trifactorised group associated with $L$.
\end{prop} 

Let $A$, $A_1$ and $A_2$ be subbraces of $B$. We identify them as the subgroups $L$, $L_1$ and $L_2$ of $K$ in $G$ respectively. If $a \in A_1$ and $b \in A_2$, then $a*b$ corresponds to the element $[\delta^{-1}(a), b]$ of $G$ which belongs to $K$. Therefore the additive group of $A_1*A_2$ can be identified  as the subgroup $[\delta^{-1}(L_1),L_2]$ of $G$. Note that $[\delta^{-1}(L_1),L_2]$ is contained in $K$. By \cite[Lemma 5.3]{ballesterbolinches2025categoriesskewleftbraces}, $\delta^{-1}(L_1)=L_1D\cap C$. Therefore we have

\begin{prop}\label{prop-add-gr-deriv}
The subgroup $A_1*A_2$ of $K$ corresponds to the subgroup $[L_1D\cap C,L_2]$ of $G$. In particular, the additive group of $B*B$ corresponds to the normal subgroup $[C,K]$ of $G$.
\end{prop}

Next we show how to compute some important subbraces of $B$ in the large trifactorised group associated to $B$. 
\begin{prop}\label{prop-trad-prop-br}
\begin{enumerate}
\item $A$ is a trivial skew brace if and only if, $[LD\cap C,L]=1$.
\item $A$ is a left ideal if and only if, $[C,L]\leq L$.
\item $A$ is a right ideal if and only if, $[LD\cap C,K]\leq L$.
\item $A$ is a strong left ideal if and only if, $L$ is normal in $G$.
\end{enumerate}
\end{prop}
\begin{proof}
\begin{enumerate}
\item By Proposition~\ref{prop-3factAss-SubBr}, we have that $(T,L,T\cap D,T\cap C)$ with $T=LD\cap LC$ is the large trifactorised group associated to $L$. Therefore, $A$ is a trivial skew brace if and only if, $T\cap C$ acts trivially on $L$, that is, $[LD\cap C,L] = 1$.
\item By {\cite[Proposition 5.2.2]{ballesterbolinches2025categoriesskewleftbraces}}, $A$ is a left ideal of $B$ if and only if, $C$ normalises $L$, that is, $[C,L]\leq L$.

\item $A$ is a right ideal if and only if,  $A*B\subseteq A$. By Proposition \ref{prop-add-gr-deriv}, the latter statement is equivalent to $[LD\cap C,K]\leq L$.

\item  This is exactly {\cite[Proposition 5.2.3]{ballesterbolinches2025categoriesskewleftbraces}}.\qedhere
\end{enumerate}
\end{proof}

We close this section with two applications of the above propositions. 



\begin{cor}\label{prop-ab-br-eq}
The following statements are equivalent:
\begin{enumerate}
\item $B$ is an abelian skew brace.\label{prop-ab-br-eq-cond-1}
\item $G$ is abelian.\label{prop-ab-br-eq-cond-2}
\item $K$ is abelian and $[C,K]=1$.\label{prop-ab-br-eq-cond-3}
\end{enumerate}
\end{cor}
\begin{proof}
\ref{prop-ab-br-eq-cond-1} implies \ref{prop-ab-br-eq-cond-2}. Since $B$ is an abelian skew brace, then  $K$ and $C$ are abelian and $[C,K]=1$ by Proposition \ref{prop-add-gr-deriv}. Hence $G=[K]C$ is abelian.

It is clear that \ref{prop-ab-br-eq-cond-2} implies \ref{prop-ab-br-eq-cond-3}. Now if $K$ is abelian and $[C,K]=1$, then $B$ is an abelian skew brace by Proposition \ref{prop-trad-prop-br}. Therefore \ref{prop-ab-br-eq-cond-3} implies \ref{prop-ab-br-eq-cond-1}, and the circle of implications is complete. 
\end{proof}


\begin{cor}\label{prop-add-mul-br-eq}
\begin{enumerate}
\item $B=A_1+A_2$ if and only if, $K=L_1L_2$.
\item $B=A_1A_2$ if and only if, $C=(L_1D\cap C)(L_2D\cap C)$.
\end{enumerate}
\end{cor}
\begin{proof}
\begin{enumerate}
Statement 1 is clear. Now, $B = A_1A_2$ if and only if, $C = \delta^{-1}(L_1)\delta^{-1}(L_2)$. By \cite[Lemma 5.3]{ballesterbolinches2025categoriesskewleftbraces}, $\delta^{-1}(L_i)=L_iD\cap C$, $i = 1,2$. Hence Statement 2 holds.\qedhere
\end{enumerate}
\end{proof}

