\begin{teo}\label{teo-3fact-ito-general}
Let $(G,K,H,E)$ be a trifactorised group, $L_1,L_2\leq K$ and $E_i=L_iH\cap E \leq E$  such that:
\begin{enumerate}

\item $E=E_1E_2$ and $K=L_1L_2$.\label{teo-3fact-ito-general-cond-2}
\item $[E,L_1]\leq L_1$ and $[E_1,K]\leq L_1$.\label{teo-3fact-ito-general-cond-3}
\item $L_iH\cap L_iE$ is an abelian subgroup of $G$ for $i=1,2$.\label{teo-3fact-ito-general-cond-1}
\item $K'H\cap E\leq E'([E,K]H\cap E)$.\label{teo-3fact-ito-general-cond-4}
\end{enumerate}
Then $K'[E,K]$ is abelian and $[K'[E,K]H\cap E,K'[E,K]]=1$.
\end{teo}
\begin{proof}
Let us denote by $T_i=L_iH\cap L_iE$, $i = 1,2$. Then $L_iE_i = L_i(L_iH\cap E) = T_i$, $i = 1,2$. By Statement \ref{teo-3fact-ito-general-cond-1}, $E_i$ is an abelian subgroup of $G$ and $[E_i,L_i] \leq [T_i, T_i] = 1$, $i = 1, 2$.  By Statement
 \ref{teo-3fact-ito-general-cond-3}, $E_2$ normalizes $L_1$. Therefore, $T_2T_1=L_2E_2L_1E_1=L_2L_1E_2E_1=KE=G$ and $G$ is the product of two abelian groups. By Itô's theorem (\cite[Kapitel~VI, Satz~4.4]{Huppert67}), $G'$ is abelian. In particular, $K'[E,K]$ is abelian.

By Proposition \ref{prop-tsang-3.3}, $[E,K]=[E_1,L_2][E_2,L_1]$.
By Statement \ref{teo-3fact-ito-general-cond-3}, $[E_1,L_2]$ and $[E_2,L_1]$ are contained in $L_1$. Therefore, $[E,K]\leq L_1$ and $[E,K]H\cap E\leq E_1$. Now, $(K'H\cap E)([E,K]H\cap E) = (K'H \cap E)[E, K]H \cap E = [E, K](K'H \cap E)H \cap E = [E, K](K'H \cap EH) \cap E = [E, K]K'H \cap E$. Hence, by Statement \ref{teo-3fact-ito-general-cond-4}, 
$[E, K]K'H \cap E \leq (E'([E,K]H\cap E))([E,K]H\cap E) \leq E'[E, K]H \cap E = E'([E, K]H \cap E) \leq E'E_1$. 

Moreover, since $K=L_1L_2$ and $L_1,L_2$ are abelian, it follows that $K'=[L_1,L_2]$. As $[[E_1, L_1], L_2] = 1$ ($[E_1, L_1] = 1$) and $[[L_2, E_1], L_1] =1$  ($[L_2, E_1] \leq L_1$), it follows that $[[L_1, L_2], E_1] = 1$ by the three subgroups lemma (\cite[Kapitel~III, Hilfssatz~1.10]{Huppert67}). Hence $[E_1, K'] = 1$. Since $G'$ is abelian, $[E'E_1,K'[E,K]]= [E_1, K'] = 1$ (note that $[[E,K],E_1]\leq [L_1,E_1]=1$). Consequently, $[K'[E,K]H\cap E,K'[E,K]]=1$, as required. \qedhere



\end{proof}


\begin{proof}[{Proof of Theorem~\ref{teo-ito-general}}]
Let $(G,K,D,C)$ be the large trifactorised group associated to $B$ and let $L_i$ be the additive group of $A_i$, $i = 1,2$. We will apply Theorem \ref{teo-3fact-ito-general} to this factorised group , where $D = H$ and $C = E$. According to Proposition~\ref{prop-3factAss-SubBr}, $E_i=L_iD\cap C$ is a subgroup of $G$, $i = 1,2$. Suppose that $B = A_1A_2$. Since $A_1$ is a left ideal of $B$, it follows that $B = A_1 + A_2$ by Lemma \ref{lemma-prod-sum-ideals-is-B}. Suppose $B = A_1+ A_2$. Since $A_1$ is a left ideal of $B$, it follows that $B = A_1A_2$ by Lemma \ref{lemma-prod-sum-ideals-is-B}. In any case, we have $B = A_1A_2 = A_1 + A_2$. By Corollary~\ref{prop-add-mul-br-eq}, $K = L_1L_2$ and $C = E_1E_2$. Since $A_i$ is abelian, $i = 1, 2$, it follows that $L_iH\cap L_iE$ is an abelian subgroup of $G$ for $i=1,2$ by Proposition~\ref{prop-3factAss-SubBr} and Corollary~\ref{prop-ab-br-eq}. Furthermore, since $A_1$ is left and right ideal of $B$, it follows that $[C, L_1] \leq L_1$ and $[E_1, K] \leq L_1$ by Proposition~\ref{prop-trad-prop-br}. By Proposition~\ref{prop-3factAss-SubBr}, the subbrace $[B,B]_+$ corresponds to the subgroup $K'D\cap C$ of $C$, $[B,B]_\bullet$ is just $C'$ in $C$ and the subbrace $B*B$ of $B$ corresponds to the subgroup $[C, K]D \cap C$ of $C$. By Proposition~\ref{prop-br-comm-car}, $[B,B]_+\leq B*B+[B,B]_\bullet=[B,B]_\bullet+B*B=[B,B]_\bullet(B*B)$. Therefore $K'D\cap C \leq C'([C, K]D \cap C)$. Applying Theorem~\ref{teo-3fact-ito-general}, it follows that $K'[C,K]$ is abelian and $[K'[C,K]D\cap C,K'[C,K]]=1$. Since $K'[C,K]$ corresponds to the skew brace commutator $[B,B]^B$ and $([K'[C,K]D\cap K'[C,K]C, K'[C,K], K'[C,K]C\cap D, K'[C,K]D\cap C)$ is the large trifactorised groups associated to $[B,B]^B$, we can apply Corollary~\ref{prop-ab-br-eq} to conclude that $[B,B]^B$ is an abelian skew brace. \qedhere
\end{proof}

\section{Proof of Theorem~\ref{teo2}}

\begin{proof}[{Proof of Theorem~\ref{teo2}}]
\begin{enumerate}
\item Let $a\in\Fix(B)$, then there exists $a_i\in A_i$, $i=1,2$, such that $a=a_1+a_2$. Let $b\in B$, then there exists $b_i\in A_i$, $i=1,2$, such that $b=b_1b_2$. Then $a = a_1+a_2= \lambda_{b_2}(a_1+a_2)=\lambda_{b_2}(a_1)+\lambda_{b_2}(a_2)=\lambda_{b_2}(a_1)+a_2$. Hence $\lambda_{b_2}(a_1)=a_1$. Since $A_1$ is trivial $\lambda_{b}(a_1)=\lambda_{b_1}\p{\lambda_{b_2}(a_1)}=\lambda_{b_1}(a_1)=a_1$. Hence $a_1\in\Fix(B)$. Analogously, $a_2\in\Fix(B)$. Therefore, $a\in (\Fix(B)\cap A_1)+(\Fix(B)\cap A_2)$. 
%Since $\Fix(B)$ is a trivial skew brace, $\Fix(B) =(\Fix(B) \cap A_1)+(\Fix(B) \cap A_2)=(\Fix(B)\cap A_1)(\Fix(B) \cap A_2)$ . 
Furthermore, if $z \in A_1 \cap A_2$ and $b=b_1b_2$, $b_i\in A_i$, $i=1,2$, then $\lambda_{b}(z)=\lambda_{b_1}\p{\lambda_{b_2}(z)} = z$ since $A_i$, $i=1,2$, are trivial skew braces. Consequently, $\Fix(B)$ is a factorised left ideal of $B$. 

Let $a\in\ker\lambda$ and $b\in B$, then there exists $a_i,b_i\in A_i$ such that $a=a_1a_2$ and $b=b_1+b_2$. Hence $\lambda_{a_1}(b)=\lambda_{a_1}(b_1)+\lambda_{a_1}(b_2)=b_1+\lambda_{a_1}\p{\lambda_{a_2}(b_2)}=b_1+\lambda_a(b_2)=b_1+b_2=b$. Thus $a_1\in\ker\lambda$. Analogously $a_2\in\ker\lambda$. Therefore, $a\in(\ker\lambda\cap A_1)(\ker\lambda\cap A_2)$, and  $\ker\lambda =( \ker\lambda \cap A_1)+(\ker\lambda \cap A_2)$.
%Since $\ker\lambda$ is a trivial skew brace, $\ker\lambda =( \ker\lambda \cap A_1)+(\ker\lambda \cap A_2)=(\ker\lambda \cap A_1)(\ker\lambda \cap A_2)$. 
Furthermore, if $z \in A_1 \cap A_2$ and $b=b_1b_2$, $b_i\in A_i$, $i=1,2$, then $\lambda_z(b) = \lambda_{z}(b_1)+\lambda_{z}(b_2 ) = b_1 + b_2 = b$ since $A_1$ and $A_2$ are trivial skew braces. Therefore $\ker\lambda$ is factorised. 


\item Assume that $A_1$ and $A_2$ are abelian skew braces. We prove first that $A_1\cap A_2\leq Z(B)$. Let $a\in A_1\cap A_2$ and $b\in B$. There exists $b_i,b_i'\in A_i$, $i=1,2$ such that $b=b_1+b_2=b_1'b_2'$. Therefore, $\lambda_a(b)=\lambda_a(b_1+b_2)=\lambda_a(b_1)+\lambda_a(b_2)=b_1+b_2$, $[a,b]_+=[a,b_1+b_2]_+=[a,b_1]_+=1$, $[a,b]_\bullet=[a,b_1'b_2']_\bullet=[a,b_1']_\bullet =1$. Hence $a\in Z(B)$. 

Let $a\in\Soc(B)=\ker\lambda\cap Z(B,+)$ and $b\in B$. By Statement~(1),  there exist $a_i\in \ker\lambda\cap A_i$, $i=1,2$, such that $a=a_1+a_2$. Let $b_i\in A_i$, $i=1,2$, such that $b=b_1+b_2$. Then, $1=[a,b_2]_+=[a_1+a_2,b]_+=[a_1 ,b_2]_+$ because $A_2$ is abelian. Since $A_1$ is abelian, it follows that $[a_1,b_1]_+=1$ and so $[a_1,b]_+=1$ and $a_1\in Z(B,+)$. Analogously $a_2\in  Z(B,+)$. Therefore, $a\in (\Soc(B)\cap A_1)+(\Soc(B)\cap A_2)$. Then $\Soc(B)=(\Soc(B)\cap A_1)+(\Soc(B)\cap A_2)$ and $\Soc(B)$ is a factorised ideal of $B$. .

Let $a\in Z(B)=\Soc(B)\cap Z(B,\cdot)$ and $b\in B$. Since $\Soc(B)$ is factorised and trivial, there exist $a_i\in \Soc(B)\cap A_i$, $i=1,2$, such that $a=a_1a_2$. Let  $b_i\in A_i$, $i=1,2$, such that $b=b_1b_2$. Then, $1=[a,b_2]_\bullet=[a_1a_2,b_2]_\bullet=[a_1,b_2]_\bullet$ because $A_2$ is abelian. Since $A_1$ is abelian $[a_1,b_1]_\bullet =1$. Hence $[a_1,b]_\bullet =1$ and $a_1\in Z(B,\cdot)$. Analogously $a_2\in Z(B,\cdot)$. Therefore, $a\in (Z(B)\cap A_1)+(Z(B)\cap A_2)$. Then $Z(B)=(Z(B)\cap A_1)+(Z(B)\cap A_2)$ and $Z(B)$ is a factorised ideal of $B$. 
\end{enumerate}
\end{proof}

\section{Proof of Theorem~\ref{teo3}}

We need a couple of preliminary results. 

\begin{lemma}\label{lemma-3fact-fact-centraliser}
Let $(G,K,H,E)$ be a trifactorised group and $L_1,L_2\leq K$ such that:
\begin{itemize}
\item $T_i=L_iH\cap L_iE$ is an abelian subgroup of $G$ for $i=1,2$.
\item $K=L_1L_2$ and $G=T_1T_2$.
\end{itemize}
Let $X$ be a subgroup of $G$ such that $X=(X\cap T_1)(X\cap T_2)$. Then $C_K(X)=(C_K(X)\cap L_1)(C_K(X)\cap L_2)$.
\end{lemma}
\begin{proof}
Let $k\in C_K(X)$. Let $k_i\in L_i$, $i=1,2$ such that $k=k_1k_2$. Note that $T_1$ centralises $k_1$ and if $t\in X\cap T_2$, we have that $1=[t,k]=[t,k_1k_2]=[t,k_1]\conj{k_1}{[t,k_2]}=[t,k_1]$. Hence $X\cap T_2$ centralises $k_1$ too. Therefore, $k_1$ centralises $(X\cap T_1)(X\cap T_2)=X$, and so $k_1\in C_K(X)$. Analogously, $k_2\in C_K(X)$. Therefore, $k\in (C_K(X)\cap L_1)(C_K(X)\cap L_2)$, and
 $C_K(X)=(C_K(X)\cap L_1)(C_K(X)\cap L_2)$.
\end{proof}

\begin{teo}\label{teo-3fact-sli-cont}
Let $(G,K,H,E)$ be a finite non-trivial trifactorised group, $L_1,L_2\leq K$ and $E_i=L_iH\cap E \leq E$ such that:
\begin{itemize}
\item $E=E_1E_2$ and $K=L_1L_2$.
\item $L_iH\cap L_iE$ is an abelian subgroup of $G$ for $i=1,2$.
\item $[E,L_1]\leq L_1$.
\end{itemize}
Then there exists a non-trivial normal subgroup of $G$ contained in $L_1$ or $L_2$.
\end{teo}
\begin{proof}
Arguing as in Proposition~\ref{teo-3fact-ito-general}, we have that $G=T_1T_2$ and $G'$ is abelian by Itô's theorem (\cite[Kapitel~VI, Satz~4.4]{Huppert67}). Since $G$ is non-trivial, $K$ is non-trivial, therefore, $L_1$ or $L_2$ is non-trivial. If $K'[E,K]=1$, every subgroup of $K$ is normal in $KE=G$. Hence $L_1$ and $L_2$ are normal subgroups of $G$, and the result is proved. Hence we may suppose that $K'[E,K] \neq 1$.

Consider $X=G'T_1\cap G'T_2=G'(T_1\cap G'T_2)=G'(T_2\cap G'T_1)=(T_1\cap G'T_2)(T_2\cap G'T_1)$. Since  $G'$, $T_1\cap G'T_2$ and $T_2\cap G'T_1$ are abelian, we can apply \cite[Corollary 1.3.5]{AmbergFranciosiDeGiovanni92}, to conclude that $X$ is nilpotent. Since $1 \neq K'[E,K] \leq K \cap X$, it follows that $K \cap Z(X) \neq 1$. By Lemma \ref{lemma-3fact-fact-centraliser}, $C_K(X)=(C_K(X)\cap L_1)(C_K(X)\cap L_2)$. Therefore, either $C_K(X)\cap L_1 \neq 1$ or $C_K(X)\cap L_2 \neq 1$. Suppose that $N=C_K(X)\cap L_1 \neq 1$. Note that $N\leq L_1\cap C_G(G')$.

Let us suppose by contradiction, that there are no non-trivial normal subgroups of $G$ contained in $L_1$ and $L_2$. Then by Lemma \ref{lemma-3fact-fact-centraliser}, $K\cap Z(G)=C_K(G)=(Z(G)\cap L_1)(Z(G)\cap L_2)=1$ because $Z(G)\cap L_i$ is a normal subgroup of $G$ contained in $L_i$, $i=1,2$. Write $C=C_G(T_1\cap C_G(G'))$. Note that $C$ contains $T_1G'$, therefore, $C$ is a normal subgroup of $G$. Since $T_1$, $T_2$ are abelian, $T_1\leq C$ and $G=T_1T_2$, it follows that $T_1Z(C) \leq C_G(T_1)$  and $T_2\cap T_1Z(C)\leq Z(G)$. Since $L_2\cap L_1Z(C)\leq K\cap (T_2\cap T_1Z(C))\leq K\cap Z(G)=1$, it follows
$$L_1(Z(C)\cap K)=L_1Z(C)\cap K=L_1Z(C)\cap L_1L_2=L_1(L_1Z(C)\cap L_2)=L_1.$$
Therefore, $Z(C)\cap K\leq L_1$. Since $Z(C)\cap K$ is a normal subgroup of $G$ contained in $L_1$, it follows that $Z(C)\cap K=1$. Therefore $1 \neq L_1\cap C_G(G')\leq Z(C)\cap K=1$, a contradiction.
\end{proof}





\begin{proof}[{Proof of Theorem~\ref{teo3}}]
Let $(G,K,D,C)$ be the large trifactorised group associated to $B$ and let $L_i$ be the additive group of $A_i$, $i = 1,2$. We will apply Theorem \ref{teo-3fact-sli-cont} to this factorised group , where $D = H$ and $C = E$. According to Proposition~\ref{prop-3factAss-SubBr}, $E_i=L_iD\cap C$ is a subgroup of $G$, $i = 1,2$.  By Corollary~\ref{prop-add-mul-br-eq}, $K = L_1L_2$ and $C = E_1E_2$. Since $A_i$ is abelian, $i = 1, 2$, it follows that $L_iH\cap L_iE$ is an abelian subgroup of $G$ for $i=1,2$ by Proposition~\ref{prop-3factAss-SubBr} and Corollary~\ref{prop-ab-br-eq}. Finally, since $A_1$ is left ideal of $B$, it follows that $[C, L_1] \leq L_1$ by Proposition~\ref{prop-trad-prop-br}. Applying Theorem \ref{teo-3fact-sli-cont}, there exists a non-trivial normal subgroup of $G$ contained in $L_1$ or $L_2$. By Proposition \ref{prop-trad-prop-br}, $N$ correspond to a non-zero strong left ideal of $B$ contained in $A_1$ or $A_2$.
\end{proof}


