\begin{prop}
Let $(B,+,\cdot)$ be a skew brace and let $A_1,A_2$ be subbraces of $B$ satisfying the following conditions:
\begin{itemize}
\item $A_1$ and $A_2$ are abelian skew braces.
\item $B=A_1+A_2=A_1A_2$.
\end{itemize}
Then
\begin{enumerate}
\item $\Soc_n(B)=(\Soc_n(B)\cap A_1)+(\Soc_n(B)\cap A_2)=(\Soc_n(B)\cap A_1)(\Soc_n(B)\cap A_2)$, $n>0$. \label{prop-soc-n-fact}
\item $Z_n(B)=(Z_n(B)\cap A_1)+(Z_n(B)\cap A_2)=(Z_n(B)\cap A_1)(Z_n(B)\cap A_2)$, $n>0$. \label{prop-center-n-fact}
\end{enumerate}
\end{prop}
\begin{proof}
Let us denote by $S_n=\Soc_n(B)$. $B/S_n=A_1S_n/S_n+A_2S_n/S_n=(A_1S_n/S_n)(A_2S_n/S_n)$ and $A_iS_n/S_n$, $i=1,2$, are abelian skew braces. Therefore, by Proposition \ref{prop-soc-center-fact},
$$S_{n+1}/S_n=\p{S_{n+1}/S_n\cap A_1S_n/S_n}+\p{S_{n+1}/S_n\cap A_2S_n/S_n}.$$
By Lemma \ref{lemma-inter-cent}, $A_1S_n/S_n\cap A_2S_n/S_n\leq Z(B/S_n)\leq S_{n+1}/S_n$. Applying \cite[Lemma 1.1.2]{AmbergFranciosiDeGiovanni92} it follows that $S_n=(S_n\cap A_1)+(S_n\cap A_2)$. For the product and the central series is analogous.
\end{proof}

