\item (weak monotonicity): If $D \cup E \in \D$ for $D \subseteq \A_N$ and $E \subseteq \A_A$ then $\rho^{\tilde{\mu}}(D,x) \ge \hat{\rho}(D \cup E,x)$.
\item (restrictive RU): if $D \in \D \cap 2^{\A_N}$ then $\hat{\rho}(D,x) = \rho^{\tilde{\mu}}(D,x)$
\end{itemize}
(ii) Assume that $|X(a)| \ge |\tilde{X}| +2$ for all $a \in \A_A$. Then $\hat{\rho}$ is RU rationalizable if and only if there exists $\tilde{mu}$ satisfying the two conditions above.
\item The above conditions becomes simple  when $\D \cap 2^{\A_N} = \emptyset$ (any choice set contains at least one aggregated alternative), the condition becomes there exists $\tilde{\mu} \in \Delta(\L (\tilde{X}))$ such that $\rho^{\tilde{\mu}}(D,x) \ge \rho(D \cup E,x)$ for all $D \cup E \in \D$ and $x \in D$ where $\emptyset \neq E \subseteq \A$.
\end{itemize}
\end{remark}


\begin{remark}\label{rem:all_aggregated}
