\subsection{Proof of Theorem \ref{thm:1}}
\begin{proof} The necessity is trivial. We prove the sufficiency. Assume the two conditions and $|X(a_0)| \ge |\tilde{X}| + 1$.

Under condition $(i-b)$, there exists $\tilde{\mu} \in \Delta (\L(\tilde{X}))$.  For each $y \in \tilde{X}$, choose an element of  $X(a_0)$ denoted by $x_0(y)$. We will also fix a unobservable alternative $\underline{x}$ that plays a special role in the following. Note that such alternatives exist because  $|X(a_0)| \ge |\tilde{X}| + 1$.

 Fix a ranking $\tilde \succ$ on $\tilde{X}$ that belongs to the support of $\tilde{\mu}$,  we extend $\tilde \succ$ and define a ranking $\succ$ on $\tilde{X}\cup X^*$ as follows. (Remember $X^*=X(a_0)$ since $\A_A=\{a_0\}$.)  First, for each  $y \in \tilde{X}$, place $x_0(y) \in X(a_0)$ just above $y$ and $\underline{x}$ at the bottom for all $\tilde \succ \in supp (\tilde \mu)$. For example, if the ranking $y_1\  \tilde \succ\   y_2\   \tilde \succ\  
 y_3$ is in the support then we extend $\tilde \succ$  to $\succ$ on $\tilde{X} \cup X^*$ as follows
 \[
 x_0(y_1) \succ y_1 \succ x_0(y_2) \succ y_2 \succ x_0(y_3) \succ y_3 \succ \underline{x}.
 \]
Finally, we define $\mu \in \Delta (\L(\tilde{X} \cup X^*))$ as follows: for each extended ranking $\succ$ defined above, we let $\mu(\succ)=\tilde{\mu}(\tilde\succ)$. 

Let $\rho$ be a random utility model that is rationalized by $\mu$. Now fix $D\subset \tilde{X}$. In the following, we will construct $\lambda \in \prod_{b \in D \cup a_0} (2^{X(b)} \setminus \emptyset)$ to establish the following equality for all $b \in D \cup a_0$: 
\[
\sum_{(S_b)_{b \in D \cup a_0} \subset \prod_{b \in D \cup a_0} (2^{X(b)} \setminus \emptyset)}\lambda((S_b)_{b \in D \cup a_0} ) \rho(\cup_{b \in D \cup a_0} S_b, S_b) =\hat\rho(D \cup a_0,b).
\]
Since $D \subset \tilde X$, for all $b \in D$, there exists $y_b$ such that $X(b)=\{y_b\}$. 


Thus, for any $(S_b)_{b \in D \cup a_0} \subset \prod_{b \in D \cup a_0} (2^{X(b)} \setminus \emptyset)$, $S_b$ is determined as $\{y_b\}$ for all $b \in D$. Thus, for simplicity, we will focus on the marginal distribution of $\lambda$ on $2^{X(a_0)} \setminus \emptyset$  and obtain the following equality: 
\begin{equation} 
\sum_{S \subseteq X(a_0)}\lambda(S) \rho(\{y_b| b \in D\} \cup S, y_b) =\hat\rho(D \cup a_0,b)\quad \text{ for all }b \in D
\end{equation}
and
\begin{equation}\label{eq:pf2}
\sum_{S \subseteq X(a_0)}\lambda(S) \rho(\{y_b| b \in D\} \cup S, S) =\hat\rho(D \cup a_0,a_0).
\end{equation}
Note that (\ref{eq:pf2}) is implied by (\ref{eq:pf1}) by the fact that the probability must be sum up to one. In the following, to simplify the notation, we identify $y_b$ and $b$ for $b \in D \subseteq \tilde X$ and write them as $y$. Thus, we write $\{y_b| b \in D\}$ as $D$. The  purpose of our proof is, thus, to show the existence of $\lambda$ on $2^{X(a_0)} \setminus \emptyset$ that satisfies the following equality for all $y \in D$,\footnote{Remember that this $\lambda$ is an aggregation function for the choice set $D \cup\{a_0\}$. For another choice set $E \cup\{a_0\}$, one can construct a desirable aggregation function in the same way.}
\begin{equation}\label{eq:pf1} 
\sum_{S \subseteq X(a_0)}\lambda(S) \rho(D \cup S, y) =\hat\rho(D \cup a_0, y).
\end{equation}


We will define $\lambda$ recursively.  We first label elements of $D$ by $y_i$ so that $\frac{\hat\rho(D\cup {a}_0,y_0)}{\hat\rho(D,y_0)}$ is maximal among $\frac{\hat\rho(D\cup a_0,y_i)}{\hat\rho(D ,y_i)}$.\footnote{Note that $D$ consists of underlying alternatives that non-aggregated alternatives represent. Remember that for each non-aggregate alternative $a \in\A_N$, $X(a)$ is singleton.  We identify $a$ and $x$, where $X(a)=\{x\}$. Thus we can view $D$ as a subset of $\tilde{X}$ as well as a subset of ${\mathscr A}$, and hence, $\hat{\rho}(D, )$ is well defined.} Initially, we define $\lambda_0$ by  
\[
\lambda_0(\underline{x}) = \frac{\hat\rho(D \cup a_0,y_0)}{\hat\rho(D ,y_0)}, \quad \lambda_0(X^*) = 1-\lambda_0(\underline{x})
\]
and all other values are zero. Then $\lambda_0$ is a probability measure because $\lambda_0(\underline{x})\le 1$ by the monotonicity with respect to aggregated alternatives.  Moreover, the chance that $y_0$ is chosen is equal to $\hat\rho(D\cup a_0, y_0)$ as desired:
\begin{align*}
\sum_{S \subseteq X(a_0)}\lambda_0(S) \rho(D \cup S, y_0)
&=\lambda_0(\underline{x})   \rho(D\cup \{\underline{x}\},y_0) + \lambda_0(X^*)   \rho(D\cup X^*,y_0) \\
&= \lambda_0(\underline{x})   \rho(D\cup \{\underline{x}\},y_0) \quad (\because x(y_0) \succ y_0 \text{ for all } \succ \in supp(\mu))\\
&= \lambda_0(\underline{x})   \rho(D ,y_0)  \quad\quad\quad\quad (\because y_0 \succ \underline{x} \text{ for all } \succ \in supp(\mu))\\
&= \lambda_0(\underline{x})   \hat\rho(D ,y_0) \\
&=\hat\rho(D\cup a_0,y_0),
\end{align*}
where the fourth equality holds because $\rho(D ,y_0)=\hat\rho(D ,y_0)$ because all elements in $D$ are non-aggregated alternatives. 


Given $\lambda_0$, we will  define $\lambda_1$ that satisfy (\ref{eq:pf1}) for $y_0$ and $y_1$. First remember that since $\frac{\hat\rho(D \cup {a}_0,y_0)}{\hat\rho(D ,y_0)}$ is maximal among $\frac{\hat\rho(D \cup {a}_0,y_i)}{\hat\rho(D ,y_i)}$, we have
\begin{eqnarray*}   
\lambda_0(\underline{x})\equiv\dfrac{\hat{\rho}(D\cup {a}_0,y_0)}{\hat{\rho}(D ,y_0)} \ge \dfrac{\hat{\rho}(D\cup {a}_0,y_i)}{\hat{\rho}(D ,y_i)}=\dfrac{\hat{\rho}(D\cup {a}_0,y_i)}{\rho(D ,y_i)} =\dfrac{\hat{\rho}(D\cup {a}_0,y_i)}{\rho(D\cup \{\underline{x}\},y_i)},
\end{eqnarray*}
where the second to the last equality holds because $\rho(D ,y_i)=\hat\rho(D ,y_i)$; and the last equality holds because $\underline{x}$ is the worst alternative for any $\succ \in supp (\mu)$. Thus $\lambda_0(\underline{x})   \rho(D\cup \{\underline{x}\}, y_i) \ge \hat{\rho}(D\cup a_0, y_i)$. By using this inequality, we have 
\begin{eqnarray*}
\sum_{S \subseteq X(a_0)}\lambda_0(S) \rho(D \cup S, y_i)=\lambda_0(\underline{x})   \rho(D\cup \{\underline{x}\}, y_i) + \lambda_0(X^*)   \rho(D\cup X^*, y_i)  &= \lambda_0(\underline{x})   \rho(D\cup \{\underline{x}\}, y_i) \\
&\ge \hat{\rho}(D\cup {a}_0, y_i).
\end{eqnarray*}
This inequality suggests that we should decrease the value of $\lambda_0(\underline{x})$ to have the desired equality for $i>0$. Given the observation, we define $\lambda_1$ given $\lambda_0$ as follows. The  idea is to move probability from $\lambda_0(\underline{x})$ to $\lambda_0(\underline{x},x_0(y_1))$ so that the chance that $y_1$ is chosen decreases to $\hat\rho(D \cup a_0,y_1)$ as desired.  More precisely, we define $\lambda_1$ as follows:
\[
\lambda_1(\underline{x})= \frac{\hat{\rho}(D\cup {a}_0,y_1)}{\hat{\rho}(D,y_1)}, \quad \lambda_1(\underline{x}, x_0(y_1))= \lambda_0(\underline{x})-\lambda_1(\underline{x}), \quad \lambda_1(X^*)=\lambda_0(X^*). 
\]
To see that  $\lambda_1$ is a probability measure, notice that $\lambda_1(\underline{x}, x_0(y_1))\ge 0$ because $\frac{\hat\rho(D \cup {a}_0, y_0)}{\hat\rho(D ,y_0)} \ge \frac{\hat\rho(D \cup {a}_0,y_1)}{\hat\rho(D ,y_1)}$. Moreover, we have the desired equalities for $y_1$ and $y_0$ as follows:
\begin{align*}
&\sum_{S \subseteq X(a_0)}\lambda_1(S) \rho(D \cup S, y_1)\\
&=\lambda_1(\underline{x})   \rho(D\cup \{\underline{x}\}, y_1)+ \lambda_1(\underline{x},x_0(y_1)
) \rho(D\cup \{\underline{x},x_0(y_1)\}, y_1) + \lambda_1(X^*)   \rho(D\cup X^*, y_1) \\ 
&= \lambda_1(\underline{x})   \rho(D\cup \{\underline{x}\}, y_1)\quad (\because x_0(y_1)\succ y_1 \text{ for all }\succ   \in supp(\mu)) \\
&= \lambda_1(\underline{x})   \rho(D , y_1) \quad (\because y_1 \succ \underline{x}\text{ for all }\succ  \in supp(\mu)) \\
&= \lambda_1(\underline{x})   \hat\rho(D , y_1) \\
&=\hat\rho(D\cup a_0, y_1)
\end{align*}
and 
\begin{align}\label{eq:315}
&\sum_{S \subseteq X(a_0)}\lambda_1(S) \rho(D \cup S, y_0) \nonumber \\
&=\lambda_1(\underline{x})   \rho(D\cup \{\underline{x}\},y_0)+ \lambda_1(\underline{x},x_0(y_1)) \rho(D\cup \{\underline{x},x_0(y_1)\},y_0) + \lambda_1(X^*)   \rho(D\cup X^*,y_0) \nonumber \\
&= \big( \lambda_1(\underline{x})+\lambda_1(\underline{x},x_0(y_1)
) \big)   \rho(D\cup \{\underline{x}\},y_0)+ \lambda_1(X^*)   \rho(D\cup X^*,y_0)\\
&=\lambda_0(\underline{x})   \rho(D\cup \{\underline{x}\},y_0) + \lambda_0(X^*)   \rho(D\cup X^*,y_0) \nonumber\\
&=\lambda_0(\underline{x})   \rho(D\cup \{\underline{x}\},y_0) \nonumber \\
&= \hat{\rho}(D\cup a_0,y_0). \quad(\because \text{Definition of } \lambda_0), \nonumber
\end{align}%make all one label (number 5)
where the second equality holds because  for all $\succ \in supp(\mu)$, $x_0(y_1)$ is the immediate predecessor of $y_1$ so adding $x_0(y_1)$ changes the only the probability of choice frequency of $y_0$, thus $\rho(D\cup \{\underline{x}\},y_0) = \rho(D\cup \{\underline{x},x_0(y_1) \},y_0)$. 

In general, at $n$th step, given $\lambda_{n-1}$ that satisfy (\ref{eq:pf1}) for all $y \in \{y_1,\dots, y_{n-1}\}$, we will define $\lambda_n$ that satisfy (\ref{eq:pf1}) for all $y \in \{y_1,\dots, y_{n-1},y_{n}\}$. First define
\[
c_n = \frac{\hat\rho(D \cup a_0,y_n)}{\hat\rho(D ,y_n) \lambda_0(\underline{x})}.
\]
 Note $0 \le c_n \le 1$ because $\frac{\hat\rho(D \cup a_0,y_0)}{\hat\rho(D ,y_0)}$ is maximal among $\frac{\hat\rho(D \cup a_0,y_i)}{\hat\rho(D ,y_i)}$. Let $\lambda_n(X^*) = \lambda_0(X^*)$ and for each $S$ in the support of $\lambda_{n-1}$ except $X^*$
 \[
 \lambda_n(S) = c_n\lambda_{n-1}(S), \quad \lambda_n(S \cup x_0(y_n)) = \lambda_{n-1}(S)-\lambda_{n}(S).
 \]
Note first that $\lambda_n$ is a probability measure given that $\lambda_{n-1}$ is a probability measure.   Note also this modification of $\lambda_n$ from $\lambda_{n-1}$ does not change the chance that $y_i$ is chosen for any $i  \le n-1$; this only changes the chance that $y_n$ is chosen because adding $x_0(y_n)$ changes only the choice frequency of $y_n$ as in (\ref{eq:315}). Moreover, we obtain the desired equalities for the choice frequency of $y_n$ as follows:
    \begin{align*}
&\sum_{S \subseteq X(a_0)}\lambda_n(S) \rho(D \cup S, y_n)\\    
&=\lambda_{n-1}(X^*)\rho(D\cup X^*,y_n) +\\
&\sum_{S \in supp(\lambda_{n-1})\setminus \{X^*\}} c_n\lambda_{n-1}(S)\rho(D\cup S , y_n) + (1-c_n)\lambda_{n-1}(S)\rho(D\cup S \cup x_0(y_n), y_n) \\
&= \sum_{S \in supp(\lambda_{n-1})\setminus \{X^*\}} c_n\lambda_{n-1}(S)\rho(D\cup S , y_n) \quad (\because x_0(y_n) \succ y_n \text{ for all }\succ \in supp (\mu))\\
&= \sum_{S \in supp(\lambda_{n-1})\setminus \{X^*\}} c_n\lambda_{n-1}(S) \rho(D, y_n) \\
&= c_n\sum_{S \in supp(\lambda_{n-1})\setminus \{X^*\}} \lambda_{n-1}(S) \hat\rho(D, y_n) \quad (\because \hat\rho(D, y_n)=\rho(D, y_n) )\\
&=c_n \lambda_0(\underline{x})\hat\rho(D, y_n)\quad (\because \sum_{S \in supp(\lambda_{n-1})\setminus \{X^*\}} \lambda_{n-1}(S)=1-\lambda_{n-1}(X^*)=1-\lambda_{0}(X^*)=\lambda_{0}(\{\underline{x}\}))\\
&= \hat\rho(D\cup a_0, y_n),
\end{align*}
where the last equality holds by the definition of $c_n$; the fourth to the last equality holds because $y_n$ is the maximal element among $D$ with respect to $\succ$ if and only if  $y_n$ is the maximal element among $D \cup S$ with respect to $\succ$ since $S\subseteq \{x_0(y_i)| i < n\}\cup\{\underline{x}\}$ and $x_0(y_i)$ is the immediate predecessor of $y_i$ for all $ \succ \in supp(\mu)$.
\end{proof}

\subsection{Proof of Theorem \ref{thm:1multiple}}
\begin{proof}

The necessity is trivial. We show the sufficiency. For each $a \in \A_A$ and $y \in \tilde{X}$, choose  an element of $X(a)$, denoted by $x_a(y)$. We also fix two alternatives $\overline{x}_a, \underline{x}_a \in X(a)$. Note that there exist such alternatives under the assumption that $|X(a)| \ge |\tilde{X}| +2$ for all $a\in \A_A$. 


By the assumption that $\tilde{\rho}$ is RUM on $\tilde{X}$, there exists a distribution $\tilde{\mu}$ over linear orders $\tilde{\succ}$ on $\tilde{X}$ that rationalizes $\hat{\rho}$ on $\tilde X$.  Based on this distribution, we will construct RUM $\rho$ on the entire set $\tilde{X}\cup X^*$ of the underlying alternatives as follows. For each ranking on $\tilde{X}$ in the support of $\tilde{\mu}$, we construct ranking on $\tilde{X} \cup X^*$: we place $x_a(y)$ right above $y$, $\overline{x}_a$ and $\underline{x}_a$ at the bottom with $\overline{x}_a$s above $\underline{x}_a$s. The order among aggregated alternatives is arbitrarily fixed. For example, let $\{a_0,a_1\}=\A_A$ and fix an order  by index. Also let $\tilde{X} = \{y_0,y_1\}$ and $y_0\ \tilde{\succ}\ y_1$. Then, we define $\succ$ on $\tilde{X}\cup X^*$ as follows: 
\[
x_0(y_0) \succ x_1(y_0) \succ y_0 \succ x_0(y_1) \succ x_1(y_1) \succ y_1 \succ \overline{x}_0\succ \overline{x}_1 \succ \underline{x}_0 \succ \underline{x}_1.
\]

Fix $D  \subseteq \A_N$ and $E \subseteq \A_A$. In the following, we will construct $\lambda \in \prod_{b \in D \cup E} (2^{X(b)} \setminus \emptyset)$ to establish the following equality for all $b \in D \cup E$: 
\[
\sum_{(S_b)_{b \in D \cup E} \subseteq \prod_{b \in D \cup E} (2^{X(b)} \setminus \emptyset)}\lambda((S_b)_{b \in D \cup E} ) \rho(\cup_{b \in D \cup E} S_b, S_b) =\hat\rho(D \cup E,b).
\]
With using the same simplified notation and the reasoning in the proof of Theorem \ref{thm:1}, the purpose of the proof is to show the existence of a probability distribution $\lambda$ on $\prod_{b\in E} (2^{X(b)}\setminus \emptyset)$ that satisfies 
\begin{equation}\label{eq:388}
\sum_{(S_b)_{b \in E} \in \prod_{b \in E} (2^{X(b)} \setminus \emptyset)} \lambda((S_b)_{b \in E}) \rho(D \cup (\cup_{b\in E} S_b), y)=\hat\rho(D\cup E,y) \text{ for all } y \in D,
\end{equation}
and
\begin{equation}\label{eq:392}
\sum_{(S_b)_{b \in E} \in \prod_{b \in E} (2^{X(b)} \setminus \emptyset)} \lambda((S_b)_{b \in E}) \rho(D \cup (\cup_{b\in E} S_b), S_b)=\hat\rho(D\cup E,b) \text{ for all } b \in E.
\end{equation}

The proof consists of two steps. At the first step, for each $a \in E$ we will construct a $\lambda^a$  in the same way as the single outside option case (i.e., Theorem \ref{thm:1}) except replace $\underline{x}$ with $\overline{x}_a$ and add $\underline{x}_a$ to all the sets. Given $\lambda^a$, in the second step, by taking a convex combination of $\lambda^a$, we will obtain the desired $\lambda$ that satisfy (\ref{eq:388}) and (\ref{eq:392}) for the given $D$ and $E$.


\textbf{Step 1: } We first label elements of $D$ by $y_i$ so that $\frac{\hat\rho(D\cup E,y_0)}{\hat\rho(D,y_0)}$ is maximal among $\frac{\hat\rho(D\cup E,y_i)}{\hat\rho(D,y_i)}$. We will construct a probability distribution $\lambda^a$ on $\prod_{b\in E} (2^{X(b)}\setminus \emptyset)$ recursively. Initially, we  define $\lambda^a_0$ by  
\begin{equation}
\lambda^a_0(\overline{x}_a, (\underline{x})_{E\setminus a}) = \frac{\hat\rho(D\cup E,y_0)}{\hat\rho(D,y_0)},\quad \lambda^a_0( (X(b))_{b\in E}) = 1-\lambda^a_0(\overline{x}_a, (\underline{x})_{E\setminus a})
\end{equation}
and all other lambdas are zero. By the monotonicity with respect to the aggregated alternatives,  we have $\lambda^a_0(\overline{x}_a, (\underline{x})_{E\setminus a})\le 1$, thus $\lambda^a_0$ is a probability measure. Moreover, the probability that  $y_0$ is chosen equals to $\hat\rho(D \cup E,y_0)$ as desired:
 \begin{align*}
 &\sum_{(S_b)_{b \in E} \in \prod_{b\in E} (2^{X(b)}\setminus \emptyset)} \lambda^a_0((S_b)_{b \in E}) \rho(D \cup (\cup_{b\in E}S_b), y_0)\\
&= \lambda^a_0(\overline{x}_a, (\underline{x})_{E\setminus a})  \rho(D \cup  \{\overline{x}_a, (\underline{x})_{E\setminus a}\},y_0) + \lambda^a_0((X(b))_{b \in E})   \rho(D\cup (\cup_{b \in E} X(b)),y_0)  \\
 &=  \lambda^a_0(\overline{x}_a, (\underline{x})_{E\setminus a})  
 \rho(D \cup  \{\overline{x}_a, (\underline{x})_{E\setminus a}\},y_0)
 \quad \quad \quad \quad \quad \quad \quad   (\because x_a(y_0) \succ y_0 \text{ for all }\succ \in supp (\mu)) \\
 &= \lambda^a_0(\overline{x}_a, (\underline{x}_a)_{E\setminus a})  \hat\rho(D,y_0) \quad \quad \quad \quad \quad \quad \quad \quad (\because  y_0 \succ \overline{x}_a, \underline{x}_b \text{ for all }b \in E \setminus a \text{ and } \succ \in supp (\mu))\\
 &=\hat\rho(D\cup E,y_0).
\end{align*}
Next we define $\lambda^a_1$ based on $\lambda^a_0$ to satisfy the equality for $\hat{\rho}(D\cup E, y_1)$. In general at the $n$th step to obtain the desired equality for $\hat{\rho}(D\cup E, y_n)$, let 
\[c_n = \frac{\hat\rho(D\cup E,y_n)}{\hat\rho(D,y_n) \lambda^a_0(\overline{x}_a, (\underline{x})_{E\setminus a})}.
\]
Note $0 \le c_n \le 1$ by our choice of $y_0$. We define $\lambda^a_n$ by 
$\lambda^a_n( (X(b))_{b \in E}) = \lambda^a_0((X(b))_{b \in E})$ and for all $(S_b)_{b \in E}\in supp (\lambda^a_{n-1})\setminus (X(b))_{b \in E}$
\[
\lambda^a_n( (S_b)_{b \in E}) = c_n\lambda^a_{n-1}((S_b)_{b \in E}),\quad 
\lambda^a_n(S_a \cup x_a(y_n) \ , \  (S_b)_{b \in E \setminus a}) = (1-c_n)\lambda^a_{n-1}((S_b)_{b \in E}).
\]
Note first that $\lambda^a_n$ is a probability measure given that $\lambda^a_{n-1}$ is a probability measure.   Note also this modification of $\lambda^a_n$ from $\lambda^a_{n-1}$ does not change the chance that $y_i$ is chosen for any $i  \le n-1$; this only changes the chance that $y_n$ is chosen because adding $x_a(y_n)$ changes only the choice frequency of $y_n$. Moreover, we obtain the desired equalities for the choice frequency of $y_n$ as follows:
\begin{align*}
& \sum_{(S_b)_{b \in E} \in \prod_{b \in E} (2^{X(b)}\setminus \emptyset)} \lambda^a_n((S_b)_{b \in E}) \rho(D \cup (\cup_{b\in E} S_b), y_n)\\
& =\lambda^a_0((X(b))_{b \in E} )\rho(D \cup (\cup_{b\in E} X(b)), y_n) \\
&+
\sum_{(S_b)_{b \in E} \in supp(\lambda^a_{n-1})\setminus (X(b))_{b \in E}} \Big[ c_n\lambda^a_{n-1}((S_b)_{b \in E})\rho(D \cup (\cup_{b \in E}S_b) , y_n)\\
&\quad\quad\quad\quad  + (1-c_n)\lambda^a_{n-1}((S_b)_{b \in E})\rho(D \cup (\cup_{b \in E}S_b) \cup x_a(y_n), y_n) \Big] \\
&= \sum_{(S_b)_{b \in E} \in supp(\lambda^a_{n-1})\setminus (X(b))_{b\in E}}
c_n\lambda^a_{n-1}((S_b)_{b \in E})\rho(D \cup (\cup_{b \in E}S_b) , y_n) \quad (\because x_a(y_n) \succ y_n \text{ for all }\succ \in supp (\mu))\\
&= \sum_{(S_b)_{b \in E} \in supp(\lambda^a_{n-1})\setminus (X(b))_{b \in E}} c_n\lambda^a_{n-1}((S_b)_{b \in E})\hat\rho(D , y_n)\\
&=c_n \lambda^a_0(\overline{x}_a, (\underline{x})_{E\setminus a})\hat\rho(D , y_n)\\
&= \hat\rho(D\cup E,y_n),
\end{align*}
where the second to the last equality holds because $\sum_{(S_b)_{b \in E} \in supp(\lambda^a_{n-1})\setminus (X(b))_{b \in E}}\lambda^a_{n-1}((S_b)_{b \in E})=1-\lambda^a_{n-1}((X(b))_{b \in E})=1-\lambda^a_{0}((X(b))_{b \in E})=\lambda^a_{0}(\overline{x}_a, (\underline{x})_{E\setminus a})
$ and the third to the last equality holds because $y_n$ is a maximal element among $D$ with respect to $\succ$ if and only if  $y_n$ is a maximal element among $D\cup (\cup_{b \in E} S_b)$ with respect to $\succ$ since $S_b\subseteq \{x_b(y_i)| i < n\}\cup\{\underline{x}_b, \overline{x}_b| b \in \A_A\}$ and $x_b(y_i)$ is the immediate predecessor of $y_i$ for all $ \succ \in supp(\mu)$. It follows that $\lambda^a$ satisfies (\ref{eq:388}) as desired: for all $y \in D$
\begin{equation}\label{eq:la_a_1}
\sum_{(S_b)_{b \in E} \in \prod_{b\in E} (2^{X(b)}\setminus \emptyset)}\lambda^a((S_b)_{b \in E})  \rho(D\cup (\cup_{b\in E} S_b), y)=\hat{\rho}(D \cup E, y).
\end{equation}

\textbf{Step 2:}  In the following, given $(\lambda^a)_{a \in \A_A}$, we will construct $\lambda$ that satisfies (\ref{eq:392}) as well as (\ref{eq:388}).  First observe 
 that for all $a \in \A_A$,
\begin{eqnarray}\label{eq:185}
\sum_{(S_b)_{b \in E} \in \prod_{b \in E} (2^{X(b) }\setminus \emptyset)}\lambda^a((S_b)_{b \in E})  \rho(D\cup (\cup_{b\in E} S_b),S_b)=
\left\{
\begin{array}{llll}
1-\sum_{y \in D}\hat{\rho}(D\cup E,y) &\text{ if }b=a,\\
0 &\text{ if $b \neq a$}.
\end{array}
\right.
\end{eqnarray}
We denote the left hand side of the above equation as $ \hat{\rho}^a(D\cup E,b)$.  

Define 
\[
\lambda= \sum_{a \in E}\lambda^a \Bigg(\dfrac{\hat{\rho}(D\cup E,a)}{1-\sum_{y \in D}\hat{\rho}(D\cup E,y)}\Bigg).
\]
Since $\sum_{a \in E}\hat{\rho}(D\cup E,a)=1-\sum_{y \in D}\hat{\rho}(D\cup E,y)$ and each $\lambda^a$ is a probability distribution on  $\prod_{a \in E}2^{X(a)}\setminus \emptyset$, so is $\lambda$.  Moreover, we have the desired equalities for choice frequency of each aggregated alternative $b \in E$ as follows:
\begin{align*}
&\sum_{(S_b)_{b \in E} \in \prod_{b\in E} (2^{X(b)}\setminus \emptyset) }\lambda((S_b)_{b \in E})\rho(D\cup (\cup_{b\in E} S_b),S_b)\\
&=\sum_{(S_b)_{b \in E} \in \prod_{b\in E} (2^{X(b)}\setminus \emptyset) }\Bigg(
\sum_{a \in E}\lambda^a((S_b)_{b \in E})  \dfrac{\hat{\rho}(D\cup E,a)}{1-\sum_{y \in D}\hat{\rho}(D\cup E,y)}\Bigg) \rho(D\cup (\cup_{b\in E} S_b),S_b)
\\
&=\sum_{a\in E} \Bigg(\dfrac{\hat{\rho}(D\cup E,a)}{1-\sum_{y \in D}\hat{\rho}(D\cup E,y)}\Bigg)
\sum_{(S_b)_{b \in E} \in \prod_{b\in E} (2^{X(b)}\setminus \emptyset)}\lambda^a((S_b)_{b \in E})  \rho(D\cup (\cup_{b\in E} S_b),S_b)\\
&=\sum_{a \in E} \Bigg(\dfrac{\hat{\rho}(D\cup E,a)}{1-\sum_{y \in D}\hat{\rho}(D\cup E,y)}\Bigg)\hat{\rho}^a(D\cup E,b) \quad (\because \text{Definition of }\hat{\rho}^a(D\cup E,b))\\
&= \Bigg(\dfrac{\hat{\rho}(D\cup E,b)}{1-\sum_{y \in D}\hat{\rho}(D\cup E,y)}\Bigg)\hat{\rho}^b(D\cup E,b)+ \Bigg(\sum_{a \in E \setminus b} \dfrac{\hat{\rho}(D\cup E,a)}{1-\sum_{y \in D}\hat{\rho}(D\cup E,y)}\Bigg)\hat{\rho}^a(D\cup E,b)\\
&=\hat{\rho}(D\cup E,b). \quad\quad (\because (\ref{eq:185}))
\end{align*}
Thus, $\lambda$ satisfies (\ref{eq:392}). Finally, to show that $\lambda$ satisfies (\ref{eq:388}), choose  $z \in D$. Then, we have
\begin{align*}
&\sum_{(S_b)_{b \in E} \in \prod_{b\in E} (2^{X(b)}\setminus \emptyset) }\lambda((S_b)_{b \in E})\rho(D\cup (\cup_{b\in E} S_b),z)\\
&=\sum_{(S_b)_{b \in E} \in \prod_{b\in E} (2^{X(b)}\setminus \emptyset) }\Bigg(
\sum_{a \in E}\lambda^a((S_b)_{b \in E})  \dfrac{\hat{\rho}(D\cup E,a)}{1-\sum_{y \in D}\hat{\rho}(D\cup E,y)}\Bigg) \rho(D\cup (\cup_{b\in E} S_b),z)
\\
&=\sum_{a\in E} \Bigg(\dfrac{\hat{\rho}(D\cup E,a)}{1-\sum_{y \in D}\hat{\rho}(D\cup E,y)}\Bigg)
\sum_{(S_b)_{b \in E} \in \prod_{b\in E} (2^{X(b)}\setminus \emptyset)}\lambda^a((S_b)_{b \in E})  \rho(D\cup (\cup_{b\in E} S_b),z)\\
&=\sum_{a\in E} \Bigg(\dfrac{\hat{\rho}(D\cup E,a)}{1-\sum_{y \in D}\hat{\rho}(D\cup E,y)}\Bigg)\hat{\rho}(D \cup E, z)\quad (\because (\ref{eq:la_a_1}))\\
&=\hat{\rho}(D \cup E, z),
\end{align*}
where the last equality holds because $\sum_{a\in E} \hat{\rho}(D\cup E,a)=1-\sum_{y \in D}\hat{\rho}(D\cup E,y)$.



\end{proof}


\section{Characterization without domain assumption}\label{sec:domain}

In the main results of the paper, we assume either that choice frequencies for all menus are available to the analyst or the weaker assumption that when a choice set containing the outside option $D \cup \{x_0\}$ is available, $D$ is also available. In this section we discuss RU rationality without these assumptions. We will focus on the case where every observable choice set contains the outside option $a_0$. The assumption that $a_0$ is always available is based on the common assumption that the outside option or status quo is always available.

\begin{definition}
An outside option domain is a set $\D \subseteq 2^{\A}$ such that $a_0 \in D $ for all $D \in \D$.
\end{definition} 


The following lemma follows from Theorem \ref{thm:1}

\begin{lemma}\label{lem:incomplete-rational}
Suppose that $|X(a_0)| \ge |\tilde{X}| + 1$. Then an outside option domain stochastic choice function is RU rational if and only if there exists $\hat{\mu}_N \in \Delta(\L(\A_N))$ such that $\hat{\mu}_N(\ \succ \in \L(\A_N) \  | a \succ b \text{ for all } b \in D \setminus \{a,a_0\}) \ge \hat{\rho}(D, a)$ for all $D \in \D$ and $a \in D \setminus a_0$.
\end{lemma}

\begin{proof}
If $\hat{\rho}$ is an outside option domain stochastic choice function that is rationalized by $(\mu,\lambda)$ then letting  $\hat{\mu}_N$ be the restriction of $\mu$ to $\A_N$ yields the desired inequality.\\

On the other hand, suppose there exists $\hat{\mu}_N \in \Delta(\L(\A_N))$ such that $\hat{\mu}_N(\ \succ \in \L(\A_N) \  | a \succ b \text{ for all } b \in D \setminus \{a,a_0\}) \ge \hat{\rho}(D, a)$ for all $D \in \D$ and $a \in D \setminus a_0$. Then there exists a complete stochastic choice function $\hat{\rho}'$ that equals $\hat{\rho}$ on $\D \times \A$ and satisfies conditions (i-a), (i-b), and (ii) of Theorem \ref{thm:1}. Since $\hat{\rho}'$ is RU rational by Theorem \ref{thm:1}, $\hat{\rho}$ is also RU rational.
\end{proof}

To eliminate the existential quantifier, we will use the following consequence of Farkas lemma.

\begin{lemma}
Let $M \in \mathbb{R}^{n \times m}$ and let $b \in \mathbb{R}^n$. Then exactly one of the two following statements holds:
\begin{enumerate}
\item There exists $\mu \in \mathbb{R}^m$ such that $M \mu \ge b$, $\mu \ge 0$, and $\mu \textbf{1} =1$.

\item There exists $\nu \in \mathbb{R}^m_+$ and $\beta \in \mathbb{R}$ such that $M^T \nu +\beta \textbf{1} <0$ and $\nu^T b + \beta \ge 0$.

\end{enumerate}

\end{lemma}

\begin{lemma}\label{lem:farkas}
Suppose that $|X(a_0)| \ge |\tilde{X}| + 1$. Then an outside option domain stochastic choice function is RU rational if and only if \[
\max_{\hat\succ \in \L (X)}\sum_{a \in D \setminus a_0, \ D \in \D}\nu(D,a) \rho^{\hat{\succ}}(D,a) \ge \sum_{a \in D \setminus a_0, \ D \in \D} \nu(D,a)\hat{\rho}(D,a)
\]
for all nonnegtaive real functions $\nu$ on $\{(D,a) \in \D \times \A_n : a\in D \}$.
\end{lemma}
\begin{proof}
Let $M$ be the matrix with columns indexed by $\hat\succ \in \L(\A)$ with each column the vector of values of $\rho^{\hat\succ}(D,a)$ for each observable $D \cup \{a_0\}$ and $a \in D$. Let $b$ be the vector of values of $\hat\rho(D \cup \{a_0\},a)$ for each $a \in D$. By Lemma \ref{lem:incomplete-rational}, the RU rationality of $\hat\rho$ is equivalent to 1. of Lemma \ref{lem:farkas}. Thus by Lemma \ref{lem:farkas}, $\hat\rho$ is RU rational if and only if there does not exist $\nu \in \mathbb{R}^m_+$ and $\beta \in \mathbb{R}$ such that $M^T \nu +\beta \textbf{1} <0$ and $\nu^T b + \beta \ge 0$. Equivalently  $\hat\rho$ is RU rational if and only if for all $\nu \in \mathbb{R}^m_+$ and $\beta \in \mathbb{R}$ and $\nu^T b + \beta \ge 0$, it holds that $M^T \nu +\beta \textbf{1} \not< 0$.\\
For each $\nu$, suppose $M^T \nu +\beta \textbf{1} \not< 0$ holds for $\beta = -\nu^Tb$. Then for all $\beta$ satisfying $\nu^T b + \beta \ge 0$ it holds that $M^T \nu +\beta \textbf{1} \not< 0$. Thus we may replace the for all $\beta$ condition above with $\beta = -\nu^Tb$. \\
Finally, we obtain the characterization $\hat\rho$ is RU rational if and only if for all $\nu \in \mathbb{R}^m_+$  it holds that $M^T \nu \not< \nu^Tb \textbf{1}$. This is exactly the same as the inequality \[
\max_{\hat\succ \in \L (X)}\sum_{a \in D \setminus a_0, \ D \in \D}\nu(D,x) \rho^{\hat{\succ}}(D,a) \ge \sum_{a \in D \setminus a_0, \ D \in \D} \nu(D,a)\hat{\rho}(D,a) \] and thus the result is shown.


\end{proof}


