\section{Independent $\lambda$: Monotonicity}

\begin{remark}
If $\lambda$ is independent, $\hat{\rho}$ satisfies monotonicity: 
$\hat{\rho}(B,b)\ge \hat{\rho}(B\cup E,b)$
\end{remark}

\begin{proof}
\[
\hat{\rho}(B,b)= \sum_{D\in {\mathscr D}(B)}
\prod_{a \in B} \lambda_a(D(a))\rho(\cup_{a \in B} D(a),D(b)).
\]

\begin{eqnarray*}
\displaystyle \hat{\rho}(B\cup E,b)
&=&\sum_{D\in {\mathscr D}(B\cup E)}
\prod_{a \in B\cup E} \lambda_a(D(a))\rho(\cup_{a \in B\cup E} D(a),D(b))\\
&=& \sum_{D' \in {\mathscr D}(E), D\in {\mathscr D}(B)}
\prod_{a' \in E} \lambda_{a'}(D'(a')
)\prod_{a \in  B} \lambda_a(D(a))
\rho((\cup_{a' \in E} D'(a'))\cup(
\cup_{a \in B} D(a)),D(b))\\
&=& \sum_{D\in {\mathscr D}(B)}
\prod_{a \in  B} \lambda_a(D(a))
\sum_{D' \in {\mathscr D}(E)}
\prod_{a' \in E} \lambda_{a'}(D'(a'))
\rho((\cup_{a' \in E} D'(a'))\cup(
\cup_{a \in B} D(a)),D(b))\\
&\le& 
\sum_{D\in {\mathscr D}(B)}
\prod_{a \in B} \lambda_a(D(a))\rho(\cup_{a \in B} D(a),D(b))=\hat{\rho}(B,b),
\end{eqnarray*}
where the inequality holds because we have for each $D\in {\mathscr D}(B)$
\[
\sum_{D' \in {\mathscr D}(E)}
\prod_{a' \in E} \lambda_{a'}(D'(a'))
\rho((\cup_{a' \in E} D'(a'))\cup(
\cup_{a \in B} D(a)),D(b))\le \rho(\cup_{a \in B} D(a),D(b))
\]
(This holds because  $\rho$ satisfies the monotonicity)
\end{proof}

