\section{Introduction}

Let $\D$ be the unit disk in the complex plane, and $\vz : \pd\D\to\C$ be a (homeomorphic) embedding.
Then $\Oz$, the interior domain bounded by the Jordan curve $\vz(\pd\D)$, is called a Jordan domain, and
$\vz$ is called a parametrization of the Jordan curve $\pd\Oz$.
By the Jordan--Schoenflies theorem, $\vz$ admits a homeomorphic extension from $\overline{\D}$ to $\overline{\Oz}$.
Notably, this theorem requires no assumptions on the regularity of $\vz$ or the boundary $\pd\Oz$.

In variational methods within Geometric Function Theory \cite{AIM2009,HK2014,IM2001,R1989} and Nonlinear Elasticity \cite{A1995,B1976,C1988},
Sobolev regularity of homeomorphisms plays a crucial role.
In Nonlinear Elasticity, the question of Sobolev homeomorphic extension arises in the context of boundary value problems for elastic deformations.
The deformations are minimizers, obtained by taking the infimum of a given elastic energy functional over the space of Sobolev homeomorphisms.
Consequently, a fundamental question is whether the class of admissible homeomorphisms is nonempty—that is, whether a homeomorphic $W^{1,p}$-extension exists.

It is important to note that such extensions may not always exist.
Verchota \cite{V2007} constructed a boundary homeomorphism $\vz:\pd\D\to\pd\D$ that cannot be extended to a Sobolev homeomorphism in $W^{1,2}$. 
Furthermore, Zhang \cite{Z2019} demonstrated the existence of a Jordan domain for which the boundary parametrization,
obtained by Carath\'eodory's theorem from the exterior Riemann map, does not admit a homeomorphic $W^{1,1}$ extension.

Thus, this calls for a geometric condition of the Jordan domain to
guarantee the existence of a homeomorphic $W^{1,p}$-extension for $p\in [1,2)$. Under proper geometric conditions, the problem is well-investigated:
If $\Oz$ is convex, Verchota \cite{V2007} showed that the harmonic extension of any boundary parametrization lies in the Sobolev space $W^{1,p}$, for any $p\in [1,2)$.
A.~Koski and J.~Onninen \cite{KO2021} considered the case when $\pd\Oz$ is rectifiable.
Moreover, P.~Koskela et al \cite{KKO2020} obtained an extension theorem when $\Oz$ is a John domain.

To establish a general geometric condition for the extension problem,
A.~Koski and J.~Onninen \cite{KO2023} derived a criterion based on a series of internal distances within the Jordan domain.
The Gehring--Hayman theorem \cite{GH1962} shows that the internal distance  of a pair of points in the Jordan domain is comparable to the length of the respective hyperbolic geodesic.
Inspired by the above results, O.~Bouchala et al. \cite{BJKXZ2024} obtained a relationship between Sobolev homeomorphic extendability and $L^q$-integrability of the hyperbolic metric $h_{\Oz}$.
\begin{theo}{\cite[Theorem 1.2]{BJKXZ2024}}\label{old_t1}
    Let $\Oz$ be a Jordan domain, $z_0\in\Oz$ and $q\in (1,\fz)$. Let us assume that
    \begin{equation}\label{previous-result}
        \int_{\Oz}\left(h_{\Oz}(z,z_0)\right)^q\,\od z < \fz.
    \end{equation}
    Then each homeomorphic parametrization $\vz:\pd\D\to\pd\Oz$ of our Jordan curve
    has a homeomorphic extension in the class $W^{1,p}(\D,\C)$ for all $p\in [1,2)$.
\end{theo}
Moreover, O.~Bouchala et al. showed the sharpness of the theorem.
\begin{theo}{\cite[Theorem 1.3]{BJKXZ2024}}\label{old_t2}
    There is homeomorphic parametrization $\vz:\pd\D\to\pd\Oz$ of a Jordan curve, so that 
    $\vz$ does not have a homeomorphic $W^{1,1}$-extension, even though 
    \eqref{previous-result} holds for $q = 1$ and some $z_0\in\Oz$.
\end{theo}

It is now natural to inquire whether similar results
can be obtained for refined scales,
such as critical exponents $\az$ for the sufficiency of the
integrability of $h_{\Oz}\cdot\left(\log(e + h_{\Oz})\right)^{\az}$.
For this purpose, we investigate a more general integrability condition for the hyperbolic metric.
\begin{assumption}\label{assume:phi}
    Let $\phi:[0,\fz)\to[0,\fz)$ be a continuous function so that:
    \begin{itemize}
        \item[(1)] $\phi$ is strictly-increasing, and $\lim_{t\to\fz} \phi(t) = \fz$;
        \item[(2)] There is a constant $M > 0$ such that, for all $s,t\in [0,\fz)$,
        \begin{equation}\label{con0}
            \phi(s + t) \leq M\left(\phi(s) + \phi(t)\right);
        \end{equation}
    \end{itemize}
\end{assumption}
Under the above conditions, we prove the main theorem of this paper.
\begin{theo}\label{main-1}
    Let $\Oz$ be a Jordan domain, $z_0\in\Oz$ and suppose
    \begin{equation}\label{con1}
        \int_{\Oz}\phi(h_{\Oz}(z_0,z))\,\od z < \fz,
    \end{equation}
    where $\phi$ satisfies Assumption \ref{assume:phi}.
    If
    \begin{equation}\label{con2}
        \int^{\fz}_1 \frac{1}{\phi(s)}\,\od s < \fz,
    \end{equation}
    then each homeomorphic parametrization $\vz:\pd\D\to\pd\Oz$ of our Jordan curve
    has a homeomorphic extension in the class $W^{1,p}(\D,\C)$ for all $p\in [1,2)$.
\end{theo}
The condition \eqref{con2} in our theorem is sharp. This is shown in the next theorem.
\begin{theo}\label{main-2}
    Let the function $\phi$ satisfy Assumption \ref{assume:phi} and, suppose that
    \begin{equation}\label{con2-counter}
        \int^{\fz}_1 \frac{1}{\phi(s)}\,\od s = \fz.
    \end{equation}
    Suppose that there is a simply connected domain $G$ with $g_0\in G$ so that
    \begin{equation}\label{con2-assume}
        \int_G \phi(h_G(g_0,z))\,\od z < \fz.
    \end{equation}
    Then there exists a Jordan domain $\Oz$ with $z_0\in\Oz$ such that \eqref{con1} holds, while at the same time,
    there exists a homeomorphic parametrization $\vz:\pd\D\to\pd\Oz$ of the Jordan curve
    that does not have a homeomorphic $W^{1,1}$-extension.
\end{theo}
To illustrate the results above, let us consider the functions $\phi_{\az} : [0,\fz)\to [0,\fz)$,
$$\phi_{\az}(t) := t \left(\log(e + t)\right)^{\az},$$
where $\az\in (0,\fz)$. Clearly, \eqref{con2-counter} holds precisely when $\az \in (0,1]$, and \eqref{con2} holds when $\az\in (1,\fz)$.
Furthermore, one may choose $G = \D$ in Theorem \ref{main-2}, see Lemma \ref{lemm:integrability} below.

Theorem \ref{main-2} relies on the following result
according to which even a $W^{1,1}$-extension may fail when the internal diameter $\diam_I$ of the Jordan domain is infinite.
\begin{theo}\label{main-3}
    Let $\Oz$ be a Jordan domain satisfying $\diam_I(\Oz) = \fz$.
    Then, there is a homeomorphic parametrization  $\vz: \pd\D \to \pd\Oz$ of the boundary Jordan curve
    so that $\varphi$ does not have a homeomorphic $W^{1,1}$-extension.
\end{theo}




\section{Sobolev homeomorphic extension, Theorem \ref{main-1}}

In this section, we first recall some fundamental definitions.
We then review the method introduced by A.~Koski and J.~Onninen.
As the main result of this section, we prove Theorem \ref{main-1}.

\medskip

Let $\Oz\subset\C$ be a Jordan domain. For $x,y\in\overline{\Oz}$, the internal distance $d_I(x,y)$ is defined as
$$d_I(x,y) = \inf_{\gz\in\Gz_{x,y}} \ell(\gz),$$
where $\Gz_{x,y}$ denotes the set of all rectifiable curves in $\Oz$ connecting $x$ and $y$, and $\ell(\gz)$ represents the length of the curve $\gz$.
The internal diameter of the domain $\Oz$, denoted by $\diam_I(\Oz)$, is given by
$$\diam_I(\Oz) = \sup_{x,y\in\pd\Oz} d_I(x,y).$$

\medskip

The arc length element for the hyperbolic metric of $\Oz$ is given at $z\in\Oz$ by
$$\od_{S_{hyp}} = \frac{2|g'(z)||\od z|}{1 - |g(z)|^2},$$
where $g$ is the local inverse of the universal covering map $f:\D\to\Oz$.
In our simply connected case, the map $f$ is the conformal homeomorphism obtained by the Riemann mapping theorem.
For $z_1,z_2\in\Oz$, the hyperbolic metric $h_{\Oz}(z_1,z_2)$ is defined by 
$$h_{\Oz}(z_1,z_2) = \inf_{\gz\in \Gz_{z_1,z_2}} \int_{\gz} \,\od_{S_{hyp}}.$$
The infimum is actually achieved by a hyperbolic geodesic. 

The hyperbolic metric is invariant under conformal mappings.
Moreover, let us consider the quasi-hyperbolic metric $k_{\Oz}(z_1,z_2)$ defined by
$$k_{\Oz}(z_1,z_2) = \inf_{\gz\in \Gz_{z_1,z_2}} \int_{\gz} \frac{1}{\dist(z,\pd\Oz)}\,|\od z|.$$
It holds that $k_{\Oz}(z_1,z_2)$ is comparable to $h_{\Oz}(z_1,z_2)$ for all $z_1,z_2\in\Oz$.
For more information on the hyperbolic metric, see \cite{AIM2009}.

\medskip

Next we turn to the method proposed by A.~Koski and J.~Onninen.
We begin by recalling the definition of a dyadic family of closed arcs in $\pd \D$.
Let $\bN := \{0, 1, 2, \dots\}$ and define $\bN^+ := \bN\setminus\{0\}$. 
\begin{defi}
	Let $n_0\in\bN^+$. A family
	$$I := \{I_{n,j}\subset\pd \D : n\geq n_0,\ j = 1,2,3,\ldots,2^n\}$$
    of closed arcs is called dyadic, if for every $n\geq n_0$,  arcs $I_{n,j}$, $j = 1,2,3,\ldots,2^n$, are
	\begin{enumerate}[(i)]
		\item of equal length,
		\item pairwise disjoint apart from their endpoints,
		\item cover $\pd \D$,
	\end{enumerate}
	and, for each arc $I_{n,j}$ there are two arcs in $I$ of half the length of $I_{n,j}$ 
	and so that their union is precisely $I_{n,j}$; 
	these arcs are called the children of $I_{n,j}$ and $I_{n,j}$ is their parent.
\end{defi}

\begin{theo}{\cite[Theorem 3.1]{KO2023}}\label{t0}
	Suppose that $\Omega$ is a Jordan domain and $\varphi\colon\pd \D \to \partial\Omega$ is a boundary homeomorphism.
	Suppose that for some $n_0\in\bN^+$ there is a dyadic family $I = \{I_{n,j}\}$ of closed arcs in $\pd \D$ such that the following hold:
	\begin{enumerate}[1.]
		\item For each $I_{n,j}$ with $n \geq n_0$ there exists a crosscut $\Gamma_{n,j}$ (i.e., a curve in $\Omega$)   connecting 
				   the endpoints of the boundary arc $\varphi(I_{n,j})\subset\partial\Omega$ and such that the estimate
				   \begin{equation}\label{e0}
					\sum^{\infty}_{n = n_0}2^{(p-2)n}\sum^{2^n}_{j = 1}\left(\ell(\Gamma_{n,j})\right)^p<\infty
				   \end{equation}
				   holds. Here $\ell$ stands for the Euclidean length. 
		\item The crosscuts $\Gamma_{n,j}$ for $n\geq n_0$ are all pairwise disjoint apart from their endpoints at the boundary, where $n$ and $j$ are allowed to range over all their possible values.
	\end{enumerate}
	Then $\varphi$ admits a homeomorphic extension from $\overline{\D}$ to $\overline{\Omega}$ in the class $W^{1,p}(\D, \C)$.
\end{theo}

To establish the main theorem,
we prove the following key lemma,
which generalizes \cite[Lemma 2.4]{BJKXZ2024}.

\begin{lemm}\label{lemma:crosscut}
	Suppose that $\Omega$ is a Jordan domain and $f\colon\overline{\D}\to\overline{\Omega}$ is a homeomorphism that is conformal on $\D$.
    Let us assume, further, that $\phi$ satisfies Assumption \ref{assume:phi} and \eqref{con1}.
 Let $\xi_1,\xi_2\in\pd \D$ be such that 
 $$|\xi_1 - \xi_2| \leq \frac{4 \pi}{1 + \pi^2} \approx 1.156,$$
 let $\gamma$ be the hyperbolic geodesic connecting $\xi_1$ and $\xi_2$,
 and $\wt{\gz}$ the shorter-length part of the boundary connecting $\xi_1$ and $\xi_2$.
 Then we have, for $\Gamma := f(\gamma)$ joining $f(\xi_1)$ and $f(\xi_2)$, that
 $$
 		\big(\ell(\Gamma)\big)^2\leq c\left(\int^{\fz}_{\frac{\log 2}{2}} \frac{1}{\phi(s)}\,\od s\right) \int_{\Delta} \phi\left(h_{\Omega}(z, f(0))\right)\od z,
 $$
 	where $\Delta$ is the region bounded by $\Gamma$ and $f(\wt{\gz})$, and $c$ is an absolute positive constant.
\end{lemm}
\begin{proof}
    We follow the same method as in the proof of \cite[Lemma 2.4]{BJKXZ2024}:

    Without loss of generality,
    we assume that the chosen points on the unit circle satisfy
    $\xi_1 = \overline{\xi_2}$, $\Re \xi_1 > 0$ and $\Im \xi_1 > 0$.
	Consider the M\"obius transformation $T$ mapping the unit disk onto the upper half-plane $\bH^+$,
	$$T(z) = a\,\frac{1-z}{1+z},$$
	where $a = \frac{1+\xi_1}{1-\xi_1}=\frac{i\Im\xi_1}{1-\Re\xi_1}$. 
    Then $T$ satisfies the following properties:
    \begin{itemize}
        \item[(1)] $T(\xi_1) = 1 = -T(\xi_2)$, $T(1) = 0$ and $T(-1) = \infty$;
        \item[(2)] $T(\D) = \bH^+$, and $T$ maps the hyperbolic geodesic $\gamma$ connecting $\xi_1$ and $\xi_2$ to the upper half of the unit circle, i.e., $\pd \D\cap \bH^+$. 
    \end{itemize}

    For all $m\in\bN^+$, define $\theta_m := \frac{\pi}{2^m}$, 
    and set 
    $$C_m := \{e^{i\theta}: \theta\in (\theta_{m+1},\theta_m)\}.$$
    For approximating purposes, define $R_m := 1 - \frac{1}{2^{m + 1}}$, $z_m := e^{i\theta_m}$,
    and let
	$$A_m := \left\{re^{i\theta}: r\in (R_m,1]\text{ and }\theta \in (\theta_{m+1},\theta_m)\right\}.$$
    To handle angles between $\frac{\pi}{2}$ and $\pi$, define
    $$A_{-m} := \left\{z\in\D: -\overline{z}\in A_m\right\}, \quad z_{-m} := -\overline{z_m},\quad C_{-m} = \{ z : -\overline{z} \in C_m \}.$$

