    \medskip

    We set $g := f\circ T^{-1}$.
    By \cite[(2.4), (2.6), and the inequality right after (2.6)]{BJKXZ2024},
    the following results hold: For all $m\in\Z\setminus\{0\}$ and $\oz\in A_m$,
        \begin{equation}\label{lemma:eq01}
            h_{\bH^+}(\omega, T(0)) \geq |m|\log 2,
        \end{equation}
        \begin{equation}\label{lemma:eq02}
            \ell(g(C_m)) \leq \frac{c_1}{2^{|m|}}|g'(z_m)|,
        \end{equation}
        \begin{equation}\label{lemma:eq03}
            \left|g(A_m)\right| \geq \frac{c_2}{2^{2|m|}}|g'(z_m)|^2,
        \end{equation}
    where $c_1$ and $c_2$ are positive constants independent of $m$.
    Then, by \eqref{lemma:eq01}, \eqref{lemma:eq03},
    along with the invariance of the hyperbolic metric under conformal mappings and Assumption \ref{assume:phi}, 
    we conclude that
    \begin{align*}
        \int_{g(A_m)} \phi\left(h_{\Oz}(\oz,f(0))\right)\,\od \oz
        & = \int_{g(A_m)} \phi\left(h_{\bH^+}(g^{-1}(\oz),T(0))\right)\,\od z\\
        & \geq \left|g(A_m)\right| \phi\left(|m|\log 2\right)\\
        & \geq \frac{c_2\phi\left(|m|\log 2\right)}{2^{2|m|}}|g'(z_m)|^2.
    \end{align*}
    Combining this with \eqref{lemma:eq02} and \eqref{con1}, it follows that
    \begin{align*}
        \left(\ell(g(C_m))\right)^2 \leq \frac{(c_1)^2}{c_2}\frac{1}{\phi\left(|m|\log 2\right)}\int_{g(A_m)} \phi\left(h_{\Oz}(\oz,f(0))\right)\,\od \oz.
    \end{align*}
    Thus, by the Cauchy--Schwartz inequality,
    \begin{align*}
        \ell(\Gz) 
        & = \sum_{m\in\Z\setminus\{0\}} \ell(g(C_m))\\
        & \lesssim \sum_{m\in\Z\setminus\{0\}} \left(\frac{1}{\phi\left(|m|\log 2\right)}\int_{g(A_m)} \phi\left(h_{\Oz}(\oz,f(0))\right)\,\od\oz\right)^{1/2}\\
        & \lesssim \left(\sum_{m\in\Z\setminus\{0\}} \frac{1}{\phi\left(|m|\log 2\right)}\right)^{1/2} \left(\sum_{m\in\Z\setminus\{0\}} \int_{g(A_m)} \phi\left(h_{\Oz}(\oz,f(0))\right)\,\od\oz\right)^{1/2}\\
        & \lesssim \left(\sum_{m\in\Z\setminus\{0\}} \frac{1}{\phi\left(|m|\log 2\right)}\right)^{1/2} \left(\int_{\Delta} \phi\left(h_{\Oz}(\oz,f(0))\right)\,\od\oz\right)^{1/2}.
    \end{align*}
    The last inequality follows from the fact that $\{g(A_m)\}_{m\in\Z\setminus\{0\}}$ is pairwise disjoint
    and that $g(A_m)\subset \Delta$.
    Furthermore, by Assumption \ref{assume:phi}, we obtain
    \begin{align*}
        \sum_{m\in\Z\setminus\{0\}} \frac{1}{\phi\left(|m|\log 2\right)}
        & = 2 \sum_{m\in\bN^+}\frac{1}{\phi\left(|m|\log 2\right)}\\
        & \lesssim \frac{1}{\phi(\log 2)} + \sum^{\fz}_{m = 2} \int^{m}_{m - 1} \frac{1}{\phi\left(x\log 2\right)}\,\od x\\
        & \lesssim \int^1_{1/2} \frac{1}{\phi(x\log 2)}\,\od x + \int^{\fz}_1 \frac{1}{\phi(x\log 2)}\,\od x\\
        & \lesssim \int^{\fz}_{\frac{\log 2}{2}}\frac{1}{\phi(x)}\,\od x < \fz.
    \end{align*}
    This completes the proof of Lemma \ref{lemma:crosscut}.
\end{proof}

\smallskip

\begin{rema}
    The estimation in Lemma \ref{lemma:crosscut} is not optimal,
    providing only a uniform upper bound for $\ell(\Gamma)$.
    The result does not offer any insight into the sharpness of the estimate itself or the exponent $\frac{\log 2}{2}$.
    % In fact, the exponent $\frac{\log 2}{2}$ can be replaced by any constant within the interval $(\frac{\log 2}{2},\log 2)$,
    % though this would result in a different constant $c$.
\end{rema}

