Lemma \ref{lemma:crosscut} leads to a stronger result.
\begin{defi}
	Let $k\in\bN$. A sequence of points $\{x_0,x_1,\ldots,x_k\}\subset\pd \D$ is called a cycle if there exist
	$0 < \theta_1 <\ldots<\theta_k<2\pi$ such that $x_j = e^{i\theta_j}x_0$ for $j=1,...,k$.
    Specifically, set $x_{k + 1} = x_0$.
\end{defi}
% Recall that, the internal distance $d_I$ for $\Oz$ is defined by, for any $x,y\in\Oz$,
% $$
% d_I(x,y) = \inf\{\ell(l): \text{rectifiable } l\subset \Oz,\text{ and $x,y$ are the endpoints of $l$}\}.
% $$
% Also,the internal diameter of $\Oz$, denoted by $\diam_I$, is defined by 
% $$
% \diam_I(\Oz) = \sup_{x,y\in\pd\Oz} d_I(x,y).
% $$
\begin{lemm}\label{lemma:internal diameter}
    Let $\Oz$, $f$ and $\phi$ be defined as in Lemma \ref{lemma:crosscut}.
    Given all $k\in\bN^+$ and a cycle $\{x_0,x_1,\ldots,x_k\}\subset\pd \D$ satisfying
    \begin{equation}\label{equ:sizecondition}
        \max\{|x_i - x_{i + 1}|: i = 0,1,\ldots,k\} \leq \frac{4 \pi}{1 + \pi^2},
    \end{equation}
    let $\gamma_i$ be the hyperbolic geodesic connecting $x_i$ and $x_{i + 1}$.
    Then we have, for $\Gamma_i := f(\gamma_i)$ joining $f(x_i)$ and $f(x_{i + 1})$, that
    $$
 		\sum^k_{i = 0}\big(\ell(\Gamma_i)\big)^2\leq c\left(\int^{\fz}_{\frac{\log 2}{2}} \frac{1}{\phi(s)}\,\od s\right) \int_{\Oz} \phi\left(h_{\Omega}(z, f(0))\right)\od z < \fz,
    $$
    where $c$ is a positive constant.
    Furthermore,
    $$\diam_I(\Oz) < \fz.$$
\end{lemm}
\begin{proof}
    Noticing that $\{\Gamma_i\}^k_{i = 0}$ is pairwise disjoint,
    the estimate for $\sum^k_{i = 0}\big(\ell(\Gamma_i)\big)^2$ follows directly from Lemma \ref{lemma:crosscut}.

    It is clear that, there exists a fixed constant $K\in\bN$ such that,
    for all $x,y\in\pd\Oz$, we can find a cycle $\{x_i\}^K_{i = 0}$ satisfying \eqref{equ:sizecondition}, and
    $f(x_l) = x$, $f(x_m) = y$ for some $l,m\in\{0,1,\ldots,K\}$ with $l\leq m$.
    Then, by the Gehring--Hayman inequality and the Cauchy--Schwartz inequality, we obtain
    \begin{align*}
        (d_I(x,y))^2 
        & \leq \left(\sum^m_{i = l} \ell(\Gamma_i)\right)^2\\
        & \leq K\sum^K_{i = 0} \left(\ell(\Gamma_i)\right)^2\\
        & \leq cK\left(\int^{\fz}_{\frac{\log 2}{2}} \frac{1}{\phi(s)}\,\od s\right) \int_{\Oz} \phi\left(h_{\Omega}(z, f(0))\right)\od z < \fz.
    \end{align*}
    This completes the proof of Lemma \ref{lemma:internal diameter}
\end{proof}

