\begin{proof}[Proof of Theorem \ref{main-1}]
For $n\in\bN^+$, and let $\Tz_n := \{\tz_{n,j}\}_{j = 0,\ldots,2^n - 1}$ be a cycle on the unit circle satisfying the conditions
\begin{itemize}
    \item[(1)] $\tz_{n,0} = 1$;
    \item[(2)] $\tz_{n,j} = e^{i\frac{2\pi j}{2^n}}\tz_{n,0}$ for all $j = 0,\ldots,2^n - 1$.
    %\item[(1)] $\{\tz_{n,j}\}^{2^n - 1}_{j = 0}$ is all the $n$-level dyadic points on $\pd\D$;
    %\item[(2)] $\{\tz_{n,j}\}^{2^n - 1}_{j = 0}$ is a cycle.
\end{itemize}

Let $f:\D\to\Oz$ be the conformal homeomorphism obtained by the Riemann mapping theorem.
By Carath\'eodory's theorem, $f$ extends continuously to a boundary parametrization $f:\pd\D\to\pd\Oz$.
Notice that $\{\Tz_n\}_{n\in\bN^+}$ forms a dense subset of $\pd\D$, and $\Tz_n \subset\Tz_m$ if $n\leq m$.
Thus, there is $n_0\in\bN^+$ such that, for all $n\geq n_0$, 
$$\left|f^{-1}(\vz(\tz_{n,j + 1})) - f^{-1}(\vz(\tz_{n,j}))\right|\leq \frac{4\pi}{1 + \pi^2},$$
for all $j = 0,\ldots,2^n - 1$.

Consider the crosscut $\Gz_{n,j} = f(\gz_{n,j})$ connecting $\vz(\tz_{n,j})$ and $\vz(\tz_{n,j + 1})$,
where $\gz_{n,j}$ is the hyperbolic geodesic connecting $\xi_{n,j} := f^{-1}(\vz(\tz_{n,j}))$ and $\xi_{n, j + 1} := f^{-1}(\vz(\tz_{n,j + 1}))$.
By Lemma \ref{lemma:crosscut}, for all $p\in [1,2)$ and $n\geq n_0$, we obtain
\begin{align*}
    2^{n(p - 2)}\sum^{2^n}_{j = 1} \left(\ell(\Gz_{n,j})\right)^p
    &\lesssim 2^{n(p - 2)}\sum^{2^n}_{j = 1}\left(\int_{\Delta_{n,j}}\phi(h_{\Oz}(z_0,z))\,\od z\right)^{p/2}\\
    &\lesssim 2^{n(p - 2)}2^{n(1 - p/2)} \left(\sum^{2^n}_{j = 1}\int_{\Delta_{n,j}}\phi(h_{\Oz}(z_0,z))\,\od z\right)^{p/2}\\
    &\lesssim 2^{n(p/2 - 1)} \left(\int_{\Oz}\phi(h_{\Oz}(z_0,z))\,\od z\right)^{p/2},
\end{align*}
where $\Delta_{n,j}$ is the region defined in Lemma \ref{lemma:crosscut}
with respect to the points $\xi_{n,j}$ and $\xi_{n,j + 1}$. 
Then, by \eqref{con1}, for all $p \in [1,2)$ we have
$$\sum^{\fz}_{n = n_0} 2^{n(p - 2)}\sum^{2^n}_{j = 1} \left(\ell(\Gz_{n,j})\right)^p \lesssim \left(\sum^{\fz}_{n = n_0}2^{n(p/2 - 1)}\right)\left(\int_{\Oz}\phi(h_{\Oz}(z_0,z))\,\od z\right)^{p/2} < \fz$$
By Theorem \ref{t0}, the boundary parametrization $\vz$
admits a homeomorphic extension from $\overline{\D}$ to $\overline{\Oz}$ in the class $W^{1,p}(\D,\C)$.
This completes the proof of Thenrem \ref{main-1}.
\end{proof}
