    Let $\oz_0$ be defined as in \eqref{equ:limit:point}.
    Without loss of generality, we assume that $\oz_0 = e^{i\pi}$.
    We construct the sequence of intervals $\{I(\tz_n,\dz_n)\}_{n\in\bN^+}$ satisfying the following properties
    \begin{itemize}
        \item[(1)] The intervals $\{I(\tz_n,\dz_n)\}_{n\in\bN^+}$ are pairwise disjoint, and $\oz_0\notin I(\tz_n,\dz_n)$;
        \item[(2)] For all $n\in\bN^+$, $\tz_n = e^{it_n}$ where $0 < t_1 < t_2 < \ldots < \pi$, and
        $$\lim_{n\to\fz} t_n = \pi;$$
        \item[(3)] For all $n\in\bN^+$, it holds that
        \begin{equation}\label{equ:interval:lowerbound}
            \inf_{\oz\in I(\tz_n,\dz_n)} d_I(f(0),f(\oz)) \geq 4^n.
        \end{equation}
    \end{itemize}
    The construction of these intervals proceeds in two steps:

    \smallskip

    \textbf{Step 1.}
    By \eqref{equ:limit:point}, we choose $t_1\in (0,\pi)$ such that 
    $$\tz_1 = e^{it_1}\in \pd\D \setminus \{\oz_0\}\quad\text{and}\quad d_I(f(0),f(\tz_1)) \geq 8.$$
    Let $\gz_1$ be the internal geodesic connecting $f(0)$ and $f(\tz_1)$.
    There exists $r_1\in (0,10^{-6})$ and $\eta'_1\in \gz_1\cap \pd B(f(\tz_1),r_1)$ such that
    $$d_I(f(0),\eta'_1) \geq 8 - 10^{-5}.$$
    By the continuity of $f$, there is $\dz_1 \in (0,\fz)$ such that
    $$0 < t_1 - \dz_1 < t_1 + \dz_1 < \pi,$$
    and
    $$f(I(\oz_1,\dz_1)) \subset \pd\Oz \cap B\left(f(\oz_1),r_1\right),$$
    and it is easy to see $\oz_0\notin I(\oz_1,\dz_1)$.
    By triangle inequality, for all $\oz\in I(\oz_1,\dz_1)$, we further conclude that
    $$d_I(f(0),f(\oz)) \geq d_I(f(0),\eta'_1) - 2\pi r_1 \geq 4.$$

    \smallskip

    \textbf{Step 2.}
    Suppose we have already constructed the intervals
    $\{I(\tz_n,\dz_n)\}^k_{n = 1}\subset \pd\D$ satisfying:
    \begin{itemize}
        \item[1.] They are pairwise disjoint and $\oz_0\notin \bigcup^k_{n = 1}I(\tz_n,\dz_n)$;
        \item[2.] There is a sequence $0 < t_1 < \ldots < t_k < t_k + \dz_k < \pi$ such that $\tz_n = e^{it_n}$,
        $$\pi - \frac{\pi}{2^{n - 1}} < t_n - \dz_n < t_n + \dz_n < \pi,$$
        for all $n\in\{1,2,\ldots,k\}$; 
        \item[3.] For all $n\in \{1,2,\ldots,k\}$, \eqref{equ:interval:lowerbound} holds.
    \end{itemize}
    Choose $t_{k + 1}\in (t_k + \dz_k, \pi)\cap (\pi - \frac{\pi}{2^{k}},\pi)$, and $\tz_{k + 1} = e^{it_{k + 1}}$ such that
    $$\tz_{k + 1}\in \pd\D \setminus \left(\{\oz_0\}\cup\bigcup^k_{n = 1} I(\tz_n,\dz_n)\right),$$
    and
    \begin{equation}\label{equ:point:lowerbound}
        d_I(f(0),f(\tz_{k + 1})) \geq 2\times4^{k + 1}.
    \end{equation}
    Since $\oz_0$ is the interior point of $\pd\D\setminus\bigcup^k_{i = 1} I(\tz_i,\dz_i)$,
    the existence of $\tz_{k + 1}$ follows from \eqref{equ:limit:point}.
    % $$\sup_{\oz\in\pd\D\setminus(\{\oz_0\}\bigcup^k_{n = 1} I(\tz_n,\dz_n))} d_I(f(0),f(\oz)) = \fz.$$
    %Let $\gz_{k + 1}$ the internal geodesic connecting $f(0)$ and $f(\tz_{k + 1})$.
    % Since 
    % $$d_I(f(0),f(\tz_{k + 1})) \geq 2(k + 1),$$
    By \eqref{equ:point:lowerbound} and using the similar method as in \textbf{Step I},
    for a sufficiently small $r_{k + 1}\in (0,10^{-6})$,
    there exists $\dz_{k + 1} \in (0,\fz)$ such that
    $$\max\left\{\pi - \frac{\pi}{2^k}, t_k + \dz_k\right\} < t_{k + 1} - \dz_{k + 1} < t_{k + 1} + \dz_{k + 1} < \pi,$$ 
    and
    $$f(I(\tz_{k + 1},\dz_{k + 1})) \subset \pd\Oz \cap B(f(\tz_{k + 1}),r_{k + 1}) \setminus f\left(\bigcup^k_{n = 1}I(\tz_n,\dz_n)\right).$$
    Moreover, for all $\oz\in I(\tz_{k + 1},\dz_{k + 1})$, we have
    $$d_I(f(0),f(\oz)) \geq 4^{k + 1}.$$
    It is easy to check that $I(\tz_{k + 1},\dz_{k + 1})$ satisfies all the properties.
    By induction, we obtain the desired sequence of intervals $\{I(\tz_n,\dz_n)\}_{n\in\bN^+}$.

    \smallskip

    % By the compactness of $\pd\D$,
    % there exists a limit point of $\{\tz_n\}_{n\in\bN^+}$, denoted by $\tz_0$.
    % Without loss of generality, we assume that, for any $n\in\bN$,
    % $$\tz_n = e^{it_n}\quad \text{where}\quad 0 < t_1 < t_2 < \ldots < t_n < \ldots < t_0 < 2\pi,$$
    % with 
    % $$\lim_{n\to\fz}e^{it_n} = e^{it_0}.$$ 
    % Since the intervals $\{I(\tz_n,\dz_n)\}_{n\in\bN^+}$ are pairwise disjoint, it follows that
    % $$e^{it_0}\notin I(\tz_n,\dz_n),$$
    % for any $n\in\bN^+$.
    Based on these intervals, we construct the boundary parametrization $\vz:\pd\D\to\pd\Oz$ as follows.
    The definition of $\vz$ is given in three cases

    \textbf{Case I.} 
    Set 
    $$\vz(e^{i\pi}) = f(e^{i\pi}).$$

    \textbf{Case II.} 
    For any $n\in\bN^+$, set 
    $$A_n := \left\{e^{i(\az + \bz)}: \az = \pi - \frac{\pi}{2^n}, \bz \in \left[0,\frac{\pi}{4^n}\right]\right\}.$$
    Consider the homeomorphism $g_n: A_n \to I(\tz_n,\dz_n)$ with constant speed (rescaling),
    with
    $$g_n\left(e^{i(\pi - \frac{\pi}{2^n})}\right) = \tz_{n}e^{-i\dz_{n}}\quad\text{and}\quad g_n\left(e^{i(\pi - \frac{\pi}{2^n} + \frac{\pi}{4^n})}\right) = \tz_{n}e^{i\dz_{n}}.$$
    Then, on each $A_n$, define $\vz := f\circ g_n$.

    \textbf{Case III.} 
    It is easy to see that 
    $$\pd\D\setminus \left(\{e^{i\pi}\}\cup\bigcup_{n\in\bN^+}A_n\right)$$ 
    is a countable union of disjoint open intervals on $\pd\D$.
    Define $\vz$ on each interval by rescaling (Similarly as in Case II).
    This completes the construction of $\vz$.

    It is obvious that $\vz$ is injective.
    Notice that $\vz$ is continuous at $e^{i\pi}$,
    and thus the mapping $\vz$ is a boundary parametrization.

    If $\vz$ admits a homeomorphism extension $\varPhi\in W^{1,1}_{loc}$, then
    for some $\ez\in (0,1)$ such that $\D(\varPhi(0),\ez)\subset \Oz$,
    by the definition of internal distance and \eqref{equ:interval:lowerbound},
    it holds that for all $n\in\bN^+$ and $\wt{\oz}\in\pd \D(\varPhi(0),\ez)$
    $$\inf_{\oz\in A_n} d_I(\wt{\oz},\varPhi(\oz)) \gtrsim 4^n,$$
    where the equivalence constant relies on $\ez$.
    We choose $\eta \in (0,\fz)$ such that 
    $$\D(0,\eta)\subset \varPhi^{-1} \left(\D(\varPhi(0),\ez)\right).$$
    Then
    \begin{align*}
        \int_{\D} |D\varPhi(z)|\,\od z
        & \geq \int^{2\pi}_0 \int_{\gz_{t}} |D\varPhi(z)||z|\,\od z\,\od t\\
        & \geq \eta\sum_{n\in\bN^+} \int_{e^{it} \in A_n}\int_{\gz_{t}} |D\varPhi(z)|\,\od z\,\od t\\
        & \gtrsim \eta\sum_{n\in\bN^+} \frac{\pi}{4^n} 4^n \gtrsim \eta\sum_{n\in\bN^+} 1 = \fz,
    \end{align*}
    where $\gz_t$ is the line segement connecting $\eta e^{it}$ and $e^{it}$.
    We conclude that $\varPhi\notin W^{1,1}(\D,\C)$. This completes the proof of Theorem \ref{main-3}.
\end{proof}
