\begin{lemm}\label{lemm:integrability}
    Given a simply connected domain $\Oz$ and the corresponding Riemann mapping $f: \D \to \Oz$,
    set $z_0 := f(0) \in\Oz$.
    Let $\phi$ be a function satisfying Assumption \ref{assume:phi}.
    If $\phi(h_{\Oz}(z_0,\cdot))\in L^1$, then $\phi(h_{\D}(0,\cdot))\in L^1$.
    Moreover,
    \begin{equation}\label{lemma:phi:equ}
        \int^1_0 \phi\left(\log\left(\frac{1}{1 - r}\right)\right)\,\od r < \fz.
    \end{equation}
\end{lemm}
\begin{proof}
    By a change of variable and the fact that $h_{\D}(0,z)$ depends only on $|z|$, we obtain
    \begin{align*}
        \fz > \int_{\Oz} \phi(h_{\Oz}(z_0,z))\,\od z 
        & = \int_{\D} \phi(h_{\D}(0,z)) |\det Df(z)|\,\od z\\
        & = \int^1_0 \int_{S_r} \phi(h_{\D}(0,z)) |\det Df(z)|\,\od \sz_r(z)\od r\\
        & = \int^1_0 \phi(h_{\D}(0,r)) \int_{S_r} |\det Df(z)|\,\od \sz_r(z)\od r.
    \end{align*}
    The first equality holds due to the invariance of hyperbolic metric under conformal mappings.

    Notice that, for a fixed $r_0\in (0,1)$, there is $\wt{r}_0\in (0,\fz)$ such that
    $B(\oz_0,\wt{r}_0)\subset f(r_0\D)$.
    We conclude that, for any $r\in [r_0,1)$,
    \begin{align*}
        \int_{S_r} |f'(z)|\,\od \sz_r(z) \geq 2\pi \wt{r}_0.
    \end{align*}
    By the Cauchy--Riemann equations, we have $|f'(z)|^2 = |\det Df(z)|$ and hence
    \begin{align*}
        \int_{S_r} |\det Df(z)|\,\od \sz_r(z) \geq \dz,
    \end{align*}
    by the Cauchy--Schwartz inequality where $\dz \in (0,\fz)$ is a constant. Thus, 
    \begin{align*}
        \int_{\D\setminus r_0 \D} \phi(h_{\D}(0,z)) \od z
        & \leq 2\pi \int^1_{r_0} \phi(h_{\D}(0,r))\,\od r\\
        & \leq \frac{2\pi}{\dz} \int_{\Oz} \phi(h_{\Oz}(z_0,z))\,\od z < \fz.
    \end{align*}
    Since $\phi(h_{\D}(0,\cdot))$ is bounded in $r_0\D$, we conclude that $\phi(h_{\D}(0,\cdot))\in L^1$.
    Moreover,
    by Assumption \ref{assume:phi}, we have
    \begin{align*}
        2\pi \int^1_0 r \phi\left(\log\left(\frac{1}{1 - r}\right)\right)\,\od r \leq \int_{\D} \phi\left(h_{\D}(0,z)\right)\,\od z < \fz.
    \end{align*}
    Since $\phi$ is non-decreasing, it follows that \eqref{lemma:phi:equ} holds.
\end{proof}

