\begin{lemm}\label{lemm:series}
    Let $\{a_n\}^{\fz}_{n = 1}\subset \R^+$.
    If $\sum^{\fz}_{n = 1} a_n = \fz$, then
    \begin{equation}\label{lemm:series:equ}
        \sum^{\fz}_{n = 1} a_n \left(\sum^n_{k = 1}a_k\right)^{\dz - 1}
    \end{equation}
    \begin{itemize}
        \item[(i)] diverges if $\dz\in [0,\fz)$; 
        \item[(ii)] converges if $\dz\in (-\fz,0)$. 
    \end{itemize}
\end{lemm}
\begin{proof}
    Given $n\in\bN^+$, let $S_n := \sum^n_{k = 1}a_k$,
    we have
    \begin{align*}
        \log \left(\sum^{n + 1}_{k = 1} a_n\right) - \log \left(\sum^n_{k = 1} a_n\right)
        & = \log \left(1 + \frac{a_{n + 1}}{S_n}\right)\leq \frac{a_{n + 1}}{S_n}.
    \end{align*}
    Then,
    \begin{align*}
        \sum^n_{k = 1}\frac{a_{k + 1}}{S_k} \geq \log \left(\sum^{n + 1}_{k = 1} a_n\right) - \log a_1 \to\fz\quad\text{as} \quad n\to\fz,
    \end{align*}
    which shows that \eqref{lemm:series:equ} diverges when $\dz = 0$.
    Moreover, notice that $\{a_n\}^{\fz}_{n = 1}$ is positive and $\sum^{\fz}_{n = 1}a_n = \fz$,
    we have, for any $\dz > 0$,
    \begin{align*}
        \sum^{\fz}_{n = 1} a_n \left(\sum^n_{k = 1}a_k\right)^{\dz - 1} \gtrsim  \sum^{\fz}_{n = 1} a_n \left(\sum^n_{k = 1}a_k\right)^{-1} = \fz.
    \end{align*}
    \medskip
    When $\dz\in (-\fz,0)$, using summation by parts and Bernoulli's inequality, we get
    \begin{align*}
        \sum^{n}_{k = 1} a_k \left(\sum^k_{j = 1}a_j\right)^{\dz - 1}
        & = \left(S_n\right)^{\dz - 1}\sum^n_{k = 1} a_n - \sum^{n - 1}_{k = 1}\left(S_{j + 1}\right)^{\dz - 1} - \left(S_j\right)^{\dz - 1}\sum^j_{k = 0}a_k\\
        & = \left(S_n\right)^{\dz} + \sum^{n - 1}_{k = 1}\frac{\left(S_j + a_{j + 1}\right)^{1 - \dz} - \left(S_j\right)^{1 - \dz}}{\left(S_{j + 1}\right)^{1 - \dz}\left(S_j\right)^{1 - \dz}}S_j\\
        & = \left(S_n\right)^{\dz} + \sum^{n - 1}_{k = 1}\frac{\left(1 + \frac{a_{j + 1}}{S_j}\right)^{1 - \dz} - 1}{\left(S_{j + 1}\right)^{1 - \dz}}S_j\\
        & \geq \left(S_n\right)^{\dz} + (1 - \dz)\sum^{n - 1}_{k = 1}\frac{a_{j + 1}}{\left(S_{j + 1}\right)^{1 - \dz}},
    \end{align*}
    then, it holds that
    \begin{align*}
        (a_1)^{\dz} 
        & \geq \left(S_n\right)^{\dz} + (-\dz) \sum^{n}_{k = 2} a_k \left(\sum^k_{j = 1}a_j\right)^{\dz - 1}\\
        & \to \sum^{\fz}_{k = 2} a_k \left(\sum^k_{j = 1}a_j\right)^{\dz - 1}\quad\text{as}\quad n\to\fz.
    \end{align*}
    This finishes the proof.
\end{proof}

