\begin{proof}[Proof of Theorem \ref{main-2}]
By Assumption \ref{assume:phi} and \eqref{con2-counter}, we obtain
$$\sum_{n\in\bN^+}\frac{1}{\phi(n)} \geq \sum^{\fz}_{n = 2}\int^{n + 1}_n \frac{1}{\phi(x)}\,\od x = \fz$$
For any $n\in\bN^+$, set $a_0 = 0$,
$$a_n := \frac{1}{\phi(n)}\left(\sum^n_{k = 1}\frac{1}{\phi(k)}\right)^{-2/3}\quad\text{and}\quad b_n := \sum^{n - 1}_{k = 0} a_k.$$
Then
\begin{itemize}
    \item[(1)] By Assumption \ref{assume:phi}(1), 
    $a_n$ is non-negative, non-increasing and 
    $$\lim_{n\to\fz} a_n = 0;$$
    \item[(2)] By Assumption \ref{assume:phi}(2), there is a constant $c_M > 1$ such that, for all $n\in\bN^+$,
    \begin{equation}\label{equ:decrease}
        \frac{a_n}{a_{n + 1}} \leq c_M;
    \end{equation}
    \item[(3)] By Lemma \ref{lemm:series}, 
    \begin{equation}\label{equ:convergence}
        \sum_{n\in\bN^+} (a_n)^2 \phi(n) < \fz\quad\text{and}\quad \sum_{n\in\bN^+}a_n = \fz. 
    \end{equation}
\end{itemize}
Consider the domain obtained by gluing by a half disk with a sequence of trapezoids:
\begin{align*}
    R := A \cup \bigcup_{n\in\bN^+} R_n,
\end{align*}
where
\begin{align*}
    &A = \{(x,y)\in\R^2: x\leq 0, |x|^2 + |y|^2 \leq (c_Ma_1)^2\},\\
    &R_n:= \left\{(x + b_n,y)\in\R^2 : 0\leq x \leq a_n, 0\leq |y|\leq c_M\left(a_n - \frac{x(a_n - a_{n + 1})}{a_n}\right)\right\}.
\end{align*}



