% Recall that the quasihyperbolic metric, for any $x, y \in \Oz$, is
%     $$k_{\Oz}(x,y) = \inf_{\Gamma} \int_{\Gamma} \frac{1}{d(z,\pd \Oz)} \od z,$$
% where the infimum can be taken over all piecewise smooth curves $\Gamma$ in $S$ that join $x$ and $y$.

Set $r_n(s) := c_M\left(a_n - \frac{s(a_n - a_{n + 1})}{a_n}\right)$ for all $s\in [0,a_n]$.
Recall that $k_{R}$ denotes the quasi-hyperbolic metric of the domain $R$.
By \eqref{equ:decrease}, it holds that
\begin{align*}
    k_R(0,(s + b_n,t))
    & \leq k_R(0,(s + b_n,0)) + k_R((s + b_n,0),(s + b_n,t))\\
    & \lesssim \sum^{n}_{k = 1} \frac{a_k}{c_Ma_{k + 1}} + \int^t_0 \frac{1}{r_n(s) - r}\,\od r
    \lesssim n + \log\left(\frac{r_n(s)}{r_n(s) - t}\right),
\end{align*}
where the equivalent constants do not rely on $n$, $s$ and $t$.
Then, by Lemma \ref{lemm:quasilinear} and Lemma \ref{lemm:integrability}, we obtain
\begin{align*}
    \int_{R_n} \phi(k_R(0,z))\,\od z
    &\lesssim |R_n| \phi(n) + \int^{a_n}_0\int^{r_n(s)}_{-r_n(s)}\phi\left(\log \frac{r_n(s)}{r_n(s) - |t|}\right)\,\od t\,\od s\\
    &\lesssim (a_n)^2 \phi(n) + \left(\int^{a_n}_0 r_n(s)\,\od s\right)\left(\int^1_0 \phi\left(\log \frac{1}{1 - |t|}\right)\,\od t\right)\\
    &\lesssim (a_n)^2 \phi(n) + (a_n)^2 \left(\int^1_0 \phi\left(\log \frac{1}{1 - t}\right)\,\od t\right).
\end{align*}
% Now, we need to find the sequence $\{(a_n,r_n)\}_{n\in\bN}$ such that
% \begin{itemize}
%     \item[(1)] $a_n \to \fz$ as $n\to\fz$;
%     \item[(2)] 
%     \begin{equation*}
%         \sum_{n\in\bN}r_n (a_{n + 1} - a_n)\Phi\left(\sum^{n}_{j = 1} \frac{a_{j + 1} - a_j}{r_j}\right) < \fz;
%     \end{equation*}  
%     \item[(3)] 
%     \begin{equation*}
%         \sum_{n\in\bN}(a_{n + 1} - a_n)r_n < \fz.
%     \end{equation*}
% \end{itemize}
Combining this with \eqref{equ:convergence} and Lemma \ref{lemm:integrability}, we have
\begin{align}\label{equ:quasihyper:intergrability}
    \int_R \phi(k_R(0,z))\,\od z 
    & = \int_{A} \phi(k_R(0,z))\,\od z + \sum_{n\in\bN^+}\int_{R_n} \phi(k_R(0,z))\,\od z\notag\\
    & \lesssim \int_{A} \phi(k_R(0,z))\,\od z \notag\\
    & \quad \qquad+ \left(\sum_{n\in\bN^+} (a_n)^2 \phi(n)\right)\left(1 + \int^1_0 \phi\left(\log \frac{1}{1 - t}\right)\,\od t\right) < \fz. 
\end{align}

\smallskip

On the other hand, because $\sum_{n\in\bN^+} (a_n)^2 < \fz$, 
and $a_n$ is positive and decreasing,
without loss of generality, assume that
$$\sum_{n\in\bN^+} (a_n)^2 = \sum_{n\in\bN^+}\frac{1}{4^n}.$$
For any $n\in\bN^+$, set $i_n$ the maximal integer such that
$$\sum^{\fz}_{k = i_n} (a_k)^2 \geq \sum^{\fz}_{k = n + 1}\frac{1}{4^k}.$$
Then, the sequence $\{i_n\}_{n\in\bN^+}$ is non-decreasing, and, for all $n\in\bN^+$ such that $i_{n + 1} > i_n$,
\begin{equation}\label{equ:category}
    \sum^{i_{n + 1}}_{k = i_{n} + 1} (a_k)^2 \leq \frac{1}{4^{n - 1}}.
\end{equation}
% We construct a non-decreasing sequence $\{i_n\}_{n\in\bN^+}\subset \bN^+$ by induction: Set $i_0 = 0$.
% \begin{itemize}
%     \item[1.] Choose $i_1$ the maximal integer such that
%     $$\sum^{i_1 - 1}_{k = 1} (a_k)^2\leq \frac{1}{16};$$
%     \item[2.] For $m\in\bN^+$, assume that $i_1,\ldots,i_m$ are already chosen, which satisfies
%     \begin{equation}\label{equ:category}
%         \sum^{i_n - 1}_{k = i_{n - 1}} (a_k)^2\leq \frac{1}{16^n},
%     \end{equation}
%     for any $n\in\{1,\ldots,m\}$. Then, set $i_{m + 1}$ be the maximal integer such that
%     $$\sum^{i_{m} - 1}_{k = i_{m - 1}} (a_k)^2\leq \frac{1}{16^{m + 1}}.$$
% \end{itemize}

We assume, for convenience, 
that the sequence $\{i_n\}_{n\in\bN^+}$ is strictly increasing.
Set $l_n = \frac{1}{2^n}$. 
We aim to fold the union $\bigcup^{i_{n + 1}}_{k = i_n + 1} R_n$
into a rectangle $Q_n$ with height $8c_Ml_n$ and width $w_n$.
If the series of $\sum w_n$ converges, then the desired Jordan domain is obtained.

The construction proceeds as follows:
For a fixed $n\in\bN^+$, set $m_1 := i_n + 1$. Let 
$m_2$ be the minimal integer such that $m_1 < m_2 < i_{n + 1} - 1$ and
$$\frac{l_n}{2} \leq a_{m_1} + a_{m_1 + 1} + \cdots a_{m_2 - 1}\leq 2 l_n.$$
Next, let $s_1$ be the smallest non-negative integer satisfying
\begin{equation}\label{equ:overlap}
    3c_M a_{m_2} + a_{m_2} + a_{m_2 + 1} + \cdots + a_{m_2 + s_1 - 1} \geq c_M a_{m_1},
\end{equation}
and let $m_3$ be the minimal integer such that $m_2 + s_1 \leq  m_3 < i_{n + 1} - 1$ with
\begin{equation}\label{equ:enoughlength}
    \frac{l_n}{2} \leq a_{m_2 + s_1} + a_{m_1 + s_1 + 1} + \cdots a_{m_3 - 1}\leq 2 l_n.
\end{equation}

By induction, there exists an integer $K_n\in\bN^+$ and a sequence of integers $\{m_d\}^{K_n}_{d = 1}$ such that
$$i_n + 1 = m_1 \leq m_2 \leq m_2 + s_1 \leq m_3 \leq m_3 + s_2 \leq m_4 \leq \cdots \leq m_{K_n} = i_{n + 1}.$$
Note that $m_{K_n}$ does not necessarily satisfy \eqref{equ:enoughlength}.
