\title{Characterizations of contracting Hurwitz bisets}

\begin{abstract}
A critically finite branched self-cover $f: (S^2, P) \to (S^2, P)$ determines naturally three iterated function systems: one on the pure mapping class group $\cG:=\PMod(S^2, P)$, one on the Teichm\"uller space $\cT:=\Teich(S^2, P)$, and one on a finite-dimensional real vector space $\cV$.  We show that contraction for any one of these systems implies contraction for the others.  

 \end{abstract}

\subjclass{37F10, 57M12, 57K20}

\keywords{Thurston map, mapping class group, joint spectral radius, holomorphic correspondence, biset}


