\subsubsection{PMPM Approach}\label{sec:PMP}
In Section~\ref{sec: MP in HAD}, we showed that applying the MPM in HAD receivers entangles the output signals, rendering MPM invocation unwieldy.
%rendering the invocation of the MPM unwieldy.
One approach to remedy this difficulty is presented in the following theorem.





\begin{theorem}\label{Thr:PMPM} 
Let  $\{\boldsymbol{W}_{{\mathrm{\!\! A}},n}\}_{n=1}^{N}$ be a set of analog combiners, each satisfying  $\boldsymbol{W}_{{\mathrm{\!\! A}},n}^H\boldsymbol{W}_{{\mathrm{\!\! A}},n}=\alpha^2 M_{{\mathrm{RF}}}\boldsymbol{I}_{\!L}$. Let the number of snapshots processed by $\boldsymbol{W}_{{\mathrm{\!\! A}},n}$ be $K$
and let the signal $\boldsymbol{S}_n$ in~\eqref{eq:Q_n} be periodic, i.e., $\boldsymbol{S}_n=\boldsymbol{S}$. 
Let $\{\boldsymbol{W}_{\!\mathrm{D},n}\}_{n=1}^N$ be a set of $N$ baseband digital combiners, 
each  processes the output of the $n$-th analog combiner, $\boldsymbol{Q}_n$ in~\eqref{eq:Q_n}. %, for $n=1,\ldots N$. 
Setting $\boldsymbol{W}_{\!\mathrm{D},n}=\frac{1}{\alpha^2 M_{\mathrm{RF}}}\boldsymbol{W}^H_{\mathrm{\!\! A},n}\in \mathbb{C}^{L \times M}$ yields an aggregate output of the $N$ combiners, $\boldsymbol{Y}_{\!\!\mathrm{PMPM}} \in\mathbb{C}^{M\times K}$, which is given by:
\begin{align}
\boldsymbol{Y}_{\!\!\mathrm{PMPM}} 
=\boldsymbol{A}\boldsymbol{S}+\sum_{n=1}^{N}  \boldsymbol{P}_{\boldsymbol{W}_{\!\!{\mathrm{A}},n}} \boldsymbol{Z}_{n},  
\label{eq:y_PMPM}
\end{align}
where 
$\boldsymbol{P}_{\boldsymbol{W}_{\!\!{\mathrm{A}},n}}=\frac{1}{\alpha^2 M_{\mathrm{RF}}}\boldsymbol{W}_{\!\!{\mathrm{A}},n} \boldsymbol{W}_{\!\!{\mathrm{A}},n}^H$.
The signal $\boldsymbol{Y}_{\!\!\mathrm{PMPM}}$ is equivalent to the $K$-snapshot input signal, $\boldsymbol{X}$, of the FD receiver in~\eqref{eq:X}. The SNR of both $\boldsymbol{Y}_{\!\!\mathrm{PMPM}}$  and  $\boldsymbol{X}$ is 
%operating at %  i.e., 
%$\mathrm{SNR}=
$\tfrac{1}{M}\Tr( \boldsymbol{A}\boldsymbol{\Phi}\boldsymbol{A}^H)$. In particular, 
%\blu{and operating at a $10\log M$~dB lower SNR}, i.e.,
% PMPM/FD>> and negative sign removed with lower
% \begin{equation}\label{eq:snr_PMPM_FD}
% \boldsymbol{Y}_{\mathrm{PMPM}} \Big|_{\substack{\!\!\!\!\tilde{K}=NK \\ \mathrm{SNR_{PMPM}}}} 
% = \boldsymbol{X} \Big|_{\substack{\tilde{K}=K \\ \mathrm{SNR_{\mathrm{FD}}}=M \times \mathrm{SNR_{PMPM}}}}.
% \end{equation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Note: hspace/vspace>> elastic the space may not be as needed (rubber)
% \! will do space of 1/4 character, more specific.
\begin{equation}\label{eq:snr_PMPM_FD}
\boldsymbol{Y}_{\!\!\mathrm{PMPM}} \Big|_{\substack{\hspace{0.01cm}\tilde{K}=NK 
%\\ \mathrm{SNR}= \tfrac{1}{M}\Tr( \boldsymbol{A}\boldsymbol{\Phi}\boldsymbol{A}^H) 
}} 
= \boldsymbol{X} \Big|_{\substack{\hspace{0.01cm} \tilde{K}=K 
%\\ \mathrm{SNR}=\tfrac{1}{M}\Tr( \boldsymbol{A}\boldsymbol{\Phi}\boldsymbol{A}^H)
}}.
\end{equation}
\end{theorem}
