\section{Algorithm}
\label{app:algorithm}
\subsection{SQL Rewind Algorithm} \label{app:sql_rewind_algorithm}
We formalize the end-to-end SQL-Rewind pipeline in Algorithm \ref{alg:sql_rewind}, outlining each stage from raw post extraction to the construction of high-quality training tuples.

\begin{algorithm}[H]
\begin{algorithmic}
\Require $\mathcal{D}_{\text{raw}}$ (Stack Overflow posts), $\mathcal{W}$ (training databases); 
         $target\_size$; $max\_iter$
\Ensure $|\mathcal{G}| \geq target\_size$
\Procedure{SQL\_Rewind}{}
    \State $\mathcal{G} \gets \emptyset$ \Comment{collected training tuples}
    \For{each $post$ in $\mathcal{D}_{\text{raw}}$}
        \If{\Call{overlap\_with\_BIRD\_CRITIC}{$post$}}
            \State \textbf{continue}
        \EndIf
        \State $C \gets$ \Call{extract\_sql}{$post$} \Comment{regex extraction}
        \For{each $sql$ in $C$}
            \For{each $db$ in $\mathcal{W}$}
                \State $sol\_sql \gets$ \Call{adapt\_schema}{$sql, db$}
                \If{\Call{exec\_ok}{$sol\_sql, db$}}
                    \Comment{issue synthesis and verification}
                    \For{$i \gets 1$ \textbf{to} $max\_iter$}
                        \State $(\sigma_{\text{issue}}, r_{\text{issue}}, T) \gets$ \Call{gen\_issue}{$sol\_sql, db$}
                        \If{\Call{validate}{$\sigma_{\text{issue}}, r_{\text{issue}}, T, sol\_sql, db$}}
                            \State \textbf{break}
                        \EndIf
                    \EndFor
                    \If{\textbf{validation failed}} \textbf{continue} \EndIf
                    \Comment{user query generation}
                    \For{$j \gets 1$ \textbf{to} $max\_iter$}
                        \State $\mathcal{P} \gets$ \Call{gen\_user\_query}{$\sigma_{\text{issue}}, r_{\text{issue}}, T, db$}
                        \If{\Call{consistent}{$\mathcal{P}, \sigma_{\text{issue}}, T, sol\_sql$}}
                            \State \textbf{break}
                        \EndIf
                    \EndFor
                    \If{\textbf{consistency failed}} \textbf{continue} \EndIf
                    \State $\mathcal{G} \gets \mathcal{G} \cup \{\langle db.\mathcal{S}, \mathcal{P}, \sigma_{\text{issue}}, T, sol\_sql\rangle\}$
                    \If{$|\mathcal{G}| \geq target\_size$}
                        \State \textbf{break all loops}
                    \EndIf
                \EndIf
            \EndFor
        \EndFor
    \EndFor
    \State \Return $\mathcal{G}$
\EndProcedure
\end{algorithmic}
\caption{Automatic construction of \textsc{Six-Gym} training instances with \textbf{SQL-Rewind}.}
\label{alg:sql_rewind}
\end{algorithm}





\subsection{\method Algorithm}
\begin{algorithm}
\begin{algorithmic}
\Require $\mathcal{P}$, $\mathcal{S}$, $\sigma_{\text{issue}}$; $\sigma^\ast$, $T$; $F = (f_1, \dots, f_k)$
\Ensure Trajectory $\tau' = ((t_1, \sigma_1, o_1), \dots, (t_n, \sigma_n, o_n))$
\State \textbf{Function:} \textsc{BIRD-FIXER}
\Procedure{FunctionalPlan}{}
    \State Annotate symbolic functional plan $F = (f_1, \dots, f_k)$ from teacher LLM
    \For{each $f_i$ in $F$}
        \State $f_i$ represents an abstract debugging operation mapping $\sigma_{\text{issue}}$ to $\sigma^\ast$
    \EndFor
\EndProcedure

\Procedure{BackwardInference}{}
    \State Given the problem $(\mathcal{P}, \mathcal{S}, \sigma_{\text{issue}})$ and the corrected query $\sigma^\ast$
    \State Generate a step-by-step functional plan $F = (f_1, \dots, f_k)$
    \State $F$ is annotated by the teacher LLM to map $\sigma_{\text{issue}}$ to $\sigma^\ast$
\EndProcedure

\Procedure{ForwardValidation}{}
    \State Using $(\mathcal{P}, \mathcal{S}, \sigma_{\text{issue}})$ and candidate plan $F$
    \State Regenerate solution using \textsc{SQL-Act} with teacher LLM
    \If{Regenerated SQL passes all test cases in $T$}
        \State Accept $F$
        \State Retain executable trace $\tau' = ((t_1, \sigma_1, o_1), \dots, (t_n, \sigma_n, o_n))$
    \Else
        \State Discard plan $F$
    \EndIf
\EndProcedure
\end{algorithmic}
\caption{\method: Functional planning, backward inference, and forward validation for SQL issue fixing.}
\label{alg:bird_fixer}
\end{algorithm}



