\title{Discrete Lorenz Attractors in 3D Sinusoidal Maps}
\author[a]{Sishu Shankar Muni}
\affil[a]{School of Digital Sciences, Digital University Kerala, Technopark phase-IV Campus, Mangalapuram, 695317, Thiruvananthapuram, India}
