\subsection{Orientability and tractability for instances at distance 1 from bipartite graphs}

We show that every instance with min-uncut number 1 has an EFX-orientation and moreover, one can be computed efficiently. 


\begin{theorem}
% \begin{restatable}{theorem}{Edge-OCT1-general-condition}
\label{thm:Edge-OCT1-general-condition}
    Consider an \EFXO instance $\mathcal I=(G,w)$, where $V(G)$ can be partitioned into sets $A$ and $B$ such that
    \begin{itemize}
        \item $G[A]$ consists only of 1-edges where each connected component contains at most one cycle, and
        \item $G[B]$ contains only 0-edges.
    \end{itemize}
    Then $\mathcal I$ is a yes-instance and given the sets $A$ and $B$, an EFX-orientation can be found in linear time.
    % $O(m+n)$.
% \end{restatable}
\end{theorem}

% Note that the structure of the edges between $A$ and $B$ can be arbitrary.
\begin{proof}
    We give a constructive proof of the existence of EFX-orientations for such instances, which also implies the claimed algorithm, see \Cref{fig:orient}.
    \begin{description}
        \item[Step 1:]
            We begin orienting each connected component in $G[A]$.
            For each component that contains a cycle, we orient the 1-edges of this cycle around it, making it a directed cycle. The remaining 1-edges of this component are oriented away from the cycle -- such an orientation assigns exactly one edge to every agent. Since there is exactly one cycle in this component, we are done.
            For each component that contains no cycle (is a tree) we choose an arbitrary vertex as the root and orient all 1-edges in $G[A]$ away from the root. This completes the orientation of all edges with both endpoints in $A$.
        \item[Step 2:]
            For each vertex $u$ selected as a root in the previous step, check if there is a vertex $v\in B$ such that $w(uv)=1$ and if so, orient the edge $uv$ towards $u$. 
            % it has at least one 1-edge to a white vertex (which therefore was not considered in the Step 1) we orient one of these 1-edges towards $u$.
        \item[Step 3:]
            Orient every edge in $G[B]$ arbitrarily and every remaining edge (which must have an endpoint each in $A$ and $B$) towards its endpoint in $B$.
    \end{description}
    \begin{figure}[ht]
        \centering
        \includegraphics[scale=1.1]{orient.pdf}
        \caption{
            \EFXO created during the proof of \Cref{thm:Edge-OCT1-general-condition}.
            Initial graph with two parts $A$ and $B$, and result after application of Step 1, 2, and 3;
            the edges that were oriented by the previous step are in color.
        }%
        \label{fig:orient}
    \end{figure}

    We now argue that the result is an EFX-orientation.
    Since every vertex $w\in A$ gets at most one item (i.e., at most one edge oriented towards it), it cannot be strongly envied, by \Cref{obs:strong_envy_conditions} (3). By \Cref{obs:strong_envy_conditions} (1), no vertex in $B$ can strongly envy another vertex in $B$ since all edges between these vertices are 0-valued. It remains to show that vertices in $A$ do not strongly envy vertices in $B$. 

    Suppose for a contradiction that a vertex $u\in A$ strongly envies $v\in B$. Notice that if  $u$ is not selected as a root in Step 1, then, it gets an item it values as 1 in this step and  by \Cref{obs:strong_envy_conditions} (2), $u$ cannot strongly envy $v$. So, $u$ is a root. If $v$ does not satisfy the check made in Step 2 for $u$, it must be the case that $w(uv)=0$ and by \Cref{obs:strong_envy_conditions} (1), $u$ cannot strongly envy $v$. Otherwise, Step 2 ensures that $u$ gets an item it values as 1, and by \Cref{obs:strong_envy_conditions} (1), it cannot strongly envy $v$. 

    It is straightforward to check that given the sets $A$ and $B$ the algorithm runs in linear time. Indeed, it is a linear-time process to compute the unique cycle (if one exists) in each connected component of $G[A]$, after which each edge in the graph is accessed only a constant number of times. 
\end{proof}

Recall that for a graph $G$, a partition of the vertex set into sets $A$ and $B$ is a {\em bipartition} if the graph induced on each of these sets is edgeless. Equivalently, a graph is bipartite if and only if it has a bipartition.

\begin{lemma}\label{lem:corollaryEOCT} \app
    If an \EFXO instance $(G,w)$ has min-uncut number 1, then $G$ has a bipartition $(A,B)$ where the sets satisfy the premise of \Cref{thm:Edge-OCT1-general-condition}. Moreover, given an edge $e$ such that $G-e$ is bipartite, the sets $A$ and $B$ can be computed in linear time.
\end{lemma}



\begin{proposition}{\rm \cite{IwataWY16,RamanujanS17}}\label{linear-time-OCT}
    There is a linear-time algorithm that, given a graph $G$ either correctly answers that the min-uncut number is more than 1 or produces an edge $e$ such that $G-e$ is bipartite.
\end{proposition}

% As a result of \Cref{thm:Edge-OCT1-general-condition}, \Cref{lem:corollaryEOCT}, and \Cref{linear-time-OCT} we obtain the following. 

\tractableEOCTone*

\begin{proof}
    Direct combination of \Cref{thm:Edge-OCT1-general-condition}, \Cref{lem:corollaryEOCT}, and \Cref{linear-time-OCT}. 
\end{proof}


