            \centering
            \includegraphics[page=1,scale=1.1]{rectilinear_3SAT.pdf}
            \subcaption{\textsc{Planar Monotone 3-SAT} consists of non-crossing orthogonal segments; each clause is monotone.}%
            \label{fig:rectilinear_3SAT_sat}
        \end{subfigure}
        \hfill
