\section{Appendix: Rate Laws}
\label{app:rate-laws}

Our model is governed by the following 19 rate laws. Note that in each sum over reveal‐indices (e.g.\ $k\neq j$), we implicitly exclude $k=g$, since no species $I_{j,k}$ (or $I_{j,k,\ell}$) is defined for $k=g$ (the host never reveals the prize door).


\begin{flalign}
&\frac{d[P]}{dt}
  = -k_1\sum_{j=1}^3 [P][D_{j}],                                                   &&\\
&\frac{d[D_{j}]}{dt}
  = -k_1[P][D_{j}]
    - k_2\sum_{\substack{i=1\\ i\neq j}}^3 [I_{i}][D_{j}]
    - k_{\mathrm{sw}}\sum_{\substack{p,q=1\\ p\neq q}}^3 [I_{p,q}][D_{j}]
    - k_{\mathrm{st}}\sum_{\substack{s=1\\ s\neq j}}^3 [I_{j,s}][D_{j}],           &&\\
&\frac{d[I_{j}]}{dt}
  = k_1[P][D_{j}]
    - k_2\sum_{\substack{k=1\\ k\neq j}}^3 [I_{j}][D_{k}],                           &&\\
&\frac{d[I_{j,k}]}{dt}
  = k_2[I_{j}][D_{k}]
    - k_{\mathrm{st}}[I_{j,k}][D_{j}]
    - k_{\mathrm{sw}}\sum_{\substack{\ell=1\\ \ell\neq j,k}}^3 [I_{j,k}][D_{\ell}],  &&\\
&\frac{d[I_{j,k,\ell}]}{dt}
  = k_{\mathrm{sw}}[I_{j,k}][D_{\ell}],  \qquad \text{for } \ell \neq j,\ k          \\[\baselineskip]
&\frac{d[I_{j,k,j}]}{dt}
  = k_{\mathrm{st}}[I_{j,k}][D_{j}], \qquad \text{with } j \neq k.                   &&
\end{flalign}


\section{Appendix: Identical Rate Constants}
\label{app:degenerate}

The expression for \(W(t)\) in eq.~\eqref{eq:Wt} contains removable singularities whenever two of the three pseudo-first-order rate constants coincide.  In each case, one can apply l’Hôpital’s rule. For \(k_2 = k_{\mathrm{sw}} \neq 3k_1\) (\(k_{\rm st}=0\)), the cumulative win concentration is 

\begin{equation}
\label{eq:twoequal}
\begin{aligned}
W_{k_2=k_{\mathrm{sw}}}(t) &= 2 P_0 \bigg[\frac{k_{\mathrm{sw}}^{2}\,e^{-3D_{0}k_{1}t}\,e^{-D_{0}k_{\mathrm{sw}}t}\,\bigl(e^{3D_{0}k_{1}t}-e^{D_{0}k_{\mathrm{sw}}t}\bigr)}
     {3\,(3k_{1}-k_{\mathrm{sw}})^{2}}\\[6pt]
       &\quad - \frac{D_{0}\,k_{\mathrm{sw}}^{2}\,t\,e^{-D_{0}k_{\mathrm{sw}}t}}
         {3\,(3k_{1}-k_{\mathrm{sw}})}
         - \frac{e^{-D_{0}k_{\mathrm{sw}}t}\,\bigl(D_{0}k_{\mathrm{sw}}t - e^{D_{0}k_{\mathrm{sw}}t} + 1\bigr)}
         {3}\,\bigg].
\end{aligned}
\end{equation}




